window.SONGS_KK = [{"id":70,"title":"Абайлап қарашы менің көздерім","text":"[Куплет 1]\nАбайлап қарашы менің көздерім,\nАбайлап қарашы менің көздерім,\n//  Тәңір саған қарап тұр,\nАспаннан бәрін көріп!\nАбайлап қарашы менің көздерім!  //\n\n[Куплет 2]\nАбайлап менің тілім сөйлеші!\nАбайлап менің тілім сөйлеші!\n//  Иса сені есітіп тұр,\nСаған сұрақ қойып тұр,\nЕшкімді сен ренжітпеп пе едің?  //\n\n[Куплет 3]\nҚұлағым неге бұл сөзге құмарсың?\nҚұлағым неге бұл сөзге құмарсың?\n//  Құдай көктен есітіп тұр,\nСаған сұрақ қойып тұр,\nҚұлағым неге бұл сөзге құмарсың?  //\n\n[Куплет 4]\nАсықпай абайлап басшы аяғың!\nАсықпай абайлап басшы аяғың!\n//  Тәңір бәрін көріп тұр,\nКүнәдан тезірек қайт,\nИса сені Өзіне шақырып тұр!  //\n\n[Куплет 5]\nАбай бол жүрегім кімге сенесің?!\nАбай бол жүрегім кімге сенесің?!\nЖүрегіңді көріп тұр, сенесің бе, сен Оған?!\nАбай бол жүрегім кімге сенесің?!","songNumber":"221"},{"id":291,"title":"Адамдар адасар","text":"[Куплет 1]\nАдамдар адасар,\nЖол таппай тура!\nКүш алар, бас тауып,\nМәсіхке кезігіп!\nМәсіхпен жүру қуаныш,\nҚуаныш, қуаныш!\nҚараңғы түнде жарықта,\nМені қорғайды!"},{"id":561,"title":"Адамдарды Жаратушымен","text":"[Куплет 1]\nАдамдарды Жаратушымен\nТілдескеннен артық.\nНе жұбаныш, не қуаныш\nБіз мүлде таппадық.\n\n[Припев 1]\nҚұдаймен мәңгі тілдескен тамаша,\nҚұдаймен тілдескен сондай тамаша.\n\n[Куплет 2]\nТәңірмен тілдессең сен,\nҰлы Ұстазбен мәңгі,\nТолық біліп аласың,\nҚұдай берген пәнді.\n\n[Куплет 3]\nТілдессең сен Тәңірмен\n«Әкем» деп қана,\nҚұшағында Әкенің,\nТабасың сен пана.","songNumber":"12"},{"id":31,"title":"Адамдар, ойланыңдар","text":"[Куплет 1]\nАдамдар ойланыңдар,\nҚұлақ сап сөз тыңдаңдар,\nЖаратқан жер дүниені,\nҚұдайдан артық кім бар!\n\n[Припев 1]\n//   Ол сенің жанашырың!\nАңсаған арман жырың!\nМәңгілік өмір сыйлар,\nОл сенің Құтқарушың!  //\n\n[Куплет 2]\nАдамдар ойланыңдар,\nКүнәдан бой тартыңдар!\nБіз үшін құрбан болған,\nИсаны ойға алыңдар!\n\n[Куплет 3]\nАдамдар ойланыңдар,\nӨкініп кеш қалмаңдар,\nИсаның сөзін тыңдап,\nЖүрекпен қабылдаңдар!","songNumber":"1"},{"id":99,"title":"Адамзатты Құдай сонша сүйеді","text":"[Куплет 1]\nАдамзатты Құдай сонша сүйеді\nЖалғыз Ұлын біз үшін құрбан етті\nТүспей тозаққа әркім Оған сенуші\nМәңгі өмірге ие болады\n\n[Припев 1]\nАллелуя аллелуя аллелуя аллелуя аумин\nАллелуя аллелуя аллелуя аумин"},{"id":501,"title":"Адасқан адамға","text":"[Куплет 1]\nАдасқан адамға жол көрсетіңдер,\nЖығылғанды демеңдер көтеріп.\nБарлық өлілерге шындықты айтыңдар,\nҰйықтап жатқанды оят қайтадан.\n\n[Припев 1]\n// Адасқан адамға жол көрсетіңдер,\nЖығылғанды демеңдер көтеріп. //\n\n[Куплет 2]\nҚұнның төленгенін бәріне айтыңдар,\nЖалыныңдар Исаға келуге.\nҚұтқару ерлігін даңқтап мадақтаңдар,\nБақытсыздар бақытын таба алсын.\n\n[Куплет 3]\nҚасірет шеккенге, қайғырып жүргенге,\nТек Құдай Рухы мереке берет.\nСеніммен шаттанып, Исаға ерушіге\nЖер бетіне жар салу берілді.","songNumber":"2"},{"id":404,"title":"Адасып жүргенде азап шегіп","text":"[Куплет 1]\nАдасып жүргенде азап шегіп,\nСен мені іздедің, Құтқарушым.\n// Алдамшы өмірге қызығумен\nӨзіңнен адасып жүріппін мен. //\n\n[Куплет 2]\nКеремет мынау бір табиғатың,\nАй менен жұлдызды жарқыраттың,\n// Аспан мен жерді де Сен жараттың,\nБарлығы Өзіңе бағынатын. //\n\n[Куплет 3]\nМың алғыс айтамын Өзіңе мен,\nКөкірегімді ояттың Рухыңменен.\n// Көзімді аштың Сен, жұмулы еді,\nЖүрегім тас еді, жібіттің сен. //\n\n[Куплет 4]\nТәңірім, Өзіңе бас иемін,\nҚұдіретті күшіңе мен сенемін.\n// О, неткен күнәкар жан едім мен,\nАйқышта азаппен Сені өлтірген. //\n\n[Куплет 5]\nСен мені сүйесің, иланам ғой,\nЖаныңды мен үшін қинадың ғой.\n// Өзіңе келгенді кешіріп Сен,\nМәңгілік өмірді сыйладың ғой. //\n\n[Куплет 6]\nБар бақыт Өзіңсің өмірдегі,\nКүнәмді жуасың көңілдегі.\n// Тек қана Өзіңе бас иемін,\nТәңірім, кешірші, кешір мені. //","songNumber":"98"},{"id":484,"title":"Адасып көп жылдар жүріппін","text":"[Куплет 1]\nАдасып көп жылдар жүріппін,\nЖарық деп түнекті сүйіппін.\nТәңірдің сөзінен бейхабар,\nКүнәнің құлы боп жүріппін.\n\n[Припев 1]\n\"Жол, шындық, мәңгі өмір - Менмін\" деп,\nТәңірім шақырды мені де.\nӘкеге Менсіз жан бармас деп,\nЖеңді Ол өлімді мәңгіге.\n\n[Куплет 2]\nМәңгілік жерінен Ол келген,\nРухымен адамға Ол енген.\nМәңгілік болмысын паш етіп,\nМәсіхте Ол өліп, тірілген.\n\n[Куплет 3]\nЖаңа өмір басталады Мәсіхпен,\nБауырым, сен де кел, кешікпе.\nЖалғанның бітері жақында,\nЖол, шындық, мәңгі өмір Мәсіхте.","songNumber":"99"},{"id":510,"title":"Адонай","text":"[Куплет 1]\nАлғыс айтамыз Саған, Тәңір,\nСенің мейірің үшін.\nШөлімізді қандырдың Сен, Тәңір.\nАсқақта, Адонай!\nШөлімізді қандырдың Сен, Тәңір.\nАсқақта, Адонай!","songNumber":"3"},{"id":413,"title":"Ажарлы Киелі кітап менің қолымда","text":"[Куплет 1]\nАжарлы Киелі кітап менің қолымда.\nМен тынбастан мақтаймын,\nМадақтаймын Тәңірімді.\nӨмір берген, су берген жаныма шөлдегенде.\nАлғыс айтамын өмір бойы Құдіретті Иемізге.\n\n[Припев 1]\n// Киелі Кітап, киелі\nАдамзат оны сүйеді.\nҚиыншылықтар келгенде\nЖаныма қуат береді! //","songNumber":"3"},{"id":1026,"title":"Азап шегіп, торығатын","text":"[Куплет 1]\nАзап шегіп, торығатын,\nКездесер күндер мұң басатын.\nБатыл болғын,\nНық сенім арт сол кезде Исаға.\nӘке алдына ақ ниетпен\nКелгеніңді көрдім мен сонда.\n\n[Припев 1]\nСиынам сонда мен\n«Сен арқылы Тәңір\nБөленгей құрметке,\nО, Аллелуя!»","songNumber":"4"},{"id":476,"title":"Айқара ашылды Көктің қақпалары","text":"[Куплет 1]\nАйқыш ағаштағы Құрбандық арқылы,\nАйқара ашылды, Көктің қақпалары\nСенімен жүздессем қасыңа барамын,\nКенеліп Әкенің күшіне!\n\n[Куплет 2]\nАйқыш ағаштағы Құрбандық арқылы,\nАйқара ашылды, Көктің қақпалары\nСенімен жүздессем қасыңа барамын,\nКенеліп Әкенің даңқына!\n\n[Припев 1]\n// Иса Патшалығын бізге ашты,\nПатшалық өз құшағын бізге жайды! //\n\n[Куплет 3]\nТек құшағыңда махаббатқа толам,\nӘке құшағында Исаны мен көрем!\nСенімен жүздессем қасыңа барамын,\nКенеліп Әкенің даңқына!","alternateTitle":"Иса Патшалығын бізге ашты"},{"id":414,"title":"Айқыш алдында тұрған сол күнің есіңде ме?","text":"[Куплет 1]\nАйқыш алдында тұрған сол күнің есіңде ме?\nЕсіңде ме, қалай жүрегіңнің сыздағаны?\n//  Саған бұл жолды Иса-өтеушің ашып берген,\nМәңгі қуаныш алдыңда күтіп тұр сені! //\n\n[Куплет 2]\nБұл жолмен жүрді Иса, азаптан әлсіреген,\nСенің әлсіремеуің үшін қимындық жолда\nАйқышпен өтті Өзі алды көктің наласын,\n.....................................\n\n[Куплет 3]\nӘкем, не үшін, Сен Мені азапқа , қалдырдың?!\nСыйынды Иса, бар күнәны мойнына алып!\n// Ол өлімімен, Жаратқан Иені, даңқтады,\nҚұдай сүйіспеншілігін бәрі көрсін - деп! //\n\n[Куплет 4]\nТыңдашы досым, біз екеуміз өмірімізбен,\nДаңқтау керекпіз, Өтеушінің ұлы ерлігін!\n// Ол, бізді сүйді, айнымас сүйіспеншілікпен,\nБарлық адамға сыйлады, Иса рақымын! //"},{"id":331,"title":"Айнаға қарашы","text":"[Куплет 1]\nАйнаға қарашы, не көресің?\nАузым, мұрным, көзім, шашым да бар,\nАузым, мұрным, көзім, шашым да бар."},{"id":681,"title":"Айтқан сөзін Құдайымның","text":"[Куплет 1]\nАйтқан сөзін Құдайымның\nАшуланбай қабылдашы.\nҚұтқарылып сен де бүгін\nЖарыққа сол жақындашы.\n\n[Припев 1]\nЕртеңгі күн белгісіз ғой\nБүгін келші құтқарылшы\nСөзін тыңдап асығып сен\nЖарыққа сол жақындашы.\n\n[Куплет 2]\nБұл өмірден аларым жоқ,\nЖақсылықпен тапқаным жоқ\nСенушідей өмір сүріп,\nЖақындашы сол жәннатқа"},{"id":493,"title":"Айтшы: Қанның жігерін сен білдің бе?","text":"[Куплет 1]\nАйтшы: Қанның жігерін сен білдің бе?\nАқталдың ба Иса Қанымен?\nРахатын Оның жаныңмен сездің бе?\nТазардың ба, Иса қанымен?\n\n[Припев 1]\nТазартыл!\nОның Қаны күнәның дағын кетірер,\nАйқышта Мәсіхтің төгілген Қаны,\nҚардай әппақ қып ағартады.\n\n[Куплет 2]\nКүнде сен Оның алдында тұрсың ба?\nАқталдың ба, Иса Қанымен?\nРақымдылығын сездің бе Құдайдың,\nТазардың ба, Иса Қанымен?\n\n[Куплет 3]\nМәсіхтің келуіне дайынбысың?\nАқталдың ба, Иса Қанымен?\nҚасиетті өлкеге кірер жаның,\nТазарсаң Қанымен Мәсіхтің.\n\n[Куплет 4]\nКешірім сұрап жамандықтан жерін,\nМәсіхтің Қанымен ақтал сен!\nАйқышта Қаны төгілген сен үшін,\nМәсіхтің Қанымен тазар сен.","songNumber":"100"},{"id":34,"title":"Ақ батаң қонсын жеріме, ояну келсін еліме!","text":"[Куплет 1]\nҚұтқаруға қазақ елін, Тәңір Иса келді!\nШексіз рақымын көрсетіп, мейірімін берді.\nМәңгі мекен алтын қала, баратын жеріміз,\nАқ жолыңды көрсет Ием, Саған біз келеміз!\n\n[Предприпев 1]\nАңсаймыз Сені! Аңсаймыз Сені!\nТәңірім келші, Иса!\n\n[Припев 1]\nАқ батаң қонсын жеріме, ояну келсін еліме!\nҚазақстан Сенің жүзіңді іздесін,\nХалқым Сені мадақтасын!","alternateTitle":"Құтқаруға Қазақ елін..."},{"id":297,"title":"Ақ мамықтағы қыс қойнында","text":"[Куплет 1]\nАқ мамықтағы қыс қойнында,\nТау, қырат, дала, беліміз.\nЕскі әуеннің қанатында,\nҚалғиды қартаң жеріміз.\n\n[Припев 1]\nМәсіхтің туылу мейрамы,\nАдаспау үшін жолдан.\nМәсіхтің туылу мейрамы,\nЖүректе шамы жанған.\n\n[Куплет 2]\nҚауымда домбыра жаңғыртып,\nМейрам әуені төгілді.\nСол түнгі аспанды жарық қып,\nЕрекше жұлдыз көрінді.","songNumber":"158"},{"id":25,"title":"Ақ пейілді, жарқын жүзді Ием менің!","text":"[Куплет 1]\nАқ пейілді, жарқын жүзді Ием менің!\nПәктігің, әділдігің ұнайды Сенің.\nБалаңды көктен туған нұрға бөлеп\nӘлдилеп жетеледің.\n\n[Припев 1]\nКиелі, Қасиетті Тәңірім Сен!\nЕремін мәңгілікке Соңыңнан мен.\nЖолыңа құрбан еттім өмірімді\nҚорғаушы Ием Сенсің!","songNumber":"11"},{"id":1004,"title":"Ақ пейілді Ием менің","text":"[Куплет 1]\nАқ пейілді Ием менің\nЗор сеніммен Саған келемін\nЖүрегімнен шыққан әнімен\nАлғысымды айтамын мен\nЖүректің төріне, Иса\nКүтемін, шақырам Сені\nАңсап, сағынамын жүзіңді\nКелші осы жерге.\n\n[Предприпев 1]\n// Иса - Саған, басымды ием! //\n\n[Припев 1]\n// Киелі, Сен Ұлысың, Сені сүйемін.\nСен сондай ғажапсың, Сені сүйемін.\nСен сондай кереметсің, Сені сүйемін.\nСен маған қымбатсың, Сені сүйемін! //\n\n[Бридж 1]\nСені сүйемін. Сені сүйемін.","alternateTitle":"Иса - Саған, басымды ием!"},{"id":133,"title":"Ақыр соңында","text":"[Куплет 1]\nАқыр соңында мен өзімнің Рухымды\nБүкіл адамзаттың үстіне төгемін\n\n[Припев 1]\n// Ұл-қыздарың пайғамбарлық сөз айтады\nЖастарың аян көреді\nҚарттарың түс көреді\nКиелі рух қонғанда //\nКиелі рух келші осында\nКиелі рух бізбен бірге болсын"},{"id":323,"title":"Алақай!","text":"[Куплет 1]\nАлақай, алақай!\nЖасұлан келді, Айжан да бар!\nАлақай, алақай!\nАрман мен Айгерім де бар!\nАлақай, алақай!\nБота мен Дәурен осында!\nАлақай, алақай!\nҚуанамыз бәріміз!"},{"id":24,"title":"Алаңға кіргенде","text":"[Куплет 1]\nБар әлем жырлаңдар Иені,\nӘндетіп алдына келіңдер!\nМойындаңдар Ием деп Құдайды,\nОл бізді жаратқан!\n\n[Припев 1]\nАлғыс жыр айтыңдар қақпадан өткенде!\nАлғыс айтыңдар Құдайға, алаңға кіргенде!\nАлаңға кіргенде!\n\n[Куплет 2]\nЖаратқан Иеміз мейірімді,\nМәңгілік рақым етеді,\nҰрпақтан ұрпаққа біздерге\nАдал боп қала береді!","songNumber":"44","alternateTitle":"Бар әлем жырлаңдар Иені,"},{"id":419,"title":"Алаңға кіргенде","text":"[Куплет 1]\nБар әлем жырлаңдар Иені,\nӘндетіп алдына келіңдер!\nМойындаңдар Ием деп Құдайды,\nОл бізді жаратқан!\n\n[Припев 1]\nАлғыс жыр айтыңдар қақпадан өткенде!\nАлғыс айтыңдар Құдайға, алаңға кіргенде!\nАлаңға кіргенде!\n\n[Куплет 2]\nЖаратқан Иеміз мейірімді,\nМәңгілік рақым етеді,\nҰрпақтан ұрпаққа біздерге\nАдал боп қала береді!\n\n[Куплет 3]\nAll the earth, come shout to the Lord\nWith songs of joy, let's worship Him\nKnow that the Lord, He is our God\nHe's the one who created us.\n\n[Припев 2]\nWith thanksgiving we will sing\nInto Your courts with praise\nWe praise You and worship You\nOh Lord our God\nInto Your courts with praise\nInto Your courts with praise.\n\n[Куплет 4]\nЖаратқан Иеміз мейірімді.\nМәңгілік рақым етеді\nҰрпақтан ұрпаққа біздерге.\nАдал бол қала береді.\n\n[Куплет 5]\nCreator God, You are so good\nSo great is Your unfailing love\nAge to age, from time to time,\nForever is Your faithfulness.","alternateTitle":"Into Your Courts"},{"id":880,"title":"Алғыс айта бастасам қиналғанда","text":"[Куплет 1]\n// Алғыс айта бастасам қиналғанда\nМұңдарымды ұмытамын сол кезде\nСыйлағандарың есіме түскенде,\nРиза болам Саған,\nРиза болам Саған //  Әкем!\n\n[Припев 1]\nБәрі үшін, бәрі үшін рахмет!\nҚұтқарушым бәрі үшін рахмет!\nБірге болу Сенімен керемет,\nБәрі үшін бәрі рахмет Саған!\nРизамын мен, ризамын мен Саған!\nРухыңменен бәрін бердің маған,\nОрындалды арманым аңсаған,\nБәрі үшін рахмет!\nБәрі үшін рахмет Саған!\n\n[Куплет 2]\n// Алғысымды көтеремін дұғада,\nБас иемін иілемін алдыңда.\nМұқтажымды айтпай-ақ білесің де,\nРизамын мен Саған,\nРизамын мен Саған //  Иса!\n\n[Куплет 3]\n// Білесің жолдарым мен ойларымды,\nБілесің жүргенімді, тұрғанымды.\nАлғыстар бар шексіз жүрегімде,\nРизамын мен Саған,\nРизамын мен Саған //  Иса!"},{"id":71,"title":"Алғыс, Ием","text":"[Куплет 1]\nАлдыңа Сенің келем,\nАйтқым келеді менің Саған, Ием:\n// Алғыс, Ием! //\nМаған бергендеріңе,\nЖарылқау рақымыңды төккеніңе\n// Алғыс, Ием! //\n\n[Припев 1]\nҚуанышпен мен,\nМадақ әнімен,\nСозам қолымды\nСаған айтамын:\nАлғыс, Ием,\nСаған айтам:\nАлғыс, Ием!\n\n[Куплет 2]\nӨміріме Сен келдің,\nТүнекті серпіп маған нұр бердің,\n// Алғыс, Ием! //\nКүнәм мен ұятты алдың,\nӘлсіз бен ауруды сауықтырдың.\n// Алғыс, Ием! //","songNumber":"5"},{"id":540,"title":"Алғыс Ием Саған","text":"[Куплет 1]\nАлғыс Ием Саған\nҚұтқарушы Патшам.\nШын жүректен Саған\nБіз ән саламыз.\n\n[Припев 1]\nҚуанышты өмір бердің,\nБіз Саған ризамыз.\nСен бізді құтқардың\nҚайғы күнәдан.\nМадақтаңдар бар халық!\nТәңір Иеңді мадақта.\nМадақтаңдар! Ол ізгі!\nМәңгі Оның мейірімі.\nМадақтаңдар!","songNumber":"5"},{"id":879,"title":"Алғысқа толы атың","text":"[Куплет 1]\nАлғысқа толы атың,\nЖер-көкке сыймас даңқың!\nКеремет ұлы салтанатың\nӘндетсем әнім жетпес,\nЖырласам жырым жетпес\nТәңірімсің Сен мақтанатын.\n\n[Припев 1]\n// Сен келгенде жаныма\nАшылады қуана Саған жүрегім,\nСен сөйлесең жүрекке\nТүсінеді бір сәтте\nЕй, менің жан дүнием,\nСенсің Тәңірім\nЖүрегімді көретін\nСенсің Бағушым,\nЖүрекпен сөйлесетін.\nБілесің маған қандай сөздің керегін. //\n\n[Куплет 2]\nШақырған барлық жанға жақынсың,\nТек Сен ғана\nСенген жан жаңылмас жолында,\nТүнекте болып жарық,\nЖан рухта болып азық\nКелесің бәрін қолға алып.\n\n[Куплет 3]\nЖүректен шыққан алғыс,\nТөгеді тек қуаныш.\nТек Сенің табиғатыңмен\nҚосылсам сендей болсам,\nРухыңмен ұшып-қонсам,\nБұдан артық бар ма екен арман."},{"id":214,"title":"Алғыс Саған","text":"[Куплет 1]\nАлғыс Саған\nТәңірді біз дауыстап\nМадақтайық\nКиелі Құдай\nМәңгі мадақталсын\nОл мәңгі біздің Иеміз\nТіземді бүгіп\nЖариялаймын мен\nИса-Тәңірім\nАумин"},{"id":173,"title":"Алғыс Саған, жалғыз Саған","text":"[Куплет 1]\n// Алғыс Саған, жалғыз Саған,\nАлғыс Саған Иса!  //\nТәңір маған сөйледің Сен\nСол сәт өзгердім мен.\nМәңгі өмір сыйладың Сен\nКиелі Рухыңмен.\n\n[Припев 1]\nО, Құдайым, өмір бұлағы Сен!\nЖалғыз Саған табынамын мен.","songNumber":"197"},{"id":549,"title":"Алдымда асу бар","text":"[Куплет 1]\nАлдымда асу бар,\nАлыс және ауыр,\nҚұдайым қорғайды жалғыз қалдырмайды!\nКөп қайғы қасірет,\nжолымда кездеседі,\nТәңірім Өзі күш беріп, көмектеседі!"},{"id":395,"title":"Алиллуйя Алиллуйя","text":"[Куплет 1]\nАлиллуйя Алиллуйя\nАлиллуйя Құдай Патша\nАлиллуйя Алиллуйя\nАлиллуйя Ұлы Құдай Патша\n\n[Припев 1]\nКүш жеңісімен бәріне\nӨз атағын көрсеттің\nӨлімді ойсыратты біздің Құдай\nҚұрбан болып біз үшін\nКүнәлардан босаттың\nОның рақымымен құтқарылдық"},{"id":328,"title":"Аллелу","text":"[Куплет 1]\n//// Аллелу ////  Құдайды мадақтаңдар\n//// Аллелу ////  Құдайды мадақтаңдар.\nҚұдайды мадақтаңдар, Аллелу,\nҚұдайды мадақтаңдар, Аллелу,\nҚұдайды мадақтаңдар, Аллелу,\nҚұдайды мадақтаңдар!","songNumber":"6"},{"id":231,"title":"Аллелуйя, Адонай көкте мәңгі бір Құдай!","text":"[Куплет 1]\nАллелуйя - Адонай, көкте мәңгі, бір Құдай!\nТалай жылдар, пайғамбарлар, жазған солай,\nАллелуйя - Адонай, көкте мәңгі, бір Құдай!\nТалай жылдар, Иерусалим, тұрған солай!\n\n[Припев 1]\nСенсің менің жан-арманым Иерусалим!\nҚұдай сені жарылқасын Иерусалим!\nНеге, неге мұңаясың Иерусалим!\nҚұдай біздің арамызда Иерусалим!\n\n[Куплет 2]\nИсраилдың Патшасы, қасиетті жыршысы,,\nДәуіт Патша жүрген қала Иерусалим!\nДаналардың данасы, жарлылардың панасы,\nСүлейменді көрген қала Иерусалим!\n\n[Куплет 3]\nЖарық болып, нұр болып, Көкке барар, жол болып,\nҚұтқарушым, келген қала Иерусалим!\nКөздеріне жас ала, жүрегіне мұң тола,\nҚұтқарушым сүйген қала Иерусалим!"},{"id":329,"title":"Аллелуя","text":"[Куплет 1]\nАллелуя! Аллелуя!\nАллелуя! Аллелуя!\nАллелуя! Аллелуя!\nАллелуя! Аллелуя!\n\n[Куплет 2]\nСені сүйеміз!\n\n[Куплет 3]\nҚұрметті Иса!\n\n[Куплет 4]\nҚұтқарушым!\n\n[Куплет 5]\nИса Иеміз!\n\n[Куплет 6]\nАллелуя!","songNumber":"8","copyright":"1972 Манна Мусик, Инк."},{"id":898,"title":"Аллелуя","text":"[Куплет 1]\nАллелуя,\nАллелуя\nҚұдіретті Тәңірге - Патшаға!\nАллелуя,\nАллелуя\nҚұдіретті Тәңірге - Патшаға!\n\n[Куплет 2]\nАллелуя!\nКиелі, киелі,\nСен Тәңірсің құдіретті,\nЛайықсың Тоқты,\nЛайықсың даңққа!\nСен киелісің, киелі,\nСен Тәңірсің құдіретті,\nЛайықсың Тоқты,\nЛайықсың даңққа!\nАумин!","songNumber":"7","alternateTitle":"Құдіретті Тәңірге - Патшаға!"},{"id":650,"title":"Аллелуя, Адонай","text":"[Куплет 1]\nАллелуя, Адонай!\nАллелуя, Адонай!\nОсанна! Осанна!\nАллелуя, Адонай!\nАллелуя, Ел Шаддай!..\n\n[Куплет 2]\nАллелуя, Яһве!..\n\n[Куплет 3]\nАллелу, Яһве-Ире!..\n\n[Куплет 4]\nАллелу, Яһве-Кадош!..\n\n[Куплет 5]\nАллелу, Яһве-Шалом!..\n\n[Куплет 6]\nАллелу, Яһве-Нисси!..\n\n[Куплет 7]\nАллелу, Яһве-Рафа!..","songNumber":"9"},{"id":390,"title":"Аллилуйя, Иса тірі","text":"[Куплет 1]\nАллилуйя, Иса тірі,\nӨлім жеңілді, мәңгі өмір берілді\nИса мәңгі тірі,\nОл тірі, Ол тірі\nАлғашқы болып келді Ол, Соңғысы да Ол\nҰлы бостаңдықпен, жеңіс берді Ол бізге\nТірілген Исамыз, Ол тірі, Ол тірі\nАллилуйя, Иса тірі, Иса тірі, Иса тірі."},{"id":397,"title":"Алып шыққан түнектен","text":"[Куплет 1]\nАлып шыққан түнектен,\nӨміріме солмас гүл еккен.\nҮмітімді артамын Саған Тәңірім.\nӘлсіз үнді естіген.\nТұңғиықтан шығарған,\nКөз жасымды сүртіп тиылтқан,\nАлғысым менің шексіз Саған Тәңірім\nАяғыма берік тұрғызған.\n\n[Припев 1]\nМен жаңа бір ән айтамын, айтамын.\nЕнді үнсіз қарап тұрмаймын.\nМен жаңа бір ән айтамын Құдайға\nСүйіспеншілігін жырлаймын.\n\n[Куплет 2]\nБақытты болар адам\nЖаңа өмірге жасап қадам.\nТаусылмас керемет істері Тәңірдің\nМәңгі өмір сыйлаған.\nБарлық адам қуанса,\nЖан-тәнімен Саған ұмтылған\nДауыстап Сені мадақтаса, даңқтасын,\nҰлы Құдай, Ұлы Құдай!","songNumber":"36"},{"id":563,"title":"Анық сенемін, менің Исам","text":"[Куплет 1]\nАнық сенемін, менің Исам,\nАспанның мұрасын берді маған.\nМені жұбатып, қуантады.\nИеленемін сол мұраны.\n\n[Припев 1]\n// Салтанат әнді айтам мәңгі,\nМенің ғажап Исам туралы!  //\n\n[Куплет 2]\nЖан-тәніммен Оған берілдім,\nИсаның перзенті енді болдым.\nТек одан табам нан мен сусын,\nТыныштыққа толды жүрегім.\n\n[Куплет 3]\nПана болды күшті қолымен,\nОған батыл анық сенемін мен.\nҚиындықта да рухым риза,\nҒажап Досым, мәңгі қасымда.\n\n[Куплет 4]\nСенімен ғана табар рухым,\nҒажапқа толы өмір мен тыным.\nМен кішірейіп, Сен өсесің.\nСаған жүрегімді берейін.","songNumber":"174"},{"id":693,"title":"Аңсаймын Сені","text":"[Куплет 1]\nМәңгіге, құтқардың үрейден,\nДауысыңмен, соңыңа ерем.\nТағзым ете, қолдарымды көкке созамын!\nСен себепкер, бар тіршілігіме.\nБаурайды Әкем, мейірімділігімен.\nЖарқын жүзіңді, көруді әрқашан аңсаймын.\n\n[Припев 1]\nАңсаймын - Сені!\nАңсаймын Сені - Ием!\nСені - Ием !\n\n[Куплет 2]\nКелер күн, нұр берер өмірге,\nКиелі Рух, ән төгер көңілге.\nДауысың Сенің, бағыт береді жолыма.\nТабар ма еді, тыныштық жаным?\nАйқышта Ұлың, төкпесе қанын!\nБілемін енді, өмірім мәңгігіе қолыңда!\n\n[Бридж 1]\nАңсаймын Сені! Аңсаймын Сені!\n\n[Бридж 2]\nБүкіл, әлемнің Иесі - Сен !\nДүние, қолыңда жалғыз - Сенің !","copyright":"Хиллсонг Унитед"},{"id":642,"title":"Аңсаймын Сені, Ием келе гөр","text":"[Куплет 1]\nАңсайм(ын) Сені, Ием, келе гөр!\nАңсайм(ын) Сені, Ием, келе гөр!\n// Аллелуя! //\n// Аңсайм(ын) Сені, Ием келе гөр! //\nАллелуя!\n// Барух ха ба бэшем Адонай, Халэлуйя! //\n// Барух ха ба бэшем Адонай! //\nХалэлуйя!\n// Барух ха ба бэшем Адонай, Халэлуйя! //\n//// Барух ха ба бэшем Адонай! ////\n//// Халэлуйя! ////","songNumber":"1"},{"id":515,"title":"Арайлап атқан, жарық таңдардан","text":"[Куплет 1]\nАрайлап атқан, жарық таңдардан,\nТәңірім менің Сені көремін.\nЖарқырап жанған, жарық жұлдыздан\nТәңірім менің Сені көремін.\n\n[Припев 1]\n// Сені сағынамын, Саған ұмтыламын\nЖүрегім менің Сені іздейді! //\n\n[Куплет 2]\nКөкте самғаған, қыран құстардан\nТәңірім менің Сені көремін.\nБиік шыңдардан, асқар таулардан\nТәңірім менің Сені көремін."},{"id":207,"title":"Арайлап атты таңдарым","text":"[Куплет 1]\nАрайлап атты таңдарым,\nНұрыңа мені бөледің.\nТәңірім Иса, қаныңмен,\nКүнәмнің құнын өтедің.\n\n[Припев 1]\nҚиналдың Иса мен үшін,\nАйқышқа беріп тәніңді,\nҚұтқарып алдың күнәдан,\nӘлемді және елімді.\n\n[Куплет 2]\nШыдадың Ием, мен үшін,\nЖаныңды салып азапқа,\nАдамның әрбір ұрпағы\nБармайды сенсе тозаққа.\n\n[Куплет 3]\nКеудеңнен қаның төгілді,\nТамшылап жерге тоқталмай,\nКүнәсіз Иса керілді,\nАйқыштан бақыт тапқандай.\n\n[Куплет 4]\nКүнәні енді жасама,\nКиелі Иса қаны үшін,\nТәубеге келші бауырым,\nӨмірдің ұғып мәнін шын.","songNumber":"136"},{"id":415,"title":"Арайлы бүгін таң атты","text":"[Куплет 1]\nАрайлы бүгін таң атты,\nҚұшағын Құдай бізге ашты.\nКездесіп бүгін,Тәңірім,\nТағзым еттім алдыңда.\n\n[Припев 1]\nСездің бе жүрек, сездің бе?\nКездесер күнді Құдаймен.\nКештің бе мені, кештің бе?\nКүнәмды менің Құдайым.\n\n[Куплет 2]\nСенімен болу тамаша,\nҚолымды бердім балаша.\nЖетелеп мені келесің,\nТастама, Иса, тастама.\n\n[Куплет 3]\nКөнліңді бұршы жеріме,\nҚазақ деген еліме.\nЖалынып, Иса, сұраймын,\nҚұтқаршы қазақ елімді","songNumber":"9"},{"id":901,"title":"Арайымен атқан күннің нұр күліп","text":"[Куплет 1]\nАрайымен атқан күннің нұр күліп,\nЖан-жүрегім ақтарылды жаңғырып.\n// Бұлақ көзін ағып жатқан таптым мен,\nҚуанышым таусылмайды мәңгілік. //\n\n[Куплет 2]\nҮміт, мақсат алға мені жетелер,\nЕш солмайтын мәңгілік сый әперер.\n// Жарығың боп мына өмірде жүруге,\nТәңір Ием, Өзің қуат бере гөр. //\n\n[Куплет 3]\nАйтпай-ақ та жүрегімді білесің,\nМұқтажымның ең асылын, киесін.\n// Оятсаңшы қазағымды, елімді,\nҚұтқарылсын, қисық жолын түзесін. //\n\n[Куплет 4]\nШапағатың бүкіл елге тарасын,\nШаттық әнім шарлап қазақ даласын.\n// Басымды иіп сұраймын мен, Тәңірім!\nҚұтқарсаңшы барлық қазақ баласын. //","songNumber":"27"},{"id":381,"title":"Арнадым әнімді","text":"[Куплет 1]\nЖүр еді қасарысып жүрегім,\nАлыс кетіп мен Сенен, мейірімді жүзіңнен!\nСонда Сен құшағыңды ашып кең,\nШақырдың Өзің мені зор мейіріміңмен!\n// Алдыңа келемін Ием,\nКешірім сенен өтінем.\nЖан сырымды ақтарам Саған,\nТек қана Саған. //\n\n[Куплет 2]\nҚалауым қарсы болып еркіңе,\nАдасты алыста берік болмай сертіне.\nКелемін қалжыраған күйімде,\nСенемін Тәңірім қабылдайсың үйіңе.\n// Қабылдап Әке Өзіңе,\nҚуантты мені мәңгіге.\nМадақтап Ұлы Есіміңді мен,\nАрнадым әнімді. //\n\n[Куплет 3]\nСенімің әлсіресе сенің де,\nҚысылма қайтадан Иемізге келуге.\nСебебі сені Ол шын сүйеді,\nТәңірім, кешіріп рақымына бөлейді\n// Есімі мәңгі киелі,\nМадақта Тәңір Иені.\nСарқылмайды мәңгілікке,\nОның мейірімі. //","alternateTitle":"Жүреді, қасарысып жүрегі"},{"id":674,"title":"Асқақсың","text":"[Куплет 1]\nМен тұрмын ұлылығыңа бас иіп,\nРақымыңды жамылып.\nМен тұрмын, білем күнәға батқанмын,\nТоқты қаны мені жуған.\n\n[Предприпев 1]\nЕнді ұқтым: махаббатың Сенің ұлы,\nӨміріңді бердің Сен мен үшін, Тәңір.\n\n[Куплет 2]\nМен тұрмын махаббатыңа бас иіп,\nКешірілдім мен кешіруге.\nМен тұрмын, білем қалауың Сенің:\nДаңқыңа бөленгенім менің.\n\n[Припев 1]\nШырқайм: Асқақсың! Асқақсың!\nТапты мені махаббатың,\nТірілтті, енді қолыңдамын Сенің(1)\n\n[Припев 2]\nШырқайм: Асқақсың! Асқақсың!\nМахаббатыңмен мен өзгердім,\nИса, Ұлы Мәртебелімсің!","songNumber":"11","copyright":"2003, 2004 Куриоус? Мусик УК"},{"id":552,"title":"Асқар биік көк аспан","text":"[Куплет 1]\nАсқар биік көк аспан,\nЖүректі тербер арман.\nМәсіхтегі тағдырым,\nОртақ іске айналған.\n\n[Припев 1]\n// Туыс болдық бәріміз,\nДостық біздің сәніміз.\nИсаның біз хатымыз,\nМәсіхші - ол атымыз. //\n\n[Куплет 2]\nДостығы Оның ісінде,\nКүнделікті өмірде.\nДертімізден жазылтты,\nҚайғымыздан арылтты.\n\n[Куплет 3]\nӘрбіріне адамның,\nҚұтқарылу хабарын,\nЖеткізейік, білеміз,\nМәсіхшілер боларын.","songNumber":"216"},{"id":459,"title":"Асқар таулардан да Ұлысың","text":"[Куплет 1]\n//  Асқар таулардан да Ұлысың,\nАспандағы жұлдыздардан да биіксің. //\n\n[Припев 1]\n// Иә, Саған ұқсас ешкім жоқ Тәңірім\nИә, тізе бүгіп келіп тұрмын алдыңа! //\n\n[Бридж 1]\n////  Тек Сен ғана лайықсың мадаққа,\nТек Сен ғана лайықсың құрметке! ////","songNumber":"7","alternateTitle":"Тек Сен ғана лайықсың мадаққа"},{"id":261,"title":"Асқар шыңды таулардан, ең биік ғажаптардан","text":"[Куплет 1]\nАсқар шыңды таулардан,\nең биік ғажаптардан,\nТаба алмадым, таба алмадым,\nЖүрегімнің қалауын!\n\n[Куплет 2]\nСарқыраған сулардан,\nЖауған жаңбыр мен қардан,\nТаба алмадым, таба алмадым,\nЖүрегімнің қалауын!\n\n[Куплет 3]\nҚанша әсем сұлуға мен қарадым,\nЖүрегімнің сұрауын таба алмадым,\nҚанша құмар сүрсемде,\nҚанша өмір көрсемде,\nТаба алмадым, таппадым,\nЖүрегімнің қалауын!\n\n[Припев 1]\nСенсің - Әке! Сенсің - Әке!\nЖүрегімнің қалауы,\nЖүрегім тек бір Өзіңмен толады,\nЕш нәрсемен, ештеңемен,\nТолмайды екен, Сенің орның,\nНегізісің жүрегімнің"},{"id":172,"title":"Аспан бізге ашық","text":"[Куплет 1]\nАспан бізге ашық.\nЖарылқаулар төгіледі.\nІзгілік беру тағынан\nЖарылқайды Өз халқын Ол.\nҚуаныш пен бақыт,\n\n[Припев 1]\nСаулық пен өмір.\nАспаннан төгеді\nҚұдай жақсылық.\nСенетін адамға,\nОған табынатын\nТәңір игілік береді.","songNumber":"2"},{"id":587,"title":"Аспанда бір қала бар","text":"[Куплет 1]\nАспанда бір қала бар, көшелері алтыннан,\nҚабырғасы жақұттан, қақпалары асылдан.\n\n[Припев 1]\nАлтын қала, сен менің арманымсың,\nАсыл қала, Тәңірдің мекенісің,\nАлтын қала, сен алыс аспандасың,\nЖерден ұшып, оған қашан жетем шіркін?!\n\n[Куплет 2]\nСол қалада тек қана қасиеттілер тұрады,\nИсаны олар мадақтап, мәңгі думан құрады.\n\n[Куплет 3]\nКөре алады қаланы шын тәубеге келгендер,\nКүнәларын қалдырып, тек Исаға ергендер.","songNumber":"222"},{"id":154,"title":"Аспандағы Әкеміз","text":"[Куплет 1]\nАспандағы Әкеміз,\nСенің Атың киелі тұтылсын!\nСенің Патшалығың келсін!\n\n[Куплет 2]\nАспанда болғандай, жерде де\nСенің еркің орындалсын!\nБізге бүгін күнделікті\nНанымызды бере гөр!\n\n[Куплет 3]\nБізге күнә жасағандарды\nКешіргендей, кешіргендей\nБіздің кінәларымызды да,\nКешіре гөр, кешіре гөр!\n\n[Куплет 4]\nБізді теріс жолға азып\nШығуа қалдырмай,\nБізді жамандықтан\nҚұтқара гөр, құтқара гөр\n\n[Куплет 5]\nӨйткені Патшалық та,\nҚұдірет те, Ұлылық та,\nМәңгілік Сенікі!\nАумин! Аумин!"},{"id":636,"title":"Аспандағы Әкеміз","text":"[Припев 1]\nАспандағы Әкеміз,\nКиелі болсын Сенің атың,\n\n[Куплет 1]\nКелсе екен патшалығың,\nБере гөр бізге нанымызды.\n\n[Куплет 2]\nБіз басқаларды кешіргендей,\nБізді де кешіре гөр.\n\n[Куплет 3]\nСақтай көрші бізді,\nШайтанның азғыруынан."},{"id":150,"title":"Аспандағы жарық күн қызарып барып батпай ма","text":"[Куплет 1]\nАспандағы жарық күн,\nҚызарып барып батпай ма?\nТіршіліктің дәм-тұзын,\nҚұдай мен адам татпай ма?\n\n[Куплет 2]\nҚанағат, тоқтам, әрқашан\nАбырой саған әперер.\nТіршілікте мәңгілік,\nСені тек Құдай мәпелер.\n\n[Куплет 3]\nАрманшыл менің бауырым,\nТілеймін саған тура жол.\nСол тіршілік тұтқасы\nАқиқат біреу: Иса - Ол.\n\n[Куплет 4]\nАйналаңа көз салып,\nАқылмен бәрін сарала.\nӨмірдің тап тұтқасын,\nӘлемді түгел арала.\n\n[Куплет 5]\nМына өмірдің мәні мен\nМақсатына көз жеткіз.\nАқиқаттың, ақ жолдың\nШұғыласын жарқ еткіз!\n\n[Куплет 6]\nҚайта тумай өмірге,\nМәңгілікке бармайсың.\nМынау жалған өмірден,\nТек өкініш қармайсың.\n\n[Куплет 7]\nКөктемде шыққан қызғалдақ,\nКүз болғанда солады.\nБүгінгі байлық, шат өмір,\nЕртең-ақ қурай болады.\n\n[Куплет 8]\nТек қана Құдай мәңгілік,\nМәңгілік болып қалады.\nҚұлпырып өскен қызыл гүл,\nКүз жеткенде солады.\n\n[Куплет 9]\nАйналайын, бауырым,\nАрманың болсын мәңгілік.\nТура жолға кел сен де,\nҚұдайды жырла ән қылып."},{"id":268,"title":"Аспандағы Құдай Әкеміз","text":"[Куплет 1]\n// Аспандағы Құдай Әкеміз,\nСенің атың киелі болсын\nСенің Патшалығың келсін\nИсаның Атынан аумин! //\n\n[Припев 1]\n// Сен Нұрыңда бізге әзірлеп\nбергенің үшін рахмет Ием!\nСен шындықсың, тар жолсың Иса\nСен мәңгі өмірсің! //"},{"id":952,"title":"Аспанда жарық ай, самсаған жұлдыздар","text":"[Куплет 1]\nАспанда жарық ай, самсаған жұлдыздар.\nРақымын аямай нұрын төкті Құдай.\nБүгін жар саламыз Иса Сөзін елге\nҚұдайдан Ол келген күнәң үшін жерге\n\n[Припев 1]\nИса Тәңір жүрегімде жаса мәңгі,\nӨзіңменен өміріміз болсын сәнді.\nМадақталсын киелі Атың бар әлемге.\nБір Өзіңе арнайық  жыр менен әнді.\n\n[Куплет 2]\nКөктегі Әкемнің айтқан сөзі балғын\nІнжу маржан Сөзін бауыр сенде алғын.\nКешірім алғанда күнәңды ақтайды\nАжалдан, апаттан жаныңды сақтайды.\n\n[Куплет 3]\nИем Жаратушым, Тәңірім, Бағушым!\nАтыңды даңқтаймын Иса Құтқарушым.\nШексіз мейіріңмен аштың құшағыңды.\nСыйладың Сен бізге ғажап жұмағыңды.","songNumber":"175"},{"id":886,"title":"Аспанда жұлдыз шашқан","text":"[Куплет 1]\n// Аспанда жұлдыз шашқан,\nӘр сөзің Сенің маржан,\nЖүректің кілтін тапқан - Тәңірім!\nӨмірдің - бұлағына,\nМахаббаттың дәміне,\nЖеткіздің Рухыңменен Тәңірім! //\n\n[Припев 1]\n// Қандай қуанышпен майлансам,\nСондай рахатпен мен мадақтаймын!\nҚандай рақымды мен қабылдасам\nСондай бақытпен алғыстаймын! //\nӘн жолдаймын, сиынамын, табынамын!\n\n[Куплет 2]\nПеріштелер көктегі,\nТірі жандар жердегі,\nМадақтайды тек Сені, тек Сені.\nКөк аспан үстіндегі,\nЖер асты теңіздегі,\nМадақтайды бір Сені, бір Сені."},{"id":396,"title":"Аспанда патшалық тағың","text":"[Куплет 1]\nАспанда патшалық тағың\nАл жер Сенің аяқ-тірегің\nҮй салу лайық жер іздедім\nКиелі үйіне тыныштық тілеп\nО, Құдай жүрегімді Саған\nМен арнап бердім тағзым етіп\nО, Әке мен сүйемін Сені\nКиелі мадақталсын Атың\n\n[Припев 1]\nКиелі мадақталсын Атың\nЖерде және аспанда\nКиелі мадақталсын Атың\nӨмірімде, жүрек тағымда\n\n[Куплет 2]\nИман жол жан жүрек үйіне\nСенемін Киелі Рух келгеніне\nМахаббат бұл үйдің иесі\nБар байлықтан қымбат ол әрине\nО, Құдай мен Саған беремін\nҚұрбандық ретінде мадағымды\nО, Иса мен сүйемін Сені\nКиелі мадақталсын Атың"},{"id":684,"title":"Аспанда таңғы жұлдыз туған кезде","text":"[Куплет 1]\nАспанда таңғы жұлдыз туған кезде,\nНұрынан жердің жүзі арайланды\nШығыста данышпандар атқа қонып,\nКөз тігіп, кең дүние қарай қалды.\n\n[Припев 1]\nО, ғажап, дүниеге сәби келді.\nО, ғажап, бұл әлемге өмір келді.\nИіліп, данышпандар тағзым етіп\nАлдыңда нәрестенің сәлем берді.\n\n[Куплет 2]\nҚуаныш жер жүзіне таратылды,\nБетлехем шахарында бала туды.\nДәуіттің ұрпағынан Исраилде,\nКелді, - деп, Құтқарушым, - дала тұрды.\n\n[Куплет 3]\nТаңданды бүкіл әлем қайран қалып,\nӘндетті періштелер сайран салып.\nЕркексіз таза қыздан туған сәби,\nТүбінде жай ғана адам болмас анық.","songNumber":"159"},{"id":373,"title":"Аспан мен жердің Патшалардың Патшасы","text":"[Куплет 1]\nАспан мен жердің Патшалардың\nПатшасы Иса\nМәңгі Киелі\nЖалғыз Оған шынайы, мен\nТабынамын жүрекпен\nОны сүйемін\n\n[Припев 1]\nИса Ұлы Құдай\nИса Тірі Құдай\nБүкіл даңқ Саған, бүкіл мадақ Саған\nСенің салтанатың бар әлемді толтырды\nДүние тізе бүгіп табынады\nИса Мәсіх мәңгі Киелі"},{"id":167,"title":"Аспанның күші қуатына толған","text":"[Куплет 1]\nАспанның күші қуатына толған.\nСен үшін Иса күреседі.\nСиынып сенімде нық бол әрқашан.\nСен үшін Иса күреседі.\n\n[Припев 1]\nБарлық құрмет, барлық даңқ.\nБарлық алғыс Исаға.\n\n[Куплет 2]\nСансыз дұшпандардың жүзін қайырып\nСен үшін Иса күреседі.\nҚаны менен бізге жеңіс әкеліп\nСен үшін Иса күреседі.\n\n[Куплет 3]\nАлға басу қиын, бірақ сен тайма.\nБіз үшін Иса күреседі.\nҚорықпа сен досым, Тәңір жаныңда.\nБіз үшін Иса күреседі.","songNumber":"8"},{"id":687,"title":"Атың даңқталсын","text":"[Куплет 1]\nАтың даңқталсын, Тәңірім,\nБереке, ырыс бар жерде, молшылықта да,\nАтың даңқталсын.\nАтың даңқталсын, Тәңірім,\nШөл далада мен қалсам да, таршылықта да,\nАтың даңқталсын.\n\n[Предприпев 1]\nӘрбір сыйыңды мадақпен қайтарамын,\nАйналамды түнек басса да Саған айтам:\n\n[Припев 1]\nҚастерленсін Тәңірдің Аты!\nҚастерленсін Аты!\nҚастерленсін Тәңірдің Аты!\nҚастерленсін даңқты Оның Аты!\n\n[Куплет 2]\nАтың даңқталсын, Тәңірім,\nКүн нұрын маған төккенде,\nТыныштықта да Атың даңқталсын.\nАтың даңқталсын, Тәңірім,\nАзапқа толы жолдарда,\nҚиындықта да Атың даңқталсын.\n\n[Бридж 1]\nСен бердің, Сен алдың!\nСен бердің, Сен алдың!\nЖүрегімнің қалауы:\nАтың қастерленсін!","songNumber":"13","copyright":"2002 Танкыоу Мусик"},{"id":724,"title":"Атың Мадақталсын","text":"[Куплет 1]\nАтың мадақталсын\nОрман тауым көлімде\nЖер мен аспан төрінде\nАтың мадақталсын!\n\n[Куплет 2]\nАтың мадақталсын\nШексіз мына ғаламда\nЖүрегім ой санамда\nАтың мадақталсын!\n\n[Предприпев 1]\nӘрбір атқан таңым үшін мадақтаймын\nЕсіміңді бар әлемге жариялаймын!\n\n[Припев 1]\nАтың мадақталсын Тәңір\nМәңгі мадақталсын\nӨзіңмен ғажап біздің өмір\nКиелі есімің даңқталсын!\n\n[Куплет 3]\nАтың Мадақталсын\nБиік шыңға жетсем де\nТерең құзға кетсем де\nАтың Мадақталсын\n\n[Куплет 4]\nАтың Мадақталсын\nҚандай сыннан өтсемде\nШаттыққа кенелсем де\nАтың Мадақталсын\n\n[Бридж 1]\n// Беретін де Сенсің Ием!\nалатын да Сенсің Ием!\nҚұдіретің мен еркіңе,\nмен басымды Ием! //","copyright":"2002 Танкыоу Мусик"},{"id":571,"title":"Атың мадақталсын әр жерде!","text":"[Куплет 1]\nӘке, Сені сүйеміз, Саған әндетеміз.\n\n[Припев 1]\nАтың мадақталсын әр жерде!\nАтың мадақталсын, атың мадақталсын,\nАтың мадақталсын әр жерде!\n\n[Куплет 2]\nИса, Сені сүйеміз, Саған әндетеміз.\n\n[Куплет 3]\nКиелі Рухты сүйеміз, Оған әндетеміз.","songNumber":"223","alternateTitle":"Әке Сені сүйеміз"},{"id":550,"title":"Атың Сенің киелі","text":"[Куплет 1]\n// Атың Сенің киелі,\nИса бізді сүйеді.\nКүнәмізді кешіріп,\nБолдық өмір тиегі. //\n\n[Припев 1]\n// Қуанайық, шаттанайық,\nЖарты жолда тоқтамайық.\nИса Мәсіх арқылы\nМәңгілікке аттанайық! //\n\n[Куплет 2]\n// Иса Сені сағынамын,\nАйтқаныңа бағынамын.\nИса Сөзі арқылы\nҚұдайымды танығанбыз. //\n\n[Куплет 3]\n// Сен бұл жердің тұзысың,\nСен бұл жердің нұрысың.\nҚұдай Әке жіберген\nҚұтқарушы Ұлысың. //","songNumber":"4"},{"id":603,"title":"Аумин","text":"[Куплет 1]\n/Тәңір Ие, бірге болып\nҚорған болып саған, жарылқасын\nБет жүзін, бұрып саған\nТыныштық сыйласын/\n\n[Припев 1]\n/Аумин, аумин, аумин\nАумин, аумин, аумин/\n\n[Куплет 2]\n/Тәңір Ие, бірге болып\nҚорған болып саған, жарылқасын\nБет жүзін, бұрып саған\nТыныштық сыйласын/\n\n[Припев 2]\n/Аумин, аумин, аумин\nАумин, аумин, аумин/\n/// Аумин, аумин, аумин\nАумин, аумин, аумин ///\n\n[Куплет 3]\n/Ол сенімен, бірге болсын\nҰрпағыңнан ұрпағыңа\nӨз үйің де, жүрегіңде\nНемереңмен, шөбереңде/\n\n[Куплет 4]\n/Ол сенімен, бірге болсын\nҰрпағыңнан ұрпағыңа\nӨз үйің де, жүрегіңде\nНемереңмен, шөбереңде/\n\n[Куплет 5]\n/Құдай жүрсін\nҚолдап, қорғап\nОл қасыңда, тастамайды\nҚамқорлайды, жетелейді\nӘрқашанда, Ол қасыңда/\n\n[Куплет 6]\n/Таң сәріден\nҚара түнге\nӘрбір жерде\nОл жаныңда\nЖыласаң да, қуансаң да\nОл сенімен, тастамайды/\n//// Әрқашан да, Ол қасыңда ////\n\n[Припев 3]\n/Аумин, аумин, аумин\nАумин, аумин, аумин/"},{"id":407,"title":"Аф-аф ит үреді","text":"[Куплет 1]\nАф-аф, аф-аф ит үреді,\n\"Азығым бар, бәрі жақсы\" - дейді."},{"id":236,"title":"Ахау! Бауырларым","text":"[Припев 1]\nАхау! Бауырларым, бауырларым,\nАрналды сіздер үшін осы әнім.\n// Келіңдер аяулы жұрт, мәңгі өмірге\nЖол ашып құшақ жайған бұл Тәңірге //\n\n[Куплет 1]\nКөп болды-ау, құстай қанат қағысқалы\nАрмысың бауырларым осындағы\n// Арада қилы-қилы жылдар өтіп\nҚұдайдан бірте-бірте алыстағы //\n\n[Куплет 2]\nБауырлар, ұмытпаңдар өз еліңді\nКең далам шалғай жүрген қазағымды\n// Күйзелген қазақ үшін жүрегімді\nТәңірім қабыл алсын тілегімді //\n\n[Куплет 3]\nҚайғысын бұл дүниенің ойлама деп\nҚұдайым бетін бұрды біздің елге\n// Келіңдер, кешікпеңдер, құтқарам деп,\nСендерге жұмақ төрін дайындады //\n\n[Куплет 4]\nӘр түрлі дін жолымен құтылам деп\nҚапыда қалып жүрме бауырларым\n// Исаның құрбан болған қаныменен\nҚұдайым құтқарады бәріңді де //\n\n[Куплет 5]\nҚиналып шаршағандар, бәріңе де,\nБеремін жан тыныштық Маған кел деп.\n// Тәңірім есік қағып шақырады.\nБауырлар, жүрегіңді аш түсінуге //\n\n[Куплет 6]\nЖұмақтын бар есігін айқара ашып,\nТәңірім шақырып тұр барлығынды.\n// Жабылар ол есіктің уақыты жақын.\nБауырлар, асығыңдар, үлгеріңдер //","songNumber":"102"},{"id":832,"title":"Ашагөр көктің есігін","text":"[Куплет 1]\nАшагөр көктің есігін,\nКөзіңді қадай гөр бізге.\nСаған мадақтар, әндер өшірілмей тұрар.\nҚарашы аспанды ашып.\n\n[Куплет 2]\nҚона гөр дәл осы жерге\nКүтеміз аңсаймыз Сені\nМінажаттың хош иісі аспанға жетіп тұр.\nҚона гөрші, О,Тәңір Ие.\n\n[Припев 1]\nКелші осы жерге,\nОрын алшы дәл қазір.\nҚабылдай гөрші біздің тағзымымызды алшы,\nСенің атың Иса,\nТек Сенің атың Иса\nТек қана Сенің атың мәңгі болсын осында."},{"id":887,"title":"Ашылды сәні өмірдің","text":"[Куплет 1]\nАшылды өмір ғажабың,\nТаза сүюі жүректің\nКек сақтамаған жан-дүниелерден,\nШын өмір болып ағатын.\nАшылды сәні өмірдің,\nТербелеткен махаббатың\nЖол табады жүректерге бұл сезім,\nМәңгілікке апаратын!\n\n[Припев 1]\nСен болмасаң, өмір ғажабы тоқталады, жоғалады!\nСен болмасаң, өмірдің сәні, болмағаны, тоқтағаны.\nСен болмасаң,\nЖүректің әні жырланбайды, қабылданбайды!\nЕгер де Сен болмасаң, жүректерде таза сезім болмайды!\nЕгер де Сен болмасаң,\nҚорғамасаң, жұбатпасаң, қолға алмасаң,\nҚұтқармағанда мені, білмер ем Сені,\nСезбес ем сүйгеніңді!\nЕгер де Сен болмасаң,\nӨмірімде, жан дүниемде, жүрегімде!\nЕгер де Сен болмасаң,\nБезіп кетер едім мен өз-өзімнен!\n\n[Припев 2]\nҚұтқардың Сен сезімсіздіктен,\nҚұтқардың Сен сенімсіздіктен,\nҚұтқардың Сен аяусыздықтан,\nЖүрегімді, жан дүниемді\n\n[Куплет 2]\nӨмірдің суығы тез,\nтоқтамайды уақыт бір кез.\nӨзіңсің тыным жоқ жүрек пен ойға,\nСенсіз өмір өтер босқа."},{"id":818,"title":"Ашылмайтын бұл әлі құпия-сыр","text":"[Куплет 1]\nӘркімдер-ақ сұрап жүр Ғайса кім деп\nКейбіреулер пайғамбар Ғайса демек\n// Ашылмайтын бұл әлі құпия-сыр\nСондықтан түсіндірме бергенім жоқ-ай //\n\n[Куплет 2]\nЕгер де бәріне айтсам Ғайса сол деп,\nНайза ұшында өлтірер мені түйреп.\n// Жемтігімді көмуге де бермей рұқсат\nӨлімтіктей тастар еді итке сүйреп //\n\n[Куплет 3]\nҒайсаның туы айтады бері жүр деп,\nСенбейтін кейбіреулері Оған күлмек.\n// Ғасыр бойы алысқан дұшпандар-ай,\nМаңдайына дақ салмақ Оны күндеп //\n\n[Куплет 4]\nҰстара әділ тілі Ғайса тілі,\nАсауды жуасытар тірі жүндеп.\n// Қиянатшыл замандар өтсе-дағы\nҒайса жолы мәңгілік өмір сүрмек. //"},{"id":883,"title":"Әке бізді сүйеді","text":"[Куплет 1]\n//   Әке бізді сүйеді,\nТаңдап алды Ол бізді,\nАнаның құрсағынан, таңдап алды бізді!  //\n\n[Припев 1]\n//   Біз сүйеміз Әкені!\nБіз сүйеміз!  //\n\n[Куплет 2]\n//  Әке бізге сөйлейді,\nқызым, ұлым бол- дейді!\nМұрасына Иеміз,\nҚызым, ұлым - дейді!  //\n\n[Куплет 3]\n//  Біз Әкеге сенеміз,\nСенгендіктен жеңеміз,\nАйтқанын орындайтын,\nӘкеге сенеміз!  //"},{"id":812,"title":"Әке, Иса, Киелі Рух","text":"[Куплет 1]\nҚұдай, Сені мадақтап,\nРахмет айтамыз Саған.\nГүлдей жайнап, шаттанып,\nӘнге қосамыз.\nБізді мәңгі құтқардың,\nСен тозақтың отынан.\nСағынышпен тағы да,\nСені тосамыз.\n\n[Припев 1]\n//  Әке, Иса! Әке, Иса, Киелі Рух, //\nСенімен әр кез боламыз,\nӘркез, бірге боламыз.\nМадақтаймыз Сені әрқашан,\nҚуанышқа мәңгі толамыз.\n\n[Куплет 2]\nБарлық ұлттың бір ғана Тәңірісің,\nЖер мен көктің Иесі, Жаратушым.\nАдамзаттың мәңгілік жыр-әнісің,\nСен тірісің, ұлысың, Құтқарушым!"},{"id":65,"title":"Әке қалаймын","text":"[Куплет 1]\nӘке қалаймын Сенімен болуды,\nСені сезуді, Сені сүюді\nКиелігіңнен Сенің күш-қуат аламын\nКиелі Рухтан мен рухтанамын\n\n[Припев 1]\nО Ием! Сені сүйемін, сүйемін\nСенімен болған қандай ғажайып\nСенің алдыңда тұрмын Иса, о Иса.\nСен керексің әрқашан маған."},{"id":217,"title":"Әкеміз - Құдай, Тәңірім - Иса","text":"[Куплет 1]\nЕгер жүрсем, ажалға, жақын мен\nқорықпаймын еш, зұлымдықтан!\n//  Өйткені, Тәңірім, біргесің - Сен,\nмәңгілік, жолымсың - Ием!  //\n\n[Припев 1]\n//  Әкеміз - Құдай,\nТәңірім - Иса,\nтыныштығым - Киелі Рух!  //","songNumber":"36"},{"id":126,"title":"Әкенің махаббатында шомыламын мен","text":"[Куплет 1]\n// Әкенің махаббатынада шомыламын мен!\nӘкенің махаббатында қуанамын мен!\nИса Әкенің құшағын бізге Сен аштың бізге! //\n\n[Куплет 2]\nӘкенің махаббатынада кенелемін мен!\nӘкенің махаббатынада еркелеймін мен!\nИса Әкенің құшағын бізге Сен аштың бізге!\n\n[Припев 1]\n// Жан дүнием толықтай сауықты,\nЖүрегімде Исаның әділдігі.\nӘкетайым Саған алғыс айтамын,\nӨмірімді ғажайып өзгерттің! //\nӘкетай рахмет Саған!"},{"id":639,"title":"Әке, Сен әрқашан мейірімдісің","text":"[Куплет 1]\nӘке, Сен әрқашан мейірімдісің,\nУәдеңе өте беріксің, ешкімге ұқсамайтын.\nҚолыңда көтеріп жүресің Өзің,\nЖетелейді тірі Сөзің, балаңды тастамайсың.\n\n[Припев 1]\nМейірімді! Мейірімді!\nМадақтаймын мәңгіге мейіріңді.\nМейірімді! Мейірімді!\nАрдақтаймын киелі мейіріңді.\n\n[Куплет 2]\nӘке, Сен күнәмді еске алмайсың,\nКүш беріп әркез қолдайсың,\nКүресте тастамайсың.\nЖанымды мейіріміңе бөледің,\nРақымың шексіз, көремін, тек Өзіңе сенемін.","songNumber":"23"},{"id":177,"title":"Әке Сенсің менің бағым","text":"[Куплет 1]\nӘке Сенсің менің бағым,\nБақытым Сенсің арманым.\nСенсіз маған өмір жоқ,\nБаратын да жерім жоқ,\nСенсіз маған өмір жоқ,\nТәңірім.\n\n[Куплет 2]\nСенсің менің шын өмірім,\nАшылып тұр Саған жүрегім.\nТолқиды менің өмірім,\nСенсің менің Тәңірім.\nТолқиды менің көңілім,\nТәңірім.","songNumber":"17"},{"id":161,"title":"Әке Сені мен сүйемін","text":"[Куплет 1]\nӘке Сені мен сүйемін\nӘлемдегі бар нәрседен артық\nКерексің маған.\nО, Иса, Құтқарушым,\nСаған бар өмірімді арнаймын,\nАрнаймын Саған.\n\n[Припев 1]\nПеріштелер Сені мақтайды,\nБіз де мақтаймыз тек Сені.\nИем менің, Сен өмірім,\nТек Сен үшін өмір сүрем.\nИем менің, сүйем Сені,\nМәңгі болшы Сен менімен.\n\n[Куплет 2]\nБарымды тек Саған арнаймын,\nБар тіршілік қолыңда Сенің.\nСүйемін Сені.\nӘр күнімді Өзің сыйлайсың,\nПатшалығың үшін қолданшы,\nҚолданшы Ием.","songNumber":"19"},{"id":80,"title":"Әкетайым","text":"[Куплет 1]\nИса барлық күнәмді Сен ақтап алдың.\nКиелі қаныңмен жуып тазарттың.\nТәңірім Өзіңсің өміріме келдің,\nКөктегі Әкеммен мені таныстырдың.\n\n[Припев 1]\nӘкетайым менің\nШын жүрегімнің түкпірінен\nСенің алдыңа келіп басымды ием.\nӘкетайым менің\nБар әлемнің алтынынан қымбат\nСенің Киелі Рухың\nТәңірімсің Сен.\nСүйемін Сені\nСүйемін Сені","songNumber":"60","alternateTitle":"Иса барлық күнәмнан Сен ақтап алдың"},{"id":514,"title":"Әкетайым жан, әнім Саған арналады","text":"[Куплет 1]\nТыныштықта келемін мен Өзіңе!(Өзіңе)\nҚұлақ салып, балдай тәтті сөзіңе(сөзіңе)\nӘкетайым сұраймын, ақ-батаңды (батаңды)\nТолтыршы мені - Киелі Рухыңа!\n\n[Припев 1]\nӘкетайым - жан,әнім Саған арналады, жүрегім!\nБалапандай, қанатыңның астына алдың - Сен мені!\nӘкетайым - жан,әнім Саған арналады, жүрегім!\nБалапандай, қанатыңның астына алдың - Сен мені!\n\n[Бридж 1]\nӘкетайым! Әкетайым! Әкетайым! Әкетайым!\nӘкетайым! Әкетайым! Әкетайым! Әкетайым!","alternateTitle":"Тыныштықта келемін мен Өзіңе"},{"id":311,"title":"Әкетайым, Рухыңнан айналайын","text":"[Куплет 1]\nӘкетайым Сенің Рухыңнан айналайын.\nӨмірімдегі шексіз мейіріміне бас ием.\nӨз қолыңмен мені балам деп, жетелеші.\nБүкіл өмірім жетпес Саған алғысты айтуға.\n\n[Предприпев 1]\nӘкетайым, Әкетайым, Әкетайым, Әкетайым.\n\n[Припев 1]\nЖалғыз Ұлыңды құрбандыққа Сен\nМен үшін шалдың сүйгендіктен.\nМені тозақтан сақтап, мәңгі өмір бердің.\nРизамын Саған Ием менің\nШын жүрегіммен табынамын.\nӘкетайым Рухыңнан айналайын."},{"id":885,"title":"Әке, түсінер жанымды Сен ғана","text":"[Куплет 1]\nТолқуымды менің осындай\nТүсінер жалғыз Сен ғана,\n// Тербетесің мені толқындай\nСездірмей сырымды басқаға //\n\n[Припев 1]\n// Әке! Әке! Әке! Әке!\nТүсінер жанымды Сен ғана! //\n\n[Куплет 2]\nӘке-Саған айтсам барлығын,\nСақталғанды көңілде,\n// Жақсының сақтайсың жалынын,\nЖаманның жабасың жолдарын! //\n\n[Куплет 3]\nРақымдылығың Сенің шексіз,\nҚұтқарып алдың кексіз,\n// Тазалайсың мені алтындай,\nТозақтың отына лақтырмай! //"},{"id":894,"title":"Әлдекім үйін құмға тұрғызыпты","text":"[Куплет 1]\n/// Әлдекім үйін құмға тұрғызыпты! ///\nЖауын жауды.\n\n[Куплет 2]\n/// Жауын жауып, су көтеріліп тасыды! ///\nСонда үй құлады!\n\n[Куплет 3]\n/// Екіншісі үйін, жартасқа тұрғызыпты! ///\nЖауын жауды.\n\n[Куплет 4]\n/// Жауын жауып, су көтеріліп тасыды! ///\nБірақ, үй құламады!\n\n[Куплет 5]\n/// Үйлеріңнің негізі Мәсіх болсын! ///\nЖауын жаумасын!\n\n[Куплет 6]\n/// Жауын жауып, су көтеріліп тасыйды! ///\nСонда үй құламас!","songNumber":"224"},{"id":213,"title":"Әлемді жаратты Құдай","text":"[Куплет 1]\nӘлемді жаратты Құдай!\nОсы әлемді жаратты Құдай!\nБүкіл әлемді жаратты Құдай!\nСүйікті Құдайым!\n\n[Припев 1]\nОл мені жаратты!\nОл сені жаратты!\nОл бізді жаратты!\nБіздің сүйікті Құдай!\n\n[Припев 2]\nБілемін: Ол сүйеді мені!\nБілемін: Ол сүйеді сені!\nБілемін: Ол сүйеді бізді,\nБіздің сүйікті Құдай!\n\n[Припев 3]\nОл сүйеді мені!\nОл сүйеді сені!\nОл сүйеді бізді,\nБіздің сүйікті Құдай!"},{"id":621,"title":"Әлемді Құдай Сүйеді","text":"[Куплет 1]\nМен тек айқышты ұстайм(ын)\nМен әрқашан Құдайды ұстайм(ын)\nТек махаббат мені құтқарды\nШынжырдың бәрін жойды\n\n[Припев 1]\nӘлемді Құдай сүйеді\nЖалғыз Ұлын біз үшін берд(і)\nОған кі-ім сенеді, тозаққа түспей\nМәңгі өмірге ие болады\n\n[Куплет 2]\nМен Иемізді күтем(ін)\nОның сөзіне сенем\nРақыммен құтқарылдым\nРақыммен боса-атылдым\n\n[Бридж 1]\nӨте құнды қан\nМені босатты\nБарлық ма-ақтау Исаға\nБәрін тапсырам\nТек саған Иса\nМенің Құтқарушым\n\n[Предприпев 1]\nМәңгі өмірге ие болады"},{"id":712,"title":"Әлемнің бәрін Құдай жаратқан","text":"[Куплет 1]\n// Әлемнің бәрін Құдай жаратқан,\nЕшнәрсе Онсыз пайда болмаған. //\n\n[Припев 1]\nМадақтаймын Сені,\nМадақтаймын Сені, Ием.\nМадақтаймын Сені, Мәңгілік, Аумин!\n\n[Куплет 2]\nО, неткен бай Құдайдың даналығы,\nНеткен терең Оның білік-парасаты.\nО, неткен шексіз Оның даналығы,\nНеткен терең Оның білік-парасаты.","songNumber":"16"},{"id":850,"title":"Әлеміме таң болып атқан","text":"[Куплет 1]\nӘлеміме таң болып атқан\nПәксің Сен Көгершінім\nӘлемімді толтырып жатқан.\nЕм таптым Көгершінім\n\n[Припев 1]\nКөктен келген көкейімде\nСыйың мол Көгершінім\nСені сүйіп өтемін мен\nРиза бол Көгершінім\n\n[Куплет 2]\nҚара бұлттар айырылған\nӨрісіңнен Көгершінім\nЖарық таңым қайырымды\nӨмірімсің Көгершінім\n\n[Куплет 3]\nЖан дүниемді табындырған\nСүйемін Көгершінім\nМені сонша сағындырған\nКиелі Көгершінім."},{"id":446,"title":"Әлемімсің","text":"[Куплет 1]\nӘкем, Сені мен сүйемін,\nЖүрегімнің қалауынан да,\nСен керексің.\nИса, сүйікті Құтқарушым,\nБәрі үшін Саған қарыздармын,\nСаған бәрін берем.\n\n[Предприпев 1]\nМадақтайды періштелер,\nБіз балаңбыз, табынамыз.\n\n[Припев 1]\nӘлемімсің, Құдайымсың,\nӨмірімді Саған арнайм.\nТәңірімсің, Сені сүйем,\nСенен ешкім айыра алмайды.\n\n[Куплет 2]\nМенде бардың бәрін берем,\nПатшам, Сен үшін өмір сүрем,\nТек Сен үшін.\nӘрбір күнім Сенің сыйың,\nСенің еркіңмен өткіземін мен,\nТек Сен үшін.","songNumber":"14"},{"id":53,"title":"Әлихан қайда?","text":"[Куплет 1]\nӘлихан қайда? Әлихан қайда?\nОл мұнда ма? Ол онда ма?\nОны көріп тұрмын!\nОны көріп тұрмын!\nМіне ол! Міне ол!"},{"id":275,"title":"Ән Айтамыз біз","text":"[Припев 1]\nӘн айтамыз біз, мадақтаймыз шын жүректен.\nӘн айтамыз біз, көкпенен бірігіп,\nЖар саламыз біз мадақтаймыз Исаны!\n\n[Куплет 1]\nҰлы да таң ғажайып, халықтар мен патшалар\nАлдыңда тізе бүгіп, тағзым етеді, Иса!\nТек сен үшін ( өмір сүрем)\nСен бізді босатасың, махаббатпен толтырасың\nЖүректе от жағасың Құдай ұлы тек сен үшін,\nТек Сен үшін, ( өмір сүрем)"},{"id":627,"title":"Ән Айтамын Мен","text":"[Куплет 1]\nБұл қойылым емес\nИем, шын жүректі\nҒибадат деп тілеймін\nСезімге батуға\nМен мүлдем ұмтылмаймын\nМен тек сен үшін айтамын\n\n[Припев 1]\nОо Ән айтамын мен\nШын жүрекпен айтсам тек\nТек саған менің Ием\nБілмеймін неге\nЖасадым жасанды оны\nОл Сенің даңқың үшін\n(Ооо Ооо)\n\n[Куплет 2]\nКемелдіктің орнына\nЖүрегімді қаладың\nБар нәрсемді беремін\nБір сәтке созылатын әннен де\nАдалдыққа толы өмір сүремін\nӘнім тек мақсатпен шырқала берсін -\nАқыр соңында, Бар даңққа лайықсың"},{"id":132,"title":"Әндетемін саған Иерусалим","text":"[Куплет 1]\nӘндетемін саған Иерусалим,\nБерекелі болсын Иерусалим.\nТәңір жарылқасын, Иерусалим,\nБейбітшілікте бол, Иерусалим.\n\n[Припев 1]\nШалом, шалом, Иерусалим,\nШалом, шалом,\nБейбітшілікте бол Иерусалим!\nТәңір жарылқасын, Иерусалим!.\n\n[Куплет 2]\nБейбітшілікте бол, Иерусалим,\nҚорғаның нық болсын, Иерусалим.\nҚуанышқа толсын жүрегіміз,\nӘн айтылсын саған, Иерусалим.\n\n[Куплет 3]\nҰмыта алмаймын сені, Иерусалим,\nОйымнан шығармаймын, Иерусалим.\nЕсімдесің сен, Иерусалим,\nМадақтаймын сені, Иерусалим.","songNumber":"14"},{"id":327,"title":"Әнмен мадақтаймын","text":"[Куплет 1]\nӘнмен мадақтаймын Атыңды, Ием!\nМадақтаймын Атыңды, Ием!\nСенің Атыңа құрмет пен ұлылық!\n\n[Куплет 2]\nАсқақтатам Сенің Атыңды, Ием!\nАсқақтатам Атыңды, Ием!\nСенің атыңа құрмет пен ұлылық!","songNumber":"15"},{"id":362,"title":"Ән саламыз Иемізге","text":"[Куплет 1]\n// Ән саламыз Иемізге. //\n// Ән саламыз Оған. //\nӘн саламыз Иемізге.\n\n[Куплет 2]\n// Өлімнен Иса тірілді. //\n// Өлімнен Иса. //\nӨлімнен Иса тірілді.\n\n[Куплет 3]\n// Мәсіх әлемнің Иесі. //\n// Мәсіх әлемнің. //\nМәсіх әлемнің Иесі.\n\n[Куплет 4]\n// Тәңірді мәңгі мадақта. //\n// Тәңірді мәңгі. //\nТәңірді мәңгі мадақта.","songNumber":"225"},{"id":942,"title":"Ән сал, Тәңірге аллелуя","text":"[Куплет 1]\nӘн сал, Тәңірге аллелуя!\nАллелуя!\n\n[Куплет 2]\nӨлімді жеңді, тірілді Иса!\n\n[Куплет 3]\nКөк пен жердің Патшасы - Иса!\n\n[Куплет 4]\nМадақта Оны жүрегіңмен!","songNumber":"16"},{"id":439,"title":"Ән салып, би билейік","text":"[Куплет 1]\nӘн салып, би билейік.\nҚолыңды көкке көтер.\nБіздің Құдай - шындық және өмір.\nМұқтаждықтар болғанда\nҚұдайға сен сиыншы.\nОл саған жауабын береді.\n\n[Припев 1]\n//// Себебі Ол - Иса тірі!  ////","songNumber":"15","alternateTitle":"Иса - тірі, себебі - Ол"},{"id":176,"title":"Әнім менің Саған арналады","text":"[Куплет 1]\nӘнім менің Саған арналады,\nЖүрегімнен шыққан.\nӘнім менің Сені мадақтайды,\nМәңгілікте тұрған.\n\n[Припев 1]\nТек Сен арманымсың!\nТек Сен қорғанымсың!\nСүйемін Сені менің Тәңірім!","songNumber":"22"},{"id":630,"title":"Әнімізбен мадақтаймыз Исаны","text":"[Куплет 1]\nӘнімізбен мадақтаймыз Исаны,\nСүйгендіктен ардақтаймыз Исаны.\nДаңқта Оны, даңқта Оны, Осанна,\nТәңіріміздің мейірімін шырқа адамзат!\n\n[Припев 1]\nӘсем әлем қарасаң,\nМәсіх оны жаратқан,\nНәрін беріп, күш дарытқан,\nЖұмаққа жол ашқан.\nМәңгіге даңқы артқан,\nКүнәлардан арылтқан,\nЖырла Оған, жырла Оған,\nҚуаншы әрқашан.\n\n[Куплет 2]\nМейірімін көремін әрбір гүлден,\nӘн, күй, жырды естимін әрбір елден.\nДаңқта Оны, даңқта Оны, Осанна,\nТәңіріміздің мейірімін шырқа адамзат!","songNumber":"38"},{"id":696,"title":"Әрбір Адамзат","text":"[Куплет 1]\nӘрбір адамзат Исаға келіп\nАлдында тізе бүгеді\nӘрбір тіл біткен\nпенде мойындайды\nИса мәңгілік Тәңір\n\n[Куплет 2]\nМен Оны мадақтаймын\nМен Оны даңқтаймын\nӘр күні Оның атын мадақтаймын\nИса, Иса\nИса Аллелуйя Иса!","alternateTitle":"Мен Оны мадақтаймын"},{"id":225,"title":"Әр бір айтқан сөзіңді","text":"[Куплет 1]\nӘрбір айтқан сөзіңді, мен аңсаймын Тәңірім!\nЖарылқауға толады, бүкіл менің өмірім!\n\n[Припев 1]\nСені көргім келеді Иса-Құтқарушымсың менің!\nСенімен болғым келеді, мәңгілікке, тек Сенімен!\n\n[Куплет 2]\nАлып бердің азаттық, Өз-киелі қаныңмен,\nШындық жолмен келемін,салып берген Рухыңмен!"},{"id":892,"title":"Әр бір күн мен әр сағат","text":"[Куплет 1]\nӘр бір күн мен әр сағат,\nҚұдай Өзі қорғайды!\nӘр бір күн мен әр сағат,\nҚұдай сені сақтайды!\nӘр бір күнмен, әр сағат,\nМенімен бірге!\nӘр бір күн мен әр сағат,\nИса бізбен бірге!"},{"id":361,"title":"Әрбір күн мен әр сағат Құдай Өзі қорғайды","text":"[Куплет 1]\n// Әрбір күн мен әр сағат Құдай Өзі қорғайды.\nӘрбір күн мен әр сағат Құдай сені сақтайды.\nӘрбір күн мен әр сағат менімен бірге,\nӘрбір күн мен әр сағат Иса бізбен бірге. //","songNumber":"226"},{"id":562,"title":"Әрбір қимылым Сенде Иса","text":"[Куплет 1]\nӘрбір қимылым Сенде Иса,\nЖаныма күш бердің.\nӘрбір тынысым Сенде Ием\nӘрбір қадамым Сенде Иса,\nЖүректің жолысың,\nӘрбір қадамым Сенде Ием.\n\n[Предприпев 1]\nЛа-ла-ла-ла,\nЛа-ла-ла-ла.\n\n[Припев 1]\nСенің жүзіңді көремін әрқашан,\nТолқындай таусылмайды мейрімін.\nМахаббатыңа мен толамын,\nӘке мұны қалай түсінемін?","songNumber":"18","copyright":"1996 Меркы / Винеярд Публишинг | Винеярд Сонгс Канада | ИОН Публишинг"},{"id":637,"title":"Әрбір сөздің мақсаты","text":"[Куплет 1]\nӘрбір сөздің мақсаты,\nЖүрегімнің барлық қалауы\nМадақтасын Сені Тәңірім.\n\n[Припев 1]\nСен барлық бұлттардан жоғарысың!\nБиіксің Сен адамзаттың ойынан.\nЕркіңді іздеймін жүрегіммен,\nСенемін мен Құдайдың рақымына.\n\n[Бридж 1]\nӘрбір сөздің мақсаты\nӘрбір сөздің мақсаты\nӘрбір сөздің мақсаты","songNumber":"18"},{"id":783,"title":"Әрдайым қасымда боласың Сен","text":"[Куплет 1]\n//  Әрдайым қасымда боласың Сен,\nСен мені қорғап, мәңгі қолдайсың.\nКиелі Рухыңмен мені жетелеп,\nМәңгі өмірге құшақ жайып шақырасың.  //\n\n[Припев 1]\n//  Келіңдер Жаратқан Иеге арнап,\nӘндетейік қуана жырлап.\nБи билеп те Оны мадақтап,\nАттанайық мәңгілікке Исамен!  //\n\n[Бридж 1]\nШат - тана! O-o-o-o-o!\nШат - тана! O-o-o-o-o!","songNumber":"19"},{"id":790,"title":"Әрдайым қуаныңдар","text":"[Куплет 1]\nӘрдайым қуаныңдар,\nТағы да қуаныңдар.\n// Еш нәрсені уайымдамай\nТәңірді мадақтаңдар. //\n\n[Припев 1]\n// Қуаныңдар, қуаныңдар!\nТағы да қуаныңдар!\nҚуаныңдар, қуаныңдар!\nИемізге қуаныңдар. //\n\n[Куплет 2]\nӨздеріңе сонда Құдай\nТыныштық сыйлайды.\n// Ақыл менен ойларыңды\nИса Мәсіхте сақтайды. //","songNumber":"21"},{"id":151,"title":"Әрдайым қуанып жүріңдер шаттанып","text":"[Куплет 1]\nӘрдайым қуанып жүріңдер шаттанып,\nЖүрек сырын Тәңірге бірге ақтарып.\nБақытты болайық отырған бәріміз,\nКөкке жетсін бірігіп салған әніміз.\n\n[Припев 1]\nЖұмақтың гүлін терейік,\nШын жүректен Исаға келейік.\nЖұмақ кілті тек Соның қолында,\nЖүрейік күмәнсіз соңында.\n\n[Куплет 2]\nБір-біріңді ұғынып сыйлап өтіңдер,\nЖұмаққа қол ұстасып бірге жетіңдер.\nСүйіспеншіліктерің шынайы болсын,\nБастарыңа кетпейтіндей бақыт қонсын.\n\n[Куплет 3]\nҚұтты болсын бас қосқан осы тойларың,\nБірге болсын бар кезде арман, ойларың.\nСәт сапар тілейміз, оң болсын жолдарың,\nЖазылмасын мықты ұстаған қолдарың.","songNumber":"207"},{"id":1001,"title":"Әр жаңа күнде","text":"[Куплет 1]\nӘр жаңа күнде Сені көремін,\nБар жаратылыс Сені бейнелейді.\nӨз күшіммен жете алмаймын мейіріміңе\nБұзылмайтын Келісіміңді менмен бекіттің\n\n[Припев 1]\nАйтқым келеді тек қана\nӘн айтады менің жаным.\nАлғыс Саған сүйгеніңе мені Әке!\nСен рақымыңды төгесің\nШөл далада бақ жасайсың,\nАлғыс Саған сүйгеніңе мені Әке!\n\n[Куплет 2]\nӘр жаңа күнде Сені естимін,\nМені шақырасың Өз тыныштығыңа\nАдалдығың Сенің қажетті маған\nЖүрек тынышталады сенімділікте.\n\n[Припев 2]\nАйтқым келеді тек қана\nӘн айтады менің жаным.\nАлғыс Саған сүйгеніңе мені Әке!\nСен рақымыңды төгесің\nШөл далада бақ жасайсың,\nАлғыс Саған сүйгеніңе мені Әке!\n\n[Припев 3]\nСенің ойың ең жоғары\nСенің жоспарың таңқалдырады\nАспан жерден биіктесе\nӨз еркіңді Сен орындайсың."},{"id":511,"title":"Әр күнде Иені дәріптейік","text":"[Куплет 1]\nӘр күнде Иені дәріптейік\nДауыстап Оған алғыс берейік\nМадақтаймыз Оның ғажап істерін\n\n[Припев 1]\nБүкіл жаныммен Сені сүйемін\nОсы әнді Саған Иса арнаймын\nӨз өмірімді, әрбір күнімді\nИса Саған мен бағыштаймын!\n\n[Куплет 2]\n// Оның салтанатын әндетейік\nОның соңынан жүріп ерейік\nМадақтаймыз Оның ғажап істерін! //\n\n[Бридж 1]\n// Иса Саған алғыс айтам!\nИса Саған алғыс айтам!\nИса Саған алғыс айтам! //"},{"id":299,"title":"Әр күнде Иса маған қажетсің","text":"[Куплет 1]\nӘр күнде, Иса маған қажетсің,\nӘр-бір сәтте, өмірімде.\nКиелі-Сенің қасыңда болғым келеді,\nҚұшағыңа, мені алшы!\n\n[Припев 1]\nТәңірім-Сені мадақтаймын, жүзіңді аңсаймын,\nСен-жалғыз, Сен-маған қажетсің!\nӘр күнде мен, табынамын, өзімді арнаймын,\nСен-жалғыз, Сен-маған қажетсің!\n\n[Бридж 1]\nИса-жалғыз, Сен-маған,қажетсің!"},{"id":15,"title":"Әркімдер-ақ сұрап жүр Ғайса кім деп","text":"[Куплет 1]\nӘркімдер-ақ сұрап жүр Ғайса кім деп,\nКейбіреулер: пайғамбар - Ғайса демек.\nАшылмайтын бұл әлі құпия сыр,\nСондықтан түсіндірме бергенім жоқ.\n\n[Куплет 2]\nЕгерде бәріне айтсам Ғайса - Сол деп,\nНайза ұшында өлтірер мені түйреп.\nЖемтігімді көмуге бермей рұқсат,\nӨлімтіктей тастар еді итке сүйреп.\n\n[Куплет 3]\nҒайсаның туы айтады: бері жүр деп,\nСенбейтін кейбіреулер Оған күлмек.\nҒасыр бойы алысқан дұшпандары,\nМаңдайыма дақ салмас Оны күндеп.\n\n[Куплет 4]\nҰстара Ғайса тілі, әділ тілмек,\nАсауды жуасытар тірі жүндеп.\nҚиянатшыл замандар өтсе дағы,\nҒайса жолы мәңгілік өмір сүрмек.","songNumber":"103"},{"id":891,"title":"Әсем Әуен","text":"[Куплет 1]\nО,Құдай қарашы маған\nЖаным ұмтылады Саған\nСаған арнап,мен ән айтам\nОян жаным,оян рухым\nТыңдашы жүректің үнін\nТән сәріде Сені мадақтаймын\n\n[Припев 1]\n//  Әсем әуен! Әсем әуен!\nТәңірге - әсем әуен!\nИса! Иса! Иса - әнімсің Сен! //"},{"id":216,"title":"Байлығым менің мәңгілік","text":"[Куплет 1]\nБайлығым менің мәңгілік\nАйтамын оны ән қылып.\nҚұдайдан келген қуаныш\nЖүректі барады жандырып\n\n[Куплет 2]\nАрманға жеткен - көңілім көктем,\nӨміріме жоқ менің өкпем.\nЖайнаған күндей - айналам гүлдей\nҚұлпырады бағым бүгінде"},{"id":334,"title":"Бақытты","text":"[Куплет 1]\nБақытты Сенің үйіңде,\nМадақтаған тек Сені.\nБақытты жүрегін арнап,\nБағыттаған әр адам.\nКүш-қуат толтырасың,\nКездескенше Өзіңмен.\n\n[Куплет 2]\nТыңдашы, о, Құдай Иеміз,\nЖарылқашы біздің жерді,\nӨтінеміз.\n\n[Бридж 1]\n//// Киелісің Сен!\nКиелісің Сен!\nКиелі Құдайсың! ////","songNumber":"23"},{"id":884,"title":"Бақытты Құдай алдында құр алақан тұрған","text":"[Куплет 1]\nБақытты Құдай алдында құр алақан тұрған,\nПатшалығы Құдайдың тек соларға арналған.\nБақытты шындық, әділдік үшін қудаланған,\nҚұдай патшалығы тек сондайларға арналған.\nБақытты күнәларына өкініп қайғырған,\nОларды Құдай Өзі жұбататын болады.\nБақытты өмірінде кішіпейілді болған,\nСондайлар Құдайдан қанағат табатын болады.\n\n[Припев 1]\n// Су жағасындағы жайқалған ағашқа ұқсайды,\nЖасыл жапырақтары сарғаймайды, түспейді.\nОлар өз уақытында жемістерін береді.\n//  Не істесе де табыссыз // ол қалмайды. //\n\n[Куплет 2]\nБақытты әділет аңсап жүріп зарыққан,\nСондайлар Құдайдан қанағат табатын болады.\nБақытты бар тірі жанға мейірімді болған,\nҚұдайдың мейірімі тек сондайларға түседі.\nБақытты шынымен жүректері таза болған,\nСондайлардың бәрі Құдайды көретін болады.\nБақытты Құдаймен татуластырып жүргендер,\nОндайлар Құдайдың рухани баласы болады."},{"id":475,"title":"Бақытты өмір бір Сенде","text":"[Куплет 1]\nБақытты өмір бір Сенде,\nАдасып жүрген кезде\nОйламаған бір жол бастадым.\nЖақыным болды бір дос\nӨмірімді өзгертті.\nРизашылығым шексіз Оған.\n\n[Припев 1]\nАлғыс Саған, алғыс Саған\nҚұдайдың құрбандық тоқтысы.\nАлғыс Саған, алғыс Саған\nМәңгілік Саған мен ризамын.","songNumber":"28"},{"id":763,"title":"Балапаным, қайырлы түн!","text":"[Куплет 1]\nБалапаным, қайырлы түн!\nМұнда қорғайды сені Құдай.\nЖайлы жатып жақсы тұр!"},{"id":363,"title":"Бал бөбектің аралы бұл","text":"[Куплет 1]\nБал бөбектің аралы бұл,\nКәусар Нұрдан жаралған.\n// Шапалақтап шақырады,\nБала көктем алыстан. //\n\n[Куплет 2]\nШарапаты, сәулесі мол,\nӘсем қала, нұр қала.\n// Исаменен шаттанады,\nҚуанышпен сан бала. //","songNumber":"228"},{"id":307,"title":"Балық суда","text":"[Куплет 1]\nБалық - суда, құстар - көкте,\nБұғы - тауда, гүлдер - далада.\n\n[Припев 1]\n// Құтқарушы сүйеді бәрін\nОл бізді, балаларды да! //\n\n[Куплет 2]\nҚытай мен қазақты да, Үнді мен полякты да,\nАғын да, қарасын да, Қабылдайды ұясына.\n\n[Куплет 3]\nТыңдашы досым! Құдай сені сүйеді,\nҚұшағын жайып, Күнде күтеді.","songNumber":"229"},{"id":240,"title":"Балық суда жүзе бер","text":"[Куплет 1]\nБалық суда жүзе бер,\nҚұдай сені жаратты.\nБалық тез жүзе бер,\nҚұдай саған қуанды."},{"id":794,"title":"Бар арманға жеткізіп","text":"[Куплет 1]\nБар арманға жеткізіп, барлығынан өткізіп,\nСынақтан төзімділікке.\nҚасиетке толтырып, Құдай қасиетіне,\nЖерден көкке көтеріліп.\n\n[Припев 1]\n// Кел бауырлар келіңдер,\nКереметтерді көріңдер.\nЖаңа өмірдің бастауы,\nИса Мәсіхке сеніңдер. //\n/// Нағыз бақыт Исада ///\n\n[Куплет 2]\nЖанат бақыт күшпенен, сенімнен алынады.\nБәрін тек сенген алады,\nЖасын төккен жолында, қуанышпен орады.\nЖемістерн ол алады.\n\n[Куплет 3]\nБақыт жолын қуғандар, Мәсіхтен тек таймаңдар.\nСоңына дейін шыдаңдар.\nМұраны иемденіп, құр алақан қалмаңдар.\nМұрагері атаныңдар."},{"id":1013,"title":"Бар арманым менің","text":"[Куплет 1]\nҚуантуды, Сені Иса мен қалаймын\nТәнімді Құдайым Сен жаңартшы.\nО, Тәңір, бас июді армандаймын,\nМахаббат нұрын көрсету үшін.\n\n[Припев 1]\nБар арманым менің бұл әлемде -\nҚуаныш болу Тәңірге.\nБар арманым менің бұл әлемде -\nҚуаныш болу Тәңірге.\n\n[Куплет 2]\nКішіпейіл боп Сені мен шақырамын,\nЖаным мен жүрегімді тазартшы.\nҚұдайым, Саған мен жалынамын\nТағыңа Сен жол көрсетші.","songNumber":"106"},{"id":822,"title":"Бар әлемді жаратқан Құдіретті Құдай","text":"[Куплет 1]\nБар әлемді жаратқан Құдіретті Құдай\nЖалғыз Өзің өмірімді менің өзгерттің.\nМахаббатың мен сыйыңды шексіз мәңгілік,\nКеледі енді Тәңірім мен жыр еткім.\n\n[Припев 1]\nАтыңды Тәңірім мен даңқтаймын!\nБасымды Саған ғана шын иемін.\nӨмір мен сүюдің көзісің Сен,\nҚабыл ал дұғамды сиынам мен.\n\n[Куплет 2]\nБар әлемді жаратқан Құдіретті Құдай\nСенсің маған түнекте жарық сыйлаған.\nМахаббатыңды жаныма менің сездірген,\nҚызмет етемін шын жүрекпен тек Саған.","songNumber":"29"},{"id":835,"title":"Бар әлемді жаратқан құдіретті Құдай","text":"[Куплет 1]\nБар әлемді жаратқан, Құдіретті Құдай\nЖалғыз Өзің өмірімді менің өзгерттің.\nМәңгі жырлаймын енді Сенің ұлы ісіңді\nСенің шексіз рақымыңды маған сыйлаған.\n\n[Припев 1]\nСаған Құдай, мадақ пен даңқ болсын,\nБасымды Саған ғана иемін.\nСаған Құдай өмірім арналсын,\nҚабыл ал, дұғамды сиынам мен.\n\n[Куплет 2]\nБар әлемді жаратқан, Құдіретті Құдай!\nСенсің маған түнекте жарық сыйлаған\nШексіз мейіріміңді жүрекке сездірдің,\nҚызмет етемін шын жүрекпен тек Саған!"},{"id":367,"title":"Бар әлемді Сен өтедің","text":"[Куплет 1]\nБар әлемді Сен өтедің\nБердің махаббат пен жарық\nТастай жүректі жібітіп\nСен үміт бердің\n\n[Куплет 2]\nСенің алдыңда біз тұрмыз\nБәріміз Саған қымбатпыз\nБәріне Саған ризамыз\nО, Құдайым\n\n[Припев 1]\nМадақтаймын Сені табынамын\nМадақтайды Сені мәңгі елім\nКүшің шексіз Құдайым\nРақымың ұрпақтан - ұрпақтарға","alternateTitle":"Әлемді Сен құтқардың"},{"id":416,"title":"Бар әлем жырлаңдар Иеңді шаттанып","text":"[Куплет 1]\nБар әлем жырлаңдар Иені шаттанып\nИеңе қызмет ет қуанып\n// Келіңдер Құдайға да ұстасайық\nТанып ап Иең деп Құдайды //\n\n[Куплет 2]\nОл бізді жаратқан\nҮндет ал халқым Құдайдан\n// Қамқоршы-ау Ол бізге\nШопан да отарын бағатын //\n\n[Куплет 3]\nАлғысты айтыңдар қақпадан өткенде\nМадақтап алаңға кіріңдер\n// Алғысты айтыңдар Құдайға\nМадақтаңдар Тәңірдің есімін //\n\n[Куплет 4]\nИеміз мейірімді\nМәңгіге рақым етеді\nҰрпақтан ұрпаққа біздерге\nАдал боп қала береді"},{"id":676,"title":"Бар біздің Құдай","text":"[Куплет 1]\nДүниені әуел бастан жаратқан\nЖаратушы неге жоқ дейсің\nБар бар бар біздің Құдай\nАспандағы Құдай Әке бар\nКүнәҺар дүниені құтқарған\nҚұтқарушы неге жоқ дейсің"},{"id":567,"title":"Бар күнәларымды Құдай кешірді","text":"[Куплет 1]\nБар күнәларымды // Құдай кешірді // ,\nБар күнәларымды Құдай кешірді,\nИса Мәсіх арқылы.\n\n[Куплет 2]\nҚуанышқа толды // менің жүрегім // ,\nҚуанышқа толды менің жүрегім,\nИса Мәсіх арқылы.\n\n[Куплет 3]\nБіз бірге Тәңірге // ән саламыз // ,\nБіз бірге Тәңірге ән саламыз,\nИса Мәсіх арқылы.","songNumber":"230"},{"id":88,"title":"Бар күшімді","text":"[Куплет 1]\nБар күшімді салып Жүлдеге ұмтылам\nМендегінің бәрі\nОған арналады\nЕшкімде ешқашан\nЖоспарыңнан Сенің\nАйыра алмайды мені\nНық білемін\nМендегі Біреу осы өмірден\nӘлде қайда күшті.\n\n[Припев 1]\nЕнді тауды да қозғалтамын\nМәсіхпен бәрі мүмкін. Білемін.\nЕнді мықты мен тұраламын\nТәңір нығайтады мені\n\n[Припев 2]\nБәрі мүмкін.\nСенімен бәрі мүмкін\n///  Мендегі Біреу осы өмірден\nӘлде қайда күшті ///"},{"id":20,"title":"Барлық аспан","text":"[Куплет 1]\nБарлық аспан атыңды мадақтайды Ием.\nСенің көркің немен теңеседі екен.\n\n[Припев 1]\n//  Мәңгі отырасың (Мәңгі отырасың)\nЖарқыраған тақта. (Жарқыраған тақта.)\nТек Сенің алдыңда (Тек Сенің алдыңда)\nТізе бүгемін мен !  //\n\n[Куплет 2]\nМадақтаймын Сенің даңқыңды жан Ием,\nСен біз үшін өміріңді құрбан еттің.\n\n[Куплет 3]\nАялаймын Сенің Сөзіңді жан Ием.\nЖаратушым, бір Өзіңе дұға етем.","songNumber":"40","copyright":"1987 Танкыоу Мусик"},{"id":538,"title":"Барлық кезде","text":"[Куплет 1]\nБарлық кезде, сыйыну деймін,\nҚуанышқа бөленемін!\nМаған бақыт, өмір беріп Ол жетелейді!\nКөмектеседі, жәрдем береді!\nҚұдай еркін орындауды үйренемін,\nОрындаймын мен Құдай еркін!"},{"id":708,"title":"Барлық күштерден биіксің","text":"[Куплет 1]\nБарлық күштерден биіксің,\nЖаратылыстардан, табиғаттардан.\nЖоғары бүкіл ақылдан, даналықтан.\nПатшалардың Патшасы Сен!\n\n[Куплет 2]\nАтақтан, даңқтардан Ол жоғары,\nЖоғары ғажаптардан адамзат көрген.\nЖер бетіндегі зор байлықтан жоғары,\nТеңдесі жоқ мейірім берген!\n\n[Припев 1]\nАяусыз айқышқа таңдырды,\nӘкесі бас тартып қалдырды.\nРаушандай жерге тапталған,\nБар күнәмнан ақтаған,\nОл Жоғары!","songNumber":"17"},{"id":985,"title":"Бар тілек арманым жүректе","text":"[Куплет 1]\nБар тілек арманым Жүректе орын алғаны\nӨмірде мәнсіз қалары айқын,\nБұл жалғанның мансабы\nТолассыз бітпес азабы.\nБір күн күлге айналады, бәлкім\n\n[Припев 1]\nСонда мен қол жайып, Көктегі Құдайға\nКелуін күте аңсаймын,\nИемді мен мадақтаймын.\nӨмір жолында қиын болса да,\nКүтуден Оны талмаймын.\nМәңгі мадақтаймын Құдайды\nОл жанымда, үнемі бол менің жанымда\nӨзімді саған арнаймын, жүректі кірден сақтаймын.\nОл жанымда тыныштық береді жаныма\nИемді мен мадақтаймын өтініп сұраймын\nБолшы қасымда, бол //  жанымда //\n\n[Куплет 2]\nҚай бағыт-бағдар жолыма сәуле шашады,\nАлдыға қадам басамын, әлсіз.\nЖалына Исаны жанымда бол деп сұраймын,\nОнысыз бұл жалғанның бәрі мәнсіз."},{"id":964,"title":"Бартімей енді соқыр емес","text":"[Куплет 1]\nБартімей енді соқыр емес!\nИса оның көзін ашты ғой.\nБартімей енді соқыр емес!\nОл бәрін анық көреді."},{"id":178,"title":"Бар халықтар келіңдер","text":"[Куплет 1]\nБар халықтар келіңдер,\nМадақтауға Иемізді.\nОл лайықты барлық мадаққа,\nТек Ол лайықты барлық мадаққа.\nИеміздің даңқың біз,\nЖар саламыз бүкіл әлемге.\nОның даңқың жар саламыз біз,\nТек Оның даңқын жар саламыз біз.\n\n[Припев 1]\nИсаның даңқы ең биік\nОған ешкім жете алмас\nОл ғажайып.\nОл біздің Иеміз"},{"id":911,"title":"Бар халықты құдай сүйеді","text":"[Куплет 1]\nБар халықты құдай сүйеді\nНеге білемісің?\nШақырады сені күтеді\nСоны сеземісің?\n\n[Припев 1]\nМейірімі мол, кешіреді Ол,\nМәңгі қуанышқа, бөлейді бізді,\nРақымы да мол, түсінеді Ол,\nӨмір бойы сүйіп өтеді сізді!\nМейірімі мол, кешіреді Ол, бізді!\n\n[Куплет 2]\nМахаббатын сонда білерсің,\nНұрға бөленсең!\nШындық сені мәңгі қорғайды,\nСоңынан ерсең!\n\n[Куплет 3]\nБақыт деген осы бағытта,\nСөзіме сенші!\nКөп кешікпей жан достарыңды,\nШақырып келші!","alternateTitle":"Мейірімі мол Тәңір"},{"id":904,"title":"Басымды иіп алдыңа","text":"[Куплет 1]\nБасымды иіп алдыңа, тәубе етіп жүр едім.\nОрындалды тілегім, жарылардай жүрегім.\nСенсіз жүріп Құдайым, қиналушы ем ұдайы.\nСол күндерге кешірім, жүрегіммен сұраймын!\n\n[Припев 1]\n// Қазақстанның бар халқы\nДұға етсін бауырға,\nБарлық халық бір болып,\nТой болсыншы қауымда! //\n\n[Куплет 2]\nТіл жетпейді айтуға, Иса Саған рахмет\nДаналық бер халқыма, әр пенденді әділ ет.\nЖамандықты жоқ қылып,дұшпандарды әлсіз ет.\nРухыңнан айналдым, Киелі Иса Назарет!\n\n[Припев 2]\nҚазақстанның бар халқы\nДұға етсін бауырға\nБарлық халық бір болып\nТой болсыншы қауымда!\nОсы жолдан таймандар\nЕртең бәрін білесің\nБар күнәннан айырылып,\nПеріштедей жүресің!"},{"id":378,"title":"Батаңды бер екі жасқа Тәңірім","text":"[Куплет 1]\nБатаңды бер екі жасқа Тәңірім,\nҚол ұстасқан Сенің мәңгі жолыңда!\nАқ батаңмен алға қарай жетеле,\nТілектері болсын Сенің еркіңде!\n\n[Куплет 2]\nҚасиетті қоллдарыңмен бағыттап,\nСақтай гөр, оларды, өмір өткелдерінде!\nАқ батаңмен сүйемелдеп қорғаштап\nКөмекке кел азап-қайғы шеккенде!\n\n[Куплет 3]\nЖақындарына төк мейіріміңді,\nҚұтқаруға әкелші Сен оларды.\nЖарияланған бұл Ізгі хабарың,\nОлардың да жүректерін жібітсін.\n\n[Куплет 4]\nҚұдай Сөзін естігенде халайық,\nАдам жақсы мәңгі өмірге лайық.\nСау адамның мойындауы күнәңді,\nҚабылдуы Иса сыйлар өмірді."},{"id":869,"title":"Батырдай күшті Сенің бейнең бар","text":"[Куплет 1]\n//  Батырдай күшті Сенің бейнең бар,\nГүлден де нәзік, Әке сенің мінезің,\nСен үшін қымбат бүкіл адамзат,\nҚымбат қой Әке, Сенің бізді сүйгенің! //\n\n[Припев 1]\n//  Жарылқауды Иса Мәсіхпен бердің,\nЖүректерді толтырдың, қуаныш пен алғысқа!\nЖарылқауды Иса Мәсіхпен бердің,\nЖүректерді толтырдың, жарылқау мен батаға! //\n\n[Куплет 2]\n// Алғыс айтамыз Әке Өзіңе,\nБатаңды беріп, жібердің осы өмірге!\nЖолды түзетіп, Өзіңе қарай,\nБалаларыңды жетелейсің мәңгіге! //"},{"id":1016,"title":"Бауырым айқыш ағашқа қара","text":"[Куплет 1]\nБауырым,айқыш ағашқа қара,\nСен үшін, Құдай-Иса,құрбан болды!\nӨмірін-Ол, сен үшін қиды, сен үшін!\nКүнәдан Ол тазартты, ақтады, босатты!\nӨмірін-Иса, тек сен үшін қиды,\nКүнәдан, Ол тазартты сені!\n\n[Припев 1]\nКөзіңді көтер, Айқыш ағашқа!\nИудейдің Патшасы, әлемнің Патшасы!\nСенің Патшаң-құрбан болды!\nИса - Өз қанын төкті,\nАйқыш ағаш арқылы, саған өмір берді!\n\n[Куплет 2]\nБар әлем, күнәға батып, шаршаған,\nТүнекте, жүріп, шындық жолдан, адасқан.\nӨмірін-Иса, тек сен үшін қиды,\nКүнәдан, Ол тазартты , ақтады, босатты\nӨмірін-Иса, тек сен үшін қиды,\nКүнәдән, Ол тазартты сені!","alternateTitle":"Көзіңді көтер айқыш ағашқа"},{"id":507,"title":"Бауырым бет бұрайық","text":"[Куплет 1]\nБауырым бет бұрайық Құдайға,\nБауырым бірге өмір бастаған.\nБауырым жастай күліп ойнаған,\nБауырым жастық кезде бір болған.\n\n[Припев 1]\nҚұдіретті Құдай бар,\nҚұтқаратын Құдай бар.\nОның Аты Киелі,\nОның Аты құтқарады.\n\n[Припев 2]\n// Құдайсыз адам қасірет шегеді,\nҚұдайсыз адам аброй төгеді.\nҚұдайсыз адам жалғыз боп келеді,\nҚұдайсыз өлім көреді. //\n\n[Куплет 2]\nБауырым өмір беретін Құдай,\nБауырым Иса арқылы саған.\nБауырым басқа бір де бір адам,\nБауырым сені құтқара алмайды.\n\n[Припев 3]\nКеліп таяп келеді Ол,\nЖер жүзін Құтқарады Ием.\nТез тізе бүгіп біз Оған,\nЖүректен орын берейік."},{"id":1006,"title":"Бәрі де жақсы болады","text":"[Припев 1]\n//  Бәрі де жақсы болады,\nӘрдайым Сен қасымда ,\nИса - Тәңірім!\nМен сенемін Сен жетелейсің мені! //\n\n[Куплет 1]\n//  Нұрсың Сен өмірімде,\nЕң жақын жүрегіме,\nБақытсыздықтан бізді сақтайсын,\nӘркезде бізбен бірге! //\n\n[Припев 2]\n// Бәрі де жақсы болады,\nӘрдайым Сен қасымда ,\nИса - Тәңірім!\nМен сенемін Сен жетелейсің мені! //\n\n[Бридж 1]\n//  Менің атым мәңгі - Өмір Кітабында,\nЖазылды мен сенемін!\nБүкіл әлем шайқалса да,\nИса Тәңір - менің тірегім! //","alternateTitle":"Нұрсың Сен өмірімде"},{"id":1025,"title":"Бәрі жақсы болып көрінді","text":"[Куплет 1]\nБәрі жақсы болып көрінді,\nБәрі жақсы болып сезілді.\nӨткізген мынау күндерім,\nНе жақсылық әкелді?\n\n[Припев 1]\nБіреулер іздейді байлықты\nБайлықтан іздейді бақытты.\nМынау жалған дүниеде\nІздеумен өтер уақытты.\n\n[Куплет 2]\nЕң жақсысы өмірдің\nҚұдайға ғана бағыну.\nМойынсұнып әрқашан\nШын жүректен табыну.\n\n[Куплет 3]\nКөзімізді ашайық,\nАяқты нық басайық.\nҚұдай Сөзімен сергек боп\nИсаның келуін тосайық.\n\n[Куплет 4]\nМәңгілік қамқор Құдайың\nБір өзіңе жар екен.\nБұдан асқан тыныштық\nБақытты өмір бар ма екен?","songNumber":"27","alternateTitle":"Жалған байлық"},{"id":145,"title":"Бәріміз бірге Әкеміздің үйінде","text":"[Куплет 1]\n/// Бәріміз бірге, бірге болайық\nИсаның денесінен ажырамайық! ///\n/// Бәріміз бірге, Әкеміздің үйінде,\nӨмір сүрейік бір-бірімізді сүйіп! ///\n/// Кел кел табарсың, жүрегіңнің панасын.\nКел ер соңымнан, Иса жолы шындық жол ///"},{"id":320,"title":"Бәріміз бірге болғанда!","text":"[Куплет 1]\nБәріміз бірге болғанда қуанамыз,\nБәріміз бірге болғанда бақыттымыз.\nАйжан келгенің жақсы, Иса сені сүйеді,\nБәріміз бірге болғанда бақыттымыз."},{"id":628,"title":"Бәрін де білесің Құдайым менің","text":"[Куплет 1]\nСаған теңдей нұрлы әндетеміз,\nШарықтайды әнде түнекте Өзіңе.\nСенен жасыра алмай мен ештеңені,\nБәрінде көресің, бәрінде сезесің,\nБәрінде білесің Құдайым менің.\n\n[Припев 1]\nКеремет ғажап жасаған істерің,\nМұны мен шын жүректен мойындаймын.\nСені мақтаймын, тамаша жаралдым,\nМұны мен шын жүректен мойындаймын.\nНа-на-на-на-на\n\n[Куплет 2]\nСенің бар ойларың маған жоғары,\nАқылыңда қаншама олардың саны.\nСанап шықсам барлық ой жоспарыңды,\nҒылым саны жетпейді, ойымнан кетпейді,\nКеремет істерің Құдайым менің."},{"id":899,"title":"Бәрің, бәрің келіңдер","text":"[Куплет 1]\nБәрің, бәрің келіңдер,\nБұл ғажапты көріңдер,\nМәсіх келді дүниеге!\nАлақай ау, алақай!\n\n[Припев 1]\nЛя- Ля- Ля- Ля- Ля- Ля!\nЛя- Ля- Ля!\nҚуанамыз Исаға!\n\n[Куплет 2]\nБәрің, бәрің шаттана,\nӘн салыңдар шарықтап,\nИсаға қуанамыз, алақай-ау, алақай!\n\n[Куплет 3]\nЖарық жұлдыз көрінді,\nҚұтқарушы Мәсіхте,\nТәңір жерге жіберді, алақай-ау, алақай!","songNumber":"231"},{"id":769,"title":"Бәрі Одан","text":"[Куплет 1]\nБәрі Одан,\nОл бәрін жаратты.\nБәрі Одан,\nОл бәрін жаратты.\n\n[Припев 1]\nБәрі үшін Оған даңқ!\nБәрі үшін Оған даңқ!\nБәрі үшін Оған даңқ!\nМәңгіге аумин!\n\n[Куплет 2]\nТүпсіз тұңғиық - Мәсіх даналығы.\nТылсым құпия - Тәңір жолдары.\n\n[Куплет 3]\nО, Иса, азап шектің біз үшін.\nМәсіх, өлімнен бізді құтқардың.\n\n[Припев 2]\nБәрі үшін Саған даңқ!\nБәрі үшін Саған даңқ!\nБәрі үшін Саған даңқ!\nМәңгіге аумин!","songNumber":"25"},{"id":602,"title":"Бәрі тыныш, әлем ұйықтап жатқанда","text":"[Куплет 1]\nБәрі тыныш, әлем ұйықтап жатқанда,\nЖарық ай, тып-тынық түн далада.\nБұл дүниеге Құтқарушым шырылдап,\nКелді, міне, қуанышқа кенелтіп.\n\n[Припев 1]\n// Қуаныңдар, қуаныңдар, қуаныңдар!\nПәк Нәресте - Иса келді дүниеге,\nҚұтқаруға бәрімізді күнәдан. //\n\n[Куплет 2]\nБәрі тыныш, әлем ұйықтап жатқанда,\nТәңіріміз бүгін бізді жарылқады.\nҚуаныштан жүрегіміз ән салып,\nИса Мәсіх, Саған бола шаттанып.","songNumber":"160"},{"id":784,"title":"Бейбітшілік орнасын елімізде","text":"[Куплет 1]\nБейбітшілік орнасын елімізде,\nБарлық ұлттар бірігіп жерімізде.\nТуысқандай өмір сүр бауырларым,\nДостық болсын мәңгілік төрімізде.\n\n[Припев 1]\nНиетіміз ақ болсын,\nхалқымызға бақ қонсын.\nБата беріп сақ қылсын Жаратқан Ие.\nҰмытпаңдар достарым,\nүлкен кіші жастарым.\nБұл өмірде шындық жол Иса Мәсіхте.\n\n[Куплет 2]\nБірігумен жеңейік жамандықты,\nКүнәларға теңейік надандықты.\nБілім алып, көркейіп жетілейік,\nСонда ғана білеміз бар шындықты.\n\n[Куплет 3]\nҚалайды Ол осы жолда жүргеніңді,\nҚуанышқа кенеліп күлгеніңді.\nӨсиеттерін орындап қызмет етіп.\nАдал болып ұзақ өмір сүргеніңді.","songNumber":"30"},{"id":589,"title":"Берген уәдесі мәңгі болады","text":"[Куплет 1]\nБерген уәдесі мәңгі болады,\nИсаның қаны оны растайды.\nТүңілсең де, сен үмітіңді үзбе,\nҚұдай сертінен таймайды.\n\n[Припев 1]\nӨмірде бәрі жойылсын мейлі:\nУәдесін Құдай орындайды.\nКөк аспандағы жұлдыз сөнсе де,\nУәдесінде Ол тұрады.\n\n[Куплет 2]\nАзап шеккенде, қараңғы түнде,\nЖүрекке уайым-қайғы түскенде,\nЖанымды күмән абыржытпайды:\nҚұдай сертінен таймайды.\n\n[Куплет 3]\nӨмір сынағы өршеленсе де,\nҚанның жігері күш берер бізге.\nҚуанып сонда мен мадақтаймын,\nҚұдай сертінен таймайды.\n\n[Куплет 4]\nТіріліп қайта көкке кетеміз,\nОнда періште бізді күтеді,\nЖеңіс гүл тәжін аламыз сонда:\nҚұдай сертінен таймайды.","songNumber":"148"},{"id":333,"title":"Берік тұрамын","text":"[Куплет 1]\nБерік тұрамын мен Исаның Атымен.\nОның берген билігімен\nБерік тұрамын мен.\n\n[Припев 1]\nМаған дұшпан келсе де,\nМүлде құлап қалмаймын.\n    Оның берген билігімен\n    Оның берген билігімен\n    Оның берген билігімен\nБерік тұрам.","songNumber":"26"},{"id":555,"title":"Бесік жоқ бұл жерде","text":"[Куплет 1]\nБесік жоқ бұл жерде,Астаудан басқа.\nИеміз Иса, ұйықтап жатыр онда!\nАспан жұлдыздары да,таң қалуда,\nСабан төсеп жатқан,Ием Исаға!\n\n[Куплет 2]\nМал маңырап,Нәресте оянды,\nБірақ жас Иеміз,еш жыламапты,\nИеміз Иса,Сен қарашы маған,\nТұршы бесігімнің,қасында менің!\n\n[Куплет 3]\nИем Иса, болшы менің қасымда,\nДұға етем Саған, тастама мені!\nБатаңды берші барлық балаларға,\nБолайықшы мәңгі, Сенімен бірге!"},{"id":629,"title":"Бетлехем деген елдің шығысынан","text":"[Куплет 1]\nБетлехем деген елдің шығысынан,\nЖарық жұлдыз малшыларға көрініпті.\nСол жерде туылды Иса Мәсіх\nКөктен жерге періште әні төгілді.\n\n[Предприпев 1]\nСәби жатыр анасының құшағында\nАл Мариям үнсіз егіліп бір жылады.\nКішкентай Сәби жатыр тәттә ұйқыда\nАлдыда Оны қиындықтар күтеді.\n\n[Припев 1]\nҰйықтауда Нәресте сені не күтіп тұр\nАнасының киелі ақ сүтінен еміп.\nҚұтқаруға келіп күнәлардан елді\nҚайғыға батарсың халықтан жәбір көріп.\n\n[Куплет 2]\nЕлінде бейбітшілік пен тыныштықтың\nНұрланып бой көтерер Сенің мекенің\nО, Иса, күтеді Сені мол азаптар\nБатады патшаларға Құдай екенің.\n\n[Предприпев 2]\nӨзіңді танытып, бар шындықты айтсаң\nКейбіреулер тәубеге келер шыныменен\nБіреулер бас тартып айқышыңнан қашар\nТүсінген табысады Құдай Ұлыменен.\n\n[Припев 2]\nНе күтіп тұр Иса Өзіңді алдыда\nҚұрбан болып білегіңді түріп едің\nӨзіңе сиынып біз сеніп күтеміз\nБіз үшін Сен өліп қайта тірі едің.\n\n[Куплет 3]\nСодан соң қуанышта да, қайғылар да\nҚұдай Ұлы деп қастерледі Өзіңді\nСодан соң Сенен асқан Тәңір бар ма?\nХалық мойындады киелі сөзіңді.\n\n[Припев 3]\nНұры ай-күннен де жап жарық, сәулелі\nБолған Нәресте екен Құтқарушы\nОл бізге көрсетті адаспайтын жолды,\nҚайырымды, рақымды Жан жұрт танушы."},{"id":824,"title":"Билеймін","text":"[Куплет 1]\nМаған деген мейірімің мәңгілік шексіз\nМадақтаймын Атыңды\nСыйладың мәңгілік өмір маған\nҚұтқардың сұм тозақтан\n\n[Припев 1]\nБилеймін билеймін\nҚуанып ән саламын\nБилеймін билеймін\nРиза болып шаттанамын\n\n[Куплет 2]\nАдасып көп жылдар жүрдім мен\nТанымай Өзіңді\nБірақ та Сен мені таңдап алып\nМен сені сүйем дедің\n\n[Куплет 3]\nМен үшін қиналып азапталдың\nЖаныңды қидын Иса\nЖасаған күнәларымды кешіріп\nМен үшін өлімге бардың"},{"id":138,"title":"Билеймін (I will dance)","text":"[Припев 1]\nI will dance, I will dance\nRejoicing I will sing\nI will dance, I will dance\nI will celebrate with joy\n\n[Куплет 1]\nHow amazing Your love for me\nthat will never end\nGlory to Your holy name\nBy Your grace You've given me\neternal life\nAnd saved me from the grasp of hell\n\n[Припев 2]\n// I will dance, I will dance\nRejoicing I will sing\nI will dance, I will dance\nI will celebrate with joy //\n\n[Куплет 2]\nМаған деген мейірімің мәңгілік шексіз\nМадақтаймын Атыңды\nСыйладың мәңгілік өмір маған\nҚұтқардың сұм тозақтан\n\n[Припев 3]\n// Билеймін, билеймін\nҚуанып ән саламын\nБилеймін, билеймін\nРиза болып шаттанамын //\n\n[Куплет 3]\nLord, You had compassion\nfor my soul\nJesus, You gave Your life for me\nCleansing me with Your blood,\nforgiving my sins\nYou died for me but rose again\n\n[Припев 4]\nI will dance, I will dance\nRejoicing I will sing\nI will dance, I will dance\nI will celebrate with joy\nБилеймін, билеймін\nҚуанып ән саламын\nБилеймін, билеймін\nРиза болып шаттанамын"},{"id":474,"title":"Би толтырсын үйімізді","text":"[Куплет 1]\nБи толтырсын үйімізді,\nШаттық кернеп даланы.\nИса алдында бәрі құлап\nТәубеге кеп сиынсын.\n\n[Припев 1]\nАсқар таудан аңғарларға\nСаған мадақ қалықтасын.\nЗаңғар көктен халықтарға\nҒажайып ән құйылсын!\n\n[Куплет 2]\nБіз соңыңнан ерген кезде,\nНұрың түрсін түнекті.\nДаңқың толтырсын ғаламды,\nТасқынындай тірі судың.\n\n[Бридж 1]\nАллелуя! Аллелуя!\nАллелуя! Аллелуя!","songNumber":"28","copyright":"Хиллсонг"},{"id":424,"title":"Биік тауларменен Бақташым келеді","text":"[Куплет 1]\nБиік тауларменен Бақташым келеді,\nТар жолменен қойларын Өзі жетелеп.\n\n[Припев 1]\nМен кішкентай қошақан соңынан еріп,\nТар жолменен Иерусалимге барамын.\n\n[Куплет 2]\nМейірімді Бақташым біздерді сүйіп,\nБағады Ол бәрін де қасына жиып.\n\n[Куплет 3]\nЖаяды көк шалғынға сусынын беріп,\nСоңынан еш қалмаймыз, жүреміз еріп.","songNumber":"232"},{"id":655,"title":"Биіктегі","text":"[Куплет 1]\nМахаббатың теңізден терең,\nМұхиттай шегі жоқ.\nАдалдығың\nТаулардан биік,\nУәделерің берік.\n\n[Припев 1]\nДаңқ Құдайға!\nБәрі жырласын.\nДаңқ Құдайға биіктегі!\n\n[Припев 2]\nДаңқ Құдайға!\nБәрі жырласын.\nДаңқ Құдайға биіктегі!\n\n[Бридж 1]\nАсқақта Сен,\nҚұтқарушымыз!\nМәңгі билік құр, Патшамыз.","songNumber":"27"},{"id":318,"title":"Бозбала шақ өтті енді, кетті сендерден","text":"[Куплет 1]\nБозбала шақ өтті енді, кетті сендерден,\nҚол бұлғайды жаңа өмір, биік белдерден.\n\n[Припев 1]\nҚадамдарың құтты болсын!\nБастарыңа бақыт қонсын!\nЖас отауда бір болыңдар Тәңірмен.\n\n[Куплет 2]\nТәңірдің берген батасын сақтаңдар мәңгі,\nҚос жүрек бірге айтсын таусылмас әнді.\n\n[Куплет 3]\nЖетекші болсын өмірде Жаратқан Өзі,\nЖүректеріңде жазылсын киелі сөзі.","songNumber":"208"},{"id":431,"title":"«Болсын!» десең, әлем болар бұдан басқа","text":"[Куплет 1]\n«Болсын!» десең, әлем болады бұдан басқа,\n«Шықсын!» десең, гүлдер шығады қара тасқа.\nГүлденген жер күлге айналады, теңіз құрғап,\nКенеттен ұлы Құдай қаһарланса.\n\n[Припев 1]\nСиынамыз - бір Құдайға,\nҚорғаушымыз - бір Құдайға,\nСоттаушымыз - бір Құдайға.\n\n[Куплет 2]\nБар әлемді ақиқаттан жаратқансың,\nБас идіріп, бір шындыққа қаратқансың.\nАқырында келеріңді біз білеміз.\nБұл туралы Ізгі хабар таратқансың.\n\n[Куплет 3]\nЖалғыз Өзің жоқ нәрсені бар қыласың,\nӨз еркің ғой, қанша өмір сен сыйлайсың.\nСиынамыз бір Өзіңе Құдай Әке,\nТеңдесі жоқ бір Өзің ғой жалғыз көкте.\n\n[Куплет 4]\nҚол ұсынып, құтқарады азғырудан,\nҚұдай сүйеді, кешікпей кел сиынуға.\nЖаныңды бер, жүрегің бер, ойыңды бер,\nҚұшақ жайып күтіп тұрған бір Құдайға.","songNumber":"22"},{"id":398,"title":"Бұғы қалай","text":"[Куплет 1]\nБұғы қалай мөлдір суды аңсаса,\nМенің жаным да\nСені іздеп шөліркейді,\nТәңір, Сені аңсайды.\n\n[Припев 1]\nҚұдайым, Сен қорғанышым,\nБар үмітім менің бар күшім.\nЖанымды да, өмірімді,\nИем, Өзіңе арнадым.","songNumber":"30","copyright":"1984 Мараната Праисе, Инк."},{"id":689,"title":"Бұл әлемнің бастамасы Өзің болып","text":"[Куплет 1]\nБұл әлемнің бастамасы Өзің болып,\nӘлемнің Ақыры да Сен боласың.\nАспаннан жердегіге қуат беріп,\nАл Өзің кең әлемге құпиясың.\n\n[Припев 1]\nО,Тәңір, бұл әлемнің Патшасы.\nО, Тәңір, бұл әлемнің Қолдаушысы.\nИіліп Саған ғана тағзым етем.\n// О, Тәңір, өмірімнің берекесі. //\n\n[Куплет 2]\nКешір мені, күнәлардан арылайын,\nИса Тәңір Өзіңе мен табынайын.\nҚуаныштан, жұбаныштан көздің жасы\nТөгіледі, Құтқарушым, айналайын.\n\n[Куплет 3]\nӨзің бол мендегі шынайы сенім,\nМәңгілік жүрегімде жаса менің.\nЖаратқан, көрсет енді шындық жолын.\nЖарық көріп Саған келсін қазақ елім.","songNumber":"24"},{"id":809,"title":"Бұл әлемнің шексіз биіктігінде","text":"[Куплет 1]\nБұл әлемнің шексіз биіктігінде,\nЕштеңе жоқ Оның ұлы сүюіндей.\nЖүрегімнің тереңіңде жатқан жарық,\nМәңгілікке сыйлады маған бақыт.\n\n[Припев 1]\nМадақтаңдар, мадақтаңдар!\nКиелі Ұлды, Киелі Ұлды\nТәңіріміз Исаны.\n\n[Куплет 2]\nПеріште үні аспаннан естіледі,\nЖер бетіне жақсы хабар жеткізеді.\nЖарқыраған мына күннің щұғыласы,\nБар әлемнің жер бетіне нұр төгеді.\n\n[Куплет 3]\nМәңгі өмірге жетуге ұмтылайық,\nАдасқандарға да қол ұсынайық,\nСүюіне сүюменен жауап беріп,\nӨзі берген өміріне сай болайық.","songNumber":"42"},{"id":662,"title":"Бұл біздің Құдай","text":"[Куплет 1]\nМаған керегі\nРақымдылық,\nСөзіңе мен сенемін.\nкүтем Сені жақындатшы,\nКиелі Рухыңмен жаңарт.\n\n[Предприпев 1]\nАяғыңа жығылам\nАлдыңда бас ием\nОсы жерде табынам\n\n[Куплет 2]\nЖүрегімдесің,\nжолыма нұр шаш.\nСөздеріңнің күшімен\nҚұн төледің,\nАзат еттің,\nРухыңмен мен азатпын.\n\n[Припев 1]\nӨз еркіңмен бәрін бердің,\nАйқыш ағашта құн төледің.\nМахаббатың\nбізге төктің.\nБіздің Құдай\nӨлімнен өмірге өтті.\nМәңгіге Иеміз дәріптелсін,\nҚұл, Ол - Патша азат етті,\nБіздің Құдай.","songNumber":"32"},{"id":93,"title":"Бұл дүниеде сөзің қымбат өзіме","text":"[Куплет 1]\nІнжіл Сөзің әрқашанда қолымда,\nОқығанда жазылады, жанымда\n// Әр бір сөзің асыл тастай көзіме,\nБұл дүниеде Сөзің қымбат өзіме! //\n\n[Куплет 2]\nКиелі Рух жүрегіме жазады,\nҚұпиясын әке маған ашады,\n// Сөздеріңнің ашылғанда мәнісі,\nНұрын менің жан дүниеме шашады! //\n\n[Куплет 3]\nОқимын мен керек Сөзің жаныма,\nСөздеріңнен шам жанады алдыма.\n// Кітабыңды тастамаймын қолымнан,\nКелемін мен қадам алып жолыма. //\n\n[Куплет 4]\nКиелі кітап толып жатқан құпия-сыр,\nАшып қалсам тасып жатқан тірі су.\n// Ашықтықты күтемін мен Өзіңнен,\nКүш аламын әрбір айтқан Сөзіңнен. //"},{"id":565,"title":"Бұл Құдай жаратты ғой аспан жерді","text":"[Куплет 1]\nБұл Құдай жаратты ғой аспан жерді,\nБұл Құдай жаратты ғой адамзатты\n// Адамдар дүниенің соңына еріп\nАлданып қалған екен өткіншіге! //\n\n[Куплет 2]\nБауырым тұр орныңнан, аш көзіңді\nБіздерді Құтқарушы Мәсіх келді\n// Ол бізбен мәңгі бірге болады екен\nЕгер біз тәубе қылып, барсақ Оған! //\n\n[Куплет 3]\nТәңірім сүйеді екен бізді мәңгі\nӨз қанын төгіп кетті күнәң үшін\n// Біздерді тазалады Ол күнәдан\nҚұтқарды бұл дүниенің азабынан! //\n\n[Куплет 4]\nМәсіғім алғысым көп менің Саған\nСен ашқан жолыңменен барам Саған\n// Қолыңмен жетелеші Құдай Ұлы\nҚұдаймен жарастыршы мәңгі бізді! //\n\n[Куплет 5]\nАдамдар аш көзіңді, көр Құдайды\nБіз үшін жалғыз Ұлын берді Құдай\n// Адамзат көрмейсің бе, Құдай мейірім\nТас болып қалған ба еді жүректерің //"},{"id":90,"title":"Бұл Өмірде","text":"[Куплет 1]\nБұл өмірде Сендей тәңір көрмедім\nМахаббатты дәл осылай сезбедім\nӘр күні Саған келемін\nАтыңды көтеремін\n\n[Припев 1]\nСен Тәңір басқа ешкім жоқ\nСен Тәңір Сені сүйем\n\n[Куплет 2]\nБілемін Сен бәрінен де ғажапсың\nЕң керемет сөздерге Сен лайықсың\nӘр күні Саған келемін\nАтыңды көтеремін"},{"id":936,"title":"Бұл өмірден өтеді екен даналар да","text":"[Куплет 1]\nБұл өмірден өтеді екен даналар да,\nӨтеді екен ақ жаулықты аналар да.\nДүниені дүр сілкінткен патшалар да,\nӨтеді екен асыл сұлу арулар да.\n\n[Припев 1]\n//  Ей, адамдар, ойланыңдар,\nӨткенге көз салыңдар.\nБұл өмірде мәңгі жүрген,\nАйтыңдаршы кім бар?.  //\n\n[Куплет 2]\nКөрген түстей өте шығар көз алдыңнан,\nӨмір жалған, оны ешкім біле алмаған.\nБұл өмірдің бар беймәлім құпиясын,\nҚанша іздеп талай адам таба алмаған.\n\n[Куплет 3]\nТыңда бүгін, тыңда үнін Жаратқанның\nБағушысын батқан күн мен атқан таңның.\nПенделері жүрсінші деп мәңгілікте,\nСүйгендіктен біздер үшін төкті қанын.\n\n[Куплет 4]\nМәңгілікке барар жолды көрсетіп,\nИса Мәсіх көкке кеткен тіріліп.\nЖаратқанның аларынан берері көп,\nСен де алғын, қалма досым кідіріп.","songNumber":"104"},{"id":544,"title":"Бұл өмірдің жұмбақ сыры","text":"[Куплет 1]\nБұл өмірдің жұмбақ сыры,\nБір Өзіңнен жаралған\nАспандағы күннің нұры\nБір Өзіңнен таралған.\n\n[Припев 1]\nТәңір Ием, көз алдыңда\nОйнақтаған баладай\nӨзіңмен бір, мәңгі болсам\nӨзіңнен бақыт тапсам.\n\n[Куплет 2]\nТаңғы самал, түнгі ызғар\nБар бойыңнан табылар\nМейірімің қандай ыстық\nЖаураған жан жылынар.\n\n[Куплет 3]\nАлыс жолдан келдім Саған\nСу берші, Әке маған\nКөп адасқан мен ұлыңды\nШығарсың сен сағынған."},{"id":808,"title":"Бұралаң тар жолмен аттанып барамын","text":"[Куплет 1]\nБұралаң тар жолмен аттанып барамын,\nЖеңісті, мәңгі өмір сүремін.\n// Жүрегім жай тапты, жарқырап жанарым,\nСебебі мен Құдайға сенемін! //\n\n[Куплет 2]\nЖақсы мен жаманды айыра білемін,\nЖаныма не керегін сеземін.\n// Неліктен жаралдым, оны да білемін,\nСебебі мен Құдайға сенемін! //\n\n[Куплет 3]\nАлысып шындықпен, күресіп күнә тұр,\nЗұлым рух жайлады жалғанды.\n// Ал мені шақырып жұмақта мұра тұр,\nСебебі мен Құдайға сенемін! //\n\n[Куплет 4]\nКелсе де қайғы-мұң, ысырып тастаймын,\nАртамын жүгімді Тәңірге.\n// Өзімді сүйетін Құдай бар, саспаймын,\nЖеткізер Ол мәңгілік өмірге! //\n\n[Куплет 5]\nЗұлымдық жеңіліп, жүрегім қуанды,\nӘкеге барар жолмен келемін.\n// Жүрегім жайланып, жаным да уанды,\nСебебі мен Құдайға сенемін! //"},{"id":264,"title":"Бүгін біздің Тәңіріміз","text":"[Куплет 1]\nБүгін біздің Тәңіріміз\nБіз үшін келді бұл дүниеге\nОсы хабарды жариялады періштелер\nИса туылды, туылды Иса\n\n[Припев 1]\nАллилуйя, аллилуйя\nТуылды Иса\n\n[Куплет 2]\nҚуанайық, шаттанайық\nОның туылуын жариялайық\nОсы хабарды жариялады періштелер\nИса туылды, туылды Иса"},{"id":767,"title":"Бүгін міне қуанышта шек болмас","text":"[Куплет 1]\nБүгін міне қуанышта шек болмас,\nПеріштелер әсем әнін тоқтатпас.\nНеткен Құдай қасиетті, құдіретті!\nӨз баласын Бетлехемге жіберді.\n\n[Припев 1]\n// Патша болып туылған, айналайын баладан.\nӘлем Құтқарушысы, адамзатқа берілді.  //\n\n[Куплет 2]\nДәуіттің қаласында нұр төгілді,\nПеріштелер сонда былай тіл қатты,\n«Лайым, Құдай аспанда құрметтелсін!\nАдамдарға шапағаты төгілсін».\n\n[Куплет 3]\nҚуанамыз, ән айтамыз, шаттана,\nНәрестенің ғажап туылғанына.\nСебебі өз уақыты келген кезде,\nКүнәдан Ол құтқарады бәрін де.","songNumber":"161"},{"id":219,"title":"Бүкіл арманым менің","text":"[Куплет 1]\nБүкіл арманым менің\nТек Сенің махаббатың\nТәңір Иса өз отыңмен\nЖақтың жан-дүниемді\nБар қалауым менің\nӨзгерт өмірімді\nТек Сенде ғана мен табамын\nМенің бар арманымды\n\n[Припев 1]\nИса, И---иса\nАзат еттің мені\nЖаңарттың жанымды\nИса, Иса\nПанамсың Сен маған\nТастамайсың мені\nМенің жүрегімде Иса!"},{"id":1014,"title":"Бүкіл атақ мәртебемді беремін","text":"[Куплет 1]\nБүкіл атақ мәртебемді беремін,\nБар еңбегім, даңқымды алдыңа қоямын!\nКөрмеп еді әлем Сендей ешкімді,\nСен ғана, лайықсың, жалғыз Сен лайықсың!\n\n[Куплет 2]\nҚұрметтегенг(е) атыңды Сен жақынсың,\nМәңгі жомарт, сүюші де сол - Сен Өзіңсің,\nӨмірімді бір Өзіңмен толтырдың,\nБарлық мадақ тек Саған! Барлық мадақ тек - Саған!\n\n[Припев 1]\n// Сен лайықсың, о, Ием, ұлы даңққа!\nСен лайықсың, барлық құрметке,\nСен үшін өмір сүрем, менде бардың бәрімен,\nТабынам Саған! //\n\n[Бридж 1]\nТабынам Саған! Құрметтейм(ін) !\nМадақтайм(ын), Сені - Ием!","alternateTitle":"Сен лайықсың!"},{"id":791,"title":"Бүкіл әлемге","text":"[Куплет 1]\nБүкіл әлемге Иса Аты,\nИса Аты тарап жатыр.\nАдасқандар Иса сөзін\nТыңдап Оған оралады.\nҚуанып Иса әндетеді,\nАдасқандар оралғанда.\nҚуанып Иса би билейді\nХалықтар Оған оралғанда.\n\n[Куплет 2]\nБүкіл әлемге Иса Аты,\nИса Аты тарап жатыр.\nҚұдай Патшалығы ұлттарға,\nБарлық елге тарап жатыр.\nҚуанып Құдай әндетеді\nБарлық елдер оралғанда.\nҚуанып Құдай би билейді\nХалықтар Оған оралғанда.","songNumber":"33"},{"id":454,"title":"Бүкіл әлем Құдайдың қолында","text":"[Куплет 1]\nБүкіл әлем Құдайдың қолында!\nБүкіл әлем Құдайдың қолында!\nБүкіл әлем Құдайдың қолында!\nБүкіл әлем Оның қолында!\n\n[Куплет 2]\nНәрестелер де Оның қолында!\nНәрестелер де Оның қолында!\nНәрестелер де Оның қолында!\nБүкіл әлем Оның қолында!\n\n[Куплет 3]\nӘр күн және түн Оның қолында!\nӘр күн және түн Оның қолында!\nӘр күн және түн Оның қолында!\nБүкіл әлем Оның қолында!\n\n[Куплет 4]\nЖаңбыр және жел Оның қолында!\nЖаңбыр және жел Оның қолында!\nЖаңбыр және жел Оның қолында!\nБүкіл әлем Оның қолында!","songNumber":"233","copyright":"Публик Домаин"},{"id":986,"title":"Бүкіл әлем Құдайдың қолында","text":"[Куплет 1]\nБүкіл әлем Құдайдың қолында,\nБүкіл әлем Құдайдың қолында,\nБүкіл әлем Құдайдың қолында,\nБүкіл әлем Оның қолында!"},{"id":393,"title":"Бүкіл әлем мадақтайды Сені","text":"[Куплет 1]\nБүкіл әлем мадақтайды Сені, солай болады!\nӨйткені Тәңірім менің солай қалайды\nСенің күшің құдіретті, ұлы Патшасың\nМадақтайды Сені Әке Сенің балаларың\n\n[Припев 1]\nМадақ Саған Тәңір\nМадақ Саған\nМадақ Саған Патшам\nҚұдайым менің\n\n[Припев 2]\n/// Мадақ, мадақ Саған (3р) ///\nҚұдайым менің\nМадақ"},{"id":179,"title":"Бүкіл әлемнің Иесі","text":"[Куплет 1]\nБүкіл әлемнің Иесі\nЖанымда болады әрқашан\nҚуанышқа толса жүрегім\nБақытым алда деп білемін\n\n[Припев 1]\nРухымды аспанға көтереді\nТәңірімді әнмен шырқасам\nМәңгілікке бізді жетелейді\nМәңгіге!\nТаңдаған баласын ұмытпайды,\nӘрдайым Қамқоршы болады.\nӨзінің жаратқан балаларын\nСүйеді!\n\n[Куплет 2]\nБарлық адамзат қуансын,\nХалықтар биікке самғасын.\nБізге ашқан шындықты,\nЖасасын Құдайым, жасасын!\n\n[Куплет 3]\nБақыт сыйлады біздерге\nҮмітпен, сеніммен келгенде\nШаттық жанымды тербейді\nМәсіхпен ұдайы жүргенде."},{"id":634,"title":"Бүкіл әлемнің Патшасы","text":"[Куплет 1]\nБүкіл әлемнің Патшасы,\nТаңғажайып тірі Құдай,\nЖаңа әр күнге жол ашады.\nКөкірегімді кернейді,\nШаттандырады көңілді,\nЗұлымдықты алшақтатады.\n\n[Припев 1]\nБасталады жаңа күн Иса Мәсіхпен,\nСәулесін төгіп нұр жарқырайды.\nҚуантады жаңа күн Иса Мәсіхпен\nҚұдайға шүкір! Аллелуя!\n\n[Куплет 2]\nТабиғат та серпіледі,\nОянады халықтар да.\nҚол көтеріп Оны даңқтайды.\nАллелуя! Аллелуя!\nСүйеміз Тәңірімізді,\nДауыстап мадақтаймыз Оны.","songNumber":"34"},{"id":1030,"title":"Бүкіл жаныммен ұмтылам Саған","text":"[Куплет 1]\nБүкіл жаныммен ұмтылам Саған,\nО, Иса, қабыл ал мадақты.\nБүкіл жаныммен ұмтылам Саған,\nӨзімді Саған мен арнадым.\n\n[Припев 1]\nМадақтаймын мен,\nСенің Рухыңды аңсап.\nСенің алдында, алдында,\n///  басымды ием! ///","songNumber":"24","copyright":"1992 Танкыоу Мусик"},{"id":412,"title":"Біз бір-бірімізге доспыз","text":"[Куплет 1]\nБіз бір-бірімізге доспыз, әрине,\nҚұдай тапты бәрімізді де.\nҚол ұшымызды берейік, көмекке келейік,\nҚұдай Патшалығы орнасын жерде.\n\n[Припев 1]\nБіз бір жанұя, біз бір жанұя.\nБіз үшін Иса қанын төкті.\nБіз енді достар, біз енді достар,\nСақтаймыз сүйіспеншілікті.\n\n[Куплет 2]\nБіз бір-бірімізге доспыз, әрине,\nБірге барамыз, достар, көкке.\nСенімді нық сақтайық, үмітін ақтайық,\nБір болу үшін Иса Мәсіхте.","songNumber":"177"},{"id":480,"title":"Бізге бұл күнді, Құдай жаратқан","text":"[Куплет 1]\nБізге бұл күнді, (Бізге бұл күнді)\nҚұдай жаратқан! (Құдай жаратқан!)\nШаттанамыз, (Шаттанамыз)\nшексіз қуанып! (шексіз қуанып!)\n\n[Куплет 2]\nИса Тәңір (Иса Тәңір)\nСені сүйеміз, (Сені сүйеміз)\nӨмірімізді (Өмірімізді)\nСаған арнаймыз. (Саған арнаймыз.)\n\n[Куплет 3]\nКелгін досым (Келгін досым)\nИса Тәңірге (Иса Тәңірге)\nСаған береді (Саған береді)\nМәңгілік өмір (Мәңгілік өмір)","songNumber":"37"},{"id":827,"title":"Бізді жаратқан Иеміз","text":"[Куплет 1]\nБізді жаратқан Иеміз мейірімді\nҚолыңды көкке жайып\nОны дәріпте\nЖалғыз Ұлын Ол құрбандыққа шалды\nҚарғыс пен түнектің қақпасын жапты\n\n[Куплет 2]\nБізді жаратқан Құдай Ұлы Патша\nҚолыңды көкке жайып\nОны даңқта\nЖалғыз Ұлын Ол құрбандыққа шалды\nМәңгіліктің есігін ашты!\n\n[Припев 1]\n// Иса мадақ Саған!\nБүкіл жер Саған табынады!\nИса алғыс Саған!\nСені дәріптеп мадақтайды! //\n\n[Бридж 1]\nСені дәріптеп мадақтаймын мен!"},{"id":504,"title":"Біздің Иса","text":"[Куплет 1]\nБіздің Иса тағайындалған Ұлы Патша,\nҚұтқарушым рақымды, игі Құдай.\nБіздің Иса Құдай таңдап алған Тоқтысы,\nШынайы, тірі жол мәңгілік бізге ашқан,\nИса мадақ Саған.\n\n[Припев 1]\n// Мадақталсын Сенің Атың Иса,\nТабынсын бүкіл әлем Сенің алдыңа келіп. //\nИса мадақ Саған."},{"id":215,"title":"Біздің қала Исамызға","text":"[Куплет 1]\nБіздің қала Исамызға,\nБіздің қала Құдайға,\nБіздің қала Патшамызға,\nБіздің қала Исаға.\n\n[Куплет 2]\nИса - Тәңір, Иса - Патша,\nМенің қаламда.\nИса - Тәңір, Иса - Патша,\nАллилуйя.\n\n[Припев 1]\nҚаламыз өзгереді,\nКісілер көшеде жүреді\nЖәне айтады, өйткені Ол..."},{"id":73,"title":"Біздің Құдай","text":"[Куплет 1]\nСудан шарап жасадың,\nСоқыр көздерді аштың.\nТең жоқ Саған Құдай,\nЖоқ Сен сияқты\nШаңнан бізді көтердің,\nҚараңғы нұр төктің.\nТең жоқ Саған Тәңір,\nЖоқ Сен сияқты!\n\n[Припев 1]\nБіздің Құдай ұлы, Ол құдіретті,\nҚұдай, Сен барлығынан жоғарысың!\nБіздің Құдай емші, шексіз Оның күші,\nО,Құдай! Біздің Құдай!\n\n[Припев 2]\nЕгер Құдай бізбен болса,\nКім жолымызда тұрады?\nЕгер Құдай бізбен болса,\nКім қарсы болады бізге?"},{"id":455,"title":"Біздің Құдай Ұлы","text":"[Припев 1]\n//   Біздің Құдай Ұлы!\nКүшті құдіретті!\nОған тең келер еш нәрсе жоқ!\nЖоқ! Жоқ!  //\n\n[Куплет 1]\nТаулар мен қырлар,\nЖайлау мен көлдер,\nАспандыда Ол жаратқан!","songNumber":"234"},{"id":804,"title":"Біздің Патша, біздің Құдай-Иса Мәсіх!","text":"[Куплет 1]\nБіздің Патша, біздің Құдай-Иса Мәсіх!\nКім біз үшін құрбан болды-Иса Мәсіх,\n\n[Предприпев 1]\nКім біз үшін қанын төгіп құтқарылу берді?!\n\n[Припев 1]\n//// Иса-Патша, Иса-Тәңір,\nИса-Ием, Ол Құтқарушы! ////\n\n[Куплет 2]\nКім дүниеге нұр болды-Иса Мәсіх,\nКім біз үшін жанын қиды-Иса Мәсіх,\nКім біз үшін қанын төгіп құтқарылу берді?!","songNumber":"26","alternateTitle":"Иса-Патша, Иса-Тәңір, Кім біз үшін жанын қиды"},{"id":690,"title":"Біз жалғыз емеспіз","text":"[Куплет 1]\nБіз жалғыз емеспіз,\nИсада болдық дос-бауыр.\nМейірлі Құдай жетелеп келеді,\nКөрсін дүние махаббатын Оның.\n\n[Куплет 2]\nБіз мәңгі бір боламыз,\nЖүректе лаулап махаббат.\nҚолыңды бер, әлем тағы көрсін,\nҰлы махаббатын Иса.\n\n[Куплет 3]\nИсада болдық дос-бауыр,\nМахаббаты Оның бізбен.\nСүйейік бір-бірімізді\nБіз бірге ұлы күшпіз.\nИсада болдық дос-бауыр.\nИсада болдық дос-бауыр.","songNumber":"36"},{"id":358,"title":"Біз жалғыз жүрмейміз","text":"[Куплет 1]\nБіз жалғыз жүрмейміз\nӨмірде бізді жетелейді Құдай\nМәсіхте болдық біз бір жанұя\nӘлем көрсін махаббатты бізден\nБоламыз біз бірге әрқашан\nЖүректе махаббат лаулайды\nМаған қолыңды бер әлем білсін\nМәсіхтің шексіз рақымын\n\n[Припев 1]\nМәсіхте біз бір жанұя, о Тәңір\nОның махаббаты шексіз, алғыс Саған\nМәсіхпен біз біргеміз\nМәсіхше біз сүйеміз\n// Мәсіхте біз бір жанұя  //"},{"id":492,"title":"Біз Исамен бірге","text":"[Куплет 1]\n// Иса әлемді құтқарған!\nИса көкке есік ашқан!\nИса Саған алғыс айтам! //\n\n[Припев 1]\n// Біз Исамен бірге Әкемнің қасында,\nБіз Исамен бірге патшалықта,\nБір Исамен берге Құдайдың Рухында! //\n\n[Куплет 2]\nКөктің Патшалығында,\nӘкенің қасында.\nСүйікті Құдайдың балалары,\nШаттанып ән салып би билейді.\nКөктің Патшалығында,\nӘкенің қасында.\nСүйікті Құдайдың балалары,\nҚуанып рахатқа бөленеді."},{"id":988,"title":"Білем, Сенде мен кіммін","text":"[Куплет 1]\nКіммін мен,\nшақыратындай Ұлы Патша!\nЖоғалдым, тапты мені Ол\nМахаббатымен,\nМахаббатымен.\n\n[Припев 1]\nАзаттық берді\nИса мәңгілік.\nМен Құдай ұлы!\nДәл солай!\n\n[Куплет 2]\nҚұн төлеп азаттық берді\nРақымымен.\nКүнәға құл болдым. Иса\nМен үшін өлді.-2\n\n[Припев 2]\nАзаттық берді\nИса мәңгілік.\nМен Құдай ұлы!\nДәл солай!\nӘкем үйінде\nОрын бар маған.\nМен Құдай ұлы!\nДәл солай!\n\n[Бридж 1]\nМен таңдалдым,\nТасталмадым,\nБілем Сенде мен кіммін!\nСен жақтаушым,\nСен қолдаушым,\nБілем Сенде мен кіммін!"},{"id":881,"title":"Білемін қандай жүрек сүйеді","text":"[Куплет 1]\nБілемін қандай жүрек сүйеді,\nСол жүрек, көзбен көрмес Сен енді!\nҚызғаныш жүрегіңнен шықпайтын,\nБар жаманды алмайтын, кешірім беретін!\n\n[Припев 1]\nТек Сенің жүрегің, сүйеді шексіз мені!\nКешіріп тосады жолымды ашып береді!\nТек Сенің жүрегің,жолымды ашып береді!\n\n[Куплет 2]\nБілемін қандай жүрек сүйеді,\nІздейтін басқаның қасиетін!\nБарлығын арнайды сүйгеніне,\nӨзі құрбан болады, жүректің Иесі!"},{"id":715,"title":"Білемін мен құтқарылдым","text":"[Куплет 1]\nБілемін құтқарылдым\nҚаныңмен күнәмді жудың\nСенемін, сенемін\nМендегі ұятты алдың\nЖараларды емдедің\nСенемін, сенемін\nЖеңіске жеттім,\nТәңірім өлімді жеңді\n\n[Припев 1]\nҚұтқарушым тірі\nҚұтқарушым тірі\n\n[Бридж 1]\nАлдың жүгімді,\nқайта тірілдің\nБилеймін Сенің алдыңда\nКүтіп Сені Патшам","songNumber":"127"},{"id":656,"title":"Білуге Сені","text":"[Куплет 1]\nМәсіх қанымен мені құтқарды,\nКешірді, азат етті, тірілтті.\nҰлылығың Сенің бойымда тұр,\nМәңгілік сенемін, мәңгілік сенемін.\n\n[Куплет 2]\nСен ақиқатыңмен тұтқындадың,\nРақымыңмен жарамды емдедің.\nКиелі сөзіңмен мені жетелейсің,\nМахаббатың адал, махаббатың адал!\n\n[Припев 1]\nБілем: бердің,\nЖалғыз Өз Ұлыңды,\nБілуге Сені,\nБолсын деп мейіріміңде,\nСен мен үшін айқышта құрбан болдың,\nСен сүйдің, сүйдің лайықсыз халықты.","songNumber":"39"},{"id":956,"title":"Біліміңмен мақтанба","text":"[Куплет 1]\nНеге қаламайсың сен\nТүсінуді Исаны\nКүнәсіз ешкім құрбан болмады.\nИса Масіхтен басқа.\n\n[Припев 1]\n// Мүмкіндіктен пайдалан\nСаған беріп жатқанда.\nТән алмасаң Исаны,\nБіліміңмен мақтанба. //\n\n[Куплет 2]\nЕшқандай дін құтқармас.\nКүнәлардан бауырым.\n// Құрбандық қандар пайда бермейді.\nИса Масіхтен басқа //"},{"id":357,"title":"Бірге ән айтып, қол шапалақтаңдар","text":"[Куплет 1]\nБірге ән айтып, қол шапалақтаңдар.\nБірге ән айтып қол шапалақтаңдар.\nБірге ән айтып, қол шапалақтаңдар,\nҚұдай бізді сүйеді!"},{"id":175,"title":"Біреу Сені «жақсы» дейді","text":"[Куплет 1]\nБіреу Сені «жақсы» дейді,\nБіреу «жуас» дейді,\nБіреу Сені «өлі» дейді,\nАл мен «тірі» деймін.\n\n[Куплет 2]\nБіреу атайды «пайғамбар» деп,\nБіреу «дана» дейді.\nБіреу «бұл жай адам» дейді,\nАл мен «Құдайым» деймін,\nҚұдайымсың!\n\n[Припев 1]\nЖар саламын Сені Әлемге\nАтыңды мен көтерем.\nҰлылығыңды білетін болады\nҚұдайымсың, Сен Иса.\nЖар саламын Сені Әлемге\nАтыңды мен көтерем\nМейіріміңді әлемге көрсетем\nЖар салатым даңқыңды Сенің.\n\n[Куплет 3]\nБілемін, Сен Құтқарушым\nМаған өмір бердің.\nБілемін Сенсің жалғыз жол\nИса, Сен Құдайсың, Құдайымсың\n\n[Куплет 4]\nИса, Сені даңқтайтын таңдадым мен өмірді!\nЖар салам!","songNumber":"40"},{"id":169,"title":"Бір жерді білемін","text":"[Куплет 1]\nБір жерді білемін,\nСол тамаша жерде,\nКінәлі жандар,\nРақымдылық табады.\nІстеген күнәмыз,\nӘлемнің күнәсы\nСонда Исамен шегеленді.\n\n[Припев 1]\nАйқышта, айқышта\nҚұрбан болды біз үшін.\nАйқышта, айқышта\nБізді тірілтті.","songNumber":"41","alternateTitle":"Айқышта"},{"id":541,"title":"Бір кезде сендерді таңдады Тәңірім","text":"[Куплет 1]\nБір кезде сендерді таңдады Тәңірім\nСөнбейтін нұрының білсін деп қадірін.\nКешіріп, Киелі Рух берді жүрекке,\nЖарығын түсірді қараңғы түнекке.\n\n[Припев 1]\n// Сол нұрда жарықта болыңдар,\nАлаулап жаныңдар,\nИемізге адал боп қалыңдар. //\n\n[Куплет 2]\nБатасын береді Тәңірім аямай,\nҚорғайды, сақтайды қолында аялай.\nТек қана Исаның сөзімен жүріңдер,\nҚол ұстасып ұзақ жыл өмір сүріңдер.\n\n[Припев 2]\n// Исаның нұрында болыңдар,\nАлаулап жаныңдар,\nИемізге адал боп қалыңдар. //\n\n[Куплет 3]\nШаңырақтарың биік болсын көтерген,\nТұрмасын отау әрекетсіз бекерден.\nКөре алсын кірген жан Иса жарығын,\nСарбазысыңдар құн төленіп өтелген.","songNumber":"209"},{"id":877,"title":"Бір Құдайға сенем дегеннің, болады басы - Иса Мәсіх","text":"[Куплет 1]\nҚұрбан шалатын, жанды қиятын\nХалқым үшін келді уақыт.\nТәнге қарамай, басқаға бұрмай\nШапағатқа шықты бақыт.\nШын жүрегімен келем дегенге\nНұр есігі әркез ашық.\nБір Құдайға сенем дегеннің,\nболады басы - Иса Мәсіх\n\n[Припев 1]\n// Күн сәулесі айдың нұры\nБізге керек болмайды.\nМәсіх Нұры салтанаты,\nҰлылығы қоршайды.\nЖан дүниемді, айналамды,\nӨзі жарқыратады.\nЖүректерді тыныштыққа,\nТолтырып қуантады. //\n\n[Куплет 2]\nБір қауымға, адал бауырға,\nАйналдырды бізді Мәсіх.\nЕш алдамайтын, әділ жүретін,\nМәсіхшілер біздер болдық.\nҰстап ораза, болып дұғада,\nМәсіх Нұрына нұрландық.\nБарлық өмірді, толық жүректі\nБеретіндер біздер болдық.\n\n[Куплет 3]\nМәсіх нұрына, тірі қауымға\nАйналады ел жақында\nИсаменен біз әркез біргеміз,\nМәсіхшілерміз өйткені.\nБейбітшілікті билеуші етті,\nӘдептілікті әмірші,\nТірі Сөзімен тірілтті бізді,\nҚауымбасы Иса Мәсіх."},{"id":902,"title":"Бір шындық бар әлемде","text":"[Куплет 1]\nБір шындық бар әлемде,\nІздесең сен табарсың.\nИемденсең егерде,\nӨзіңе жол ашарсың.\n\n[Припев 1]\nҚуанышта толы Онда,\nСаған айтамын достым!\nҚұдайға құрмет көрсет,\nӨйткені Ол - махаббат!\n\n[Куплет 2]\nҚұдайға үміт артсаң,\nАрманың орындалар!\nСонда сенің бойыңда,\nМахаббат оты жанар!\n\n[Куплет 3]\nТабиғатқа қарасам,\nҚұдіретті көремін!\nҚұдайды мадақтасам,\nЖүрегімді беремін!\n\n[Куплет 4]\nҚұдайдың балалары,\nҚуанып ән салыңдар.\nКөктегі мәңгілікте,\nСыйымыз сонда болар!"},{"id":220,"title":"Ғажайып жерді Тәңір сыйлады","text":"[Куплет 1]\nҒажайып жерді Тәңір сыйлады\nБосқа жиналуды Тәңір қаламайды\nТәңір шақырады бізді қызметіне\nБір денеде Құдайды мадақтауға\n\n[Припев 1]\nТірі Құдайдың денесіміз біз\nТірі Құдайдың Иса Мәсіхтің\nТірі Құдайдың денесіміз біз\nТірі Құдайдың Иса Мәсіхтің\n\n[Куплет 2]\nҚауымдастар бір-біріңді сүйіңдер\nИсаның шексіз махаббатыменен\nШын жүрекпен бір-біріңді сүйіңдер\nҚұдайдың таза сүйіспеншілігімен\n\n[Припев 2]\nТірі Құдайдың Иса Мәсіхтің"},{"id":180,"title":"Ғажайып менің Ием","text":"[Куплет 1]\nҒажайып менің Ием,\nҚандай ғажап Тәңірім!\nҒажап менің Әкем\nМадақ айтамын Оған.\n\n[Припев 1]\nИсаның махаббаты\nЕшқашан таусылмайды.\nЖұлдыздай жарқырайды\nТәңір Иемнің жарығы.","songNumber":"34"},{"id":635,"title":"Ғажап Рақым","text":"[Куплет 1]\nҒажап рақым Сазды үндей\nҚұтқар мендей паңды\nАдасқанда жол көрсеттің\nАшып көзімді Сен\n\n[Куплет 2]\nБерген уәделері ізгі\nСөзі жанға демеу\nҚалқаным да, үлесім де\nБұл жалғанда Өзің\n\n[Припев 1]\nБұғауды сен талқандадың\nҚұн төлеп Сен Құтқарушым\nТопан судай төгін рақым\nШексіз сүйдің ғажап рақым\n\n[Куплет 3]\nИә, бар күшім ада болып\nСоңғы сәтім келсе\nАшасың Сен Өз қолыңмен\nМәңгілік есігін\n\n[Куплет 4]\nӘлем ғайып болар қардай\nКүнді түнек басар қардай\nҚұдай созар қолын маған\nМәңгі болар бірге\nМәңгі Мендіқсің Сен\nМәңгі Сендікпін мен"},{"id":143,"title":"Ғарышты айналады жеріміз қаңбақтай","text":"[Куплет 1]\nҒарышта айналады,\nжеріміз қаңбақтай!\nШексіз әлем ортасында,\nОсындай кішкентай!\n\n[Припев 1]\n// Досым қол ұсын жақыныңа!\nДосым қол ұсын жақыныңа!\nДосым қол ұсын жақыныңа!\nКөзіңнен төгілсін нұр! //\n\n[Куплет 2]\nЖамандықты ұмытшы,\nҚуаныш келді!\nКең байтақ жерімізге,\nШаттығын берді!\n\n[Припев 2]\n// Досым қуантшы жақыныңды!\nДосым қуантшы жақыныңды!\nДосым қуантшы жақыныңды!\nКөзіңнен төгілсін нұр! //\n\n[Куплет 3]\nКөктегі Әкем, әлемде,\nБәрін сүйеді!\nАсығайық жарығына,\nОның Киелі!\n\n[Припев 3]\n// Досым Тәңірді мадақтайық!\nДосым Тәңірді мадақтайық!\nДосым Тәңірді мадақтайық!\nКөзіңнен төгілсін нұр! //"},{"id":618,"title":"Ғасырлар Үміті","text":"[Куплет 1]\nИсаның хабары\nҒасырлардың үміті\nЕшқашан ол өшпейді\nЖарқырап жанады\nИсаның қауымын\nЕшкім жеңе алмайды\nЖұлдыздай жарқырайды\nНұрын ол төгеді\nЕшкім жеңе алмайды\n\n[Припев 1]\nМәсіх өлген\nБірақ қайта тірілді\nИә, Ол қайтадан келеді\nМәсіх - патша\nМәңгі жеңісте\nИә, барлық мақтау Оған тән\nИә, барлық мақтау Исаға\n\n[Куплет 2]\nБарлық ұрпақтар үшін\nОның Сөзі Жауап\nӘлем оны өзгертпейді\nДақ түсіре алмайды\nБіз мойындаймыз\nЖәне жариялаймыз\nСенеміз жазылғанға\nСенеміз Сен айтқанға\n\n[Бридж 1]\nӘн сал Аллилуйя\nМәсіх Құтқарушымыз\nӘн сал Аллилуйя\nБіздің Құдай құдіретті"},{"id":989,"title":"Ғолғота айқышында","text":"[Куплет 1]\nҒолғота айқышында\nМәсіхтің қаны төгілді.\nҚанынан Оның тыным мен\nТыныштық табамыз.\nМенің күшім жоқ,\nКүнәмен өмір сүрген кезімде,\nБірақ мойындасам,\nҚардан әппақ ағарамын.\n\n[Припев 1]\nБіз үшін төгілген\nҚаныңа сенемін, сенемін.\nКіршіксіз Сен азаптан бізді\nӨзіңмен құтқардың.\n\n[Куплет 2]\nМәсіх кешірді қарақшыны,\nқүнәсын сезінген.\nКөктегі үйдің ашты\nОл сенгенге қақпасын.\nКүнәм қаһарлы,\nБірақ Иса жуды оны айқышта.\nСаясындамын бар жерде\nОның қанатының.\n\n[Куплет 3]\nАрқалап айқыш,\nКүнәсын адамның кешірдің.\nБізді жуған Тәңір қаны\nТеңізден құдіретті.\nЖаңа мекенде мәңгілік\nБіздің шырқаймыз ән-жырды,\nЖиналып бар жерге даңқты\nҚұдайдың Тоқтысы.","songNumber":"42"},{"id":793,"title":"Ғолғота, Ғолғота, Ғолғота","text":"[Куплет 1]\nҒолғота, Ғолғота, Ғолғота...\n\n[Куплет 2]\nБулығып жасқа көздерім,\nҚараймын Саған Тәңірім.\nЖүрегімді жігерлендіріп Сен,\nАйқышқа Ием, керілдің.\n\n[Припев 1]\nШеге емес айқышта ұстаған,\nАдамдар да емес Сені қинаған.\nКөп уақыт өтсе де содан бері,\nКүнәларым менің Сені қинаған.\n\n[Куплет 3]\nБасыңда тәжің шеңгелді,\nСоғылып бардың айқышқа.\nӨз еркіңмен кергіздің Сен мен Өзіңді,\nКүнәдан құтқарып мені.\n\n[Куплет 4]\nЖиі елестейді маған\nАйқыштағы төгілген қан.\nИса, Саған басымды иемін,\nКүнәдан мені құтқарған."},{"id":738,"title":"Далада бір қоян","text":"[Куплет 1]\nДалада бір қоян шөп жеп отыр,\nШөп жеп отыр қояным, тоя жей бер.\nҚұдай мол шөп өсірер.\nТоя жеп, секіріп жүре бер."},{"id":58,"title":"Далама көз салсам, өткенді ойға алсам","text":"[Куплет 1]\nДалама көз салсам, өткенді ойға алсам,\nҚаншама күнәм бар, сан жетпес санасам.\n\n[Припев 1]\n// Жүректе маза жоқ,\nӨмірде қайғым көп.\nТыныштық таппайды,\nЖүрегім жылайды. //\n\n[Куплет 2]\nЯ, Тәңір Жаратқан, бар әлемді құлпыртқан,\nБар әлемнің Иесі, құтқаршы азаптан.\n\n[Куплет 3]\nТәңірім естіді, күнәмды кешірді.\nКүнәкар мен үшін Өз Ұлын жіберді.\n\n[Припев 2]\n// О, қандай қуаныш!\nО, қандай жұбаныш!\nТыныштық табылды,\nЖүрегім қуанды! //\n\n[Куплет 4]\nКүнәдан құтқарған, біз үшін қиналған.\nСенемін Исаға, Ол келген Құдайдан.","songNumber":"35"},{"id":497,"title":"Даланың теріп гүлдерін","text":"[Куплет 1]\nДаланың теріп гүлдерін,\nДемалып хош иіспен,\nКөкжиектен, көкжиекке,\nҚараймын үмітпенен.\nКелер-ау, менің Құдайым,\nБір кезде, бір күндерде,\nКөрмей қалам деп қорықпаймын,\nӨтсем дағы бұл өмірден.\n\n[Куплет 2]\nКешірдің балағатымды,\nКінәсіз адамдарға,\nКешірдің барлық атыңды,\nОрынсыз күнде айтылған.\nКешірдің адамның бір кез,\nӨзіңді ұмытқанын,\nҒасырлар бойы Өзіңді,\nСоншама ұқпағанын.\n\n[Куплет 3]\nКешірдің бәрін бір Өзің,\nБіздерді сүйгендіктен,\nҚұтқарылдық барлығымыз\nӨзіңе сенгендіктен,\nЖанарың бізді баулайды,\nБалаң боп жерде жүрген,\nМенсінбей кеткен талайлар,\nҚуанып қайта келген.","songNumber":"105"},{"id":127,"title":"Даңқтаймын мен Сені","text":"[Куплет 1]\nДаңқтаймын мен Сені!\nМадақтаймын мен Сені!\nТабынамын мен Саған,\nО, Иса! О, Иса! Мен Сені сүйемін!\nӨлімді Сен жеңдің,\nКүнә құлдығынан босаттың!\nЖеңіс Сен алып бердің,\nОсы дүниеде ризамын!","songNumber":"42"},{"id":296,"title":"Даңқтаймын Сені","text":"[Куплет 1]\nДаңқтаймын Сені\nШексіз сүйіп\nБіз үшін келгеніңе\nТастап үйіңді.\nТолтырып Рухқа\nБолшы жанымда.\nТәңірім даңқ саған!\n\n[Куплет 2]\nҚұстар аспанда\nДаңқтайды Сені.\nБүкіл адамзат\nДаңқтайды Сені.\nТолтырып Рухқа\nБолшы жанымда\nТәңірім даңқ Саған!","songNumber":"37"},{"id":185,"title":"Даңқтаймын Сені, шексіз сүйіп","text":"[Куплет 1]\nДаңқтаймын Сені, шексіз сүйіп\nБіз үшін келгеніңе, тастап үйіңді.\nТолтырып Рухқа, болшы жанымда.\nТәңірім даңқ саған!\n\n[Припев 1]\nҚұстар аспанда, даңқтайды Сені.\nБүкіл адамзат, даңқтайды Сені.\nТолтырып Рухқа, болшы жанымда\nТәңірім даңқ Саған!"},{"id":838,"title":"Даңқтайтын болам Мәсіх Тәңірді","text":"[Куплет 1]\nӘр күні аузымда менің:\nИса - соншама тәтті Есім!\nМен білмеймін басқа есім,\nДәріптейм тек қана Оны!\n\n[Куплет 2]\nИса деп жырлайт жүрегім,\nҒажап Құтқарушым жайлы.\nОл ғана тыным береді,\nАты Оның менімен дәйім!\n\n[Припев 1]\nДаңқтайтын болам Мәсіх Тәңірді,\nҰмытпайм Оның барлық істерін.\nШырқаймын ән Оған: Аллелуя!\nАллелуя!\n\n[Куплет 3]\nЖарқырап төксе нұрын күн,\nШуаққа бөлеп жер бетін.\nЖырлайды тағы жүрегім,\nИса Патшаға жырын!","songNumber":"21","alternateTitle":"Әр күні аузымда менің"},{"id":433,"title":"Даңқтауды Сені қалаймын әрқашан","text":"[Куплет 1]\n/// Даңқтауды Сені қалаймын әрқашан ///\nДаңқтауды\n\n[Куплет 2]\nИса махаббатымсың\nИса тастамаймын мен Сені\nТүнектен шығардың мені\nТірегімсің Сен, енді білемін мен\n\n[Припев 1]\nМен Саған мұқтажбың\nСүйемін Сені, менімен әрқашан бол\nҚұтқарушы - сүйікті досым\nДаңқтауды Сені қалаймын әрқашан"},{"id":531,"title":"Дара Тұлға! Бұл әлемнен биіксің!","text":"[Куплет 1]\nДара Тұлға! Бұл әлемнен биіксің!\nБір мен үшін заңғар көктен келіпсің.\nБетлехемде жарық жұлдыз жанғанда,\nСәби болып бұл әлемге туыпсың.\n\n[Припев 1]\n// Жүрегіме сөзіңді бердің,\nРақымыңды ісіңнен көрдім.\nӘркез маған жар боп келесің,\nСоңыңнан ердім.\nЖүрегімді сынап та көрдің,\nӘлсіздігімді де ескердің,\nМейрімің маған шексіз Сенің,\nҰлы Тәңірім.\nЖығылғанымда Сен сүйедің,\nҚуанышымда да біргесің.\nМен балаңмын, Сен маған Әке.  //\n\n[Куплет 2]\nМен үшін Сен жан азабына бардың,\nБар күнәмді «Маңдай төбеде» алдың.\nҚан сорғалап бара жатсың сүйреліп,\nЖылап тұрмын жан дүниеммен күйзеліп.","songNumber":"150"},{"id":648,"title":"Даусыңды естимін","text":"[Куплет 1]\nТағыңнан аққан өзенде тұрмын -\nӨмір суы, өмір суы.\nТазартты мені өмір берді,\nМахаббатың - демім.\n\n[Припев 1]\nДаусыңды естимін Сен ән салған кезде,\nҮміт береді менің өміріме.\nСеземін Сені, жақын келгенімде,\nҚайта жаңарттың жүрегімді Өзің.","songNumber":"43"},{"id":87,"title":"Дәнді аламыз, жерге саламыз","text":"[Куплет 1]\nДәнді аламыз, жерге саламыз,\nЕгеміз топыраққа.\nКүн нұр төгеді, жарық береді,\nМаған да жарық керегі.\n\n[Припев 1]\nТиеді маған, тиеді саған, шапағаты.\n\n[Куплет 2]\nКүн қуатымен, нұр шуағымен,\nЖылытты еккен дәнді.\nМейірімін сепкен, шуағын төккен,\nАйтамыз Тәңірге әнді.\n\n[Куплет 3]\nТәңірден алған, бойыңда қалған,\nМейіріммен бөлісіңдер.\nТүнекке жарық, беріңдер барып,\nРух дәнін егісіңдер.","songNumber":"237"},{"id":478,"title":"Дәріптеймін Сені","text":"[Куплет 1]\nИса, Иса,\nКөктен келген Құдайдың Ұлы!\n\n[Куплет 2]\nИса, Иса,\nАйқышқа алдың күнәмды,\nЖырлаймын Сені мен мәңгі.\n\n[Припев 1]\nӨмір бойы бас ием,\nАлдыңда, Патшам,\nӨмір бердің Сен,\nМені ұшырдың.\nКиелісің, Ием,\nБәрі жырлайт,\nСені мақтайт,\nҚазір де, мәңгі де,\nДәріптеймін Сені!","songNumber":"44"},{"id":335,"title":"Дәріптеймін Тәңірді,","text":"[Куплет 1]\nДәріптеймін Тәңірді,\nТағзым етем Тәңірге.\nМойындаймын:\nСүйем Сені, Тәңірім.\n\n[Припев 1]\nСөзбен айтып жеткізе алман,\nБар жүрекпен Сені сүйемін.\nБар жаныммен Сені дәріптейм,\nБар еркіммен Саған бас ием.\nБар жүрекпен Сені сүйемін,\nБар жаныммен Сені дәріптейм.\nБар еркіммен Саған бас ием,\nТәңірім.","songNumber":"45"},{"id":760,"title":"Домбырам жырла әнді","text":"[Куплет 1]\nДомбырам жырла әнді Құдайым туралы,\nАлғыстар мен мадақтарға тек Әке лайықты.\nДомбырам жырла әнді, тоқтамасын жырла\n// Жайылсын көкке, жайылсын жерге, жайылсын еліме. //\n\n[Припев 1]\n// Жырла жүрек, жырла жаным\nӘкеңе жаратқан сені\nЖаңа әнді, жаңа жырды\nАрна жаңа өміріңді //\nСен жүнжіме, сен ренжіме Әкең тәрбиелегенде,\nСен түсірме еңсеңді де жазалайды керек кезде.\n\n[Куплет 2]\nДомбырам жырла әнді даналық туралы,\nҰлылық пен даналы Оған арналады.\nҚандай дана десеңші Әкеміз көктегі,\n// Жеңді бәрін даналығымен, сүйіспеншілікпен. //"},{"id":221,"title":"Достарыма","text":"[Куплет 1]\nДостарыма бата беріп бұл күнде\nЖарылқашы, о, Тәңір, бізге келіп\nСүйспеншілігіңе бөлеші Сен\nДостық пенен тыныштығын\nӨсіп өніп гүлденсін\n\n[Припев 1]\nИса, Иса сүйікті досым менің\nСен менімен, мен Сенімен\nМәңгі бірге боламыз\n\n[Куплет 2]\nДостарымды Тәңірім жарылқашы\nӨмір бойы мадақтаймын мен Сені\nАлшы Өзін Құдайым өмірімді\nҚұтқарушым Жаратушым\nҚұдайым сүйем Сені"},{"id":987,"title":"Достарымыз сау болыңдар","text":"[Куплет 1]\nДрстарымыз сау болыңдар,\nСабағымыз енді бітті,\nБәріміз үйге барамыз.\nБіз қайтадан кездескенше,\nҚұдай бізбен болады."},{"id":107,"title":"Дұға етем аспанға жетуге","text":"[Куплет 1]\nДұға етем аспанға жетуге,\nСол жердегі Патшама ән арнаймын мен.\nЖарық сәуле сөнбейтін мекенге,\nҚалып қоймай жетсем екен.\n\n[Припев 1]\nҚазақстан жерімізге,\nТөгіледі Оның нұры,\nКелді біздің төрімізге,\nИса Мәсіх - Құдай Ұлы.\n\n[Куплет 2]\nШын жүректен сенемін мен Оған,\nЖетелейді ғажайып көктегі үйге.\nТыныштықтың қайнар көзі болған,\nЕремін мен тек Мәсіхке.","songNumber":"43","alternateTitle":"Қазақстан жерімізге төгіледі Оның нұры"},{"id":310,"title":"Дұғам Саған","text":"[Куплет 1]\nДұғам Саған Құдайым,\nБолшы менімен ұдайы,\nКүнәларымды кешіріп,\nСүйші мені әрдайым.\n\n[Куплет 2]\nКүнәдан Сен құтқардың,\nМәңгі өмір сыйладың,\nҚидың өмір біз үшін,\nМақта жаным Исаны!"},{"id":29,"title":"Дұға нұрға жетелейді","text":"[Куплет 1]\nАсыққанда бүгін үйден,\nСиындың ба, сен?\nРақымын Тәңір шақырып,\nМахаббат іздеп.\n\n[Припев 1]\nДұға нұрға жетелейді,\nЖұбатады ол бізді.\nСиынуды ұмытпаңдар,\nТүнек басқанда.\n\n[Куплет 2]\nҚудың ба, ашуды дұғамен,\nМейірім іздеп?\nКешірдің бе, досыңды сен\nКедергі еткен?\n\n[Куплет 3]\nАзаптан әлсірегенде,\nСиындың ба, сен?\nҚұдаймен түріп түнекті,\nЖеңімпазсың, сен.\n\n[Куплет 4]\nСиынып жүрекпен Оған,\nМәңгі өмір сүрем.\nҰзарар өмірім менің,\nҚұдайға берген.","songNumber":"12"},{"id":578,"title":"Дұғаның сөздерінде емес","text":"[Куплет 1]\nДұғаның сөздерінде емес,\nРухани әндерінде емес.\nЖаным тек Тәңірдің сөзінде,\nӨмірдің бастауы Өзіңде.\n\n[Куплет 2]\nМәнсіз өмір тілек етпедім,\nСенсіз шын бақытқа жетпедім.\nТербейді бір өлең сезімде,\nӨмірдің бастауы Өзіңде.\n\n[Куплет 3]\nУайымым басымнан асады,\nМұңымды Тәңірім басады.\nТілегімді Сенен сұрадым,\nӨзіңде өмірдің бұлағы.\n\n[Куплет 4]\nКешірім Өзіңмен әкелдің,\nКөктегі пейішті әпердің.\nЖан-дүнием енді жар салады,\nӨмір Өзіңмен басталады.\n\n[Куплет 5]\nДұшпандар қоймады аңдуын,\nТәңірдің есімі - қаруым.\nЖеңіске жеткізер кезінде,\nӨмірдің бастауы Өзіңде.\n\n[Куплет 6]\nСен менің тірегім, панамсың,\nҚұтқарушым, берік қамалсың.\nШындықтың қайнары сөзіңде,\nӨмірдің бастауы Өзіңде.","songNumber":"65"},{"id":647,"title":"Дүние бастан-аяқ адасқан","text":"[Куплет 1]\n// Дүние бастан-аяқ адасқан.\nЖаратушы Құдай жоқ десе. //\n\n[Припев 1]\nБар! бар! бар! бар! Құдай.\nКөкте Оның мәңгі тағы бар.\nБар! бар, бар, бар! Иса\nҚұтқарушы Ұлы Мәсіх бар!\n\n[Куплет 2]\n// Адамдар күнәсіна батып жатыр,\nҚұтқарушы Құдай жоқ десе. //\n\n[Припев 2]\nБар! бар, бар, бар! Құдай.\nКөктен келген Құтқарушы бар!\nБар! бар,бар,бар,бар! Құдай!\nКөктен келген Иса Мәсіх бар.\n\n[Куплет 3]\n// Адамдар қиыншылықтың астында.\nЕгер бізде үміт жоқ десе. //\n\n[Припев 3]\nБар! бар, бар, бар! Құдай.\nҚұтқарушы Иса Мәсіх бар.\nБар, бар, бар бар! Иса.\nҚұтқарушы Ұлы Мәсіх бар.","songNumber":"38","alternateTitle":"Жаратушы Құдай жоқ десе"},{"id":802,"title":"Дүниені бір сөзіңмен жараттың","text":"[Куплет 1]\nДүниені бір сөзіңмен жараттың\nӘлемді шындығыңа қараттың\nРухыңмен Киелі сенім бойлатып,\nОсы әнді жүрегімде ояттың.\n\n[Припев 1]\nО, Иса,Сен әлемнің тірегі,\nАдамзаттың тілегі, Тіршіліктің өзегі\nО, Иса әмір бердің өмірге\nСенген адам Өзіңе, Тірілсін деп мәңгіге.\n\n[Куплет 2]\nӘлемді сүйгендіктен соншалық,\nҚұдайым, бердің бізге-Құрбандық.\nИса боп, дүниеге келдің Сен,\nҚұтқарам, күнәдан деп, халқынды,\n\n[Куплет 3]\nМадақтап, құрметтеймін Өзіңді\nҒаламға жеткізермін Сөзіңді.\nОятып, Сенің берген рухыңмен,\nШындықты ашып бердің еркіңмен","songNumber":"46"},{"id":1034,"title":"Дүниені сүйгендіктен Жаратқан Тәңір","text":"[Куплет 1]\nДүниені сүйгендіктен,\nЖаратқан Тәңір,\nКүнәкар бұл дүниеге Ұлын берген!\nТөгілген қанымен құтқарып бізді,\nМәңгілік өмірді, бізге сыйлық еткен!\n\n[Припев 1]\nДүниенің күнәларын мойынына алып,\nОл сенің күнәң үшін, құрбан болған!\nБүгін де сені күтеді, құшағын жайып,\nҚабыл ал, Оның сыйын берген саған!\n\n[Куплет 2]\nКүнәның тұтқынында, біз жасап келдік,\nАзғырып күнәларға жетеленіп,\nҚолымызбен жасаған жамандық үшін,\nАйыпсыз, Исаның қолы шегеленген!\n\n[Куплет 3]\nОл сенің жүрегіңді тебіренткенде,\nҚанша рет тастамаймын дедің, күнәларды!\nҚұмарлық күнәлары елестегенде,\nКеттің сен күнә толған шексіз шөлге!","songNumber":"107"},{"id":692,"title":"Егер болсам","text":"[Куплет 1]\nЕгер болсам өлімге жақын мен,\nҚорықпаймын еш жамандықтан,\nӨйткені Сен менімен біргесің,\nМәңгілік сүйем Сені, Ием.\nӨйткені Сен менімен біргесің,\nМәңгілік жолым Сен, Ием.\n\n[Припев 1]\nӘкеміз - Құдай,\nТәңірім - Сен, Иса,\nТыныштығым - Киелі Рух.","songNumber":"47"},{"id":532,"title":"Егер келсе қайғы","text":"[Куплет 1]\nЕгер келсе қайғы, Айтшы жәрдем кім берер?\nЖаныңды құтқару Құдай қолынан келер.\nКөзіңді аш достым, Қиындық көп өмірде,\nБақытты табарсың, Құдаймен тілдескенде.\n\n[Припев 1]\n// Түсінбей бұл дүние, жүрегіңді жаралар,\nТек бір Құдай сүйіп, қол ұшын саған созар. //\n\n[Куплет 2]\nАқтарғын жүректі, әлсіреген қайғырған,\nТіпті Ол түнекті, жарыққа айналдырар.\nСаған қол созады, мейірімді Иеміз\nБасып уайымыңды жаныңды жайландырар.","songNumber":"151"},{"id":897,"title":"Египет","text":"[Куплет 1]\nҰмытпаймын мен, бізді құтқарғаныңды,\nТеңізді жарып Мысырдан алып шықтың Сен.\n\n[Предприпев 1]\nҚұтқардың, суларды ұстап тұрдың Тәңір Ием\nО, Яхве!\n\n[Припев 1]\nКүреседі мен үшін, Оның күшімен жеңем\nАллелуйя, аллелуйя!\nТеңіздерді жарды Ием, тұңғиыққа жетелеп.\nАллелуйя, аллелуйя!\n\n[Куплет 2]\nКүдіз бұлт боп алдымызда жүресің,\nОт болып түнде Өзің қорғайсың Ием!\n\n[Бридж 1]\nМені іздеп келдің Сен,\nҚолымнан алдың Ием!\nУәделі жерге мені апардың Тәңірім!\nІстеріңді ұмытпаймын,\nМадақтаймын Сені\nМахаббатың өлімнің күшін жеңіп шықты!"},{"id":69,"title":"Ей, адамдар, жаралғандар","text":"[Куплет 1]\nЕй адамдар жаралғандар,\nБұл дүниед-е-е-е адаспаңдар.\nИса міне, келді бізге,\nҚұтқарлыла-а-ад көз ашқандар.\n\n[Припев 1]\nСол Иса Сол Иса\nОл Тәңір Ол Тәңір\nҚұтқарушым\nҚорғанышым\nҚуанышы-ы-ым\nЖұбанышым!\n\n[Куплет 2]\nОл сыйлады мәңгілікті,\nМойнымыздан алды жүкті.\nОл сыйлады Киелі Рухты,\nОған сенген болсын мықты.\n\n[Куплет 3]\nИса - Тәңір, Ол - мәңгілік,\nОл мәңгілік құрды билік.\nПатшалардың Патшасы,\nОл бәрінен тұрды биік.","songNumber":"48"},{"id":57,"title":"Ей, өмірім-ай, сен бізді ойландырдың","text":"[Куплет 1]\nЕй, өмірім-ай! сен бізді ойландырдың,\nТіршілік келеді әлі аттырып таңдарыңды.\nКүн кештік ойланумен, күн кештік толғанумен.\nҚұдай жоқ дегендердің барлығы,\nЖүрсіңдер алданумен.\nБір кезде сұрақ туар, артында түннің күн бар?\nИесіз зат бола ма дүниеде, кезі келсе соны ұғар.\n\n[Куплет 2]\nЕй, өмірім-ай, сен бізді аяладың,\nТағдырдың сан жолында сен бізді аямадың.\n// Біз Сенің бір қойыңбыз адасып жұртта қалған.\nСалқын жер тоңдырып жүр біздерді,\nТапсаңшы, О, Жасаған! //\n\n[Куплет 3]\nЕй, адамзат-ай, сен өткір дана едің,\nҒасырлар бойы өзің ойыңды шыңдап келдің,\n// Сен неге жүрегіңнен Құдайды итересің?\nАл ертең жанға жай таппай қалсаң,\nҚұдайды сонда іздерсің. //\n\n[Куплет 4]\nАу, досым қуана бер Құдайға келгеніңе,\nБіз мәңгі борыштамыз, сол Ұлы Иемізге.\n// Саған мен не арнадым жұмбақ толы өмірімнен?\nБолашақ рухымның келбетін көремін бір Өзіңнен. //","songNumber":"41"},{"id":848,"title":"Екі мың жыл бұрындау біздің заманнан","text":"[Куплет 1]\nЕкі мың жыл бұрындау біздің заманнан.\nКүнәні өтеп, айқышқа Иса керілді.\nҚұтқарам деп адамды, көгін тастады,\nҚұрбан болды тоқтыдай, пәк қан төгілді.\n\n[Припев 1]\nҚарашы сен Мәсіхтің мұңды көзіне,\nАйқышта Ол сен үшін көп қиналған-ды.\nЖанға медеу болам деп шақырар Иса,\nБілсең егер өкініп, ұялғанды.\n\n[Куплет 2]\nКөзіңді аш, Ол сені күнде күтіп жүр,\nҚұр бекерге келген жоқ құрбан боп жерге.\nАйналаңа қарашы, Мәсіх тұр шақырып,\nТәңірімнің мейірін қабыл ал дерге.\n\n[Куплет 3]\nТапсырсаңыз жүректі Иса Тәңірге,\nӘділетті, маңызды өмір сүресіз.\nШын жүректен:«кешірші, кешір...» десеңіз,\nҚұтқарылып, жұмаққа сөзсіз кіресіз."},{"id":47,"title":"Екі мың жылдай ертерек","text":"[Куплет 1]\nЕкі мың жылдай ертерек,\nАдам боп жерге келіпсің,\nМойныңа алып күнәмді,\nМен үшін азап шегіпсің.\n\n[Куплет 2]\nКөп күнә жасап мен білмей,\nЖүргенім саған мәлім-ді,\nКітаптан таптым Інжілдей,\nАрайлап атқан таңымды.\n\n[Куплет 3]\nДүниеге Иса жарықсың,\nМәңгілік өмір беретін.\nАйқышқа барып қағыпсың,\nТозақты біздер көретін.\n\n[Куплет 4]\nМейірім шашқан көзіңнен,\nҚұдайдың нұрын сеземін,\nКиелі Сенің Сөзіңнен,\nКүш-қуат алып келемін.\n\n[Куплет 5]\nКешігіп қалмай тұрғанда,\nКешірімін тез алуға,\nАсыққын сен де, бауырым,\nЖұмақта мәңгі болуға.","songNumber":"49"},{"id":547,"title":"Екі мың жыл өтіп кетті арадан","text":"[Куплет 1]\nЕкі мың жыл өтіп кетті арада,\nҚұтқарушы туылғалы анадан.\nДүние Оны танымады, білмеді.\nТанығандар мәңгілікке бірге енді.\n\n[Куплет 2]\nҚанша ғасыр өтіп кетті арадан,\nИса сөзі бізге келіп жеткенше.\nҚанша халық өтіп кетті дүниеден,\nИса сөзін естіместен, білместен.\n\n[Куплет 3]\nҚуанышпен қабыл алшы, ей, халқым,\nІзгі хабар келіп жетті бізге де.\nҚұдайыма мың бір шүкір айтамын,\nЖалғыз Ұлын таныстырған біздерге.\n\n[Куплет 4]\nӨткен күнге ой жіберіп қарасам,\nкүнә деген батпаққа мен батыппын.\nСол азаптан Иса мені шақырды,\nжол көрсетіп жұмақ деген қалаға.\n\n[Куплет 5]\nӨмірін де, өлімін де Исаның,\nпайғамбарлар айтып кеткен алдыңда.\nАзап шекті бүкіл дүние халқы үшін.\nАйналайын Иса деген атыңнан.\n\n[Куплет 6]\nШаршамастан дұшпанменен айқаста,\nаспандағы жәннәт деген жер үшін.\nТөкті қанын бүкіл дүние елі үшін,\nсол қанының бір тамшысы мен үшін."},{"id":946,"title":"Елім-ай","text":"[Куплет 1]\nҚазағым Құдайдың сүйікті елі,\nЖайсаң жан, пейілі кең, жомарт жүрек.\nИсаны Тәңірім деп жарияланған,\nМәңгілікке ие болдың сен Оған.\n\n[Припев 1]\n// Қазақ елім-ай, қазақ елім-ай.\nИсаны қабыл алып азат елім.\nҚазақ елім-ай, қазақ елім-ай,\nСен қанатыңды жайып самға елім. //\n\n[Куплет 2]\nИсаны құрбандыққа шалып Оны,\nӨмірді мағыналы етті Құдай.\nӘлемнің билеушісі бүгін саған,\nҚұшағын ашып тұр елім, кел Оған."},{"id":445,"title":"Еліңнің қамын ойла деп","text":"[Куплет 1]\nЕліңнің қамын ойла деп,\nЖерінді жаудан қорға деп,\nБассын ісің оңға деп,\nШайтанның құлы болма деп,\n// Бабаң берген ақ бата,\nБасыңа қонсын бақ бата! //\n\n[Куплет 2]\nҚұдайдан бата қонсын деп,\nҒұмырың ұзақ болсын деп,\nӨрісің малға толсын деп,\nЖуадай жауың солсын деп,\n// Атаң берген ақ бата,\nБасыңа қонсын бақ бата! //\n\n[Куплет 3]\nРахатың көрер алда деп,\nМәңгіліктен қалма деп,\nБетінен жанның алма деп,\nЖарыңа жара салма деп,\n// Әкең берген ақ бата,\nБасыңа қонсын бақ бата! //\n\n[Куплет 4]\n// Су сұраса сүт берген,\nНан сұраса бал берген,\nТүн ұйқысын төрт бөлген,\nСен үшін тілек тілеген,\nАнаң берген ақ бата,\nБасыңа қонсын бақ бата! //\n\n[Куплет 5]\nҚұдайсыз күнің құрысын,\nӨзіңе өзің ұрысың,\nҚұдайсыз мына жалғанда,\nҚашады сенің ырысың,\n// Құдай берсе ақ бата,\nБасыңа қонар бақ бата! //","songNumber":"213","alternateTitle":"Ақ бата"},{"id":843,"title":"Ең алдымен Құдайдың","text":"[Куплет 1]\nЕң алдымен Құдайдың\nПатшалығына кіруге,\nЖәне Оның әділдігіне\nИе болуға тырысыңдар!\n\n[Куплет 2]\nСонда қажет нәрселердің\nБәрі сендерге\nҚосымша беріледі.\nАллелуя! Аллелуя!","songNumber":"1","copyright":"1972 Мараната! Мусик"},{"id":962,"title":"Ең жоғары, ең ұлы..","text":"[Куплет 1]\nЕң - жоғары, ең - ұлы!\nТабиғаттан және барлық адамнан (бүкіл ғаламнан)!\nДаналықтан, барлық амалдан!\nӘуел бастан барсың бар болғансың!\n\n[Куплет 2]\nПатшалықтардан, тақтардан,\nТаңырқанатын, бар ғажайыптардан!\nБар байлық пен інжу-маржаннан!\nЕшкім тең келмес ең ұлысың!\n\n[Припев 1]\nШегеленді, қабірде жатты!\nӨлу үшін, өмірге келді!\nСолған гүлдей, тапталған мені,\nЖаны ашып, көтерді,\nЕң - ұлы!"},{"id":450,"title":"Ең керемет және ең күшті","text":"[Куплет 1]\nЕң керемет және ең күшті,\nКітаптардың кітабы, бұл Құдай Сөзі\nКиелі кітап: «Құдай әлемді сүйеді»-дейді.\n\n[Куплет 2]\nНұх, Мұса, Дәуіт және Рутты оқимыз одан,\nПайғамбарлар мен Иса Мәсіхті,\nО, балалар, кел Оған!\n\n[Куплет 3]\nИса көктен келді деп, Киелі кітап айтады,\nОл ауруларды емдеді,\nБіз үшін өліп, тірілді.","songNumber":"236"},{"id":495,"title":"Ештеңеден қорықпаңдар","text":"[Куплет 1]\nЕштеңеден қорықпаңдар,\nҚұдайым менің Ием сақтап қорғайды.\nАбыржыма үрейленбе,\nИем мені сақтап қорғайды.\n\n[Припев 1]\nЖүрегім әлсізденіп қалжыраса да,\nИем мені сақтап қорғайды.\nӨмірімде сұрапыл дауыл соғып тұрса да,\nИем мені сақтап қорғайды.\n\n[Припев 2]\nҚұдайым менің қамалым,\nҚұдайым менің қорғаным,\nҚұдайым менің үмітім,\nМенің күшім жаратқан Ием."},{"id":776,"title":"Жақсы істі ойлап","text":"[Куплет 1]\nЖақсы істі ойлап,\nАшуыңды тарат!\nМәсіхтің баласы тек соған қара!\n\n[Припев 1]\n//  Иса мейірімді және Киелі!\nБізде сол сияқты болайық енді! //\n\n[Куплет 2]\nЖаман рух әрқашан айналамызда,\nҚұлатқысы келіп жүр қасымызда.\n\n[Куплет 3]\nЖаман рухтан сақ бол, одан қорықпа,\nЖақсылыққа ұмтыл, жасып торықпа."},{"id":937,"title":"Жақында бұл дүниенің бітер күні","text":"[Куплет 1]\nЖақында бұл дүниенің бітер күні,\nІнжірдің ашылып, жайнар гүлі.\nБіреулердің жүректерін тітірентсе,\nАл бізді қуантады оның бүрі.\n\n[Припев 1]\nТәңірдің «келем» деген сөзі анық,\nБақыттың толығы ол, жүзі жарық.\nСоншалық аңсап жүрмін сол күнді,\nКелуін періштелер сырнай тартып.\n\n[Куплет 2]\nИса айтқан бір де сөзі өтіп кетпейді,\nСенбегеннің мәңгілікке қолы жетпейді.\nЕгерде шыдай алмай басың тартсаң,\nЖүрегіңе Киелі Рух қайта қонбайды.\n\n[Куплет 3]\nДаяр бол, соңғы сағат жақын қалды,\nІсіменен ақталар адам бар ма?\nЖоқ ондай, біреу де жоқ арамызда,\nАл Иса Өз қанымен жолды салды.","songNumber":"110"},{"id":438,"title":"Жақындағым келеді Саған, Тәңірім","text":"[Куплет 1]\nЖақындағым келеді Саған, Тәңірім,\nАйқышпен болса да көтерілсем.\nТек бір арманым бар: жақындасам Саған,\nЖақындасам Тәңірім, жақындасам.\n\n[Куплет 2]\nШөл даладағы мен жолаушымын,\nҚараңғы түнде тас жастанамын.\nЖүрегім әрқашан Саған жақын,\nТәңірім. Саған жақын Тәңірім, Саған жақын.\n\n[Куплет 3]\nОянып ұйқымнан ән саламын,\nМақтан етем Сені, жыламаймын.\nҚайғыда қуанам жақындасам Саған.\nЖақындасам Тәңірім, жақындасам.\n\n[Куплет 4]\nЖердегі өмірімді бітіргенде,\nАбыройға мені бөлегенде,\nМәңгі қуанамын, жақындасам Саған.\nЖақындасам Тәңірім, жақындасам.","songNumber":"14"},{"id":882,"title":"Жақынсың Сен маған, қымбатсың Әкежан","text":"[Куплет 1]\n//  Жақынсың Сен маған, қымбатсың Әкежан!\nТастамайсың Сен, балаңды,\nТек адалдықпен, шыдамдылықпен\nБалаңды құтқарасың! //\n\n[Припев 1]\n//  Шын жүректен Сені іздеймін,\nСенемін мен, Сені табамын!\nАлыс емес, Сен жақындасың!\nІздегендерге, табыласың,\nЕсік қаққанға, ашыласың,\nӨйткені Сен - тірі Құдайсың!\nКешіріп, сүйесің,\nСен мені құтқарған туған Әкемсің! //\n\n[Куплет 2]\n// Көрмесем алыстан, жақындайсың маған\nСөйлейсің Сен жүрегіме,\nДауысты естіп жігерім артып\nӘн-жырымды арнаймын. //"},{"id":248,"title":"Жалғыз дауыс жүрегімде","text":"[Куплет 1]\nЖалғыз дауыс, жүрегімде!\nЖалғыз, Саған - Әуенімде!\nЖалғыз дауыс, жүрегімде!\nЖалғыз, Саған - Әуенімде!\n\n[Припев 1]\nКиелі! Киелі - Құд(і)ретті Құдай,Ием!\nКиелі! Киелі - Құд(і)ретті Құдай,Ием!\n\n[Бридж 1]\nТеңдесер жан жоқ, Саған - Киелі! Сен - Киелі!\nТеңдесер жан жоқ, Саған - Киелі! Сен - Киелі !\n\n[Куплет 2]\nAnd only one word comes to mind. There's only one word to describe\nOnly one word comes to mind, there's only one word to describe\n\n[Припев 2]\nHoly, Holy! Lord, God, Almighty!\nHoly, Holy! Lord, God, Almighty!\n\n[Бридж 2]\nThere is no one like You, You are holy, holy","alternateTitle":"Киелі, Құдіретті-Құдай Ием!"},{"id":212,"title":"Жалғыз Сен менің үміт артарымсың","text":"[Куплет 1]\nЖалғыз Сен менің үміт артарымсың\nҚорғаным қалқанымсың\nБір Өзіңе ғана сенімімді арттым\nСен естідің мені!\nСен мені терең ордан алып шығардың,\nСенімімді нығайттың\nАузыма ерік бердің Құдайым\nМәңгілік мадақтайын\n\n[Припев 1]\nЛа-ла-ла-ла-ла-ла-ла-ла-ла\nМәңгілік мадақтайын!\nСенің еркіңді орындайын әрдайым\nЗаңдарың жүрегімде\nКиелі Рухың апарады\nӘділдер мекеніне"},{"id":166,"title":"Жаман ойлар мазалайды жанымды","text":"[Куплет 1]\nЖаман ойлар мазалайды жанымды.\nЖаным талай ойға еріп жаңылды.\nАрылмаған азаптың дәмін таттым ұзақ тым.\nҚайғысына көндім бір сәт тозақтың.\n\n[Куплет 2]\nЖаман сезім жаулағандай бойымды.\nЖүрегімді жаралады ой-мұңды.\nБәрі болды өзімнен алыс кетіп жүзіңнен.\nБұл өмірге алаңдаған кезінен.\n\n[Припев 1]\nҚиналғанда тек Өзіңді іздеймін, неге?\nАйтшы маған Тәңірім,\nқандай менің өмірім.\nСенсіз өткен мағынасыз әр күнім.\n\n[Куплет 3]\nАрам ойдан арылдым ба білмедім.\nБар білерім Әке сөзін сермедім.\nШектім соның зардабын, жоғалғандай арманым.\nБілмегендей бұл өмірдің жалғанын.\n\n[Куплет 4]\nЖан-дүнием сөздеріңе шөлдеген.\nРухым бірақ тірі әлі өлмеген.\nӘке дейді дауыстап, алақаныңнан ұстап.\nӨлі сезім, мәнсіз ойларды тастап.","songNumber":"201"},{"id":108,"title":"Жанарыма анықтап зер сал аспан көзімен","text":"[Куплет 1]\nЖанарыма анықтап зер сал аспан көзімен,\nҮңіл жүрек түбіне, жыласын жан-дүнием.\nМейірімді көзқарасың жүректі жұбатар,\nҰғынатын тек Сенсің, қайғы келсе жылатар.\n\n[Припев 1]\nСенің әсем көздеріңнен танимын аспанды,\nБілесің Өзің мендегі бар тілек, жоспарды.\nӨмірімді көресің айқын аспан көзіңмен,\nАзап-қайғымды көріп жұбатасың сөзіңмен.\nИем Сен, Тәңір Сен, Жалғыз Сен.\n\n[Куплет 2]\nКейде жолым бұлыңғыр тартып шаршағанда мен,\nСұрақ қоямын түңілгенде осы өмірден.\nЖаным еңіреп жылағанда маған таядың,\nКөк аспандық көзіңмен көріп, мені аядың.\n\n[Куплет 3]\nКездесем жұлдыз арасынан тіккен көзіңе,\nБар үміт арманым - қашан аласың Өзіңе.\nБақыт жайлаған мәңгі жарық әлемде Сені,\nКөрем шексіз туыстық көзіңді мейірімді.","songNumber":"152"},{"id":870,"title":"Жан-дүнием Иемді мадақтайды","text":"[Куплет 1]\n//  Жан-дүнием Иемді мадақтайды,\nҚұтқарушы - Құдайды!\nҚұлының дәрежесіне қарайды,\nРақымымен көтереді! //\n\n[Припев 1]\n//  Есімі Киелі құдіретті,\nӨз қолынан құдіретін танытты!\nТозақтың мәңгі жанған отынан Ол,\nСүйіп мені алып шықты! //"},{"id":854,"title":"Жан-жағыма қарадым","text":"[Куплет 1]\nЖан-жағыма қарадым, қайдан көмек келер деп,\nТәңірім маған қашан, бостандық берер деп.\nЖан-жағыма қарадым, қайдан көмек келер деп,\nТәңірім маған қашан, бостандық берер деп.\n\n[Припев 1]\nТәңірім, Ол мені естіді, қаққандай болды есікті,\nӨмірімді, Тәңіріме күмәнсіз толық арнаймын Оған,\nЖалғыз арман, жалғыз өмір, тек сол, қалған!\n\n[Куплет 2]\nТәңірім мені жұбатты, сәбиіндей қуантты,\nАуырып тұрған жаныма, аямай берді қуатты.\nқуанышым да Өзіңсін, Жұбанышым да Өзіңсің,\nСенсіз жаным жаралы, Сенсіз күнім қараңғы!"},{"id":959,"title":"Жаным жай табады","text":"[Куплет 1]\n//// Жаным жай табады. ////\nҚұдайда!\n\n[Припев 1]\n// Өзендей бейбіт ғұмыр кешсем де,\nҚайғы бассада толқындай,\nҚандай жағдай болмасада өмірім\nЖаным жай табады Құдайда! //"},{"id":253,"title":"Жаным құтқарылды","text":"[Куплет 1]\nЖаным құтқарылды\nОның қанымен жуылды\nСенемің, сенемің.\nМәңгіге қорқыныш жоқ\nАуырудаң сауықтым мен\nСенемің, сенемің.\nМен туымды көтеремін\nСебебі өлім жеңілді\n\n[Припев 1]\nҚұтқарушым тірі,\nҚұтқарушым тірі.\n\n[Бридж 1]\nҚұлдықты бұзып, мені көтерді\nЖақында Құтқарушым келеді\nМадақтаймын мен Сені"},{"id":686,"title":"Жаным ізде Исаны","text":"[Куплет 1]\nЖаным ізде Исаны\nОл өміріңнің жолы\nОған келгенде сен\nҚуанышқа кенелесін\nЖаным ізде Исаны\nСен күнәні жеңе аласың\nСеніммен күшке\nИе боласың мәңгілік\n\n[Припев 1]\nО, Иса, Иса\nСаған мен келемін\nБауырыңа мені тартшы, о, Иса\nО, Иса, Иса\nСаған мен келемін\nСені сүйемін мәңгі бақи, о, Иса\n\n[Куплет 2]\nЖаным ізде Исаны\nОл көз жасыңды сүртеді\nШын жүрекпен келсең\nОл сені түсінеді\nЖаным ізде Исаны\nАрманың орындалады\nИсаны танып білу\nШынайы мәңгі өмір"},{"id":184,"title":"Жаңа әнмен мадақтаймын Сені Тәңірім","text":"[Куплет 1]\nЖаңа әнмен мадақтаймын Сені Тәңірім,\nҚосамын ән мен жырға Сені Құдай Ием.\nАспаннан жарылқауды жаңбырдай төгесін,\nМен оны қабылдаймын Сенен деп, Тәңірім.\n\n[Припев 1]\nҚұтқарушым, Тәңірім Сен\nЖаратушым, Ием менің\nЖұбанышым Сен менің, Иса.","songNumber":"56"},{"id":257,"title":"Жаңбыр, жаңбыр","text":"[Куплет 1]\nҚұдай Өз мейірімін бізге төкті\nРақымын моншақтай бізге шашты\nҚұшағына алды, билік бізге берді\nКиелі Рухын бізге сыйлады\n\n[Припев 1]\nЖаңбыр, жаңбыр, жаңбыр жауады\nОтпен бізді толтырады Киелі Рух, Киелі Рух\nЖүрегім лаулап жаңады, жалғыз Саған арналады\nКиелі Рух Киелі Рух\n\n[Бридж 1]\nКиелі Рухты біз сүйеміз\nКиелі Рухпен жетеленеміз\nКиелі Рухты біз сеземіз\nКиелі Рух әрдайым қасымда!"},{"id":940,"title":"Жаратқан бар әлемді Құдай Ием","text":"[Куплет 1]\nЖаратқан бар әлемді Құдай Ием,\nМейірімді, кең пейілді жан Ием.\n// Бір Өзіңсің мәңгілікке жетелер,\nБір Өзіңсің Құтқарушым, Қорғаушым. //\n\n[Припев 1]\nТуған елім, туған жерім, қазағым,\nҚанша қасірет, қаншама көп азабың.\n// Көзіңді ашып, жан-жағыңа қарашы,\nЖалған өмір жетегінде жүрсің сен. //\n\n[Куплет 2]\nБауырластар, абзал достар, туысқандар,\nҚұдай Ұлы Иса Мәсіхті қабылдаңдар.\n// Бойыңдағы бар күнәңді мойындап,\nТәубеге кеп, бір Құдайға сиыныңдар. //\n\n[Куплет 3]\nШын жүректен сенім артсаң Құдайға,\nКенелерсің қуанышқа, бақытқа.\n// Иса Тәңір шексіз сүйеді бәріңізді,\nҮлкен-кіші, жасыменен кәріңізді. //","songNumber":"111"},{"id":737,"title":"Жаратқанды мақта халық!","text":"[Куплет 1]\nЖаратқанды мақта халық!\nЖырла Оған «аллелуйя»! (қазақша)\n\n[Куплет 2]\nЖаратқанды даңқта баарың!\nЫрда ғыла «аллелуйя» (қырғызша)\n\n[Куплет 3]\nСлавьте Творца, все народы!\nПойте Ему «аллелуйя» (орысша)\n\n[Куплет 4]\nЯратқанни махта халик,\nНақша ейтип «аллелуйя»! (ұйғырша)\n\n[Куплет 5]\nLobe den Herrn meine Seele\nund Seinen heiligen Namen,\nwas Er dir Gutes getan hat,\nSeele und vergiss es nicht! Amen.\n// Lobe, lobe den Herrn meine Seele // (немісше)","songNumber":"44"},{"id":423,"title":"Жаратқан жерді де, аспанды да","text":"[Куплет 1]\nЖаратқан жерді де, аспанды да.\nШын сүйіп бас ием Құдайыма.\nАдамзат күнәдан арылсын деп\nЖіберді Өз Ұлы Исаны да.\n\n[Припев 1]\nЖетеле мені, жетеле,\nҒажайып жұмақ төріне.\nРухыңды берсең кеудеме,\nМәңгілік құлмын Өзіңе.\n// Өзіңе ғана бағынам,\nӨзіңе ғана табынам.\nӨзіңнен артық панам жоқ,\nҚұдайым Саған сиынам. //\n\n[Куплет 2]\nАдасып көп жылдар шаршадым мен,\nСонда да тыныштық таппадым мен.\nСол сәтте Құдайды ойға алып едім\nБақытқа кенеліп шаттандым мен.\n\n[Куплет 3]\nОқыдым Киелі кітабыңды.\nЖүрегім азаптан құтқарылды.\nҰмыттым қайғы мен азабымды,\nӨйткені таныдым Құдайымды.","songNumber":"112","alternateTitle":"Жетеле мені, жетеле"},{"id":245,"title":"Жаратқан Ием - Бағушым","text":"[Куплет 1]\nЖаратқан Ием - Бағушым,\nМен еш нәрседен тарықпаймын.\nМені жайлауға жаяды,\nТұнық суға апарады.\n\n[Припев 1]\nО, Иса - Құтқарушым,\nО, Иса - менің Бағушым,\nО, Иса - Жұбатушым,\nО, Иса - менің Ұстазым.\n\n[Куплет 2]\nЖаныма Ол күш береді,\nЖетектеп түзу жолменен.\nҚараңғы жерде жүрсем де,\nҚауіп-қатерден қорықпаймын.\n\n[Куплет 3]\nСебебі Ием қасымда,\nМаған сүйеніш болады.\nДұшпандарымның алдында,\nМаған дастархан жаяды.","songNumber":"45"},{"id":542,"title":"Жаратқан Ием-Бағушым","text":"[Куплет 1]\nЖаратқан Ием-Бағушым.\nМен еш нәрседен тарықпаймын.\nМені жайлауға жаяды,\nТұнық суға апарады.\n\n[Припев 1]\nО, Иса - Құтқарушым!\nО, ИСА-менің Бағушым!\nО, Иса-Жұбатушым!\nО, Иса -менің Ұстазым!\n\n[Куплет 2]\nЖаныма Ол күш береді,\nЖетектеп түзу жолменен.\nҚараңғыда да жүрсем де,\nҚауіп- қатерден қорықпаймын.\n\n[Куплет 3]\nСебебі Ием қасымда,\nМаған сүйеніш болады.\nДұшпандарымның алдында,\nМаған дастархан жаяды."},{"id":260,"title":"Жаратқан Ием, менің Бағушым","text":"[Куплет 1]\nЖаратқан Ием, менің Бағушым!\nЖаратқан Ием, менің Бағушым!\nМен ешнәрседен де, тарықпаймын!\nМен ешнәрседен де, тарықпаймын!\nМені жасыл жайлауға жайып,\nТұнық суға жетелейді!"},{"id":958,"title":"Жарат меде таза жүректі","text":"[Куплет 1]\n/// Жарат меде таза жүректі, О, Тәңірім!\nӘділдіктің Рухы жаңартшы! ///\n\n[Припев 1]\n// Алыстатпа мені Сенің жүзіңнен,\nАжыратпа мені Рухыңнан.\nҚұтарылу алдық, қуанышымды қайтаршы.\nМенің рухымды жаңартшы. //","copyright":"1988 Оне Вай Министриес"},{"id":580,"title":"Жаратушымды мен мадақтап","text":"[Куплет 1]\nЖаратушымды мен мадақтап,\nӘніме қосқым келеді.\n// Бізге келді аспанды тастап,\nҚұтқарды бізді себебі //\n\n[Куплет 2]\nҚұтқарушымды мен даңқтаймын,\nРақымы, мейірі үшін.\n// Сөздерін есімде сақтаймын,\nЖүрекке берді Өз күшін //\n\n[Куплет 3]\nБар адамзаттың, бар әлемнің,\nАлғысына Құдай лайық.\n// Ол Патшасы жер менен көктің,\nАлдына Оның барайық //","songNumber":"238"},{"id":186,"title":"Жаратушым, Құтқарушым","text":"[Куплет 1]\nЖаратушым, Құтқарушым,\nЖанымды мен Саған бағыштаймын.\nАдасқан едім, қара түнекте\nЖарық боп нұрыңды төктің Құтқарушым.\n\n[Припев 1]\nАлғыс Саған Иса!\nТабынамын мен Ием.\nАлғыс Саған Иса, Құтқарушым.","songNumber":"54"},{"id":18,"title":"Жаратушымның бар ойын","text":"[Куплет 1]\nЖаратушымның бар ойын,\nӘзірше толық білмеймін.\nТек білерім Иса Ием,\nОң жағында Құдайдың.\n\n[Куплет 2]\nКиелі сөзден оқыдым,\nҚұтқарушым екенін.\nСанаммен Оны қабылдап,\nЖүрегімменен сенемін.\nКөктегі орнын қалдырған,\nАдамзат үшін жан қиған.\nТүсінбей мен де бір кезде,\nҚабылдаудан бас тартқам.\n\n[Припев 1]\n// Иса тірі, шын сүйеді,\nТастамайды Ол ешқашан.\nКеше және дәл бүгінде,\nМәңгілік бірге әрқашан. // -рет\n\n[Куплет 3]\nМен үшін өліп, тірілген,\nИсаға анық сенемін.\nҚұтқарушым, Тәңірім,\nСоңынан мәңгі еремін.\n\n[Куплет 4]\nАқ бұлтқа мініп аспаннан,\nҚайтадан жерге келеді.\nТәубеге келсең бауырым,\nМәңгілік өмір береді.","copyright":"2005 Бридге Буилдинг Мусик, Инк."},{"id":653,"title":"Жаратылыс ән салады","text":"[Куплет 1]\nЖаратылыс ән салад(ы),\nРухың мен шындықта табынат.\nМадақталсын Ол ғана,\nҚұдай Ұлы Иса.\n\n[Куплет 2]\nМадақтайды тіршілік,\nСен ғана шын ұлысың.\nМәңгіге тек Сен ғана\nБилік етесің.\n\n[Припев 1]\nҚұдай - Ұлы!\nМадаққа толады аспан мен жер.\nҚұрметтейді Есіміңді бүкіл жер.\nҚұдай - Ұлы!\nДәріпте барлық жер, барлық аспан.\nАтыңды мадақтау үшін жаралдық,\nСенің Атыңды.\n\n[Куплет 3]\nБарлығын Саған берем,\nҮйрет өмір сүруді.\nОтыңды менде жақшы.\nБәрі естісін, бәрі көрсін.\n\n[Куплет 4]\nКиелісің Тәңір!\nЖер жар салат! Жер жар салат!","songNumber":"52","copyright":"2001 Хиллсонг Мусик Публишинг"},{"id":148,"title":"Жарияла Исаның жеңісін","text":"[Куплет 1]\nЖарияла Исаның жеңісін,\nОл саған берді сенімін.\nЕнді сен махаббат туын\nҰстай аласың биікте.\n\n[Припев 1]\nМадақта, мадақта, мадақта Иеңді!","songNumber":"3"},{"id":624,"title":"Жарқырайды Ием, салтанат нұрында!","text":"[Куплет 1]\nЖарқырайды Ием, салтанат нұрында!\nЖырласын бар әлем, әндетсін шаттана!\nНұрланады түнек, шұғыласынан - Оның!\nДүрліктірер үні, тылсым тұңғыйықты.\n\n[Припев 1]\nТәңірім - Сен ұлы!\nШырқа бізбен бірге - Сен ұлы!\nТанып-білсін дүние!\nТәңірім - Сен ұлы!\n\n[Куплет 2]\nБилігің мәңгілік, бар тірлік - қолыңда,\nӘзел де,ақырет, әзел де,ақырет\nТәңірім - Үшбірлік: Әке, Ұл, Киелі Рух!\nҚозы да, Қобылан! Қозы да, Қобылан!\n\n[Бридж 1]\n//  Қастерлі, жоғарысың!\nАбыройға - Сен, лайықсың!\nТолғайды жан дүнием, Сен - ұлы!  //\n\n[Бридж 2]\n///   Аллелуйя! Аллелуйя! Аллелуйя!\nСен - ұлы!  ///","alternateTitle":"Патшалық салтанат"},{"id":122,"title":"Жарқырап кетті айнала","text":"[Куплет 1]\nЖарқырап кетті айнала, нұрға бөлеп аймақты,\nДемалған малшыларға, топ періште үн қатты:\nТоп періште үн қатты, үн қатты.\nБетлехемге бет бұрыңдар, бесік жыры тойлансын!\nҚұтқарушы келді әлемге, барлық адам ойлансын.\nБарлық адам ойлансын, ойлансын.\n\n[Припев 1]\nҚуанып шаттаныңдар!\nМәсіх келді дүниеге,\nҚарсы алыңдар адамзат,\nБаршаға жар салыңдар.\nҚуанып шаттаныңдар,\nТаңғажайып күйге еніп,\nҒажапқа тамсаныңдар, тамсаныңдар.\n\n[Куплет 2]\nҚұндақтаулы бала жатыр,\nМал байлаған ақырда,\nНұр бейнелі пана жатыр,\nХалқы күткен ғасырлар.\nХалқы күткен ғасырлар, ғасырлар.\nМалшылардан елге хабар,\nОсылайша таралды,\nКиелі Рух көлеңкесі бізге пана бере алды,\nБізге пана бере алды, бере алды.\n\n[Припев 2]\nҚуанып шаттаныңдар!\nМәсіх келді дүниеге,\nҚарсы алыңдар адамзат,\nБаршаға жар салыңдар.\nҚуанып шаттаныңдар,\nТаңғажайып күйге еніп,\nҒажапқа тамсаныңдар, ән салыңдар.\nӘн салыңдар Иемізге, ән салыңдар.","songNumber":"162"},{"id":702,"title":"Жарылқашы, жан-дүнием","text":"[Куплет 1]\n// Иса Мәсіх құрбан боп,\nҚұтқарды тозақтан.\nЖарасы Иса Мәсіхтің\nСауықтырды еш күдігім жоқ.\nҚаны Иса Мәсіхтің\nТазартты күнәдан.\nӨлімі Иса Мәсіхтің\nМәңгілік өмір берді. //\n\n[Припев 1]\nЖарылқашы, жан-дүнием, Тәңірді,\nҚасиетті атын шын жүректен ардақта.\nЖарылқашы, жан-дүнием, Тәңірді,\nЕш ұмытпашы, бар жақсылықтарын Оның.\nЕсімім де көкте тіркелді деп мен сенем","songNumber":"53"},{"id":876,"title":"Жасама күнә ей халқым","text":"[Куплет 1]\n//   Таңдап откен әуелі бастан,\nКүналармен ажыратып тастап\nСен таңдаған жұлдыз мен едім о-о-ой!\nСаған куә болады аспан!  //\n\n[Припев 1]\n//   Жасама күнә ей халқым,\nЖақындап қара Құдайға!\nСөздеріме құлақ сал,\nҚұдай сөзін айтамын!  //\n\n[Куплет 2]\n//  Жақын барып жаныңа халқым,\nҚұдай сөзін жеткізейін,\nТыңда менің сөзімді халқым, о-о-ой!\nАзаттығымды білдірейін!  //\n\n[Куплет 3]\n//  Тыңда, тыңда, тыңдаңыздар,\nҚұдай сөзін айтайын ұйқас\nӨлеңменен айтайын достар, о-о-ой!\nҚүтқарушы болады Иса!  //"},{"id":819,"title":"Жас кезімнен мені сақтап жүрдің Сен","text":"[Куплет 1]\nЖас кезімнен мені сақтап тұрдың Сен,\nӨмірімнің қиындығын көріп Сен.\nҚұтқардың ғой сол қиындық кездерден,\nТанып Сені Әке жүрмін енді мен.\n\n[Припев 1]\n//  Жан Ә--кем! Мейірімді Әкем!\nСа-ғын-дым мен Сені, мейірім-ді Әкем! //\n\n[Куплет 2]\nӨмір бойы ойымда Сен тұрасың,\nҰлың Иса Мәсіх арқылы тірілдім.\nБұл өмірде Сенің асыл Сөзіңе\nЖүрегімнің төрінен жай беремін.","songNumber":"50","alternateTitle":"Жан Әкем! Мейірімді Әкем!"},{"id":1000,"title":"Жас кезімнен мені сақтап жүрдің Сен","text":"[Куплет 1]\nЖас кезімнен мені сақтап тұрдың Сен,\nӨмірімнің қиындығын көріп е(ді)ң.\nАзат еттің сол қиындық кезеңнен,\nАлғысымды жеткіземін әніммен.\n\n[Припев 1]\n//  Жан Ә--кем! Мейірімді Әкем!\nСа-ғын-дым мен Сені, мейірім-ді Әкем! //\n\n[Куплет 2]\nӘрқашанда ойымда Сен тұрасың,\nЖаңа өмір сыйлап мені қуанттың.\nБұл өмірде Сенің асыл Сөзіңе,\nОрын берем жүрегімнің төрінен."},{"id":875,"title":"Жасыл жайлауға жаятын, тұнық суға апаратын","text":"[Куплет 1]\nЖасыл жайлауға жаятын,\nтұнық суға апаратын!\nЖаныма күш тарататын,\nТура жолмен жетелейтін,\n\n[Припев 1]\nБағушым менің, Бағушым!\nБағушым менің, Бағушым!\n\n[Куплет 2]\n//  Адасқандарға, жол көрсететін,\nЖоғалғандарды іздеп табатын,\nҚиналғандарға жігер беретін,\nБағушым менің, Бағушым!  //"},{"id":485,"title":"Жасыл жайлауға мені жаясың","text":"[Куплет 1]\nЖасыл жайлауға мені жаясың,\nЖақсыны жаныма жаудырасың.\nСүт ішкендей мен еш тарықпаймын,\nКиелі Сөзіңді іше берем.\nҚұшағыңды жайып қарсы аласың,\nСонда мен қуанып табынамын\nБағушым менің, балаңмын Сенің,\nМейірімді Әкем!\n\n[Куплет 2]\nКүнәкар болған мені құтқардың,\nҚұрбандық қаныңмен ағарттың.\nҚұнымды төлеген, мен үшін өлген,\nҚұтқарушым, Саған сенем.\nҚұлақ маған асып, қабыл алдың,\nЕнді мен қуанып, бағынамын,\nҚұдайым менің, құлыңмын Сенің,\nМейірімді Ием.","songNumber":"66","alternateTitle":"Водишь к лугам Ты, зеленым,"},{"id":157,"title":"Жасың да, кәрің","text":"[Куплет 1]\nЖасың да, кәрің,\nЖақын да, алыс тұрғандар.\nШүкір қылайық!  Аман болайық.\n\n[Припев 1]\nҚұдайым Саған рахмет айтамыз!\nАлғысқа лайықсың!\n\n[Куплет 2]\nАрық да, толық,\nДара да, егіз жараңдар.\nШүкір қылайық! Аман болайық!\n\n[Бридж 1]\nҚұдайым Саған рахмет айтамыз!\nАлғысқа лайықсың!\n\n[Куплет 3]\nЖиналған халықтар,\nЖаны қиналып тұрғандар.\nШүкір қылайық! Аман болайық!\n\n[Бридж 2]\nҚұдайым Саған рахмет айтамыз!\nАлғысқа лайықсың!","songNumber":"47"},{"id":473,"title":"Жауға жау болуға асықпа","text":"[Куплет 1]\nЖауға жау болуға асықпа,\nІріткі салуға асықпа.\nҚызғана қарауға асықпа,\nКемшілік санауға асықпа...\n\n[Припев 1]\nАсықпа, асықпа,\nСоттауға тым асықпа,\nБасқаны даттауға асықпа.\nАсықпа, асықпа,\nКек сақтауға асықпа\nАрыңнан аттауға асықпа.\n\n[Куплет 2]\nҚатігез болуға асықпа,\nАшуға толуға асықпа.\nӨсек сөз тасуға асықпа,\nШындықтан қашуға асықпа.\n\n[Куплет 3]\nЖанжалды бастауға асықпа,\nЖүректі ластауға асықпа.\nЖалған сөз айтуға асықпа,\nСенімнен қайтуға асықпа.","songNumber":"199"},{"id":91,"title":"Жедел хабар","text":"[Куплет 1]\nЖедел хабар келеді,\nКеледі келеді!\nНе болып қалды, не болып қалды?\nБетлехем қаласында,\nҚаласында, қаласында,\nТуды Иса - Мәсіх!\nТуды Иса - Мәсіх!\n\n[Куплет 2]\nОған орын болмады,\nБолмады, болмады,\nАдам үйінде, адам үйінде,\nКедейлікте туылды,\nТуылды,туылды,\nАқырда жатты,\nАқырда жатты!\n\n[Куплет 3]\nБақташылар сол түні,\nсол түні, сол түні,\nҚуанды шексіз, Қуанды шексіз,\nПеріштелер жариялап,\nжариялап, жариялап,\nҚуанды шексіз,\nҚуанды шексіз.\n\n[Куплет 4]\nКөкте Құдай даңқталсын,\nДаңқталсын, даңқталсын,\nБерген Ұлы үшін! Берген Ұлы үшін!\nЖер жүзінде тыныштық,\nТыныштық, тыныштық,\nБолсын мәңгілік,\nБолсын мәңгілік.","songNumber":"239"},{"id":631,"title":"Жексенбі күн Мәриям Мағдалалық","text":"[Куплет 1]\nЖексенбі күн Мәриям Мағдалалық,\nӘйелдермен иіс майларын алып,\nКеле жатыр қабірге азаланып,\n«Кім алар қақпақ тасты» - деп ойланып.\n\n[Куплет 2]\nОлар келіп қараса, тас алынған,\nТұрып қалды әйелдер аң-таң болған.\nИеміз жоқ қабірге қайда қойған,\nБілмейміз кетті Оны кімдер алып.\n\n[Куплет 3]\nӘйелдерге періштелер тіл қатты,\nБұл өлімнен қайта тіріліп кетті.\nБізде ұйықтап Ол мүмкін емес Құдайдың,\nШындықты қаламайтын өлгендігіне\n\n[Куплет 4]\nЕммаусқа барған екі шәкіртке,\nБұл өмірде қиналған кезімізде.\nҚасымызға Тәңір келгендіктен,\nҒажап сөзін түсірдік есімізге.\n\n[Куплет 5]\nКиелі Сөз мәнін тек Ол ашады,\nЖүрегіміз сол сәтте жалындайды.\nСиынамын тек Оған үміт артып,\nТәңірмен қандай қамал алынбайды?"},{"id":482,"title":"Желкенші","text":"[Куплет 1]\n//   Мен теңіздегі ақ желкендей,\nӘкетайымның құшағында,\nСенім, үмітпен, сүйіспеншілікте!\nАмандық пен тыныштықта,\nШындыққа жетелейтін мені,\nЖалғыз ғана сүйіспеншілік!  //\n\n[Припев 1]\n//   Мұхитта шексіз төгілген махаббатың Сенің,\nТолқындай маған махаббатың әр күнде төгілсін!  //\n\n[Бридж 1]\n//  Иса Сен шынайы өмірімсің!\nИса Сен шындық жол!  //"},{"id":975,"title":"Жел соғып тұр","text":"[Куплет 1]\nЖел соғып тұр, жел соғып тұр,\nБара, бара қаттырақ."},{"id":400,"title":"Жеңімпаз болдық","text":"[Куплет 1]\nЖеңімпаз болдық\nОның төккен қанымен.\nОның қанының күшімен тұрамыз.\nЖеңімпаз болдық\nОның төккен қанымен,\nОл жеткізді жеңіске бізді.","songNumber":"55"},{"id":913,"title":"Жеңіс берген Исаға мадақ айтып табынамын","text":"[Куплет 1]\nЖеңіс берген Исаға мадақ айтып табынамын,\nШындықта Рухыммен жалғыз Соған табынамын!\nӨмір кітабына жазды есімімді Өз қанымен,\nЖаралары арқылы, жазды дерттерімнен!\n\n[Припев 1]\nАйқыш ағаш көтерген, Иеме табынамын!\nАйқыш ағашқа түйрелген Иеме мойынсынам!\n// Әр тамшы қаныңа, төгілген айқышта\nАлғысымды айтам Исаға! //"},{"id":707,"title":"Жеңіс ұраны","text":"[Куплет 1]\nКел Иса, Патшамсың,\nСен үшін ән саламын.\nӘрқашан мадақтаймын,\nҒажапсың Сен мәңгілік.\n\n[Куплет 2]\nКел, Иса - Иемсің,\nСөздеріңді тыңдаймын.\nПатшалығыңды көрейін\nМен емес Өзің құрған.\n\n[Припев 1]\nДаңқ, құрмет тек Тоқтыға,\nӨз мекеніңе алшы.\nАтыңмен біз жеңеміз.\nИса Атын жариялаймыз.\n\n[Бридж 1]\nКел, Иуда Арыстаны,\nСондай Құдіретті.\nКел, Иуда Арыстаны,\nНеткен кереметсің.","songNumber":"56"},{"id":694,"title":"Жер бетінде","text":"[Куплет 1]\n// Жер бетінде тек бір Тәңір бар -\nИса Мәсіх. //\n\n[Куплет 2]\nҚұдай жалғыз бүкіл әлемде,\nТәңір бәріне Ие.\nОның атында құтқарылу бар,\nИса бәріне Ие.\n\n[Куплет 3]\n//// Иса бәріне Ие. ////","songNumber":"57"},{"id":158,"title":"Жер бетіне сәуле төккен","text":"[Куплет 1]\nЖер бетіне сәуле төккен,\nБасқа нұрдан жарқын!\nАспан нұры жүрегімде,\nСол нұр - Құтқарушым.\n\n[Припев 1]\nҒажап шырақ, ғажап шырақ!\nБақытты күндер қандай ғажап!\nИса жүзі көз алдымда,\nАлдымда ғажап шырақ!\n\n[Куплет 2]\nТамаша жыр жүрегімде\nПатшаны мақтайды.\nДауыстап ән салмасам да,\nИем естіп тұрады.\n\n[Куплет 3]\nКөктем келді жүрегіме,\nМәсіх жақындады,\nТүңілген кезеңдерімде,\nЖұбанышын берді.\n\n[Куплет 4]\nЖүрегімде шаттық нұры,\nАйтам мақтау әнін.\nСыйға тартқан бақыт күні,\nИгілігі үшін.","songNumber":"178"},{"id":235,"title":"Жер жүзінде заңғар көкте","text":"[Куплет 1]\nЖер жүзінде заңғар көкте\nҚұдай мәңгі мадақталсын.\nӨзі риза болғандарға,\nТек амандық болсын.\n\n[Припев 1]\nДәуіт Ұлы туылғанда,\nКөкте осы ән шырқалған,\nТөріндегі көктің әнге,\nҚосайық үн біз де бірге.\n\n[Куплет 2]\nЖаңа жылда жаңартады,\nКүш-қуатын дарытады,\nШаттанып біз әндетеміз,\nАлғыс жырын төгілтеміз.\nИса Мәсіхтің тағында\nЖиналғанда киелілер,\nШаттық әні шарықтайды,\nМәңгілікке қалықтайды.","songNumber":"163"},{"id":591,"title":"Жер мен аспан, таусылмас көп дастан","text":"[Куплет 1]\nЖер мен аспан, таусылмас көп дастан,\nТәңір о бастан Өз қолымен орнатқан.\nКөп алғыс айтам Саған, әлемді Жаратқан\nТәңір, алғыс Саған.\n\n[Припев 1]\nТұрады тек сүйіспеншіліктен\nӨзің жаратқан әсем әлемің.\nҮстімде өз рақым-мейірімің,\nЖүрекке ыстық жолдаған сәлемің.\n\n[Куплет 2]\nБәрін берем Өзіңнен алғанды,\nТек Саған берем жүректегі арманды.\nМеншігіңмін, Сендікпін,\nТәңір алғыс Саған, туысың елдіктің.","songNumber":"240"},{"id":27,"title":"Жетелеп бізді, жетеле көкке","text":"[Куплет 1]\nЖетеле бізді, жетеле көкке,\nҚұдайым әр кез қолдай жүр бізді!\nЖарқырай жанған, жұмақ төрінен,\nШақырасың Ием - Сен, бізді!\n\n[Припев 1]\n// Мына өмір көз ілмей,\nӨте шығар дөңгелей.\nМәңгілік Сенің -\nПатшалығың орнасын //\n\n[Бридж 1]\nҚазағым жайына рухани ойлан\nӨсебер халқым Құдайды алғыста.\n\n[Куплет 2]\nБір ауыздан қолды жайып,\nХалқым бата тілейік.\nУа, жаратқан Ием құдірет,\nТілегімізді қабыл ет.\n\n[Припев 2]\n// Достың көңілін аша гөр,\nДұшпанның көңлін баса гөр. //\n// Әділеттікті Бұрғаннан сақта,\nҚайырымсыз туғаннан сақта. //\n\n[Бридж 2]\n// Рухани бірлік орналсын //","songNumber":"43"},{"id":1009,"title":"Жеткілікті","text":"[Куплет 1]\nБүкіл әлемнің Құтқарушы дүниенің билеушісі,\nҚұдайдың Ұлы Иса Мәсіх,\nТүнектің қақпасын жапты\nИеміз Иса өліп тірілген,\nАйқыш ағашта жанын қиды.\nОсы әлемге Нұр болып келген\nИса Ол - жол, шындық, өмір\n\n[Припев 1]\n// Құдайдың күші үстімде,\nОның сөзі жүрегімде.\nИсаның төгілген қаны,\nМені ақтауға жеткілікті. //\n\n[Куплет 2]\nЕнді мен бүгін Иса Иемнің,\nОның ілімін ұстанамын.\nИемнің Өзі - Ол менің жолым,\nМәңгілік есігін Ол ашты.\nИеміз Иса өліп тірілген,\nАйқыш ағашта жанын қиды.\nОсы әлемге Нұр болып келген\nИса Ол - жол, шындық, өмір\n\n[Бридж 1]\nҚұтқарушым маған Сен пана болдың,\nМенің жартасым - Иса.\nШайқалмаймын,\nҮміт келеді маған жалғыз Құдайдан."},{"id":1027,"title":"Жолбота","text":"[Куплет 1]\nҚағып, қағып темір балға,\nШегеледі Иса тәнін.\nБас иіп қарт пен жастар\nОсы айқыш алдында.\n\n[Припев 1]\nБауырым, естідің бе, бауырым?\nО, жолаушы, аялдашы!\nТауда сен қара - Жолботаға,\nАйқыш ағаш! Иса - Иең!\n\n[Куплет 2]\nШегелеп Оның аяқ-қолын,\nКиелі қанын Ол төкті.\nБөліспей ешкім Оның азабын,\nГүлдесте де ешкім лойған жоқ.\n\n[Припев 2]\nБауырым, естідің бе, көрдің бе\nОның керемет жүзін?\nКешіріп бәрін, әлем күнәсін,\nИса сен үшін сынды.\n\n[Куплет 3]\nҚара, көзі сүйіспеншілікке толы,\nЖылулық, мейірім, кешірім.\nМен қалаймын, досым, бүгін де\nКөрсетуді Оны сеніммен."},{"id":651,"title":"Жол Ғолғотаға алыс, қиналып қарадың","text":"[Куплет 1]\nЖол Ғолғотаға алыс, қиналып қарадың,\nЖараңнан тамшылап қаның ақты.\nО, Иса қымбаттым, мен үшін қиналдың,\nАзабын Өз еркіңмен көрдің.\n\n[Припев 1]\nЕшқашан ұмытпаймын айқасқан ағашты,\nБайланыстырдың көк пенен жерді.\nӨлімің жарастырды бізді Құдаймен,\nТаза қаның бізді өтеді.\n\n[Куплет 2]\nАдамзат зер салшы, әнімді тыңдашы,\nНе үміт күтесің дүниеден.\nТөгілген қанына не төлем бересің,\nРақымы Құдайдың бағасыз.\n\n[Куплет 3]\nРақымдылығыңды Сен жерге жаудырдың,\nСоның сырын ашшы Сен бізге.\nНұсқаған жолыңмен қорықпай жүрейін,\nӨмірдің әр-қилы кезінде.","songNumber":"190"},{"id":401,"title":"Жолымдағы жарық жұлдыздай","text":"[Куплет 1]\nЖолымдағы жарық жұлдыздай\nЖанып тұрсың жарқырап.\nБағымдағы мөлдір бұлақтай\nАғып жатқан сарқырап.\n// Жарық күннің күлімдеген көзіндей\nЖылу бердің Тәңірім.  //\n\n[Куплет 2]\nҚолымдағы асыл маржандай\nСенің Сөзің киелі.\nОқығанда аяулы сондай\nжүрегіме тиеді.\n// Сиынғанда үнімді естіп аспанда\nЖауап бердің Тәңірім.  //\n\n[Куплет 3]\nКөре алмай Сені көзіммен\nКөп іздедім өмірде.\nҚанша түндер Өзіңді білмей\nКөз жасымды төктім мен.\n// Енді ғана жүрегіммен сезіндім\nБар екенсің Тәңірім.  //\n\n[Куплет 4]\nАдамзатты сүйгендіктен Сен\nЖер бетіне келгенде\nМейірімді сабырлығыңмен:\nЖолыңнан қайт дегенде.\n// Азап шектің айқыш ағаш басында\nКүнәм үшін Тәңірім. //","songNumber":"79"},{"id":664,"title":"Жұлдыздарды кім жаратты?","text":"[Куплет 1]\nЖұлдыздарды кім жаратты,\nЖарқырайтын жұлдыздарды?\nЖұлдыздарды кім жартты,\nКөктегі Әкеміз"},{"id":786,"title":"Жұлдыздар жарқырап жанғанда","text":"[Куплет 1]\nЖұлдыздар жарқырап жанғанда,\nЖарық ай көрініп аспанда,\n//  Тәңірім, Өзіңе жүректі ашқанда,\nТәңірім, Сен мені құтқардың.  //\n\n[Куплет 2]\nӨмірдің таба алмай бақытын,\nЖолымның біле алмай бағытын,\n//  Тұншығып тұңғиық түбінде қалғанда,\nТәңірім, Сен мені құтқардың.  //\n\n[Куплет 3]\nКүнәнің шыға алмай торынан,\nАдасып жүріппін жолымнан.\n//  Жүректі тағы да жалғыздық басқанда,\nТәңірім, Сен мені құтқардың.  //\n\n[Куплет 4]\nӨмірдің қайғы мен азабын,\nҰмыттым күнәнің мазағын.\n//  Тәңірім құтқарды, қуаныш сыйлады,\nТәңірім, күнәдан құтқарды.  //","songNumber":"153"},{"id":695,"title":"Жұлдыздар түнде жарқырайды","text":"[Куплет 1]\nЖұлдыздар түнде\nСәулесін шашып жарқырайды\nКүн нұрын төгіп\nМұхит пен таулар\nБұл Құдайдың кереметі\n\n[Бридж 1]\nО Құдай сен бәрін жараттың\nБір өзіңе сиынамын Тәңір Ием\nКереметтігіңе таңқаламын\nҒажайып пен жараттың Тәңір Ием\n\n[Припев 1]\nМадақтаймын Тәңір Иемді\nАлғыс Айтам Тәңір Иеме\n\n[Куплет 2]\nТәңірге келіп мінажат етсең\nОл саған жауап береді\nТізерлеп келіп оған сиынсаң\nОл сені түсінеді"},{"id":564,"title":"Жұлдыздар түнереді","text":"[Куплет 1]\nЖұлдыздар түнереді,\nАстан-кестен боп көк аспан.\nКүшті әлінен айырылып,\nТағына Оның бас иер жан адасқан.\nОл келеді жарқырап Күндей,\nНұрландырып айналаны!\n//  Біреуге гүл тәжін сыйлап, марапат қылар,\nАл біреуден теріс айналады...!  //\n\n[Куплет 2]\nКөз жасы көл боп жылайды сонда,\nӨткенін еске алып ойланады.\n//  Неліктен, Тәңір, маған Сен қаталсың,\nНеліктен теріс менен айналасың?  //\n\n[Куплет 3]\nТәңір былай дер: -Есіңе түсірші\nСаған қанша қағып ем есікті...\nБілсең, сен сонда теріс бет бұрдың,\nКөңілімді қайтарғаннан не шықты?..\n\n[Куплет 4]\nҚашан қақтың дерсің-ау, Сен бәлкім,\nТәңірім, естімей мен қалдым ба?\nАйтшы, шынымен де мұқтаж кезіңде,\nҚолымды созбай, тым суық болдым ба?\n\n[Куплет 5]\nЖетім бала боп жолықтым Саған,\nЖаным күйзеліп, тілім нан сұрағам.\nБірақ та мән бермей қойдың, мен сонда,\nТырналып жарам, қансырадым.\n\n[Куплет 6]\nСүртіп жасымды, қол созған жандарға,\nҚұн жетпейтін сыйлық тартамын.\nСенім артқан қайрымды адамдардың\nКүнәларын мойныма артамын.\n\n[Куплет 7]\nКіреді олар Құдай үйіне,\nЖұмақтың нақ төріне жиналар.\nАл өзгелер күнәларын мәңгілік өтеп,\nӨшпес тозақ отында қиналар.\n\n[Куплет 8]\nКүллі жұлдыз түнереді,\nАстан-кестең боп көк аспан.\nКүшті әлінен айырылып,\nТағына Оның бас иер жан адасқан.\n\n[Куплет 9]\nОл келеді жарқырап Күндей,\nНұрландырып айналаны.\nБіреуге гүл тәжін сыйлап, марапат қылар,\nАл біреуден теріс айналады."},{"id":103,"title":"Жұмақ қазына","text":"[Куплет 1]\nЖұмақ қазына сияқты бақшадағы\nЖерге көмілген ешкім білмейтін қазына\nЖұмақ қазына сияқты бақшадағы\nЖерге көмілген ешкім білмейтін қазына\nБолған\n\n[Припев 1]\nБіреу сол қазынаны тауып қуана үйге\nБарып\nҮйін сатып жерін сатып мүлкін сатып\nСол жерді сөзсіз сатып алады"},{"id":732,"title":"Жүзген кемедей өмір білінбей","text":"[Куплет 1]\nЖүзген кемедей өмір білінбей,\nЗымырап өте шығар,\nНе күтер алда, толқын бар жолда,\nКейде құзға ұрар.\nСен де, мен де, біз мүлде білмейміз,\nТек Құдай ғана білер,\nУақыт та келер біз көкті көрер,\nБар арман орындалар.\n\n[Припев 1]\nО, қайда сол жұмақ төрі,\nТек сонда болғым келеді,\nЖарық мәңгі сөнбес жерде,\nӨлім, қайғы болмас елде.\nО, қайда сол жұмақ төрі,\nДостарымның болар бәрі,\nТоқталмас бала күлкісі, шаттық үні.\n\n[Куплет 2]\nЖаз да өтеді, қыс та жетеді,\nУағымен, көп күттірмей,\nЖастық тұрмайды, жылдар ұрлайды,\nҚарттық келер білдірмей.\nКүш біткен кезде, үміт жоқ өзге,\nТек көкке көз тігерміз.\nАрман боп келген, үмітпен сенген,\nЖарық жұлдыз көреміз.","songNumber":"144"},{"id":457,"title":"Жүрегімде қара дақ","text":"[Куплет 1]\nЖүрегімде қара дақ,\nжасырын күнә бар!\nЕнді не істеймін?\nИса былай айтады:\nЖақындасаң сен маған,\nҚардай ақ боласың!\nЖақындасаң сен маған,\nҚардай ақ боласың!","songNumber":"243"},{"id":1032,"title":"Жүрегімді арнаймын Саған","text":"[Куплет 1]\n/// Жүрегімді арнайм Саған,\nБар жаныммен мен ұмтылам Саған! ///\nИ-са Ұлысың!(...тірісің! Сен Киелісің!)\n\n[Предприпев 1]\nМахаббатыңды төкші\nЖаңбыр іспетті төгілші\nТолтыршы бізді\nӨз Рухыңмен толтыршы!\nКүнәмді Сен кешірдің\nӨз бауырыңа алдың\nРизамын Саған\nШын жүректен ризамын!\n\n[Припев 1]\nИса Ұлысың! Иса Ұлы Құдай!\nИса Тірсің! Иса Тірі Құдай!\nИса Кие-лісің! Иса Ки-елі Құдай!"},{"id":36,"title":"Жүрегімді өзгерт, о Құдай Ием","text":"[Куплет 1]\n// Жүрегімді өзгерт, о Құдай Ием,\nСаған ұқсайын, о, Тәңір Ием! //\n// Сенімде нығайт, о Құдай Ием,\nӨзіңе ұқсат, о Тәңір Ием! //\n\n[Припев 1]\nҚыш құюшысың Сен, мені жаратқан,\nЖүрегімді өзгерт, Саған жалынам!","songNumber":"63"},{"id":118,"title":"Жүрегімді өзгертші Тәңір","text":"[Куплет 1]\nЖүрегімді өзгертші Тәңір,\nСені ғана аңсап тұрайын.\nЖүрегімді өзгертші Тәңір,\nСаған ғана мойын бұрайын.\n\n[Припев 1]\nСенің атың - Ыстық Махаббат,\nСенің атың - Рақым, Шапағат.\nСұраймын мен Сенен\nБер маған даналық, қанағат.\n\n[Куплет 2]\nӨмірімді өзгертші Тәңір,\nӘлемге мен жарық болайын.\nӨмірімді өзгертші Тәңір,\nРухыңа мен Сенің толайын","songNumber":"52"},{"id":456,"title":"Жүрегіме","text":"[Куплет 1]\nЖүрегіме, жүрегіме,\nКелші менің Тәңір Иса!\nБүгін кел, қазір кел,\nМенімен бол Тәңір Иса!","songNumber":"244"},{"id":386,"title":"Жүрегіме жүз қарап","text":"[Куплет 1]\nЖүрегіме жүз қарап,\nЖүруші едім тұнжырап.\nКөп іздеген бақытым Өзі келді қолыма.\nКөрінгеннен жол сұрап\nҚараушы едім жаутаңдап.\nАқыл беріп Тәңірім Салды өмір жолына.\n\n[Припев 1]\n// Даналардың данасы,\nБар әлемнің панасы.\nӨмірімнің айнасы, Көңілімнің санасы.\nБар әлемді жаратқан,\nОй мен қырды құлпыртқан.\nТаусылмас бұлақтардай Ағып жатқан. //\n\n[Куплет 2]\nӨткен күндер зымырап,\nКелмес енді қайталап.\nАлыс емес жетер күн Тәңірімнің алдына.\nӘн айтамын ардақтап,\nТәңірімді мадақтап.\nМәңгі бірге боламын Тәңірімнің қасында.","songNumber":"61"},{"id":182,"title":"Жүрегім қуанышқа толы","text":"[Куплет 1]\n/// Жүрегім қуанышқа толы. ///\nКөктен келген.\n\n[Припев 1]\n/// Ән саламын, алғыс Саған. ///\nТәңір Иса.","songNumber":"42"},{"id":726,"title":"Жүрегіммен","text":"[Куплет 1]\nЖүрегіммен, Тәңірім,\nСені, аңсаймын,\nЖүрегіммен аңсаймын Сені.\nЖүрегіммен дауыстаймын,\nТәңірім, Саған,\nЖүрегіммен\nҮніңді естуді аңсаймын.\n\n[Припев 1]\nСен, Сен келші маған,\nМәңгіге, мәңгіге,\nШөлімді қандыршы.\nСен, Сен келші маған,\nМенімен бірге бол,\nӨмірдің қайнарысың.\nТәңір - өмірімнің бұлағы.","songNumber":"62"},{"id":183,"title":"Жүрегіммен Тәңіріме мен шаттанам","text":"[Куплет 1]\nЖүрегіммен Тәңіріме мен шаттанам,\nИем маған күш, ақыл-ойды сыйлаған.\nКүнәның билігінен азат болып,\nҚұтқарғаныңа Ием мен зор қуанамын.\n\n[Припев 1]\nЕш шынайы Тәңір жоқ Сенен Өзге.\nҚорған болдың Иса Тәңір Сен бізге.","songNumber":"44"},{"id":770,"title":"Жүрегімнің көзін аш","text":"[Куплет 1]\nЖүрегімнің көзін аш, Ием,\nЖүрегімнің көзін аш -\nСені көргім келет\nСені көргім келет\n\n[Припев 1]\nСен жоғары биіктен\nДаңқыңның нұрлы сәулесінен\nРух пен махаббат төк,\nБіз әндетеміз:\nКиелі, Киелі!\n\n[Бридж 1]\n/// Киелі, Киелі, Киелі! ///\nСені көргім келет.","songNumber":"63","copyright":"1997 Интегриты'с Хосанна! Мусик"},{"id":267,"title":"Жүрегімнің Патшасы бол Иса Мәсіғім","text":"[Куплет 1]\nЖүк алғансың, біздерді құтқару үшін,\nБарлық күналардан, тазарту үшін,\nКеселдерді Өзің шипалау үшін,\nҚұдайдан келгенсің, күнәсыз болып!\n\n[Припев 1]\n// Рухымның Патшасы бол Иса Мәсіғім!\nЖүрегімнің Патшасы бол Иса Мәсіғім! //\n\n[Куплет 2]\nІзгі хабарды дүниеге тарқату үшін,\nАдамдарды жамандықтан арылту үшін\nМәңгілік өмірді, жарату үшін,\nҚұдайдан келгенсің, күнәсыз болып!\n\n[Куплет 3]\nДүниеге тарқалған жарық нұр болып,\nКөрсетуші жолды бір жұлдыз болып\nКүшті Ұл, Құдіретті бір Мәсіх болып\nҚұдайдан келгенсің, күнәсыз болып!"},{"id":168,"title":"Жүрек көзін ашшы Ием..","text":"[Куплет 1]\nЖүрек көзін, ашшы - Ием!\nЖүрек көзін, аш - Ием!\nКөргім, келеді!\nКөргім, келеді!\n\n[Куплет 2]\nЖүректегі бар сырымды,\nТыңдашы сен жалықпай,\nЖүрейін - еркін,\nМен қамықпай!\n\n[Куплет 3]\nЖүрегіме сабыр берші\nЖаныма жақын келші\nСезгім келеді\nСенгім келеді!\n\n[Куплет 4]\nЖетелеші арманыма\nӨзіңнің ақ жолыңа\nСенгім келеді\nЕргім келеді\n\n[Припев 1]\n// Нұр шашқан - салтанатыңды!\nКөргім келеді мен даңқыңды!\nТолып - махаббатыңа\nӘндетем - Киелі! Киелі! Киелі! //\n\n[Куплет 5]\nЖүрек көзін ашшы Ием\nЖүрек көзін аш Ием\nКөргім келеді\nКөргім келеді\n\n[Куплет 6]\nЖақындатшы мені Өзіңе\nҮйретші мол төзімге\nТөзгім келеді\nТөзгім келеді\n\n[Бридж 1]\n/// Киелі! Киелі! Киелі! ///\nБолғым келеді!","copyright":"1997 Интегриты'с Хосанна! Мусик"},{"id":731,"title":"Жүрек қалай шаттанып толқымайды?!","text":"[Куплет 1]\nЖүрек қалай шаттанып толқымайды?!\nІзгі хабар танытса шын Құдайды.\n//  Өсиеті Тәңірдің дәнін ексе,\nЖайлап өсіп, ол неге жайқалмайды?!  //\n\n[Куплет 2]\nІзгі хабар - ізгілік қайнар көзі,\nОл - Құдайдың Иса атты тірі Сөзі.\n//  Адам ата, Хауа ана бойға енгізген,\nБар күнәдан құтқарар Соның Өзі.  //\n\n[Куплет 3]\nҚұдай еркін мен қалай тыңдамайын,\nМенің жаным шындыққа құмар дәйім.\n//  Күш-қуат бер, жетеле Рухыңменен,\nБолаттайын берік боп шыңдалайын.  //\n\n[Куплет 4]\nСенің атың Тәңірім, дәріптелсін!\n«Патшалығы Тәңірдің жақын» депсің.\n//  Таратайын әніммен Хабарыңды,\nТаңдаулыңды мың-мыңдап алып келсін.  //","songNumber":"113"},{"id":280,"title":"Жүремін Сенің мен жолыңмен","text":"[Куплет 1]\nЖүремін Сенің мен жолыңмен\nБағытпен Құдайдың көрсеткен.\nЖақын тануға Сені Тәңір,\nРухыңа толтыр, Киелі Рух\n\n[Бридж 1]\nӨміріңді паш еттің, Қасиетті қаныңмен\nИса бағыт бер, шындық жол Иса Ие көрсет!\n\n[Припев 1]\nСен деп өмір сүрем Саған ғана ерем,\nСенің Ізгі Сөзің таралсын әлемге\nЖеңімпаз болам мен, келеді осы күн,\nАртқа шегінбеймін - Ұлы Патшам"},{"id":605,"title":"Жүр, Ыбырайым, дайындал жолға","text":"[Припев 1]\nЖүр, Ыбырайым, дайындал жолға,\nЖүр Ыбырайым, Құдайың қасыңда.\n\n[Куплет 1]\nСонда ол бәрін тастап, бөтен елге беттеді,\nҚұдайға сенім артып, айтқанынан кетпеді.\nАштықта да Құдайға, сенуден ол талмады,\nҚанахан еліне қарай сапарын жалғады.\nМал көбейіп Лұтпен бөлінуге тура келді,\nАғасы жер таңдауға інісіне жол берді.\n\n[Куплет 2]\nСара кәрі, ұрпақ жоқ Құдай берді уәдесін,\nЖұлдыздай көбейтемін, ұрпағын, несібесін\nҚұдай сынап: «Ысқақты құрбандыққа шал», - деді,\nСенімімен құтқарып: «Мына қойды ал», - деді.\nЕгерде сен Құдайға сенім артсаң осылай,\nЖақындайсың Құдайға, Ыбырайым досыңдай.","songNumber":"242"},{"id":606,"title":"Жүсіп Жақып баласы, Рахила оның анасы","text":"[Куплет 1]\nЖүсіп Жақып баласы, Рахила оның анасы,\nОтандары олардың, Иерусалим қаласы.\n\n[Припев 1]\nКең байтақ қазақ даласы,\nБіз Құдайдың баласы.\nКөктегі отанымыз\nИерусалим қаласы.\n\n[Куплет 2]\nЖүсіп жақсы киінді, жасады істі тиімді,\nАзғырылмай күнәға, Құдайына сиынды.\n\n[Припев 2]\nИса бізді ақтады,\nАман-есен сақтады,\nАзғырылсаң айрылдың,\nОрныңнан Эдем бақтағы.\n\n[Куплет 3]\nЖүсіп бәріне көнеді, Құдайға еркін береді,\nҚиындықта мойымай, жеңіспенен келеді.\n\n[Припев 3]\nБіз де Исаға сенейік,\nжетегіне ерейік,\nҚұдайды терең қастерлеп,\nРухани жеміс берейік.","songNumber":"245"},{"id":385,"title":"Жылдар өтсе де тоқталмастан","text":"[Куплет 1]\nЖылдар өтсе де тоқталмастан,\nҮмітпен өмір сүр әрқашан.\nҚиындық болса жолыңда, Иса жаныңда,\nТастамайды сені ешқашан.\n\n[Припев 1]\nБіл, Ол келіп оятады әлемді,\nБіл, Ол келіп қуантады бар елді.\nБіл, Ол келіп бақытсыздық болмайды,\nӨзі бізді қолдайды.\n\n[Куплет 2]\nЖаңбырлы күз жабырқатса,\nЖаңбыры қармен алмасса.\nЖердегі уақыт оралмайды, шынайы үміт\nЖоғалмайды, еш жоғалмайды.\n\n[Припев 2]\nБіл, Ол келіп көрінеді әлемге.\nБіл, Ол келіп бас игізер бар елге.\nБіл, Ол келіп қуантады сенгенді,\nСенімменен жеңгенді.","songNumber":"69"},{"id":408,"title":"Жылқы зуылдап шабады","text":"[Куплет 1]\nЖылқы зуылдап шабады,\nҚұйғытып далада.\nЖылқы зуылдап шабады,\nӘрі-бері далада."},{"id":967,"title":"Жым-жырт түн","text":"[Куплет 1]\nЖым-жырт түн, Ғажап түн!\nМүлгіп тұр айнала.\nОяу тек, жұбайлар тебіренген,\nСүйкімді Сәбиге еміреніп,\nҚуанышқа кенелген! Қуанышқа кенелген!\n\n[Куплет 2]\nЖым-жырт түн, Ғажап түн!\nЖар салды көктен үн:\nҚуан, Мәсіх келді дүниеге,\nСендерге құтқарылу әкелді!\nКөктен түсті бір жарық! Көктен түсті бір жарық!\n\n[Куплет 3]\nЖым-жырт түн, Ғажап түн!\nТәңір сый ұсынды.\nЖан-тәнменен оны қабылдайық\nМақтасын Оны барлық халық!\nҚұтқарушы берді Ол, Құтқарушы берді Ол.","songNumber":"164"},{"id":72,"title":"Жыр болып бізге ашылшы Тәңір","text":"[Куплет 1]\nЖыр болып бізге ашылшы Тәңір,\nСырыңды маған ақтаршы Ием.\nҰнаттың адам баласын неге?\nМәнісін мұның ұқтыршы Құдай.\n\n[Припев 1]\nО, Құдай Ием, Өзіңсің өмір.\nО, Құдай Ием жаратқан бізді.\nБас иіп Саған келіп тұр елім,\nЖетелеп баста шындыққа Иса.\n\n[Куплет 2]\nКүнәға батқан елімді көріп,\nЖібердің бізге Ұлыңды жерге.\nҮзілген үміт жалғанды бүгін,\nМәңгілік өмір сыйладың бізге.\n\n[Куплет 3]\nТыңдашы халқым, таймашы жолдан,\nШындықты жырла Исадан алған.\nШақырған бізді шаттықа толы,\nҚазағым, елім, Исаның жолы.","songNumber":"114"},{"id":572,"title":"Жібітіп тоң жерді, қуантып бар елді","text":"[Куплет 1]\nЖібітіп тоң жерді, қуантып бар елді,\nДалама наурыз келді.\nБалалар көңілді, ән-жыры өрілді,\nНаурыз әні төгілді.\n\n[Куплет 2]\nӨкпелі жандарды, барлық балаларды,\nТатулыққа шақырады.\nИса көктен келді, тыныштығын берді,\nТыңдасын жер атырабы.\n\n[Припев 1]\nАта-аналар, үлкендер, балалар,\nҚұтты болсын наурыздарың.\nКөкке жол ашып, Мәсіхпен жарасып,\nІске ассын армандарың.\n\n[Куплет 3]\nЖаңарсын бәрі де, жасы, кәрісі де,\nНаурызда жаңару керек.\nЖүрегіңді бергін, Исаға сен келгін,\nТек Ол жаңа өмір береді.","songNumber":"241"},{"id":337,"title":"Иә, Исаны мен сүйем","text":"[Куплет 1]\nИә, иә, Исаны мен сүйем\nБар жүрегіммен.\nИә, иә, Исаны мен сүйем\nБар жүрегіммен.\n\n[Куплет 2]\nСүйесің бе, Исаны бар жүрегіңмен?\nИә, Исаны мен сүйем бар жүрегіммен.","songNumber":"66"},{"id":683,"title":"Ием, Иса","text":"[Куплет 1]\nБүкіл әлемді жаратқан менің Тәңірім,\nОйласам ғана болады бар нәрсе.\nҚұдіретіңе қайран қаламын Тәңірім!\nМадақталсын Сенің Атың әр жерде.\n\n[Припев 1]\nСөздеріме жетпейді мадақтауға Сені Ием,\nСондықтан арнаймын Саған әнімді.\nИем Иса Сені ғана қастерлеймін мен,\nЖаным Саған ұмтылды бар күшімен,\nИем Иса жүрегімнің төріндесің Сен,\nПатшам менің тек Сені,\n// Аңсаймын мен. //\n\n[Куплет 2]\nСендей керемет досты табу мүмкін емес,\nБақытты болар адам Саған сенген.\nСен болмасаң қасымда еш жұбаныш келмес,\nАқылыңнан айналдым маған берген."},{"id":125,"title":"Иемізді мадақтаңдар!","text":"[Куплет 1]\nИемізді мадақтаңдар!\nБарлық ұлттар.\nОны мадақтаңдар!\nКүллі халықтар.\n\n[Припев 1]\nОл зор мейірімін көрсетіп,\nБізге мәңгілік адал болады\nМадақтаңдар, Иемізді!\nМадақтандар, Иемізді!","songNumber":"67"},{"id":984,"title":"Иеміз Иса балаларды сүйеді","text":"[Куплет 1]\nИеміз Иса балаларды сүйеді,\nИеміз Иса балаларды сүйеді,\nИеміз Иса бәрімізді сүйеді,\nИеміз Иса бәрімізді сүйеді!"},{"id":992,"title":"Иеміз Иса менің ізгі Бағушым","text":"[Куплет 1]\nИеміз Иса менің Ізгі бағушым,\nИеміз Иса менің Ізгі бағушым,\nИсаға сенемін, Ол Ізгі Бағушы\nИсаға сенемін, Ол ізгі Бағушы"},{"id":640,"title":"Иенің Дұғасы","text":"[Куплет 1]\nКөктегі Әке\nКиелі есімің\nПатшалығың\nОрындалсын жерде\nКөктегі еркіңдей\nКөктегі Әкеміз\n\n[Предприпев 1]\nАзғырылуға жол бермей\nЖаманнан бізді сақтайды\n\n[Припев 1]\nПатшалық та\nЖәне күш те\nҰлылық та\nСенікі\nПатшалық та\nЖәне күш те\nҰлылық та\nМәңгілік\n\n[Куплет 2]\nБізге әр сәт бердің\nҚажеттің бәрін\nКүнәмді кешір\nБізде кешіргендей\nКүнә жасағанды\nКөктегі Әкеміз"},{"id":472,"title":"Иерусалим, Иерусалим","text":"[Куплет 1]\nИерусалим, Иерусалим\nКеле жатыр сенің Патшаң, салтанатта!\nИерусалим, Иерусалим!\nТас лақтырып өлтіретін, пайғамбарлар мен елшілерін.\n\n[Предприпев 1]\nҚасарыспай жүрегіңде, Құдай сөзіне жариялаған,\nҚұрмет көрсет, өміріңді Оған арнап !\n\n[Припев 1]\nСенің Әкең, сенің Иең, келе жатыр !\nСенің Патшаң, Құтқарушың келе жатыр!\nҒажап даңқта, Құдіретті - Тәңір келе жатыр!\nСені сүйіп, сені ойлап, сені аңсап келе жатыр!\nСенің сүйікті жан-досың, келе жатыр!"},{"id":1018,"title":"Иешуа!","text":"[Припев 1]\nИешуа! Иешуа!\nИешуа! Иешуа!\n\n[Куплет 1]\nКелгейсің-Құтқарушымыз!\nҚастерлі Ием!\nҚауымың Сені күтуде!\nҚалыңдығың күтуде Сені!"},{"id":638,"title":"Имануил","text":"[Куплет 1]\nИмануил!\nИмануил!\nОның Аты - Имануил!\n«Құдай бізбен бірге» - оның мәні\nБілініп тұр.\nИмануил!","songNumber":"68"},{"id":273,"title":"Имануил Құдай бізбен бірге","text":"[Куплет 1]\nИмануил Құдай бізбен бірге,\nИса -  менің жүрегімде!\n\n[Припев 1]\nҚудай бізбен Ол махаббат\nИсаның аты Махаббат!\n\n[Бридж 1]\nИса Ол Махаббат, Махаббат"},{"id":795,"title":"Имануил - Құдай, бізбен бірге!","text":"[Куплет 1]\nҒажайып түн, көк аспан, жұлдыздар жымыңдасқан,\nҚол ұстасқан қос жұбай, пана іздеп, есік қаққан,\nТолғақ қысқан жас ана, Құдай еркіне мойынсұна,\nСәбиін бөледі, мал байлаған ақырға.\nТолғақ қысқан жас ана, Құдай еркіне мойынсұна,\nСәбиін бөледі, мал байлаған ақырға.\n\n[Припев 1]\nИмануил - Құдай, бізбен бірге!\nРақымыңмен, имандылық бердің жерге,\nТалқандадың тәнде, бүкіл қарғыс, күнәні,\nЖетеледің ақ жолмен, мәңгі өмірге.\n\n[Куплет 2]\nЖаратылыс бір сәтке, секілді құлақ тосқан,\nНәрестенің даусынан, дүрлікті биік аспан.\n// Періштелер ән шырқап, дәріптесін, Ием даңқыңды!\nБүкіл адамзат, қуанып салсын той-думан! //"},{"id":950,"title":"Иса айқышта құрбандыққа шалындың","text":"[Куплет 1]\n// Иса айқышта құрбандыққа шалындың,\nТоқты ретінде.\nБар адамзаттың күнәлары үшін,\nҚорғаушым өз қаныңды Сен төктің. //\nҚұрбан болған Құдайға алғыс айтамын,\nМейірімің бізге зор молымен шашқан.\nҚұрбан болған Исаға алғыс айтамын,\nТізе бүгіп шын жүректен мойынсұнам."},{"id":568,"title":"Иса Атың жоғары","text":"[Куплет 1]\nИса Атың жоғары,\nӘлемді Құтқарушы салтанатты Иеміз.\nИмануил, Құдай бізбен бірге,\nКөктен жерге келген өмір Сөзі.\n\n[Куплет 2]\nИса - бағушым менің,\nБұтақ сабағы, Құдай Ұлы\nБейбіт Ханы, ғажап Кеңесші\nӘлемнің Иесі, жер Жарғы\n\n[Куплет 3]\nИса - сақтықтың жолы,\nХандардың ханы, Ием мәңгі\nӘділдік пен өмірдің жолы\nОл Жаратушы, Құтқарушым."},{"id":675,"title":"Иса Бағушымыз","text":"[Куплет 1]\nИса, Бағушымыз\nПатшалардың Патшасы.\nҚамқоршы - Ол бәрімізге\nМадақтаймыз Иемізді\n\n[Припев 1]\nТабынамыз біз Саған, Иса\nКөк пен жерді жаратқан Тәңір\nКөк пен жерді жаратқан Тәңір\nСен тірісің, мәңгілік Ием.\n\n[Куплет 2]\nИса, қуанамыз\nӘлемнің Патшасы\nБар күнәмізді кешірдің\nЖүрегімізді толтырдың"},{"id":977,"title":"Иса балаларға айтты","text":"[Куплет 1]\nИса балаларға айтты:\n\"Маған келіңдер! Маған келіңдер!\"\nБізді шақырады, бізді сүйеді."},{"id":332,"title":"Иса балаларды сүйеді","text":"[Куплет 1]\nИса балаларды сүйеді,\nИса балаларды сүйеді.\nҚызыл, сары, ақ, қара,\nҚұдайға бәрі де қымбат.\nИса әлемнің балаларын сүйеді!"},{"id":464,"title":"Иса балаларды сүйеді","text":"[Куплет 1]\n//  Иса балаларды сүйеді,\nБарлық ұлт балаларын!\nҚара, ақ бала болсын,\nРақымдылығын берді,\nИса бар әлем баласын сүйеді! //\nҚара, ақ бала болсын,\nРақымдылығын берді,\nИса мені де, сені де сүйеді!","songNumber":"246"},{"id":736,"title":"Иса берді жүрегіме дем","text":"[Куплет 1]\nИса берді жүрегіме дем,\nБақыттымын бұл дүниеде мен.\nОл көрсетті өмір жарығын,\nОл көрсетті жұмақ анығын.\n\n[Припев 1]\nТәрбиелеп жақсы жолына\nБақыт алып берді қолыма.\nОсылайша өмір оңалып,\nАрам ойлар, кетсін жоғалып.\nАрам, арам ойлар,\nКетсін жоғалып.\n\n[Куплет 2]\nКелші, елім, Иса жолына,\nАзғырылмай шайтан соңында.\nИса сөзін қабыл алайық,\nБіз жұмаққа бірге барайық.\n\n[Куплет 3]\nКелші, елім, бәрің келіңдер\nТек Исада тыныштық, сеніңдер.\nБіз күнәға қарсы тұрайық,\nИса сөзін оқып, ұғайық.","songNumber":"115"},{"id":516,"title":"Иса, берік негізімсің","text":"[Куплет 1]\nИса, берік негізімсің,\nТұрам еш қауіптенбей.\nИса, берік негізімсің\n// Үмітім - киелі сөздерің. //\n\n[Припев 1]\n// Мәңгі үмітім бар,\nКелешегім бар.\nҚұдайдың еркі бар,\nОған сенем\nОған сенем. //\n\n[Припев 2]\n// Сенің сөзің әділ,\nҚұдіретті, күшті.\nҚұдай - Құтқарушы,\nОған сенем. //","songNumber":"69"},{"id":548,"title":"Иса бізбен бірге","text":"[Куплет 1]\nИса бізбен бірге,\nҚазір бізбен бірге,\nОның киелі күші бар,\nҚұтқаруға сені.\nОның киелі күші бар,\nЕмдеуге сені.\nОның киелі күші бар,\nБостандық беруге.\nИса бізбен бірге."},{"id":778,"title":"Иса біздің берік панамыз","text":"[Куплет 1]\nИса біздің берік панамыз,\nТек Исадан бақыт табамыз.\nТек Исамен бірге боламыз,\nТар жолменен өтіп барамыз.\n\n[Припев 1]\nКездесейік енді аспанда,\nКездесейік Тәңір алдында.\n//  Кездесейік жұмақ төріңде,\nИе болып мәңгі өмірге.  //\n\n[Куплет 2]\nТек Исада болсын ойыңыз,\nТек Исаның сөзін тыңдаңыз.\nАбайлаңыз, құлап қалмаңыз,\nТар жолменен өтіп барамыз.\n\n[Куплет 3]\nКел, шырқайық бүгін бәріміз,\nИса болсын біздің әніміз.\nЖарасып тұр бүгін сәніміз,\nБіз Исамен мәңгі біргеміз.","songNumber":"145","alternateTitle":"Кездесейік енді аспанда"},{"id":846,"title":"Иса Біздің досымыз","text":"[Куплет 1]\nБір-бірімізбен дос болып, өмір сүрейік\nБір-бірімізді кешіріп, сыйласайық\nӨмір деген тамаша, бәріде жақсы\nҚұдай әке сүйеді, ол сені қатты\n\n[Припев 1]\nСен қиналма досым,\nСен мұңайма досым,\nБәрі жақсы болады\nҮмітіңді үзбе\nСен қайғырма досым\nСен жылама досым\nСенімен мәңгі Иса, дос болады\n\n[Куплет 2]\nУайымдама досымау, сен қайғырма\nҚиындықтар бәріде артта қалады\nҚайғыменен, уайымды, алмастырып,\nҚуанышпен, тыныштық, бізге келеді"},{"id":981,"title":"Иса бізді сүйеді","text":"[Куплет 1]\nИса бізді сүйеді,\nКиелі кітап солай дейді.\nОл бізбен бірге жүреді,\nБізді жақсы көреді.\nАрманды Ол сүйеді,\nМейірімді де Ол сүйеді.\nСаматты да сүйеді,\nКиелі кітап солай дейді."},{"id":101,"title":"Иса бізді сүйеді, аллелуйя!","text":"[Куплет 1]\nИса бізді сүйеді, аллелуйя!\nАйқышта өлді Ол, аллелуйя!\nӨліден тірілді, аллелуйя!\nОл бізге келеді, аллелуйя!","songNumber":"247"},{"id":163,"title":"Иса бізді сүйеді, аллелуя!","text":"[Куплет 1]\nИса бізді сүйеді, аллелуя!\nЕскі жылан езілді, аллелуя.\nЖеңіп шықты Мәсіғім, аллелуя,\nАқталды үмітім, аллелуя.\n\n[Припев 1]\nАллелуя, аллелуя!\n\n[Куплет 2]\nМадақтаңдар Тәңірді, аллелуя,\nСүйеді ол бәріңді, аллелуя.\nҚуантады Тәңірім, аллелуя,\nЖұбатады Тәңірім, аллелуя."},{"id":491,"title":"Исаға бәрін беремін","text":"[Куплет 1]\nИсаға бәрін беремін,\nРақымына сенемін,\nСөздерін жүректе сақтап,\nЖетегіне еремін.\n\n[Припев 1]\nБәрін арнайын, оттай жанайын,\nЖалғыз Саған, Құтқарушым, бәрін арнайын.\n\n[Куплет 2]\nАрнаймын Саған бәрін де,\nЖүрегімде мекенде,\nРақымың мен мейіріміңе,\nТолсын сана, сезімде.\n\n[Куплет 3]\nМәсіхке бәрін беремін,\nТәңіріммен біргемін.\nМойынсұнып, үміт артып,\nБауырына енемін.\n\n[Куплет 4]\nӘке, алдыңа келемін,\nСыйымды әкелемін,\nТыныштық бердің жүрекке,\nКүн сайын әндетемін.","songNumber":"84"},{"id":226,"title":"Иса - ғажайыпсың Сен","text":"[Куплет 1]\nИса-Тәңірім! Иса-өмірім!\nСенімен бірге,менің әр күнім.\nМәңгілікке Сен, өмір сыйлладың!\nШындық сөзіңмен, нұр боп төгілген,\nБақыттымын мен, қуанышым - Сен!\nМәңгілік Иса - жеңіс сыйладың!\n\n[Припев 1]\nҚұдайдың күші, көтерді мені биікке,\nЖеңістің рухын, қондырды маған жүрекке!\nМадақ әнімен,Сені көтерем!\nИса, ғажайыпсың - Сен, ғажайыпсың - Сен!\n\n[Куплет 2]\nСенің сөзіңді, орындаймын мен,\nӘрбір адамның жүрегінде Сен,\nБилік ет Иса махаббатыңмен!\nПатшалығыңды жариялаймын мен,\nҚазақ елімді, бағыштаймын мен,\nҚұтқарушымыз, Иса жалғыз Сен!","alternateTitle":"Иса Тәңірім, Иса өмірім"},{"id":461,"title":"Иса деймін ойыммен","text":"[Куплет 1]\nИса деймін ойыммен, Иса деймін жаныммен,\nМәңгілікке жетемін, қуанышым Өзіңмен.\n\n[Припев 1]\nИсаны шын сүйемін,\nБасымды Оған иемін.\nИса менің Тәңірім,\n// Исаға нық сенемін. //\n\n[Куплет 2]\nЖүргенімді қалайды, әділ таза жолымен,\nКүн нұрына балайды мәңгі жарық өмірмен.\n\n[Куплет 3]\nШын рухани өмірге жетелеші, Тәңірім,\nҚуат беріп көңілге, сүйеніш бол, Тәңірім.","songNumber":"67"},{"id":259,"title":"Иса - жарық, Иса - нұр","text":"[Куплет 1]\n// Иса - жарық, Иса - нұр!!\nИса шындық, шындық жол!\nИса! Иса! Мадақталсын Есімің!\nИса! Иса! Мадақталсын Есімің!\nШын жүректен мадақтаңдар\nМадақтаңдар кел деймін\nИса киелі, жарық боп жанады үйіңде\nЕсіңгі ашып Ол қалсын жүрегіңнің төріне\nКиелі Иса, киелі Оның сөздері\nРухыңмен толтыр біздерді\nДаналық берсін жүрекке. //"},{"id":164,"title":"Иса Жеңімпаз!","text":"[Куплет 1]\nИса Жеңімпаз! Иса Жеңімпаз!\nАуруларымды алды, Күнәмды кешірді.\nИса Жеңімпаз! Иса Жеңімпаз!\nАлғыс, мақтау Саған Құдай Ұлы!\nСенің алдыңда тұрып\nМен Сені мадақтаймын.\nНұр менен қуанышты\nСен бердің маған Ием.\nЕнді мен жасамаймын,\nМенде Мәсіх жасайды.\nҚұдай Ұлы! Сен Патшамсың!\nЖеңімпаз Иса!","songNumber":"63"},{"id":452,"title":"Иса - жердің иесі","text":"[Куплет 1]\nИса - жердің Иесі!\nБізге естіледі:\nБәрі жырлап махаббатпен\nОған бас иеді.\nТәңірдің жерінде,\nКөрінеді бізге,\nҚұдіреті Иеміздің\nТаулар, өзен, көлден.\n\n[Куплет 2]\nИса - жердің Иесі!\nАрайлы таңменен\nҚұстар сайрап дәріптейді\nШаттық берер бізге\nТәңірдің жерінде\nАспан күмбезінде,\nОрман, дала, бақшалар да\nОған әндетеді.\n\n[Куплет 3]\nИса - жердің Иесі!\nҰмытпаймыз біздер.\nТәңір - біздің әділ Қазы\nЗұлымдық өссе де.\nТәңірдің жерінде\nТоқтамайды күрес.\nМәсіх келер қуаныш пен\nТыным берер бізге.","songNumber":"70"},{"id":227,"title":"Иса - жолымсың менің","text":"[Куплет 1]\nИса - жолымсың менің!\nИса - адасқан кезде, таптың - Сен, мені!\nИса - тыныштығымсың!\nИса - қайғы түндерде, жұбаттың мені!\n\n[Припев 1]\nАңсайды Сені, жүрегім, Киелі Рухыңмен толтыр!\nАңсайды Сені, жүрегім, өмірдің мәні, жоқ - Сенсіз!\nАңсайды Сені, жүрегім, Киелі Рухыңмен толтыр!\nАңсайды Сені, жүрегім, өмірдің ,мәні жоқ - Сенсіз!\nӨмірдің мәні, жоқ - Сенсіз!\n\n[Куплет 2]\nИса - арманым менің!\nИса - Сенің еркіңде, өмір сүруге!\nИса - махаббатымсың!\nИса - өз үмітімді, Сенен үзбеймін!","alternateTitle":"Аңсайды Сені жүрегім"},{"id":963,"title":"Иса жүзім бұтағы","text":"[Куплет 1]\nСен бір жеміс ағашсың .\nОрнатылған судың бойына\n// Азғырған адасқан десе\nБауырым ешбір мойыма //\n\n[Припев 1]\n// Иса жүзім бұтағы\nҚұдай Әке Бағбаны\nБірге болсаң Исамен\nЖемісің мол болады! //\n\n[Куплет 2]\nҚорыққан тірі Құдайдан\nОл ақылды дана жан деген.\n// Жауап берші тас атқандарға\nБауырым ал сен нан менен //\n\n[Куплет 3]\nЖүрегіңді толтыр күнде оқып.\nКөктегі Әкеміз сөзіне.\n// Бауырым көрсет сен соны\nҚаласаң нені өзіңе. //\n\n[Куплет 4]\nУақытыңды көп бөл кітапқа.\nОнда өмір бұлақ көзі бар.\n// Құтқарушы есік, Жол. Шындық,\nМәңгі өмір Иса сөзі бар. //"},{"id":955,"title":"Иса Ием ағатайым менің","text":"[Куплет 1]\nИса Ием ағатайым менің,\nҚұрбан болдың мен үшін мәңгілік сыйладың.\nИса Ием Құтқарушым менің,\nӘкенің құшағына, көктің патшалығына,\nМәңгілік келісімге бізді кіргіздің.\n// Көктің патшалығы мекен-жайым менің,\nКөктің патшалығы мен оның тұрғыны //\nАумин!\n\n[Бридж 1]\n//// Исамен қандық келісімге мәңгі тұрдым мен ////\nЕнді менің өмірім Исаның қасында!"},{"id":319,"title":"Иса, Иса!","text":"[Куплет 1]\nИса, Иса!\nКиелі таңдалған Иса!\nИса, Иса!\nТірілген Жаратқан Иса!\n//   Сенің атың бал сияқты ерніме,\nСенің Рухың су сияқты жаныма.\nСені сүйемін-ау, Иса!  //\nИса, Иса!\nКиелі таңдалған Иса!\n\n[Припев 1]\n//   Жаратқан Ием жалынам Саған!\nЖаратқан Ием бата бер маған!\nСөзіңді Сенің таратайын,\nХалқыма Сені аңсаған!  //\n\n[Куплет 2]\n//  Иса, мені құтқардың\nСен өлімнен,\nСодан бері үлгі алам,\nТек Өзіңнен!  //\n\n[Куплет 3]\n//  Мен адасып жүргенде,\nӨзің таптым,\nҰлыңды қиып, мен үшін,\nКүнәмды жаптың!  //","songNumber":"65"},{"id":949,"title":"Иса келді менің өміріме","text":"[Куплет 1]\nИса келді менің өміріме\nШындық Сөзі менің жүрегімде.\n// Алғыс айтам бар күшіммен,\nТабынамын бүкіл жаныммен,\nЛайықсың барлық мадаққа\nЖалғыз Сен! //\n\n[Припев 1]\n// Сүйемін Сені, сүйемін Сені,\nТолықтай өз жүрегімді мен Саған арнаймын Ием. //"},{"id":524,"title":"Иса, келші ..","text":"[Куплет 1]\nҚұдайдын даңқын әр күнде көремін\nМен Құдайдын сүйікті баласымын\nҚұдайдын даңқын әр күнде көремін\nҚұдай менің сүйікті Әкем\nҚұдайдын Ұлы Иса Мәсіх\nКүйеу Жігіт жақында келеді\nҚұдайдын Ұлы Иса Мәсіх\nНұрлы Салтанатты Даңқты Ием\n\n[Припев 1]\nИса келші сүйікті Сенің Қалыңдығың күтүде!\nИса келші сүйікті Сенің Қалыңдығың күтүде!\nИса келші сүйікті Сенің Қалыңдығың күтүде!\nАңсап күтеді Сені Қалыңдық\n\n[Бридж 1]\nИса келші\nИса келші\nҚауым Сені күтүде!"},{"id":716,"title":"Иса, кереметсің Сен!","text":"[Куплет 1]\nИса, кереметсің Сен!\nИса, кереметсің Сен!\nСүйгенім менің Өзіңсің!\nБір Өзіңе өмірімді арнаймын, О, Иса!\nИса, кереметсің Сен!\n\n[Куплет 2]\nИса сені сүйем мен, Иса сені сүйем мен\n// Есіміңді әнге салып, мадақтаймын тек Өзіңді жан Әкем\nИса сені сүйем мен //\n\n[Куплет 3]\n// Иса құн төледің Сен\nБеріп азаттық айқышта, күнәдан сен мәңгілікке ақтадың\nИса құн төледің Сен //","songNumber":"71"},{"id":948,"title":"Иса күнәларды кешірдің","text":"[Куплет 1]\n// Иса күнәларды Сен кешірдің,\nМаған жаңа өмірді сыйладың.\nҚасиетті қаның Сенің төгілді,\nМен үшін айқышта. //\n\n[Припев 1]\n// Бүкіл әлем Тәңір Сені даңқтайды,\nЖалғыз Сені киелі мадақтайды! //\n\n[Бридж 1]\nСен Ұлысың!\nИса Саған мадақ\nСен киелісің!\nИса Саған мадақ\nСен сұлусың!\nИса Саған мадақ\nСен ғажапсың!\nИса Саған мадақ"},{"id":607,"title":"Иса, Қажетсің","text":"[Куплет 1]\nҮміт - әнұраным\nИем, әлем тыныш болғанда\nҚасымда тұрсың\nТүнде маған ән берші\n\n[Припев 1]\nИса - қажетсің\nӘрбір сәтте қажетсің\nРақымға бөленген жүрек әнін тыңда\nМәңгі мадақтаймын\n\n[Куплет 2]\nКүлдің орнына тәж\nӘлсіз жүректі табасың\nҚиындықтарымды\nАлып, жарыққа жеткізші\n\n[Бридж 1]\n//// Махаббатың менің есімде\nМәсіх менімен әрқашанда\nМейірімділігің жетелейді\nМәсіх менімен әрқашанда ////"},{"id":366,"title":"Иса қымбатсың мен үшін","text":"[Куплет 1]\n//  Иса қымбатсың мен үшін,\nБүкіл жаныммен Сені сүйемін!\nРизамын Саған Ием менің,\nСаған ризамын! Саған ризамын! //\n\n[Припев 1]\n// Ризамын Саған! Ризамын Саған! //\nРизамын Саған, ризамын!\n// Сенсіз қалай мен Тәңір Ием,\nЖол тауып қалай өмір сүрем!\nТазартшы мені Өз қаныңмен,\nМені жетеле Өз жолыңмен! //","alternateTitle":"Ризамын Саған"},{"id":678,"title":"Иса махаббатым Сен","text":"[Куплет 1]\nИса махаббатым Сен,\nИса енді, айырылмаймын мен!\nАлып шықтың, мені түнектен,\nБерік, қылып, нық қойдың Сен, білемін мен!\n\n[Припев 1]\nМен Сені, сүйемін,\nжан - дүниеммен, Саған келіп табынам!\nДосымсың, Құтқарушымсың,\nЕнді, мәңгі сиынамын, мен Саған!\n\n[Бридж 1]\nСиынамын, мен, мәңгі тек - Саған!\n\n[Куплет 2]\nJesus, lover of my soul\nJesus, I will never let You go\nYou've taken me from the miry clay\nSet my feet upon the rock and now I know!\n\n[Припев 2]\nI love You, I need You\nThough my world may fall, I'll never let You go\nMy Savior, my closest friend\nI will worship You until the very end\n\n[Бридж 2]\nWorship You my Lord until the very end!\nWorship You my Lord until the very end!","songNumber":"72"},{"id":317,"title":"Иса Мәсіх, тек Өзіңе табынамын","text":"[Куплет 1]\nИса Мәсіх, тек Өзіңе табынамын,\nБір Өзіңді көрер күнді сағынамын.\nСүйем сені, балам бол деп шақырдың,\nКүнәм көп, кешір Әке, жалынамын.\nКешір Әке, кешір Әке, кешірдің,\nКүнәмді Сен пәк қаныңмен өшірдің.\nКүнәнің мен құлы болып жүргенде,\nӨз Сөзіңмен ұлың етіп өсірдің.\n\n[Куплет 2]\nАта-бабам сенген менің Құдайым,\nТек Өзіңнен ақыл-кеңес сұрайын.\nЖүрегім де, көңілім де тазарып,\nБір ісіңе Әке мен де жарайын.","songNumber":"188"},{"id":247,"title":"Иса Мәсіх тірілді! Аллелуйя!","text":"[Куплет 1]\nИса Мәсіх тірілді! Аллелуйя!\nСалтанатты киелі, аллелуйя!\nАйқыш белгі ұстаған, аллелуйя!\nАзапқа төзе алған! Аллелуйя!\n\n[Куплет 2]\nӘн дұғаны айтайық, аллелуйя!\nИса Патшамызға біз, аллелуйя!\nАзап өлімге шыдап, аллелуйя!\nКүнәліні құтқарған, аллелуйя!\n\n[Куплет 3]\nШыдаған сол қорлығы, аллелуйя!\nБізді сақтап, қорғады, аллелуйя!\nҚазір аспанда Патша, аллелуйя!\nПеріштелер де сонда, аллелуйя!\n\n[Куплет 4]\nӘңірге ән айтамыз, аллелуйя!\nӘлемнің Иесіне, аллелуйя!\nДұғамыз біздің мәңгі, аллелуйя!\nӘке, Ұл, Киелі Рух, аллелуйя!","songNumber":"168"},{"id":368,"title":"Иса мейрімді Ұлы Құдай","text":"[Куплет 1]\nТәңірімсін ,Үмітімсің\nИса - сақтар Қорғанымсың\nӨмірімсің, Жан Досымсың\nИса - жүрегім тек Сенде\n\n[Припев 1]\nИса - мейрімді Ұлы Құдай\nӨліп, қайта тірілген\nМен үшін айқышта\nИса - Адамзат Саған риза\nМәңгі, шындық өмірді\nСыйладың Сен.\nСен - шексіз махаббатыңды\nАямай бізге төктің"},{"id":828,"title":"Иса мен сені сүйем","text":"[Куплет 1]\nО Иса сен қандай кереметсің\nМен үшін айқышта шегелендің\nЖаныңды біздер үшін қиып Иса\nМейірімді, рақымдысың Тәңір, Иса\n\n[Припев 1]\nМен сені сүйем Иса\nТөгілген қаныңменен\nЖаныңды қидың Иса, Иса\nМен сені сүйем Иса\nКүнәдан азат еттің\nСен бізді сауықтырдың\n\n[Куплет 2]\n2.О иса сен қандай мейірімдісің\nШапағат нұрыңды бізге төктің\nАдамзат күнәларын мойныңа алып\nТозаққа бармас үшін, Тәңір Иса\n\n[Припев 2]\nМен сені сүйем Иса\nБіз үшін құрбан болдың\nМәңгілік Өмір бердің\nМен сені сүйем Иса\nДаңқыңды көтеремін\nАлғысым шексіз Иса"},{"id":403,"title":"Иса мені қабылда","text":"[Куплет 1]\n//  Иса мені қабылда,\nКерек емес өзге жол.\nБауырыңда паналат,\nАйтар менде тілек сол. //\n\n[Припев 1]\n//  Асыл тастай тазала,\nЛағыл тастай жалтырат.\nДаңқың үшін О, Иса\nНұрыңменен жарқырат! //","songNumber":"73"},{"id":810,"title":"Иса мені құтқардың Сен өлімнен","text":"[Куплет 1]\n// Иса мені құтқардың Сен өлімнен,\nСодан бері үлгі алам тек Өзіңнен. //\n\n[Припев 1]\n// Жаратқан Ием жалынам Саған,\nЖаратқан Ием бата бер маған,\nСөзіңді Сенің таратайын\nХалқыма Сені аңсаған. //\n\n[Куплет 2]\n// Мен адасып жүргенде Өзің таптың,\nҰлыңды қиып мен үшін күнәмды жаптың. //","songNumber":"57"},{"id":980,"title":"Иса менің досым","text":"[Куплет 1]\nИса мені досым,\nОл мені сүйеді.\nМса менің досым,\nҚандай тамаша!"},{"id":430,"title":"Иса менің Құтқарушым","text":"[Куплет 1]\nИса менің Құтқарушым\nБарлық мадақ Саған\nҚұдайымсын, данқтаймын Сені құтқарғанын ушін мені.\nЖұбанышым, Қорғанышым, тыныштық бердің маған\nЖүрегімнең шыққан әніммен сиынамын мен Саған.\n\n[Припев 1]\nБарлық әлем өлен айтындар, Құдайға сиынып мадақтандар\nТаулар иіліп тағзым етсін, Оған алғыс айтындар.\nЖан тәніммен мадақтаймын Сені\nМахаббатыңмен толтырдың мені\nСаған ұқсас ешкім жоқ Құдай, Ием.","copyright":"1993 Хиллсонг Публишинг"},{"id":340,"title":"Иса - менің Тәңірім,","text":"[Куплет 1]\nИса - менің Тәңірім,\nАумин! Аллелуя!\nАумин! Аллелуя!\nАумин! Аумин! Аумин!\n\n[Куплет 2]\nИса - менің Ұстазым!..\n\n[Куплет 3]\nИса - менің Құдайым!..\n\n[Куплет 4]\nИса - менің Бақташым!..\n\n[Куплет 5]\nИса - менің Құтқарушым!..","songNumber":"74"},{"id":384,"title":"Иса мені сүйеді","text":"[Куплет 1]\nИса мені сүйеді,\nНық білемін осыны,\nБалаларын шақырып,\nКөтереді қолына!\n\n[Припев 1]\nИса мені сүйеді,\nИса мені сүйеді!\nИса мені сүйеді,\nКиелі кітап солай дейді!\n\n[Куплет 2]\nМейірімді жүрегі,\nАйқышқа Ол көтерді!\nМен үшін Ол қан төгіп,\nСол қаныменен жуды!\n\n[Куплет 3]\nИса мені сүйеді,\nИса тәлім береді,\nЖүрегім жараланса,\nЗұлымдық ниетінен!\n\n[Куплет 4]\nИса мәңгі менікі.\nҚауіпсізбін мен енді.\nМенің жаным Исада,\nҚұдай мені сақтайды."},{"id":979,"title":"Иса мені сүйеді","text":"[Куплет 1]\nИса мені сүйеді,\nИса мені сүйеді,\nИса мені сүйеді,\nКиелі кітап солай дейді!"},{"id":50,"title":"Исам Тәңірім","text":"[Куплет 1]\nИсам, Тәңірім\nСаған жетер ешкім жоқ\nӘр күн сайын мадақтаймын,\nШексіз махаббатыңды\nЖұбаныш, панамсың\nЖан тасалар қорғаным\nӘрбір демім,\n\n[Куплет 2]\nЖан дүнием\nТек сенің даңқың үшін\nЖар сал, халқым, Тәңірге ән айтып.\nДаңқын көтерейік Патшамыздың\nТаулар иіліп, теңіздер шулар.\nАтыңды естігенде\nҚуан, аспан, Тәңірге жаратқан.\nМәңгі сүйемін, тек мәңгі ән айтам.\nЖалғыз үмітім,\nӨмірім менің - тек Сен"},{"id":244,"title":"Иса - наным менің","text":"[Куплет 1]\nИса - наным менің,\nИса - шырыным менің,\nИса - тыныштығымсың,\nМенің қуанышым, қуатым.\n\n[Куплет 2]\nИса - жолым менің,\nИса - жарығым менің,\nИса - Тәңірім менің,\nМенің өмірім мен үмітім.","songNumber":"46"},{"id":402,"title":"Исаның құрбанымен құтылдым мен оттан","text":"[Куплет 1]\n// Исаның құрбанымен, құтылдым мен оттан,\nИсаның жарасымен жазылдым, еш күмән жоқ.\nИсаның қанымен, ақталдым күнәдан.\nИсаның өлімімен, берілді мәңгі өмір маған. //\n\n[Припев 1]\nЖарылқашы менің жаным - Тәңірді! Тәңірді!\nМенің бүкіл жан-дүнием, Киелі атын Оның!\nЖарылқашы менің жаным - Тәңірді! Тәңірді!\nЖәне ұмытпа, барлық игі істерін Оның!\n\n[Бридж 1]\nМен сенемін Сенің, құрбаныңа\nКиелі қаныңа, мәңгі өмірге!\nМенің атым Көктегі Кітапта жазылғанына,\nМен сенемін !"},{"id":436,"title":"Исаның нұры жарқырасын менен","text":"[Куплет 1]\nИсаның нұры жарқырасын менен,\nСүйіспеншілік пен пәктік тек Сенен.\nСүюдің алауы, мендегі сөнбеші,\nКөрінсін менен Исаның бейнесі.\n\n[Куплет 2]\nСонда менен көрер Мәсіхтің жүзін,\nСүйіспеншіліктің, пәктіктің ізін.\nТәңірім Рухыңмен Сен маған сөйлеші,\nКөрінсін менен Мәсіхтің бейнесі.\n\n[Куплет 3]\nТыныштық орнап жүректе, көңілде,\nЖеміс берейін нық тұрып сенімде.\nБатаңа иемін, Өзіңді сүйемін,\nКешкі асыңа қатыстыр Киелі.\n\n[Куплет 4]\nМәсіхті жырлайық, өмірдің нәрі,\nЖүректен төгілсін мадақтау әні.\nҚұтқару есігі, шындықтың бесігі,\nЖариялансын Киелі есімі.","songNumber":"191"},{"id":837,"title":"Исаның төгілген киелі қанымен","text":"[Куплет 1]\nИсаның төгілген киелі қанымен\nТазардым., ақталдым мәңгіге\nЕнді мен Қүдайға Әкетайым, деп\nӘркүнде , әрсәтте келемін\n\n[Припев 1]\nЛайықсын, лайықсын,\nлайықсын мәңгіге\nҰлысың, ұлысың Сен\n\n[Бридж 1]\nРухтан төгілген Сенің махаббатың\nБаурап алады менің жүрегімді\nРухтан төгілген Сенің махаббатың\nЖаулап алады менің өмірімді"},{"id":546,"title":"Исаны танимын","text":"[Куплет 1]\nИсаны танимын, Ол бізбен бірге,\nБалғын жүрегімен келеді бізге!\nКөктен жерге келіп қанын төкті,\nСүйіспеншілігін берді!"},{"id":283,"title":"Исаны түсінбедік бәріміз де","text":"[Куплет 1]\nИсаны түсінбедік бәріміз де,\nКүнәға үйреніпті тәніміз де.\nҚұтқарып қалады деп әр нәрсеге,\nСиынып табындық қой бәріміз де.\n\n[Припев 1]\n// Ой, адамдар, адамдар,\nЖүректеріңе қараңдар,\nИса келіп қалар, сенгендерді алар.\nСол уақытта өте кеш болар. //\n\n[Куплет 2]\nКөздеріңді ашыңдар, бауырларым,\nКүнәға толыпты тамырларың.\nҚан емес күнә жүр-ау тамырыңда,\nИманнан адамзат сен айрылдың ба?\n\n[Куплет 3]\nЛәззатты таппақсың ба арақпенен,\nШайтанға беріліп бар болмысыңмен.\nАспандағы орынды жұмақ деген,\nИсаның көмегімен табарсың сен.\n\n[Куплет 4]\nӨміріңді арнашы Оған сеніп,\nЖүректерді ашыңдар, шын сеніңдер.\nСеніп тәубе қылсаңдар ей, адамзат!\nМәңгі өмір сүресің Тәңірменен.","songNumber":"117"},{"id":806,"title":"Иса өзгертші мені","text":"[Куплет 1]\nИса өзгертші мені, Кемшілігім көп себебі.\nҚұрметтеймін тек Сені, Сендей болғым келеді.\n\n[Припев 1]\n// О, Иса, о, Иса,\nСендей болғым келеді. //\n\n[Куплет 2]\nЕнді менің жүрегім, Саған ғана сенеді.\nСенсің жалғыз тірегім, Сендей болғым келеді.\n\n[Куплет 3]\nҮмітім бар өшпейтін, Әлі-ақ лаулап жанамын.\nСенімім бар өлмейтін, Сендей түбі боламын.","songNumber":"83"},{"id":222,"title":"Иса, Өз шәкірттеріңе, өлердің алдында","text":"[Куплет 1]\nИса, Өз шәкірттеріне, өлердің алдында,\nҚолыңа нанды алдың да, шүкіршілік еттің.\nНанды үзіп, үлестіріп, сонда айтқан сөзің:\n«Достар, ауыз тигізіңдер, Бұл нан - денем Менің».\n\n[Куплет 2]\nШырын құйған ыдысты алып, өтінішпен айттың:\n«Дәмін татыңыздар, достар, шарап - Менің Қаным.\nДостар, Жаңа өсиетті қаныммен қалдырдым,\nМенің өлімім сендердің естеріңде қалсын».\n\n[Куплет 3]\nБіз үшін төгілген Қанды еске түсірейік,\nҚиналған тәніңді қазір еске біз алайық.\nТәңірім, Сені есте сақтап, тек Сені ойлайық.\nБіз үшін көп шектің азап, өлерде қиналдың.","songNumber":"193"},{"id":807,"title":"Иса Патша","text":"[Куплет 1]\nПатшалық,\nқұдіретті Құдайдың билігін\nМенің өміріме орнатты\nИсаның құрбандығы\nПатшалық,\nӘкемнің сүйіспеншілігін\nМенің жүрегіме орнатты\nИсаның құрбандығы\n\n[Припев 1]\nИса Патша Иса - Ол\nИса Құдай Иса - Ол\nИса Тәңір - Мәңгіліктің Иесі\n\n[Куплет 2]\nҚұрбандық\nМәсіхтің мен үшін айқышта\nӨліп, қайта тірілгеніне\nМадақ-жыр алғыс айтам\nҚұрбандық\nИсаның өлімі айқышта\nӘкемізбен мәңгі болуға\nмәңгі тірі жол ашты\n\n[Бридж 1]\nИсаның төгілген қанымен\nТозақтын отынан алындым мен\nКөкке ашылған жолымен\nИсаның көмегімен мен жетемін","alternateTitle":"Патшалық, құдіретті Құдайдың билігін"},{"id":481,"title":"Иса ризамын","text":"[Припев 1]\nИса ризамын,\nТілдесем Сенімен әрқашан!\nИса ризамын,\nМені тастамайсын!\n\n[Куплет 1]\nБар қайғымды,\nБар мұңымды,\nАлып Саған келемін!\nБар күнәмді әкелемін,\nСенің алдыңа!\n\n[Куплет 2]\nБар қуаныш,\nБерекеңе,\nМен алғыс айтам Саған!\nБілем Сенің адалдығың,\nМәңгі тұрады!\n\n[Куплет 3]\nЖүрегімді білесін Сен,\nБәрін Саған айталам!\nО Тәңірім өмірімді\nМен Саған тапсырам!"},{"id":596,"title":"Иса, ризамын","text":"[Припев 1]\nИса, ризамын,\nТілдесем Сенімен әрқашан,\nИса, ризамын, менің Қамқоршымсың.\n\n[Куплет 1]\nҚуансам да, жыласам да,\nСаған келіп айтамын\nБар сырымды ақтарамын Сенің алдыңда.\n\n[Куплет 2]\nБаспанамсың, паналаймын\nҚанатыңның астына.\nҚауіпсізбін мен аялы алақаныңда.\n\n[Куплет 3]\nЖүрегімді білесің Сен,\nСенімен мәңгі қаламын,\nО, Тәңір, өмірімді Саған тапсырамын.","songNumber":"248"},{"id":743,"title":"Иса сәби болды","text":"[Куплет 1]\nИса сәби болды, біздей кішкентай,\nИса өсе берді, дана бала болды."},{"id":376,"title":"Иса Сен біздің арамыздасың","text":"[Куплет 1]\nИса Сен біздің арамыздасың,\nБізді Рухың жетелейді.\nКүнәларымызды жойдың Сен,\nСенің тағың аспанда.\n\n[Припев 1]\nТәңірім, Сен-Тәңірсің бұл әлемге,\nТәңірім, Сен\n// Жан-тәніммен табынамын, //\nМен Саған.\n\n[Куплет 2]\nҚұтқарып Сен бізді күнәлардан,\nМәңгілік өмір бердің.\nҚорықпаймын мен енді өлімнен,\nДаңқтаймын Иса Тәңірді.\n\n[Куплет 3]\nБұл дүниенің жарығысың Сен,\nКім Саған ерем десе.\nҚараңғыда ол енді жүрмейді,\nЖарығыңа болады ие.","songNumber":"75"},{"id":494,"title":"Иса Сен мәңгі тірісің","text":"[Куплет 1]\nСенің алдыңда, Тәңірім ғажап өмір сүремін!\nСенің қасыңда, жеңіс туын биік көтеремін!\nІзгілік заңы, шындықтың таңы, жарқырасын мәңгі!\n\n[Припев 1]\nО, Иса - Сен мәңгі, тірісің, қасиетті, мейрімдісің!\nЖүрегімнің төріне қоншы-Құдай!\nТірегімсің- асқар таудай!\n\n[Куплет 2]\nСаған даңқ болып, арналады менің жүрегім,\nСаған, жыр болып, айтылады менің тілегім!\nӨмір жолында, алшы қолыңа, жетелеші- мені!","alternateTitle":"Сенің алдыңда"},{"id":293,"title":"Иса Сен менің берік Қорғанымсың","text":"[Куплет 1]\n// Иса Сен менің берік Қорғанымсың\nИса Шынайы жол, Өмірімсің.\nСаған сенімді артып мойынсұнам\nЖүрек түпкірінен алғыс айтам! //\nЖалғыз тек Саған\n\n[Припев 1]\n// Тәңір Өз Рухынды төкші\nӨмірімді Сен өзгертші\nСаған мен мәңгі ризамын\nҚұрметтеймін, табынамын! //\nСаған ризамын!\n\n[Бридж 1]\nЖалғыз Сен - қорғанымсың!\nЖалғыз Сен - қорғанымсың!"},{"id":136,"title":"Иса, Сен - Тәңірсің","text":"[Куплет 1]\nИса, Сен - Тәңірсің,\nШексіз ризамын мен.\nРухым, жаным, тәнім,\nСаған ашылсын кең!\n\n[Припев 1]\n//  Иса - Патша, Иса - Құдай,\nҚиналдың құрбан боп мен үшін!\nСаған, Патша, Саған, Құдай,\nМадақ, киелі күшің!  //"},{"id":503,"title":"Иса Сені аңсаймын","text":"[Куплет 1]\n// Иса Сені аңсаймын бүкіл жаныммен,\nСені күтемін шын жүрегіммен.\nСені сүйемін жалғыз тек Сені,\nСені Ием! //\n\n[Припев 1]\nЖалғыз Ұлысың,\nЖалғыз лайықсың.\nЖалғыз Сенің атың Иса,\nМәңгі даңқталсын әлемге.\nТөгілген қаның,\nМені ақтаған.\nИса алғыс Саған,\nИем Құтқарушымсың!\n\n[Куплет 2]\n// Иса мен табынамын бүкіл жаныммен.\nСаған ризамын шын жүрегіммен.\nСені даңқтаймын жалғыз тек Сені,\nСені Ием! //"},{"id":965,"title":"Иса сені сүйеді","text":"[Куплет 1]\nМұңаймашы бауырым, өмір көрікті.\nҚұдай сені сүйеді, қандай ұнамды.\n// Сүйгендіктен өз Ұлын құрбан етіпті.\nСен ісенсең кешірер барлық күнәңді. //\n\n[Припев 1]\nИса сені сүйеді,\nИса мені сүйеді.\nОл айқышта біз үшін\nТөкті қанын киелі.\nИса сені сүйеді,\nИса мені сүйеді.\n// Ол айқышта біз үшін\nТөкті қанын киелі. //\n\n[Куплет 2]\nБар адамды сүйеді Құдай бауырым,\nТек күнәні сүймейді етпе жаңылып.\n// Қабылдашы Исаны құтқарушым деп,\nКетпе деймін дозақта мәңгі жағылып. //"},{"id":463,"title":"Иса сені сүйеді, ей, бауырым","text":"[Куплет 1]\nИса сені сүйеді, ей, бауырым,\nЕсігі ашық сен үшін әр қауымның.\n//  Тәубеге кел ағайын, өтінемін,\nКімге керек уақытша сауығың.  //\n\n[Припев 1]\nМәңгілік өмір береді,\nОның қолында себебі.\nКүтіңдер, іздеңдер, асығыңдар.\nИса жақында келеді, келеді.\nИса жақында келеді.\n\n[Куплет 2]\nКөкке бізді Өзімен әкетеді,\nҚабылдасаң Исаны сол жетеді.\n//  Атымен тек Ұлының келерсің,\nАқ ниетпен айтылған уәде еді.  //","songNumber":"76"},{"id":187,"title":"Иса Сені сүйем","text":"[Куплет 1]\nИса Сені сүйем,\nМадақтаймын мен Сені.\nИса Сені сүйем\nМен үшін келгеніңе.\nИса Сені сүйем\nМадақтаймын мен Сені.\nИса Сені сүйем\nҚұтқарғаның үшін мені.\n\n[Припев 1]\nЖаныңда болғым келеді әрқашан.\nСенің қасыңда мен боламын.\nМахаббатпен мені толтырасың,\nТастамайсың Сен мені.","songNumber":"62"},{"id":685,"title":"Иса Сені сүйемін","text":"[Куплет 1]\nИса, Сені сүйемін.\nМадақтаймын мен Сені.\nИса, Сені сүйемін.\nМен үшін өлгеніңе.\nИса,Сені сүйемін\nМадақтаймын мен Сені.\nИса, Сені сүйемін\nҚұтқарғаның үшін мені.\n\n[Припев 1]\nЖаныңды болғым келеді әрқашан\nСенің қасыңда мен боламын\nМахаббатпен мені толтырасың.\nТастамайсың Сен мені,\nТастмайсың Сен мені."},{"id":338,"title":"Иса, сүйем Сені","text":"[Куплет 1]\nИса, сүйем Сені,\nБас иемін алдыңда.\nСаған тағзым етем,\nДаңқтаймын Сені.\n// Аллелуя! Аллелуя! //\nАллелу!","songNumber":"77"},{"id":425,"title":"Иса - Тәңір","text":"[Куплет 1]\n//// Иса - Тәңір! ////\nБар халықтың!\n\n[Припев 1]\nОның тағы әділетті!\nҰлы, күшті, құдіретті!\nОл біздің жанымыздың\nЖауын жеңіп шықты.\nОл біздің Құтқарушымыз!","songNumber":"59"},{"id":924,"title":"Иса - Тәңір, Патшамыз","text":"[Куплет 1]\nИса - Тәңір, Патшамыз,\nКелші осында!\nТағыңнан, орын алшы,\nМадақты, қабыл алшы!\n\n[Припев 1]\nСиынам Саған - Құтқарушым,\nМадақтаймын Сені - Мәсіғім,\nПатша боп келші, Тәңір-Иса,\nҚазір келші, басқара көрші!","songNumber":"78"},{"id":700,"title":"Иса Тәңірім, барлық өмірім","text":"[Куплет 1]\nЕй, Иса Тәңірім, барлық өмірім\nТек Өзіңмен майланғанын мен көрдім\n// Өзіңнен басқа, Тәңір жоқ асқан,\nЖүрекке сөзін Рухымен басқан е-е-й!\nҚұдайым - Сен! Жүрек Иесі! //\n\n[Припев 1]\n// Бақ қонып басқа, тыным келіп жанға,\nӨзіңмен Иса,\nӨзіңнен артық,\nЖүрекке ыстық, ешкім жоқ басқа.\nЖамандық кетіп, жақсылық егіп,\nСен жанымызға, ақ бата беріп\nЖарылқау төгіп, алдың құшағыңа. //\nЕй, жан тыныштығын,"},{"id":729,"title":"Иса! Толып тұр","text":"[Куплет 1]\nИса! Толып тұр\nМенің жүрегім.\nМен сүйем Сені, Сен ғажапсың!\nИса бәрінен де Сен қымбатсың.\nҚұтқарушым өмірім менің Сенсің.\n\n[Припев 1]\nИса! Таптым мен байлықты,\nАлтыннан да қымбат.\nИса! Сүйемін Сені\nҚұдайым, Тәңірім!","songNumber":"67"},{"id":1,"title":"Иса - Ұлы Патша","text":"[Куплет 1]\nИса - Ұлы Патша\nОртамызға келші.\nПатшаның патшасы Иса.\nСиынамыз Саған\n\n[Припев 1]\nҚұдайды мадақтаймыз біз\nҚұдайға қызмет етеміз біз\nТәңірім менің Иса Құдайым\nМәңгі менің патшамсың,\nАумин"},{"id":527,"title":"Кезектен жылдар аттанып, өтуде күн асығып","text":"[Куплет 1]\nКезектен жылдар аттанып, өтуде күн асығып,\nАптығамыз тірлік қамымен, Жаратқанға бас ұрып.\n\n[Припев 1]\n// Ал жылдар зулап, қалдырады тек ізін,\nСанаңда, санаңда сақталар, тағдырың түсін! //\n\n[Куплет 2]\nАқша қарлар жапалақтайды, құстар билеп аспанда,\nБой суынып, мұздайды жүрек, даланы ақ қар басқанда.\n\n[Припев 2]\n// Түсінсең, өткен күн ешқашан қайырылмас,\nМәсіхшіге жөн тар жолынан айырылмас! //\n\n[Куплет 3]\nАлда күтер сені жаңа жыл, құпиясы жұмбақ,\nҚуаныш па, махаббат па, не қайғы тосып тұрмақ.\n\n[Припев 3]\n// Ол жаңа жыл тек бақыт әкелсін,\nҚұдайым қолдап әр кез, Иса азаттық әперсін! //","songNumber":"82"},{"id":558,"title":"Кезектеп жылдар аттанып, өтуде күн асығып","text":"[Куплет 1]\nКезектеп жылдар аттанып, өтуде күн асығып,\nАптығамыз тірлік қамымен, уақытқа ашынып.\n// Ал жылдар зулап, қалдырады тек ізін,\nСанаңда, санаңда, сақталар, тағдырың түсін. //\n\n[Куплет 2]\nАждаһадай аяз қысады, жер ақ көрпе жапқанда,\nБой суынып, мұздайды жаның,\nЖүрекке мұз қатқанда.\nӨмірдің ызғары аяздай қысса да,\nМәсіхші, кейін шегінбе жолың тар болса да.\n\n[Куплет 3]\nАлда күтер сені жаңа жыл, құпиясы жұмбақ,\nҚуаныш па, махаббат па,\nНе қайғы тосып тұрмақ.\nАл жаңа жыл тек бақыт әкелсін,\nҚұдайым қолдап әр кез, Иса азаттық әперсін.","songNumber":"214"},{"id":313,"title":"Кел балалар ән салайық","text":"[Куплет 1]\nКел балалар ән салайық\nИса біздің қуаныш\nКең әлемге жар салайық\nИса біздің жұбаныш\nБарлығымыз мадақтайық\nИса біздің қорғаныш\nАллелуя аллелуя аллелуя амин\nМені сүйеді\nСені сүйеді\nБізді сүйеді\nАмин амин!"},{"id":792,"title":"Кел, барайық Ғолғотаға!","text":"[Куплет 1]\nКел, барайық Ғолғотаға!\nМәсіх онда шалынды құрбандыққа.\nНауқасты емдеп, өліні тірілтті,\nАйқышқа қағылды, жаудай күдікті.\nТізе бүгейік!\n\n[Куплет 2]\nКел, барайық Ғолғотаға!\nӘлемге өмір суын берген Жанға.\nАзап шегіп, Ол жаны қиналғанда,\nҚарап тұрды көз тігіп жиналғандар.\nТізе бүгейік!\n\n[Куплет 3]\nКел, барайық Ғолғотаға!\nИса Мәсіх көз салды аспанға.\n«Сен неге тастадың деді Әкеге?»\nӘлем күнәсін алғанда Өзіне.\nТізе бүгейік!\n\n[Куплет 4]\nКел, шығайық Ғолғотаға!\nИсаның сөзі естіледі онда:\n«Рухымды Саған Мен тапсырдым енді!»\nБіз үшін жанын Мәсіх құрбан етті.\nТізе бүгейік!\n\n[Куплет 5]\nКел, барайық Ғолғотаға!\n«Кешір оларды» деп өтінген Жанға.\nБіз үшін қиналып, көп азап шекті,\nКүнәміз үшін Киелі қанын төкті.\nТізе бүгейік!\n\n[Куплет 6]\nКел, шығайық Ғолғотаға!\nЖеңістің туы тігілген төбеге\nБізді құтқаруға қымбат құн төледі,\nКүнәміз үшін Киелі қанын төкті.\nТізе бүгейік!","songNumber":"192"},{"id":872,"title":"Кел бауырларым таныстырайын","text":"[Куплет 1]\nКел бауырларым таныстырайын\nӨз - Тәңіріммен бәріңді,\nОның сөздері, Оның істері,\nӨзгертеді өмірімді!\nБірге жылайтын, бірге күлетін,\nОл Жұбатушы достымыз,\nОның есімі мадаққа лайық,\nАтағы Оның, мәңгілік!\n\n[Припев 1]\n//  Көзіңмен көр кереметін\nҚұлақпен тыңда сөздерін,\nЖүрекпен қабыл ал Оны,\nИса керемет, Ол біздің!  //\n\n[Куплет 2]\nАрнайық Оған өмірімізді,\nБіз үшін Өз ұлын қыйды,\nҚұрбандығы, баға жетпес биік,\nКиелі қаны төгілді!\nЖақында Иса келеді бізге,\nДайын болайық бәріміз,\nҰйықтап қалмай Оны қарсы алайық\nҚұрмет-қуаныш көрсетіп!"},{"id":917,"title":"Келгейсің, келгейсің","text":"[Куплет 1]\n// Келгейсің, келгейсің.\nАйбынды күш құдіретіңменен.\nКелгейсің, келгейсің,\nО, Киелі Ием, келгейсің. //\n\n[Припев 1]\nДайынмын мен құзырыңа,\nЖетегіңе алғайсың.\nҚайырымды Құдай Әке\nАйыбымды алғайсың.\nКелгейсің, келгейсің,\nО, Киелі Рух келгейсің.\n\n[Куплет 2]\nЛайықсың, лайықсың,\nҚұдайдың құрбандық тоқтысы.\nЛайықсың, лайықсың.\nӨз Есіміңе лайықсың.","songNumber":"74"},{"id":410,"title":"Келемін Саған Жаратушым","text":"[Куплет 1]\n// Келемін Саған Жаратушым\nСенің шексіз махаббатың,\nТаусылмайды рақымың.  //\n\n[Припев 1]\n// Ұлысың Сен,\nСен ғажайып ұлысың.\nСенен артық ешкім жоқ,\nСаған ешкім тең келмес.  //\n\n[Куплет 2]\n// Келемін Саған, аңсап Сені.\nЖүрегімді жадыратшы,\nМәңгілікке жасашы.  //","songNumber":"71"},{"id":369,"title":"Кел, кел!","text":"[Куплет 1]\nКел, кел! Кел, кел!\nСені Иса біледі, кел, кел!\n// Құтқару тек тілегі, жүректі аш кіреді,\nБірге өмір сүреді, келші, келші. //\n\n[Куплет 2]\nКел, кел! Кел, кел!\nНәзік үнін естіші, келші.\n// Сөзін тыңда жалықпа, шақырады жарыққа\nӨз жолыңды анықта, келші, келші. //\n\n[Куплет 3]\nКел, кел! Кел, кел!\nТыныш өмірге енші, келші.\n// Құтқарушыға сенші, қолыңды Оған берші,\nРақымдылығын көрші, келші, келші. //","songNumber":"119"},{"id":394,"title":"Кел, кел бізге + Пр‍иди, приди Ты нам + Come, Come to Us","text":"[Куплет 1]\nКел, кел бізге - Имануил!\nҚұдай бізбен бірге - Имануил!\nКүтеміз біз Сені - Имануил!\nТәңір бізбен бірге - Имануил!\n\n[Припев 1]\nШаттан, шаттан, шаттан - Қазақстан,\nИмануил - Саған, келмек!\nШаттан, шаттан, шаттан - Қазақстан,\nИмануил - Саған, келмек! Шаттан!\n\n[Куплет 2]\nПриди, приди Ты нам, Еммануил.\nС тобою Бог всегда - Еммануил.\nМы ждём Тебя, Господь Еммануил.\nГосподь с тобой всегда - Еммануил.\n\n[Припев 2]\nЛикуй, ликуй, ликуй, Казахстан!\nИдёт к тебе Господь Еммануил.\nЛикуй, ликуй, ликуй, Казахстан!\nИдёт к тебе Господь, Еммануил! Ликуй!\n\n[Куплет 3]\nCome, come to us, Immanuel\nGod is with us, Immanuel\nWe're waiting for you, Immanuel\nThe Lord is with us, Immanuel\n\n[Припев 3]\nRejoice! Rejoice! Rejoice Kazakhstan!\nImmanuel will come to you.\nRejoice! Rejoice! Rejoice Kazakhstan!\nImmanuel will come to you."},{"id":748,"title":"Кел, кел бізге Имануил","text":"[Куплет 1]\nКел, кел бізге, Имануил,\nҚұдай бізбен бірге Имануил.\nКүтеміз біз сені, Имануил,\nТәңір бізбен бірге - Имануил.\n\n[Припев 1]\n// Шаттан, шаттан, шаттан Қазақстан,\nИмануел саған келмек //","songNumber":"70","alternateTitle":"Шаттан Қазақстан"},{"id":1022,"title":"Кел, қазір мадақ уақыты","text":"[Куплет 1]\nКел, қазір мадақ уақыты,\nКел, жүрегіңді Тәңірге бер.\nКел, табынуға жаныңмен,\nКел, өз Тәңіріңнің алдына\nКел.\n\n[Куплет 2]\nУақыт келет, мойындайды барлығы,\nТізе бүгіп Құдайсың деп.\nОны тану қазына асылы,\nҚуаныш жүректі кернеп.","songNumber":"82"},{"id":592,"title":"Кел, Құдайға тағзым етуге","text":"[Куплет 1]\nКел, Құдайға тағзым етуге,\nКел, қасына, көкке жетуге.\nКел, мойынсұнып Оған сен,\nКел, бақыт таппайсың бұған тең.\nКел!\n\n[Куплет 2]\nКел, мадақ айтып Исаға,\nКел, жүрегіңді Оған арна,\nКел, бүгін табын Исаға,\nКел, жалғыз Құдай - Иса Мәсіх.\nКел!\n\n[Припев 1]\n\"Құдайым\"- деп мойындайды халық,\nТағы да келесің анық,\nСенгендер жұмаққа барады\nҰлы сый алады.\nУақыт келер, бәрі Сені көрер,\nБарлық халық Сені таныр,\nАл қазір Сені тыңдағандар,\nШын бақытты болар,\nКел!","songNumber":"118"},{"id":725,"title":"Кел, Құдайды мадақтауға","text":"[Куплет 1]\n// Кел, Құдайды мадақтауға.\nКел, жүрегіңді Оған бергін.\nКел, Тәңірді мадақтауға.\nКел, Ол сені қабылдайды. Кел! //\n\n[Припев 1]\n// Уақыт келді барлығы жар салатын\nСен менің Құдайым - деп,\nӨмірдің байлығы тек сол үшін\nҚұдайды танығанға. //","songNumber":"72"},{"id":1019,"title":"Келші, келші Имануил","text":"[Куплет 1]\nКелші, келші Имануил,\nАзат етші халқымды Құдайым.\nЖалғызсырап адасып жүріппіз,\nСенің Ұлың келгенше бізге.\n\n[Припев 1]\n// Шаттан, шаттан Имануил\nСаған келмек О, Исарил. //\n\n[Куплет 2]\nХалқыңа кел Дәуіттің ұрпағы,\nҚұлдығынан шайтанның босатшы.\nТозақта сақталған қарыздардан,\nТүнектің үстіне жеңіс берші.\n\n[Куплет 3]\nКеліп қандыр шөлін ұлттардың,\nАдамзаттың жүректерін құтқар.\nАзабына халқыңның көз салшы,\nТыныштығыңды Ием, Сен әкелші."},{"id":844,"title":"Келіңдер жаратқан иеге","text":"[Куплет 1]\nКеліңдер Жаратқан Иеге.\nӘндетейік қуана жырлайық.\nАлғыс айтып, алдына келейік.\nДаңқын Оның асыра берейік.\n\n[Припев 1]\nЖаратқан Ие-Ұлы Құдай.\nАспанды да жерді жаратқан.\nЖаратылыстың мәңгі Иесі\nӨз қолымен бәрін жаратқан.\n\n[Куплет 2]\nБилеңдер шаттанып Тәңірге.\nМадақтаңдар беріліп Тәңірге\nБар дауыспен Мінәжат етейік.\nҰлылығын көтере берейік.\n\n[Куплет 3]\nКеліңдер тағзым етейік\nИемізге иілейік\nЖаратушымыз-Тәңір алдында\nОған бағынып, өмір сүрейік."},{"id":469,"title":"Келіңдер Сәбиге, адал жүрекпен","text":"[Куплет 1]\nКеліңдер, Сәбиге, адал жүрекпен,\nКеліңдер Оған Бетлехемге тезірек.\nДүниеге келді ғаламның Патшасы.\n\n[Припев 1]\nКеліңдер, тағзым етіңдер,\nКеліңдер, тағзым етіңдер,\nКеліңдер, тағзым етіңдер, Тәңірге!\n\n[Куплет 2]\nЖарықтан мәңгі жарық,\nҚұдай туды Құдайдан,\nПәк қыздан туды Ол кішіпейіл.\nАдам боп келді жаралмаған Құдай.\n\n[Куплет 3]\nИса, Саған келеміз, Саған сиынамыз.\nҚұрметтеп, Сені мадақтап ән айтамыз.\nМәңгілік Сөз адам боп жерге келді.","songNumber":"83"},{"id":661,"title":"Келіп тұрмын","text":"[Куплет 1]\nКеліп тұрмын Саған, Тәңір,\nМендегі бардың бәрімен.\nЖан-дүниемді қолыңа алшы.\nСенікімін мен мәңгі.\n\n[Припев 1]\nСенемін Саған, Иса,\nСенікімін мен мәңгі.\nӨмір сүрем бір Сен деп,\nӘн саламын бір Сен деп, Тәңір.\n\n[Куплет 2]\nҚайда барсаң, соңыңа ерем,\nШаттықта, мұңда сенім артам.\nЖүрсем деймін ізіңмен Сенің\nСен мәңгілік адалсың.\n\n[Куплет 3]\nТағзым етем,\nТағзым етемін.","songNumber":"84"},{"id":230,"title":"Кенелт Рухыңа","text":"[Куплет 1]\nІздейміз жарқын жүзіңді !\nБіз, күтеміз,құдіретіңді !\nАңсаймыз, Көктен Рухыңды !\n\n[Припев 1]\nКенелтші! Кенелт-Рухыңа!\nКенелт - Рухыңа !\nКенелтші! Кенелтші! Кенелтші!"},{"id":858,"title":"Кең пейілді жүрегіңнен айналдым","text":"[Куплет 1]\nҰлы Сенің киелі ғой,\nАтың адал!\nБас иемін иіліп кеп,\nТақ алдында!\nТәңір Сенің мейіріміңе бөленіп,\nҚуан Әке отырмын мен қасыңда.\n\n[Припев 1]\n// Кеңпейілді жүрегіңнен айналдым,\nРақымңмен тұнып тұрған бойымды,\nҚуаныш пен үміт беріп ертеңге\nЖарылқаймын сенің ғажап атыңды //\n\n[Куплет 2]\nТаң атпастан асығамын Өзіңе,\nҚадаймын мен жүзімді мен көзіңе\nРухына киелі шөлдеп жетемін\nКетпеші Сен, кетпеші Сен қасымнан\n\n[Припев 2]\n// Күнә істі мойындаймын Өзіңе,\nЖасырмаймын айтамын бар сөзімді.\nСүртіп тастап көзден аққан жасымды,\nҚұшақтадың кештім деген есімде. //"},{"id":518,"title":"Керексің тек Сен","text":"[Куплет 1]\nМәңгіге қорқыныш кетті,\nШақырдың Өзіңе келдім.\nСиынып қолымды Саған көтерем.\nМахаббатың тартты Өзіңе,\nДаңқыңды мадақтаймын, Ием.\nСені ғана көргім келеді менің.\n\n[Припев 1]\n// Керексің тек Сен,\nМаған керексің, Ием,\nТек Сен, Ием. //\n\n[Куплет 2]\nӘр күні жаңа жүрекпен\nӘн айтам, Киелі Рух, Саған.\nӘр қадамымды бағытташы, Ием.\nРухым менің қайда болар ет,\nҚұдай Ұлы азат етпесе.\nСенің қолыңдамын мен Иса енді.\n\n[Бридж 1]\nҒалам тек Сенікі,\nЖерде Сенікі бәрі.","songNumber":"85","copyright":"Хиллсонг Унитед"},{"id":874,"title":"Керемет менің күндерім, ғажайып менің түндерім","text":"[Куплет 1]\n// Керемет менің күндерім,\nҒажайып менің түндерім.\nҚасымдасың Сен мәңгі Иса!\nБолдың Сен менің тірегім,\nТыныштығыңда жүрегім,\nАлғыс айтып ән айтамын мен. //\n\n[Припев 1]\n// Еркелеген құстарына,\nМадақтаған бауырларыма,\nАйналаңа қарашы жаңа,\nБұл керемет Құдайдың ісі! //\n\n[Припев 2]\n// Алғыстайды әрбір демім Сені Ием!\nАлғыстайды әрбір ісім Сені Иса!\nАлғыстайды ой-пікірім, жан дүнием!\nАлғыстайды! //"},{"id":926,"title":"Кетпеші, Иса, менен кетпеші","text":"[Куплет 1]\nКетпеші, Иса, менен кетпеші,\nСенсіз мен қорқам өмір жолында,\nОрманда жүрген жолаушыдай жалғыз,\nСен менің қасымда әрқашан болшы.\n\n[Припев 1]\nБала кезден теріс жолменен жүрдім,\nТек Сен ғана мені сақтадың.\nЖамандығы көп Тәңірім дүниенің,\nКеңесің керек, мені қалдырма.\n\n[Куплет 2]\nТас жүрек адам сүюді білмес,\nШын бақыттылық - өзгені сүю,\nҚұдайсыз өмірдің мәні болмас,\nСүюші Ием мені қалдырма.\n\n[Куплет 3]\nМәңгілік көктемді кездестірсем мен,\nСенімен Иса Тәңірім өлсем де.\nҚабірден оят Елазар сияқты,\nӨлімнен өткіз мәңгі өмірге.","songNumber":"81"},{"id":100,"title":"Кешке үйге келгенде","text":"[Куплет 1]\nКешке үйге келгенде\nКөңілді, тыныштық.\nӘжем ең жақын досым,\nМаған тым ыстық.\nӘжем мейірімді, ақ әжем менің,\nМен үшін қанша төгілді терің.\n\n[Куплет 2]\nСиынады біз үшін,\nЖазбаны оқиды.\nМаған қыста жып-жылы\nҚолғап тоқиды.","songNumber":"249"},{"id":539,"title":"Кешікпе адасқан ұл, туған үйіңе кел","text":"[Куплет 1]\nКешікпе адасқан ұл,\nтуған үйіңе кел!\nОнда Сені күтіп тұр,\nСүйікті Әкең, аңсап!\n//  Онда, Әкең қайғырып,\nКөз жасын төгеді!\nАлысқа қарап, ұлын Ол,\nҚашан келеді - деп?!  //\n\n[Куплет 2]\nЕгер де, сен ұялсаң,\nАр-ұятың қинап,\nДұрыс істемедім-ау,\nКешірім, болама?!\nТереңге құласаңда,\nКүнаңа - ор болар,\nӘкең сені сүйеді,\nГүл егісің, Оның!\n\n[Куплет 3]\nҚасірет келіп саған,\nБақытың жоғалды,\nДостарың сені тастап,\nЖүрегіңде қайғы!\n//  Әке үйінде бақыт,\nӘкеңде тыныштық!\nӘке үйі қуаныш,\nТуған үйің сенің!  //"},{"id":443,"title":"Кешір мені, Құдай, өте кеш келдім","text":"[Куплет 1]\nКешір мені, Құдай, өте кеш келдім.\nКешіре гөр, жалынамын Құдайым.\n\n[Припев 1]\n// Кешір Сені ертерек мен білмедім.\nСөйтіп жүріп жалған досты тыңдадым! //\n\n[Куплет 2]\nҚарсыластым Сенімен, кешір мені.\nАйқыш ағашқа аямай қақтырдым,\n\n[Припев 2]\n// Қиналуға мәжбүр етіп мен Сені.\nКешіре гөр, азап отына салдым! //\n\n[Куплет 3]\nӨз қолыңмен жібітіп жүрегімді,\nОяттың мәңгілік өмірге мені\n\n[Припев 3]\n// Көзімді ашып өткен өміріме,\nКөрсеттің Сен күнәкар екенімді! //\n\n[Куплет 4]\nАлдыңда дұға етіп бас иемін.\nӨз қолыңмен жетелеші Тәңірім.\n\n[Припев 4]\n// Арнаймын бар өмірімді Өзіңе,\nКөмектесші қасиетті күресте! //\n\n[Куплет 5]\nБұдан былай ісіммен де, сөзіммен\nДаңқыңды мен асыруға сөз берем.\n\n[Припев 5]\n// Нұрды көріп жарқыраған бойымнан,\nКеле берсін жұрттың бәрі Саған! //","songNumber":"80"},{"id":256,"title":"Кешіріп, бір-біріңе қайрылмасаң","text":"[Куплет 1]\nКешіріп, бір-біріңе қайрылмасаң,\nРенжіткен адамдарды сүйе алмасаң,\nАйтарым: сен Құдайды танымайсың,\nӨйткені: «Құдай - сүю» деп жазылған.\n\n[Куплет 2]\nЖабырқап бұл өмірден түңілгенде,\nКей кезде көңілге көп түсер қайғы,\nЖігерлен, еңсеңді көтер, бауырым,\nЕсіңе ал Жаратушы Иең жайлы.\n\n[Куплет 3]\nСүйе біл сені сүймейтін адамды,\nЖойылсын залым ойлар тым қараңғы,\nСонда сен бұл өмірде жеңімпазсың,\nСенімде берік тұрып, бол табанды.","songNumber":"154"},{"id":633,"title":"Киелі Адонай, қасиетті","text":"[Куплет 1]\nКиелі Адонай, қасиетті.\nКиелі Адонай, ақ ниетті.\nКиелі Адонай, сүйемін Сені.\n\n[Припев 1]\nҰлы Құдай Саған табынамын.\nДұғамды айтып Саған ашыламын.\nКиелі Рухпен жүрегімді өзгерт менің\nҚұдай Ием, Киелі Адонай.\n\n[Куплет 2]\nАна Адонай, мошианна.\nАна Адонай, ацлеханна.\nАна Адонай, аэ-панэха.\n\n[Припев 2]\nБарух ха ба бэшем Адонай.\nМимейт Элохим аварэхет шимха.\nБитхулим шавет- цэрек аво обам.\nОдей - Иа, Ана Адонай.","songNumber":"69"},{"id":432,"title":"Киелі Әке","text":"[Куплет 1]\nАйқыш ағашта қиналдың\nКиелі қаныңды төктің\nИса рахмет Саған\nБарлық күнәмді кешірдің\nЖаңа өмірді сыйладың,\nИса рахмет Саған!\n\n[Предприпев 1]\n//  Түнектің қақпасын Сен жаптың,\nӘкеме жолымды Сен аштың!  //\n\n[Припев 1]\nКиелі Әкеме табынамын,\nТабынамын өміріммен.\nКиелі Әкеме мен арнаймын,\nМен арнаймын жүрегімді.\nКиелі Әкеме бағыштаймын,\nБағыштаймын сенімімді.\nКиелі Әкеме бас иемін,\nМен сүйемін мәңгілікке!\n\n[Куплет 2]\nКиелі Рухыңды төктің,\nӨз Сөзіңмен Сен өзгерттің мені.\nИса, сүйем Сені!\nӨмірімді Саған бердім,\nжетелеші мәңгілікке мені,\nИса, сүйем Сені!","songNumber":"13","alternateTitle":"Айқыш ағашта қиналдың, Киелі қаныңды төктің"},{"id":447,"title":"Киелі, киелі","text":"[Куплет 1]\nКиелі, Киелі, Киелі Тәңір Ие -\nҚұдіретті Құдай.\nЕрте тұрып қуанып\nӘн саламыз Оған:\nКиелі, Киелі, Киелі Тәңір Ие -\nЖанашыр да күшті.\nҮшбірлік Құдай - мәңгі махаббат.\n\n[Куплет 2]\nКиелі, Киелі, Киелі Тәңір Ие -\nҚұрметпен табынып,\nКөкте киелілер даңқтап тағзым етеді.\nПеріштелер бәрі тізесін бүгеді,\nМәңгілік Иесі мейірлі, игі\n\n[Куплет 3]\nКиелі, Киелі, Киелі Тәңір Ие -\nТылсым құпиялы.\nКөре алмас өлілер асқақ даңқын Оның.\nОл ғана тек жалғыз, Ұлы Құдай биік\nҒажап, мықты, пәк, таза, қасиетті.\n\n[Куплет 4]\nКиелі, Киелі, Киелі Тәңір Ие -\nҚұдіретті Патша,\nҚұдай Атын даңқтайды\nАспан, теңіз, жерде.\nКиелі, Киелі, Киелі Тәңір Ие -\nБіз де дәріптейміз\nМәңгі Құдайды даңқ пен мадақпен.","songNumber":"86"},{"id":188,"title":"Киелі, Киелі Құдайым","text":"[Куплет 1]\nКиелі, Киелі Құдайым\nБүкіл жер әлемге Киелісің.\nБарлық ұлттар бас исін\nКиелі Сенің Ұлыңа.\nЖарқыра, бәріне\nМейріміңді әлем көрсін.\n\n[Припев 1]\nМадақтаңдар Құдайды\nОның ғаламатын, шексіз рақымын\nСұлулығын Иса Ұлының."},{"id":326,"title":"Киелі кітап","text":"[Куплет 1]\nКиелі кітап, оған құлақ саламыз,\nОл Құдайдың Сөзі!"},{"id":330,"title":"Киелі кітаптан білеміз","text":"[Куплет 1]\nКиелі кітаптан білеміз:\n\"Құдай балаларды сүйеді\"."},{"id":969,"title":"Киелі қолы Исаның сақтады мені күнәдан","text":"[Куплет 1]\nИем Саған қол созамын мен\nКеудемді шаттық кернейді\nКүш аламын жалғыз Өзіңнен,\nАлақанымда сермейді\n\n[Припев 1]\n//  Киелі қолы Исаның,\nСақтады мені күнәдан,\nАшып жұмақ есігін,\nҚұтқарды мені, тозақтан! //","songNumber":"179","alternateTitle":"Ием, Саған қол созамын мен,"},{"id":372,"title":"Киелі Құдай біздерді","text":"[Припев 1]\nКиелі Құдай біздерді\nСақтап жүрші әрқашан.\n// Сиынып келемін Саған,\nТыныштық берші маған //\n\n[Куплет 1]\nКешке Саған келемін,\nАлдыңда тізе бүгемін.\nӘрбір атқан арайлы күн,\nБәрі де Сенің бергенің.\n\n[Куплет 2]\nАдасып жүрдім, білмедім,\nҚателікті көп істедім.\nКешірші, мені Құдайым,\nЖанымда болшы әрдайым.\n\n[Куплет 3]\nПеріштелерің қорғасын,\nӘрбір түнде біздерді.\nЕшбір жамандық болмасын,\nКөрейін тәтті түстерді.","songNumber":"250"},{"id":37,"title":"Киелі Патша, Киелі Ием..","text":"[Куплет 1]\nКиелі Патша Киелі Ием\nБір Саған ұнағым келеді\nЖалғыз тірегім Сен едің\nКиелі досым, адал досым\nЖүрекке тыныштық бересің\nҚолдап қорғап келесің\n\n[Припев 1]\nБар ғаламға жариялап\nМені таңдағаныңды\nӨмір сыйлағаныңды\nАйта бергім келеді\nШексіз махаббатыңды\nӘке деген атыңды\nСенсің жалғыз сырласым\nСаған жырым тынбасын\nМәңгі!"},{"id":704,"title":"Киелі Рух","text":"[Куплет 1]\nӘрбір тынысымсың, қалқандай Қорғаушым\nКиелі Рухың бойымда менің\nКүнделікті наным, әр күндегі нәрім\nКиелі Сөзің айтылған маған\n\n[Припев 1]\nАл мен мұқтажбын Саған Ием\nАлмен Сенсіз адасқан жанмын\n\n[Куплет 2]\nӘрбір тынысымсың, қалқандай Қорғаушым\nКиелі Рухың бойымда менің\nКүнделікті наным, әр күндегі нәрім\nКиелі Сөзің айтылған маған\n\n[Припев 2]\n// Ал мен мұқтажбын Саған Ием\nАл мен боламын мәңгі Сенімен //","alternateTitle":"Әрбір тынысымсың, қалқандай Қорғаушым","copyright":"1995 Меркы / Винеярд Публишинг"},{"id":189,"title":"Киелі Рух жылытшы менің жүрегімді","text":"[Куплет 1]\nКиелі Рух жылытшы менің жүрегімді,\nКиелі Рух жаңартшы менің бар ойымды.\nТолтыршы өмірімді Өз нұрыңменен,\nКүш берші өмір суыңмен.\n// Алғыс Саған! Алғыс Саған! //\n\n[Припев 1]\nМадақ, мадақ болсын\nСаған Тәңір Ием!\nМадақ болсын,\nмадақ болсын Саған!","songNumber":"64"},{"id":165,"title":"Киелі Рух келші бізге","text":"[Куплет 1]\nКиелі Рух келші бізге,\nСенің даңқың толсыншы осы жерге.\nСенің еркің мадақталу\nХалықтардың арасында.\nҚолымызды жайып жарылқау күтеміз.\nБос жүректер Рухыңмен Сенің толсын.\n\n[Куплет 2]\nМенің айтқан әнім\nСаған барып жетер әрқашан.\nМенің еркім Өзіңе өмірімді арнасам.\nМенің сыйым Саған көтеріліп жетсін.\nОсы әнімде мен Саған бас иемін.","songNumber":"76"},{"id":916,"title":"Киелі Рух келіп","text":"[Куплет 1]\nКиелі Рух келіп\nХалықтарды оятшы.\nСенің ұл-қыздарың\nПайғамбарлық сөз айтсын.\nТүс-аяндар беріп\nҚұпияларды ашшы.\nКелуіңді күтіп\nСеніміміз күшейіп арта берсін.\n\n[Припев 1]\nҮлкен ояныш келе жатыр.\nКүтудеміз Ол халқымызға келеді.\nҮлкен ояныш келе жатыр.\nСонда Исаға сенген\nӘркім құтқарылады.\n\n[Куплет 2]\nКиелі Рух келіп\nХалықтарды оятшы.\nСалтанат көрген ел\nДаңқыңды көтерсін.\nСілкіндіріп жерді\nҚұдіретіңді көрсетші.\nБар жаратылысың\n«О,Тәңір, тезірек кел» -\nдеп күтеді.","songNumber":"73","alternateTitle":"Үлкен ояныш келе жатыр"},{"id":928,"title":"Киелі Рух көз бердің","text":"[Куплет 1]\nКиелі Рух көз бердің.\nКөмейіме сөз бердің.\nДүние бүкіл дөңгелеп,\nКөз алдымда өзгердің.\n\n[Припев 1]\n// Күнәмді Сен кешірдің,\nПәк қаныңмен өшірдің,\nАшып бердің мен үшін\nМәңгіліктің есігін! //\n\n[Куплет 2]\nИса Мәсіх, жан Ием,\nБүгін, міне, кез келдің.\nҚұдіретті Құдайдың\nАузындағы сөз бе едің?\n\n[Куплет 3]\nСен Құдайдың Сөзісің,\nБір Құдайдың Өзісің.\nҚұрбандыққа шалынған\nҚасиетті «Қозысың».","songNumber":"12"},{"id":89,"title":"Киелі Рух күтеміз","text":"[Куплет 1]\nКиелі Рух, күтеміз Сені\nҰлылығыңмен толтыршы осы\nЖерді\nӨз халқыңның Сені аңсап,\nІздегенін қалайсың\nҚолымызды жайып\nЖарылқау күтеміз\nСені іздеген жүректерді толтыршы\n\n[Припев 1]\nЖырлап, айтар әнім\nТасқындай Өзіңе ағылады\nӨмірімді арнаймын\nЖетелеші Тәңірім\nОсы мадағымды\nҚабыл алшы Әке\nСаған келіп, бас иемін Тәңірім"},{"id":292,"title":"Киелі Рух, Сенің қасыңда","text":"[Куплет 1]\nКиелі Рух, Сенің қасыңда, мәңгі болғым келеді\nҚұшағыңа алшы.\nКиелі Рух, нәзік жүзіңді, жүрегіммен сезем, толтыршы.\n\n[Припев 1]\nКиелі Рух, Киелі Рух !\nКиелі Рух, Киелі Рух !\nӨз өмірімді, Саған бағыштаймын.\nБіртұтас болғым келеді, Сенімен Ием !\nРизамын Саған, жетеле мені.\nСаған теңдес ешкім жоқ, сүйемін Сені !\n\n[Бридж 1]\nШын жүректен, рахметімді, Саған ғана айтамын!\nСұраймын Сені, жетелеші, Әкемнің тағына!"},{"id":914,"title":"Киелі Рух, сүйемін Сені","text":"[Припев 1]\n// Киелі Рух, Киелі Рух,\nКиелі Рух, сүйем - Сені! //\n\n[Куплет 1]\nСұлусың, Ием жарқын,\nМәңгілікке жетелейді жан Досым!\nЖүректің төріне,\nШақырам Сені, күтем Сені Ием!\nТек Сенің еркің болсын өмірімде,\nҒажап махаббатың жүрегімді өзгертсін,\nБүкіл жаныммен Саған мен сенемін,\nТеңдес ешкім жоқ Саған,\nАңсап Сені сүйемін!"},{"id":559,"title":"Киелі Рух төгіледі","text":"[Куплет 1]\n//  Киелі Рух,төгіледі! Киелі Рух,төгіледі!\nКиелі Рух,төгіледі! Бойыма,бойыма!  //\n\n[Припев 1]\nТау самалы секілді,сергітеді көңілді.\nНөсеріндей көктемнің,ағылады өзені\nЖалынынан жүректің, алаулайды жер беті,\nАлаулайды жер беті!"},{"id":203,"title":"Киелі Рухтың жұмысы жүрегімде жүріп жатыр","text":"[Куплет 1]\nКиелі Рухтың жұмысы,\nЖүрегімде жүріп жатыр,\nПәк-таза, киелі болуға үйретеді!\n// Жетелеуінде, Рухыңның, жетелеуінде,\nМәңгілікке мен барамын! //\n\n[Припев 1]\n// Жетеле Ием, Киелі Рухыңмен,\nЖетеле, таза Сөзіңмен! //"},{"id":512,"title":"Киелі таңдалған Иса!","text":"[Куплет 1]\n//  И - и - са! И - и - са!\nКиелі, таңдалған - И - са!\nИ - и - са! И - и - са!\nКөк - ке, көтерілген - И - са!  //\nСенің атың бал сияқты ерніме,\nСенің Рухың су сияқты жаныма!\nСенің Сөзің шам сияқты аяғыма!\nСені сүйемін Иса!","copyright":"1988 Меркы / Винеярд Публишинг"},{"id":609,"title":"Киелі Тәңір, ұмтылам Саған","text":"[Куплет 1]\nКиелі Тәңір, ұмтылам Саған\nЖан тыныштығы Сенде, білемін.\n\n[Припев 1]\n// Кеудеңде Сенің табамын тыным,\nБасылады жүрегім менің //\n\n[Куплет 2]\nБілемін Сенде мәңгі қуаныш\nЖәне баянды махаббат.\n\n[Куплет 3]\nЕшкім мені енді айыра алмайды,\nБұл мәңгілік қуаныштан.\n\n[Куплет 4]\nКелгенде менің ақырғы демім,\nҚабылдарсың мені, сенемін.","songNumber":"84"},{"id":238,"title":"Көз тігем жалғыз Өзіңе","text":"[Куплет 1]\nКөз тігем жалғыз Өзіңе,\nҚұдайым Сен Жартасым!\nО, Иса, Саған «Осанна»\nБарша халық жар салсын.\nӨлкеңді тастап көктегі,\nЖерге келдің Сен маған.\nЖүрегімді беріп енді,\nҰмтыламын тек Саған.\n\n[Куплет 2]\nБұл әлемде барлық нәрсе,\nӨзгереді тұрмайды.\nО, Иса, Саған «Осанна»,\nЖүрегім жырлайды.\nМәңгі тірі Иса Ием,\nМен үшін азап шекті.\nАңсаймын мен Тәңіріммен\nКездесетін сол сәтті.\n\n[Куплет 3]\nТүнек те түріліп әлі,\nЖарық түсері анық.\nО, Иса, Саған «Осанна»,\nМадақтасын бар халық.\nБар күмәннан тазалайсың,\nБойыма менің енген.\nМәңгі сүйіспеншілікпен,\nӨзіңмен бірге келген.","songNumber":"170"},{"id":713,"title":"Көзімді ашшы Тәңірім","text":"[Куплет 1]\nКөзімді ашшы Тәңірім\nКөзімді ашшы Тәңірім\nСені көргім келед(і)\nСені көргім келед(і)\n\n[Припев 1]\nЛайым даңққа бөленіп\nҚұдіретіңмен жарқырашы,\nМадақтаймыз Сені\nТәңіріміз Киелі, Киелі,\n\n[Бридж 1]\nКиелі, Киелі, Киелі.\nКиелі, Киелі, Киелі.\nКиелі, Киелі, Киелі.\nСені көргім келеді","copyright":"1997 Интегриты'с Хосанна! Мусик"},{"id":306,"title":"Көк аспанда","text":"[Куплет 1]\nКөк аспанда, алғашқы,\nТүнгі жұлдыз қалқиды!\nБалаларға айтады,\nБұл күн де аяқталды!\n// Ұл-қыздар ұйықтайды,\nЖұлдыздар жарқырайды! //\nМамаларымен бірге\nБалалар сиынады\nШүкір бұл күнге"},{"id":978,"title":"Көк аспан күтеді мені","text":"[Куплет 1]\nКөк аспан күтеді мені\nҚуаныштың болмай шегі\nКездесем Тәңірім Исамен\nКиелі Рухпен, Әкеммен.\n\n[Припев 1]\n// Гүл тәжі, әрине гүл тәжі\nБеретін сыйлығы Әкемнің.\nГүл тәжі, әрине гүл тәжі\nБеретін сыйлығы Әкемнің./\n//  Аллелуя! Аллелуя! ////  ////\n\n[Куплет 2]\nБұл жұмақтың қаласы шашбауын\nАйнала періште толған гүл.\nЖарқырап жүздері достардың\nИсаның келуін күтіп тұр.\n\n[Куплет 3]\nКездесем Петірмен, Жоханмен\nжәне көп киелі бауырмен.\nҚұшақтайд(ы) мені олар жақын кеп,\nҚуаныш таусылмайд(ы) тасып кең.","songNumber":"88"},{"id":190,"title":"Көк пен жердің Иесі","text":"[Куплет 1]\nКөк пен жердің Иесі,\nСу мен жер аспанның,\nБүкіл аспан киелі тағың.\nДаңқты Тәңірге мадақ.\n\n[Припев 1]\nҒажап Тәңір ғаламнан да биік\nКиелісің, Киелісің\n// Жер мен көктің Иесі //\n\n[Куплет 2]\nТаңертең ертемен\nНұрыңа шаттанамын\nҚараңғыда сүрінсем мен\nАтыңды шақырамын.\n\n[Бридж 1]\n/// Аллелуя көк пен жердің Иесіне ///"},{"id":728,"title":"Көктегі Әкеміз","text":"[Куплет 1]\nКөктегі Әкеміз,\nКиелі есімің қастерлене берсін!\nПатшалығың жерге келсін!\nЕркің Көкте орындалғандай,\nЖерде де, орындалсын!\nКүнделікті нанымызды, бере гөр!\nКінәліні кешіргендей,\nКүнәмізді кешіре гөр!\nЖамандыққа түсірмей,\nАзғындықтан сақтай гөр!","songNumber":"16"},{"id":26,"title":"Көктегі Әкемізге болсын деймін мадақ!","text":"[Куплет 1]\nКөктегі Әкемізге болсын деймін мадақ!\nОның мейірімділігі бізбен бірге болмақ.\nКөктегі Әкемізге болсын деймін мадақ!\nОның рақымдылығы бізге жетіп тұрмақ.\n\n[Припев 1]\n// Сән-салтанат Иемізге!\nБар мақтау Құдайға!\nКиелі Рухын біздерге\nЖар болсын, Аумин! //\n\n[Куплет 2]\n// Құтқарушым Саған да Болсын деймін мадақ!\nСенде ғана сая тапты күнәкар ұрпақ. //\n\n[Куплет 3]\n// Киелі Рух Саған да болсын деймін мадақ!\nӨмірдегі шындық жолды көрсеттің анық. //\n\n[Бридж 1]\nКөктегі Әкемізге болсын деймін мадақ,\nҚұтқарушым Саған да болсын деймін мадақ,\nКиелі Рух Саған да, болсын деймін мадақ!","songNumber":"89"},{"id":742,"title":"Көктемде, көктемде","text":"[Куплет 1]\nКөктемде, көктемде бәріде өседі,\nКөктемде, көктемде бүршік атады."},{"id":487,"title":"Көктем келді айнала құлпырып","text":"[Куплет 1]\nКөктем келді айнала құлпырып,\nжер жасылын жамылып.\nҚұстар келді, әндете сән құрып,\nкөктемгі күн жылынып.\n\n[Припев 1]\nҚуанышты сонда хабар естілді,\nИем Иса тірілді! тірілді!\nҚуанышты сонда хабар естілді,\nИем Иса тірілді, тірілді!\n\n[Куплет 2]\nҚұдіретті ісі бұл Құдайдың,\nескі жылан езілді.\nҚұдай ұлы Мәсіх өліп, тіріліп,\nөмір жеңді өлімді.\n\n[Куплет 3]\nБар әлемді өлімнен құтқарып,\nмәңгі өмір сыйлады.\nКиелі Рух жан - дүниемді ақтарып,\nжаңа өмір басталды.","songNumber":"169"},{"id":45,"title":"Көктен келген түспесе нұрың","text":"[Куплет 1]\nКөктен келген түспесе нұрың,\nСәулеңсіз Сенің, солады жаным!\nЖүректен сыздап, шығады мұңың!\nЖалғыздық қоршап шаршатты мені\nЖаным қиналып, іздеді Сені,\nЖеткізді тағдыр Сенің - Өзіңді!\n\n[Припев 1]\nҚос аққудай көк айдында,\nЖүзіп жүрмін Сен жанымда\nСенемін мен мәңгі таза махаббатыңа!\nАялайсың, тербетесің,\nЖұбатасың, кешіресің,\nСенемін мен ыстық сезім махаббатыңа!"},{"id":649,"title":"Көмекке келдің","text":"[Куплет 1]\nТізерлеп ғибадат етіп\nБарымды беріп сені іздеуге\nМен сендікпін Ием\n\n[Куплет 2]\nТапсырамын өмірімді\nМейірімді Құдай бас иемін\nСенің төріңде мен\n\n[Припев 1]\nШақырдым, Сен жауап бердің\nСен маған көмекке келдің\nСен бар жерде болғым келеді\n\n[Бридж 1]\nӨмірде Сен мадақтал\nӘлемде Сен мадақтал\nБар жүректен Сен мадақтал\n(Мадақтал, Мадақтал)"},{"id":81,"title":"Көрсеттің бізге шындықты ашып","text":"[Куплет 1]\nЖүректе толқын сыймайды тасып,\nӨзіңе деген алғысым Ием!\nМәңгілік өмір сыйладың бізге,\nӨмірдің қиын азабын тыйып\nАсудай асып, толқиды тасып,\nКеудемді соғады бір сезім симай.\nКөмегі әркім өсірген жалған,\nШуағын төкті өмірдің жаңа\n\n[Припев 1]\nӨмірдің әні Өзіңсің сәні!\nӨзіңмен бігре шаттанамын,\nСенімге Сенің шексіз талас,\nСерігім болды Тәңірім Құдай.\n// Алаңда Сенің адамда мәңгі\nСаламыз әнге Жаратқан Ием,\nКөрсеттің бізге шындықты ашып!\nМың алғыс айтамыз Саған Иеміз. //"},{"id":2,"title":"Көтерілді шаңырақ","text":"[Куплет 1]\nКөтерілді шаңырақ,\nЖұмақтағы төрінде.\nӘке бәрін шақырып,\nДайындаған үйіне.\n\n[Припев 1]\n// Тойға шақырылған кезіңде\nДайын бол қашанда\nДүниеге байланба\nҚұщағына сыйғызады\nӘкеміз шақырғанда\nАлданып қалып қалма //\n\n[Припев 2]\n// Естімген көз көрмеген той басталды мәңгілік\nҚұтқарылған әрбір жанның дайындады Әке орнын //\n// Күтіп отыр әр баласын дастарханның басында\nКелсін қалсын деп мәңгі жайындаған отбасында. //"},{"id":44,"title":"Күз де келді сарғайды жапырақ","text":"[Куплет 1]\nКүз де келді сарғайды жапырақ,\nЖер бетіне түсті шашырап.\nКүз күндері жабырқау әуенмен,\nӘн салады нәзік сезіммен.\n\n[Припев 1]\nБіржола әсем жаз сен де кеттің,\nКөктемнің қызуын әкеттің.\nЕнді орақ науқаны тұсында,\nКүз бізге мол жеміс ұсынды.\n\n[Куплет 2]\nӨмірдің күзі де басып алды,\nКүндер мен уақыт асығады.\nСұрапыл әлемнің көз алдында,\nТаңда шұғыла жарқырады.\n\n[Припев 2]\nҚұдіретті әділ би Исаның,\nАлдына сен нені әкелдің.\nОл сенің жемісіңді күтеді,\nСені жұмаққа жетелейді.\n\n[Куплет 3]\nКүз келді дала тегіс мұздады,\nҚажыған жүректер сыздады.\nКүнә түнегі жерді қаптады,\nАзапсыз таңымыз атпады.\n\n[Припев 3]\nОрасан науқан күні келеді,\nСонда әркім жауап береді.\nОл күн көпке үрей әкеледі,\nБүкіл әлем дүр сілкінеді.","songNumber":"194"},{"id":610,"title":"Күзде теңіз жағалауы","text":"[Куплет 1]\nКүзде теңіз жағалауы,\nКөмкерілер алтынмен.\nОртасында шағалалар,\nЖарысады толқынмен.\n\n[Припев 1]\nАйтшы, досым, қай суретші\nСалған мұның бәрін?\nҚұдай Ие сол Суретші,\nОны мадақтайық.\n\n[Куплет 2]\nТүрлі-түрлі балықтар бар,\nСол теңіздің түбінде.\nМініп алып көк дельфинге,\nЖүзсе толқын үстінде.\n\n[Куплет 3]\nАқ қайыңға қараңдаршы,\nЖапырағын төгеді.\nТөбесінен төңкеріліп,\nКөк аспан көрінеді.\n\n[Куплет 4]\nНеткен ғажап асау теңіз,\nАлтын күн мен шағала.\nМадақ айтып Тәңіріңе,\nЗор мейірін бағала.","songNumber":"251"},{"id":935,"title":"Күйе басқан шырағыңның","text":"[Куплет 1]\nКүйе басқан шырағыңның,\nШынысын тазалашы.\nЖарық қыл үйдің ішін,\nҚараңғы қаптамасын.\n\n[Припев 1]\nСұраймын бауырларым,\nСұраймын бір туғаным.\nТазалашы жүрегіңнің,\nШырағын шырағын.\n\n[Куплет 2]\nҚанша үй қараңғыда,\nКүнәнің тұтқынында.\nІздейді өмір суын,\nАйтып бер сұрағанға.\n\n[Куплет 3]\nЖарқырайды үйдің іші,\nҚолымда Киелі Інжіл.\nОқимын Тәңір Сөзін,\nІшемін өмір сусын.\n\n[Припев 2]\nТазартты жүрегімді,\nЖоқ қылды күнәларды.\nТәңірімнің жүзі өткір\nҚылышы, қылышы.","songNumber":"105"},{"id":920,"title":"Күлімдеген күн нұрындай","text":"[Куплет 1]\nКүлімдеген күн нұрындай,\nЖанымдасың Сен менің.\nКөктемдегі ақ жауындай\nСені аңсап жүремін.\n// Кетер едім Сен болмасаң адасып,\nКетер еді-ай жүрегімді мұң басып. //\n\n[Куплет 2]\nСаған деген жаңа әнім\nТаусылмайтын дәрия.\nМаған деген мейірімің\nАшылмайтын құпия.\n// Айсыз түнде жарық шаштың жолыма.\nНағыз бақыт алып бердің қолыма. //\n\n[Куплет 3]\nЖүрегімнің нәзік үнін\nСезесің Сен білемін.\nӨмірімнің әрбір күнін\nТыныштыққа бөледің.\n// Сен менің биік ұшқан Арманымсың.\nБәрінен де Сен бүгін жоғарысың. //","songNumber":"75"},{"id":930,"title":"Күлімдеп күннің көзі","text":"[Куплет 1]\nКүлімдеп күннің көзі,\nБойыма жылу берді.\nКиелі Тәңір Сөзі,\nЖаныма қуат берді.\n\n[Припев 1]\n// Тәңірім, сүйем деді.\nЖанарым күлімдеді.\nАрманым бұдан артық,\nБар ма еді? //\n\n[Куплет 2]\nЖарқырап көрінеді,\nМәңгілік өмір лебі.\nЖүректен сезіледі,\nТәңірдің ыстық демі.\n\n[Припев 2]\n// Өмірдің қайнар көзі,\nКиелі Тәңір Сөзі.\nСол түні жер бетіне,\nКелді Өзі. //\n\n[Куплет 3]\nЖұбатып көңілімді,\nӨзгерткен өмірімді.\nҚуантқан жүрегімді,\nСүйемін Тәңірімді.\n\n[Припев 3]\n// Ағылып төгіледі,\nӨмірім берекелі.\nКүнәнің құлдығында,\nЖоқпын енді. //","songNumber":"106"},{"id":106,"title":"Күнәдан тазалаймын","text":"[Куплет 1]\nКүнәдан тазалаймын,\nКелші, Маған, балам.\nТар жолда жетелеймін,\nЖол көрсетіп саған.\n\n[Припев 1]\nСаған Әке боламын,\nҚалдырмаймын жалғыз.\nҚуанышты жүзіңмен\nАйтарсың Сен алғыс.\n\n[Куплет 2]\nҮйіме апарамын\nҚарсы алып Мен сені,\nҚасыңнан табыламын\nШақырсаң сен Мені.\n\n[Куплет 3]\nҚұтқарылғандардың.\nҚұдай берген орын бұл,\nШаршап-шалдыққанның","songNumber":"253"},{"id":932,"title":"Күнәмді айтқым келмеп еді","text":"[Куплет 1]\nКүнәмді айтқым келмеп еді,\nСонда аяқ-қолым сырқырап,\nКүні бойы жүрдім ыңқылдап.\nКүні бойы жүрдім ыңқылдап.\n\n[Припев 1]\nӘділетсіз ісі кешірілген,\nКүнәсі ақталған бақытты!\nМойнына Тәңір күнә қоймаған,\nТәңірді алдамайтын бақытты!\n\n[Куплет 2]\nСебебі Сенің қолың\nЗілдей болып үстімде жатты\nСонда жаздың аптабындағы\nКөк шөптей солып қалдым\n\n[Куплет 3]\nКүнәмді Саған арттым\nҚылмыс пен әділетсіздікті\nӨзіңе жасырмай айттым\nСонда Өзің мені кешірдің\n\n[Куплет 4]\nҚұдайсыз адамдар бақытсыз\nАл егер Тәңірге сеніміңді\nЖүктесең Ол бақыт береді\nРақымменен Құдай қоршайды\n\n[Куплет 5]\nТәңірге қуаныңдар,\nӘділдер шаттаныңдар!\nШын жүректен адалдар,\nҚуанып ән салыңдар!","songNumber":"92"},{"id":285,"title":"Күнәнің құнын","text":"[Куплет 1]\nКүнәнің құнын төледің.\nӘлемге жарық-нұр төктің.\nӨшкен жүректерді жандырып,\n\n[Припев 1]\nБізге үміт бердің\nСенің алдыңа біз келдік.\nСаған қымбат қой әр балаң\nӘке, Саған алғысымды\nМәңгі жаудырамын.\nДаңқын Сенің көтерілсін\nҚұрмет, билік Сенде, Әкем\nКүшің Сенің шексіз Ием\nМейірімің мәңгілік."},{"id":569,"title":"Күннен үйрен жарықты сыйлауды","text":"[Куплет 1]\nКүннен үйрен жарықты сыйлауды,\nӘлемге мейіріммен қарауды.\n\n[Припев 1]\n// Жауабын күтпе ізгі ісіңнің,\nКүнге кім нені бере алады? //\n\n[Куплет 2]\nКүннен үйрен бар жолды тазалап,\nҚиналған адамға күш беруді.\n\n[Припев 2]\n// Күннен үйрен шаттанып, жарқырап.\nКөкте тұрып, жерді жылытуды! //\n\n[Куплет 3]\nӨкінбей, күрсінбей, абыржымай,\nҚуанта біл күн қуантқандай.\n\n[Припев 3]\n// Күн сияқты Тәңірге сен ұмтыл,\nжамандықтан, жақсылыққа бет бұр! //\n\n[Куплет 4]\nҚымбатты досым қайда жүрсең де,\nАйналаң Мәсіх жарығы болсын.\n\n[Припев 4]\n// Адамдар көріп жақсы ісіңді,\nкөктегі Әкені мадақтасын! //\n\n[Куплет 5]\nОл жанып тұрғанда үйрен досым,\nаспаннан жолдап, нәзік сәлемін.\n\n[Припев 5]\n// Жүрекке шертіп айтады бізге,\nшындықтың күні жоқ болар кезін! //","songNumber":"107"},{"id":336,"title":"Күн нұрына жер бөленгенде","text":"[Куплет 1]\n//  Күн нұрына жер бөленгенде,\nтылсым Құдірет кернегенде,\nЖыр жолдаймын Саған,Тәңірім-Ием!\nСен менің ғажап-Жаратушым,\nСен абзал досым-Құтқарушым!\nШақырдың мені,керемет дүниеңе.  //\n\n[Предприпев 1]\nКөңілімді қуанышқа бөледің,\nжүрегіме,Киелі Рухыңды бердің!\n\n[Припев 1]\nӘн саламын,мадақтаймын,\nәрбір сәтте Сені даңқтаймын!\nКиелі Рух! Киелі Рух!\nКөктен келген,жұбанышым,\nмәңгі Серік,қуанышым,\nКиелі Рух! Киелі Рух!\n\n[Бридж 1]\n////////  Киелі Рух! Киелі Рух!  ////////"},{"id":375,"title":"Күні, түні талмаймын","text":"[Куплет 1]\nКүні-түні талмаймын,\nТәңірді мадақтаймын.\nЖаратқаны қанша мың,\nСанаудан мен шаршадым.\n\n[Припев 1]\nКүні, айы, жарығы,\nӨзен, көлі, арығы.\nБақа, шаян, балығы,\nОрман, тауы, қорығы.\nАуа, суы, гүлдері,\nАрыстан мен пілдері.\nКең даласы, шөлдері.\nБау бақшасы, белдері.\n\n[Куплет 2]\nДостар, бері келіңдер,\nМаған жәрдем беріңдер.\nОн-ақ саусақ бар менде,\nБірге санап көріңдер.\n\n[Куплет 3]\nБәрін санап бітпейміз,\nСанына да жетпейміз.\nГүлдендірген өмірді,\nМадақтайық Тәңірді.\n\n[Припев 2]\nАрпа, бидай, сұлысы,\nТары, талқан, күріші.\nАнар, алма, жүзімі,\nЖал, жаясы, шұжығы.\nҚұрт, ірімшік, айраны,\nБал, шекері, майлары.\nҚымыз, шұбат, саумалы,\nЖеміс-жидек, баулары.","songNumber":"252"},{"id":33,"title":"Күтесің Сен мені","text":"[Куплет 1]\nКүтесің Сен мені Иса,\nМейіріміңе кенелемін.\nӨмірімді гүлдендіріп,\nҚабылдайсың мені Иса.\n\n[Припев 1]\n// Шаттан әрдайым Құдайға,\nҚайталаймын шаттан! //\nШаттан, шаттан, қайталаймын\nШаттан!\n\n[Куплет 2]\nЖер әлемге таратылсын,\nСенің киелі рақымың.\nБарлық адам тағзым етсін,\nҰлысың Сен бізге мәңгі.\n\n[Куплет 3]\nБүкіл әлем мадақтасын,\nСенің киелі атыңды.\nҚуаныштан ән саламын,\nШаттанамын бір Өзіңде!"},{"id":56,"title":"Күшім менің","text":"[Куплет 1]\nКүшім менің Сенде, Ием\nРухыңа мені бөледің.\nРақымы шексіз Тәңір Ием.\nҚайда жүрсем де біргесің.\nДаусыңды естимін, Ием\nМені қорғайтын Сен.\n\n[Припев 1]\nИса-құрбандық Тоқтысы\nЛайықтысың құрметке\nИса-құрбандық Тоқтысы\nЛайықтысың Сен.\n\n[Куплет 2]\nКүнәм үшін қиналдың Сен\nАтыңды мадақтаймын мен\nРақымы шексіз Тәңір Ием\nҚұлаған кезде көтердің\nШөліркегенде су бердің\nМені қорғайтын жалғыз Сен"},{"id":252,"title":"Кім бар аспанымда менің?","text":"[Куплет 1]\nКім бар аспанымда менің? Сен ғана,\nӨмірімнің мәні тек Сен, о, Иса!\n// Сен мен үшін отта болдың,\nМені қаныңмен ақтадың,\nКөкке, Әкеме, о, Иса, жол аштың. //\n\n[Куплет 2]\nЖалған дүние қызық емес,\nСен ғана, Қажетсің маған өмірде, о, Иса!\n// Бұ дүние мені аямас,\nКөмегіңсіз оңай болмас,\nМенің жігер-күшім Сенсің, о, Иса!. //\n\n[Куплет 3]\nЖоқшылықта тастамайтын Сен ғана,\nЖүзім өнімін бермесе, о, Иса!\n// Бидай егісін салмаса,\nМалға жұт түсіп қырылса,\nҮмітім жалғыз Өзіңде, о, Иса!. //\n\n[Куплет 4]\nЖау мен отта қалдырмайтын Сен ғана!\nКүнә жан-жақтан таласа, о, Иса!\n// Оттың жалыны шарпыса,\nБарлық жауларым жабылса,\nСен Қамалымсың, Күшімсің - о, Иса!. //\n\n[Куплет 5]\nБұл өмірмен қоштасқанда - Сен ғана!\nСенің қолыңда тыныштық - о, Иса!\n// Қайғы жанымды қысқанда,\nТабиғат күші өшкенде,\nӘнім өшпес от ішінде - о, Иса!. //","songNumber":"86"},{"id":465,"title":"Кім жаратты","text":"[Куплет 1]\nКім жаратты, самғап ұшқан құстарды,\nСамғап ұшқан құстарды, самғап ұшқан құстарды?\nКім жаратты, самғап ұшқан құстарды?\nБіздің Құдай!\n\n[Куплет 2]\nКім жаратты, самсаған жұлдыздарды,\nСамсаған жұлдыздарды,самсаған жұлдыздарды?\nКім жаратты, самсаған жұлдыздарды?\nБіздің Құдай!\n\n[Куплет 3]\nКім жаратты, толқыған теңіздерді,\nТолқыған теңіздерді,толқыған теңіздерді?\nКім жаратты, толқыған теңіздерді?\nБіздің Құдай!\n\n[Куплет 4]\nКім жаратты, самғап ұшқан құстарды,\nСамсаған жұлдыздарды, толқыған теңіздерді?\nКім жаратты, сенімен де, мені,\nБіздің Құдай!\nКім жаратты, сенімен де, мені,\nБіздің Құдай!","songNumber":"254"},{"id":598,"title":"Кім жаратты бәрін?","text":"[Куплет 1]\nКім жаратты бәрін? Орман, теңіз, гүлді?\nКөктің есігін Кім ашып берді?\nКім бояды гүлді? Кім шығарды күнді?\nКім әнді салуға берді үнді?\n\n[Припев 1]\nҚұдай, Ол бәрін біледі,\nДаңқ пен мадаққа Ол лайық.\nБізге мәңгі өмір береді,\nОны бірге мадақтайық.\n\n[Куплет 2]\nКім бақыт береді? Кім іздеп келеді?\nАдасқанда бізді Кім көреді?\nКім өмір сыйлайды? Бізді Кім қимайды?\nТүнектен жарыққа Кім жинады?","songNumber":"255"},{"id":705,"title":"Кіммін мен, бүкіл әлем Патшасы","text":"[Куплет 1]\nКіммін мен, бүкіл әлем Патшасы\nОйлайтын мен жайлы\nМенің жан дүнием?\nКіммін мен, Құдайдың ғажап Нұры\nЖетелейтін мені қараңғы дүниеде\n\n[Припев 1]\nІстеген ісім емес, рақымың Сенің Әке\nРақымыңды төгесің, ісіме қарап емес\nМен тек бүгін бар, ертең болмайтын\nГүл іспетті мен қурайтын\nКеліп кетер өмірге, қас-қағым сәтке\nБірақ Сен үніме құлақ түресің\nҚұласам Сен кешіресің\nМәңгілік өмір беріп, шынайы, мәңгіге\n\n[Куплет 2]\nКіммін мен, бәрін көруші Құдай\nКешіріп күнәмді, ақтайтындай мені\nКіммін мен, бар биліктің Иесі\nСыйлайтын тыныштық, әлем қиналғанда","copyright":"2003 СВЕКС Мусик | Клуб Зоо Мусик"},{"id":529,"title":"Кімнен көңлің қалды өмір сүргің келмей?","text":"[Куплет 1]\nКімнен көңлің қалды өмір сүргің келмей?\nЖүрек құлазыды кешірімін бермей.\nЕсіңе ал енді Исаның азабын,\nБетіне түкірді көрсетіп мазағын.\nАдамдарды сүйді, жақсылық сыйлады,\nҚабылдап үкімді айқышта қиналды.\n\n[Припев 1]\n// Оның Кім екенін өте кеш біледі,\nАдамдар өзегін өкініш тіледі.\nҰмыта алмайсың мейрімді жанарын,\nАйқыштан кешіріп қарадың. //\n\n[Куплет 2]\nТікен тәж басыңда, қан жапты бетіңді,\nКөз тіктің аспанға түсінер Өзіңді.\nШулады бәрі де өліміңді күтіп,\nАйғайлап әлі де амалдары бітіп.\n«Түс» - дейді - «айқыштан» айқайы жұрттардың,\nЕгер Құдай болсаң Өзіңді құтқарғын.\n\n[Куплет 3]\nБұдан қорқынышты ештеңе жоқ шығар,\nҚараңғылық басты, жер жоқ енді бұғар.\nОң жағында тұрған жазасы тым қатты.\nОны мойындаған қарақшы тіл қатты:\n«Сол жарық өлкеде еске ал дер едім,\nҚұдай екеніңе күмәнсіз сенемін».","songNumber":"137"},{"id":847,"title":"Кішкене бала","text":"[Куплет 1]\nКішкене бала болсамада,\nИсаменен өсемін,\nОл жол, Ол шындық,\nОл өмір мен соңынан еремін!\nСүйеді Иса сүйеді! Білемін Ол сүйеді!\nАйқышта өлді мен үшін,\nБілемін Ол сүйеді!"},{"id":666,"title":"Кішкентай үйрегім","text":"[Куплет 1]\nКішкентай үйрегім, көлде жүзеді,\nКөлде жүзеді.\nБасын суға батырады, құйрығы жоғарыда."},{"id":519,"title":"Қажетсің Сен Ием маған","text":"[Куплет 1]\nҚажетсін Сен Ием маған\nЖүрегімен алдыңа жы- ғылам\nБір Өзіңе арналған сый- ымен\nАсығамын Иса жалғыз Саған\nБір Өзіңе бағынамын\nСені аңсайды менің көз жанарым\nәрбір күнім өтті Сені іздеумен\nӨмірімнің мәні жалғыз Сен!\n\n[Припев 1]\nСен жанымда болған сайын\nКүннен күнге Сені аңсаймын\nӨз Рухыңмен баурап алған\nБар жанымды бағыштаймын\nҚұшағыңа алшы мені\nЖаулап алдың жүрегімді\nАлыстасам да мен Сеннен\nСенсіз қалай өмір сүрем?!","alternateTitle":"Сенсіз қалай өмір сүрем"},{"id":551,"title":"Қазақстан - елім бар","text":"[Куплет 1]\nҚазақстан - елім бар, ұлан байтақ жері бар,\nКең пейілді, ақ көңіл, бауырмалды халқы бар.\nМақтан етіп ардақтайтын, ұлдары мен қыздары бар,\nТүркістан мен Отырардай, қасиетті жері бар.\n\n[Куплет 2]\nАрыстан-баб, Яссауи, әулиесі тағы бар.\nҚұдай берген бар байлық, Қазақстан жерінде.\nЖалғыз ғана Иса жоқ, Қазақ, сенің төріңде,\nБілмей Оны кетпеңіздер, қазақ, осы күйіңде.\n\n[Куплет 3]\nҚазақстан ұлдары, Қазақстан қыздары,\nШын жүрекпен қабылда, Құтқарушы Исаны.\nИса болса жүректе, барлық елдің ұлттары,\nҚұтыласың сонда сен, тозақтан да, оттан да.\n\n[Куплет 4]\nЕнді қазақ бауырлар, мына сөзді тыңдаңдар,\nКөкті Құдай жаратқан, жерді Құдай жаратқан.\nСен сиынған әулие, оны Құдай жаратқан,\nҚұтқармайды әулие, тозақтан да, соттан да.\n\n[Куплет 5]\nЖаратушы Құдайдың, жаратқанына табынып,\nАдаспаңдар қазақтар, адаспаңдар қазақтар.\nЖерде емес қасиет, елде емес қасиет,\nЖалғыз ғана Исада, құдіретті қасиет.","songNumber":"78"},{"id":104,"title":"Қазақстанның жеріне","text":"[Куплет 1]\nҚазақстан жеріне, Құдайдың тірі Сөзі келді.\nАлматы аспанына, құтқарылу әкелді.\nСаған айтар әніміз, ешқашан да таусылмайды.\nДаңқыңды көтереміз, Сен оған лайықтысың !\n\n[Припев 1]\nЖарылқанған жерде, тұрмыз,\nБұл Киелі, табан тіренішің!\nМадақтаймыз, бәрі естісін,\nҚұдай Патшалығы жақындады!","songNumber":"95"},{"id":782,"title":"Қайғы тартып қиналғанда","text":"[Куплет 1]\nҚайғы тартып қиналғанда\nЖол таба алмай адасқанда,\nБір Өзіңе келдім Әке,\nКөрінбейтін болсаң да.\nҚараңғыда жатқанымда,\nКүнәға әбден батқанымда\nБар екенсің сездім Әке,\nКөрінбейтін болсаң да.\n\n[Припев 1]\nКөрінбейтін Көктегі Әке,\nБір Өзіңе сиынамын мен.\nЖүрегімнен шыққан осы әніммен,\nБар әлемді жаратқан Ием,\nАспаннан нан жаудыртқан Ием,\n//  Көрінбейтін Көктегі менің Әкем.  //\n\n[Куплет 2]\nЖан жүрегім жылағанда,\nӘлсізденіп құлағанда,\nҰмтыламын Саған Әке,\nКөрінбейтін болсаң да.\nӨзің мені құтқарғанда,\nКөңілімді жұбатқанда.\nБасымды идім Саған Әке,\nКөрінбейтін болсаң да.","songNumber":"155","alternateTitle":"Көрінбейтін Көктегі Әке,"},{"id":997,"title":"Қайда жүрмін, қайда тұрмын?","text":"[Куплет 1]\nҚайда жүрмін, қайда тұрмын?\nҚұдай менің жанымда.\nОны көзбен көрмесемде,\nБілемін, Ол жанымда."},{"id":753,"title":"Қайырлы таң, Айша","text":"[Куплет 1]\nҚайырлы таң, Айша,\nҚайырлы таң, Айша.\nЕстисің бе қоңырауды?\nЕстисің бе қоңырауды?\nДін-дан-доң! Дін-дан-доң!"},{"id":52,"title":"Қайырлы таң, Мәдина!","text":"[Куплет 1]\nҚайырлы таң, Мәдина!\nҚайырлы таң, Мәдина!\nҚұдай сені сүйеді!\nҚұдай сені сүйеді!\nСені әсем жаратқан,\nСені әсем жаратқан!\nҚұдай сені сүйеді,\nОл сені сүйеді!"},{"id":785,"title":"Қалдым мен тоғай ішінде","text":"[Куплет 1]\nҚалдым мен тоғай ішінде\nТұман қаптап көрсетпейді ешнәрсе\nУайым-қайғы жүректі езеді,\nҚарсы шықтың, тұман, сен бізге.\n\n[Припев 1]\nКүннің нұры - Иса Мәсіх Өзіңсің, Өзіңсің,\nҚұдайым жіберді ел үшін, мен үшін.\nСенен басқа маған бақыт жоқ,өмірім - Сен,\nБасымды ием Саған, күнәмді кешірдің.\n\n[Куплет 2]\nКесіп өтіп қалың тұманды,\nКүннің нұры маған жол салды.\nЖетеледі мені үйіме,\nТұманнан мені құтқарды.","songNumber":"93"},{"id":657,"title":"Қамкөңіл жатқан","text":"[Куплет 1]\nҚамкөңіл жатқан тіршілік етіп,\nЖалынам Саған,\nӘлемге зер салшы, Тәңір.\nДертінен жерді сауықтырш(ы), Тәңір,\nКүнәмнан мені тазартшы.\nМәсіхте болдық енді бір дене,\nЖаңа әлем құрамыз\nМахаббат толы жүрекпен.\nКүнәның құлы емеспіз енді.\nКөктен тудық біз Киелі Рух келіп.\n\n[Куплет 2]\nЖаңартшы әр күнді,\nОт лаулатшы, Тәңір.\nЖаңартып мені\nСоңыңнан ерт, Тәңір.\nШындықпен Сен тұрғыз\nМахаббат әлемін.\nКиелі Рух, Сен жаңбырша жаушы.\n\n[Куплет 3]\nБолашақ жаңарып даңқыңмен,\nЖаңа өмір нұры.\nПатшалығын жерде орнатқан күн\nТәңіріміздің.","songNumber":"94"},{"id":919,"title":"Қамқоршым да, сырласым да, қолдаушым Өзің","text":"[Куплет 1]\nҚамқоршым да, сырласым да, қолдаушым Өзің!\nСүрінуге шақ қалғанда бересің төзім\nМенің жалғыз сүйенерім, тірегім Өзің\nМаған жол бастайсың, жалғыз тастамайсың\nҚамқор, жан Әкешім Сенсің\n\n[Припев 1]\nТек Сенсің Тәңір, бір Саған сиынамын,\nСаған ұмтыламын, өмірлік серігім болшы Өзің\n\n[Куплет 2]\nҚатігез, зұлым дүниеге нұр болсам деймін\nКөмектесші әзәзілдің соңынан ермейін\nҚателессем, білемін мін тақпай төзесің\nМені кешіресің, жанымды білесің\nЖақын сырласатын Досым.\n\n[Куплет 3]\nБерші маған нық сенім мен пәк таза жүрек\nРенжіткенді сүйе алайын, жіберші демеп\nБар уайымымды әкелемін алдыңа Сенің\nӨзің жарылқашы, Өзің баталашы\nӨзің сақтап жүрші, Өзің қолдашы Тәңір.","songNumber":"74"},{"id":922,"title":"Қанатыңның астында алаңсыз","text":"[Куплет 1]\nҚанатыңның астында алаңсыз,\nТыныштықта боламын, Тәңір.\nСол жерден сізде қорған табасыз,\nМейіріміне кенелер өмір.\n\n[Припев 1]\n// Қанатының, Қанатының, Қанатының астында. //\n\n[Куплет 2]\nҚанатыңның астына тығылам,\nМенің берік баспанам Өзіңсің.\nКеш түсіндім білмедім бұрыннан,\nШексіз Сенің сүйіспеншілігің.\n\n[Куплет 3]\nАлаңсыз өмір сүргің келе ме?\nИсаның соңынан сен қалмай ер.\nТағдырыңды қолына бергін де,\nОның қанатының астына кел.","songNumber":"88"},{"id":906,"title":"Қандай бақыт, Құдайдың қолындамын","text":"[Куплет 1]\nҚандай бақыт, Құдайдың қолындамын!\nҚұдайдың қолындамын!\nҚандай бақыт!\n\n[Куплет 2]\nАзатпын мен, Ол мен үшін өлді!\nОл мен үшін өлді!\nАзатпын мен!\n\n[Куплет 3]\nЖүрегіме, Киелі Рух берді!\nКиелі Рух берді!\nЖүрегіме!\n\n[Куплет 4]\nТынышталам, күшін маған берді!\nКүшін маған берді!\nТынышталам,","songNumber":"257"},{"id":768,"title":"Қандай ғажайып Есімің","text":"[Куплет 1]\nӘуел баста Өзің орнаттың\nСөзіңмен айтып бәрін,\nКүллі істерің шапағатты,\nПатшалығың мәңгілік.\n\n[Припев 1]\n// Қандай ғажайып Есімің,\nҚандай ғажайып Есімің,\nИса Мәсіх - Ұлы Патшам!\nҚандай ғажайып Тәңірім,\nЕшкім тең келмейтін. //\nИса Мәсіх\n\n[Куплет 2]\nҮнсіз аспанды қаламадың,\nСен біз үшін көктен келдің.\nРақымыңмен күнәмды кештің,\nБоламыз мәңгі бірге.\n\n[Бридж 1]\nӨлімді жеңіп қайта тірілдің,\nКүнә мен өлім жеңілді.\nЖеңімпаз Ием,\nМәңгіге Сені мадақтайды,\nҰл мен қызың!\nСенде Патшалық!\nСенде салтанат!\nҚазір әрі келер күнде.\nБар билік Сенде,\nБар күште Сенде,\nСенің Есімің керемет!"},{"id":92,"title":"Қандай рахат, бақыттымын","text":"[Куплет 1]\nҚандай рахат, бақыттымын,\nИса Құтқарушым.\nКөкте, қасиетті елде,\nМаған орын дайын.\n\n[Припев 1]\nДаңқ Исаға мен үшін,\nҒолғотада қиналған.\n// Аллелуйя, аллелуйя, аллелуйя! Аумин. //\n\n[Куплет 2]\nЖердегі байлық тең келмес,\nОнда алтын қала.\nИсамен мәңгі тұрамын,\nТопырақ болсам да.\n\n[Куплет 3]\nАспанда киелі елде,\nКүн нұры сөнбейді.\nБар жүрек мақтан айтады,\nЖылау да естілмейді.\n\n[Куплет 4]\nБауырлар, ол дүниеде\nҚуаныш берілді.\nБәріміз алатын жарық\nНұр болып төгілді.","songNumber":"180"},{"id":468,"title":"Қандай тамаша Әке үйінде","text":"[Куплет 1]\nҚандай тамаша Әке үйінде!\nМәңгілік үйде, Әке үйінде!\nҚандай тамаша Әке үйінде!\nҚуаныш әрқашан онда!\n\n[Куплет 2]\nИса Әкеге, апаратын жол!\nМәңгілік үйге, Әкемізге!\nИса Әкеге, апаратын жол!\nҚуаныш әрқашан онда!\n\n[Куплет 3]\nИса күтеді Әке үйінде!\nМәңгілік үйде, Әке үйінде!\nИса күтеді Әке үйінде!\nҚуаныш әрқашан онда!\n\n[Куплет 4]\nКездесеміз сенімен Әке үйінде!\nМәңгілік үйде, Әке үйінде!\nКездесеміз сенімен Әке үйінде!\nҚуаныш әрқашан онда!","songNumber":"258"},{"id":925,"title":"Қанша қиындықтар","text":"[Куплет 1]\nҚанша қиындықтар\nӨмірімізде өтіп жатқанда,\nҚуанышсыз күндер\nАдам қайғырудан шаршағанда,\nҚұдайым, сұраймын,\nЖұбаныш әкелші жаныма,\nӘкелші, әкелші жаныма, әкелші жаныма.\n\n[Куплет 2]\nАсығып жүргенде,\nТіршілік арасында кеткенде,\nКөңілім толмайды, Сенсіз істеген әр ісіме.\nӨзіңнен сұраймын,\nСенімімді сақташы жаныма,\nСақташы, сақташы жаныма, сақташы жаныма.\n\n[Куплет 3]\nӘлсіздік келгенде,\nУайым күндері маған жеткенде,\nМені тастамайсың,\nСенемін Сенің колдауыңа.\nЖалғыз қалғанымда,\nСөйлейсің жүректен жаныма,\nЖүректен, жүректен жаныма, жүректен жаныма.\n\n[Куплет 4]\nТыныштық іздеймін,\nАспанда нәзік түн жамылғанда,\nСұлу ай жарқырап,\nЖұлдыздар төгіліп жанғанда.\nСонда мен сеземін,\nБір Өзің керексің жаныма,\nКерексің, керексің жаныма, керексің жаныма.","songNumber":"156"},{"id":601,"title":"Қаншама керемет істерін, мен Оның байқамаппын","text":"[Куплет 1]\nҚаншама керемет істерін,\nМен Оны байқамаппын,\nСоқыр болды көздерім,\nСен мені қол жая күтесің,\nМен оны, байқамаппын,\nДәлел оған сөздерің!\n\n[Припев 1]\nЕлең етіп елігіп мен\nЖалғанға түстім орға.\nҚол ұшыңды сұраймын,\nКөмек бер маған,\nКешірім сұрайм(ын),\nТек алып шық, мен жалынамын.\nҚұтқара гөр мені\nОсы батпақтан Жаратқан!\n\n[Куплет 2]\nСен мені тағы да құтқардың,\nМен оны байқамаппын,\nЖолыңнан адасыппын\nСен мені әлі де күтесің,\nМен оны байқамаппын\nШайтанға алданыппын."},{"id":342,"title":"Қаны Мәсіхтің","text":"[Куплет 1]\nҚаны Мәсіхтің тазартты мені,\nҚаны Мәсіхтің азаттық берді.\nҚаны Мәсіхтің тазартты мені\nБарлық күнәлардан.\n\n[Припев 1]\nМадақ пен құрмет қаның үшін,\nМадақ пен құрмет қаның үшін,\nМадақ пен құрмет қаның үшін,\nСүйетін Иса.","songNumber":"95"},{"id":109,"title":"Қара жүрегім менің","text":"[Куплет 1]\nҚара жүрегім менің,\nҚардай аппақ болад!\nЖуғанда Мәсіхтің қаны оны,\nМен сонда кіремін,\nалтындай қалаға таза жүрекпен!","songNumber":"256"},{"id":102,"title":"Қараңғы түн аспанда, Иса нұрын төгіп тұр","text":"[Куплет 1]\nҚараңғы түн аспанда,\nИса нұрын төгіп тұр\nСамал желдің лебімен,\nЖаңа әнін беріп тұр!\nОл - тыныштық Иесі,\nАдамзатқа Киелі,\nОл - Патшасы өмірдің,\nИса - Саған келіп тұр!\n\n[Припев 1]\n// Бұлттардан биік Ием,\nКүн сәулесі астында,\nӨз - Патшалығын құрар,\nКүтеді Ол жаннатында! //\n\n[Куплет 2]\nЖүрегімнің төрінде,\nИса - Өзі сөйлеп тұр,\nЖүрегім таза болса,\nақ батасын беріп тұр.\nОл - тыныштық Иесі,\nКөк пен жердің, Киелі,\nРухым сонда шаттанып,"},{"id":477,"title":"Қараңғы түнде тыныштық енгенде","text":"[Куплет 1]\nҚараңғы түнде тыныштық енгенде\nСен ұйықтамайсың анам менің!\nЕстимін ерніңнің жәй ғана сыбырын,\nАтымды қайталап сиынасың.\n\n[Куплет 2]\nЕгер қасымда сен болмағаныңда,\nТөзер ме едім қиындыққа.\nАнам сен мені Құдайға жолдадың,\nҚұдай қауымына жетеледің.\n\n[Куплет 3]\nӨмірден қалған бетіңдегі іздер\nБалалық шақтан таныс маған.\nЖайсыз мінезіммен тыңдамай сені мен,\nЖүрегің жаралы, жыладың сен.\n\n[Куплет 4]\nМенің қайғымнан ағарды шаштарың,\nБілемін оған себепші мен.\nКешір, анашым, кешірші анашым,\nКөп қайғы тартқыздым, кешір мені.\n\n[Куплет 5]\nБар аналардың балаға арнаған,\nДұғасын Тәңірім қабыл алсын.\nМәңгілік орында аналар да көрсін,\nӨз ұлдары мен қыздарын да.","songNumber":"215"},{"id":110,"title":"Қасиетті сәби дүниеге келді","text":"[Куплет 1]\nҚасиетті сәби дүниеге келді,\nТартып сыбызғы, гулетеміз қобызды.\nҚасиетті Сәби дүниеге келді,\nКүй шалқытып ән саламыз.\nИса - дүниенің Тәңірі,\nБіздің арамызға келді,\nИса - дүниенің Тәңірі\nБізге рақымдылығын жасады.","songNumber":"259"},{"id":801,"title":"Қастерленсін","text":"[Куплет 1]\nҚастерленсін Тәңірдің Аты,\nМақтаныш пен қадірлеуге Ол лайық.\nБір дауыспен киелі қолды көтеріп,\nӘн сал: Қастерленсін,\nҚастерленсін, қастерленсін\nТәңірдің Аты.","songNumber":"96"},{"id":945,"title":"Қатты сүйемін","text":"[Куплет 1]\nҚатты сүйемін мен, Жаратқан Иемді.\nӨмір бойы Иса Саған табынамын.\nӘділді, рақымды, өте қайырымды,\nАлдыңа Әкетайым деп келемін.\n\n[Припев 1]\nКөрсеткен мейіріміңді,\nХалқыма төге гөр Ием!\nҚұтқарылу рақымыңды,\nӘр адамға Иса жеткізе гөр.\nШексіз зор махаббатыңмен,\nЖүректерді өзгерте гөр.\nӘкетайым тізе бүгіп,\nҚазақ елім үшін сиынамын!"},{"id":811,"title":"Қиналған шақтарда күнәлардан","text":"[Куплет 1]\nҚиналған шақтарда күнәлардан,\nӨмірден түңіліп безінгенмін\n//  Тек қана шын сүю бар екенін\nӨзіңнен Тәңірім сезінгенмін!  //\n\n[Куплет 2]\nҚолыма Сен алып, аяладың\nӘкелік, мейірбан, махаббатпен\n//  Көрсеттің өмірдің сара жолын\nАрылттың жалғанды ақиқатпен!  //\n\n[Куплет 3]\nТас жүрек жібіді мұздап қалған\nСен менің маздадың арманымды\n//  Көзімді ашып Сен қараңғыда\nШындыққа өзгерттің жалғандықты!  //","songNumber":"86"},{"id":927,"title":"Қиналсам да бұл өмірде","text":"[Куплет 1]\nҚиналсам да бұл өмірде,\nСен тұрасың жүрегімде,\nТар жолменен өтіп келем,\nЖалғыз Өзің тірегім де.\n\n[Предприпев 1]\nЕлім алыс, бірақ Саған қайырылмайды,\nО, Құдайым, көмегіңсіз еш болмайды!\n\n[Припев 1]\nҚұдай Әке, құтқара гөр бауырымды,\nИса, Ием, құтқара гөр елімді.\n//  Өтініп мен Сенен сұрап тұрмын!  //\n\n[Куплет 2]\nДауыл соғып долданса да,\nЖалғыз Сенсің елге пана,\nЖұмыр жер мен көк аспан да,\nБарлық билік Сенде Иса.\n\n[Куплет 3]\nЖаным күйеді солар үшін,\nӘрбір бейбақ қазақ үшін,\nАрашала тозақ оттан,\nМенің халқым құтқарылсын.","songNumber":"121"},{"id":302,"title":"Қиын болса, жабырқасаң","text":"[Куплет 1]\nҚиын болса, жабырқасаң,\nӨпелеп, келеберсең,\nДостым менің Исаға кел!\nОл түсінер бәрінде,\nҚиналсаң кім жұбатады?\nИса, Иса!\nКінәмізді кім кешіреді?\nИса, Иса!\nСүйіп бізді, кім құтқарады?\nИса, Иса!\nӘр кезде, кім көмектеседі?\nИса, Иса!"},{"id":429,"title":"Қозыны жетектегендей","text":"[Куплет 1]\nҚозыны жетектегендей,\nБағушым, алға апар,\nСенің үнің кең жайлауға,\nТұнық суға шақырар.\n// Құтқарушым! Құтқарушым!\nМен үшін Сен қан төктің. //\n\n[Куплет 2]\nМаған дос бол жер бетінде,\nСақта қозыларыңды,\nЖетекте көк шалғынменен,\nҚұтқар адасқандарды.\n// Құтқарушым! Құтқарушым!\nСен күнәмді кешірдің. //\n\n[Куплет 3]\nИгілігіңді бере гөр,\nУәдеңді Сен орында,\nҰзақ жолдан қайтқан кезде,\nИем, мені қабылда.\n// Құтқарушым! Құтқарушым!\nЖақындата гөр мені. //\n\n[Куплет 4]\nМаған өсиетіңді Се,\nСүюге қабілет бер,\nҮйрет сүйіспеншілікпен,\nМені өмір сүруге.\n// Құтқарушым! Құтқарушым!\nМені жалғыз қалдырма. //","songNumber":"93"},{"id":521,"title":"Қой сияқты","text":"[Куплет 1]\nҚой сияқты біз адастық,\nӘркім өзі жол тапқысы келді.\nКүнәкармыз,\nДаңқынан Оның айрылдық біз.\nТек Сенің даңқыңды көрсек дейміз біз,\nТек Сенімен бір болуды қалаймыз.\n\n[Припев 1]\nТәңір,\nмейірің Сенің шексіз,\nАлдыңда бас иеміз.\nКешші бізді, Өзіңе алшы.\nТек Сенімен бір болуды қалаймыз.\n\n[Куплет 2]\nКүнәмызды алды Өзіне,\nТоқтысы Құдай керілді айқышқа.\nҚарғыс алды, адамдар аластады Оны.\nКүнәкар жерден бізді Өзіңе алшы,\nКиелі қаныңмен Сенің біз тазарсақ.","songNumber":"97"},{"id":42,"title":"Қол аяғымды","text":"[Куплет 1]\nҚол аяғымды Тәңір босаттың\nМен мадақтаймын\nБи билеймін тек Саған\nМен мадақтаймын\nМен мадақтаймын\nМен мадақтаймын\nБи билеймін тек Саған"},{"id":120,"title":"Қолдағы саусақтың бәрі он шақты","text":"[Куплет 1]\nҚолдағы саусақтың бәрі он шақты,\nӘр қолыма Құдай бестен орнатты.\n\n[Куплет 2]\nШапалақтай алам, көмек беремін.\nТентектігін қолдың кейде көремін.\n\n[Куплет 3]\nБес-бестен саусақты Құдай жаратты.\nМадақтайық Оны, болып жауапты.","songNumber":"261"},{"id":345,"title":"Қол көтеріп","text":"[Куплет 1]\nҚол көтеріп мадақтайық,\nБізге келген Иса Мәсіх,\nТек Сен ғана мені басқармақсың.\n\n[Припев 1]\nДәріптеймін Сені тек,\nБос ойымды лақтырып.\nЖаныма келші, Киелі Рух,\nБөлеп Өзіңе толтыршы.\nБір Өзіңе арнаймын өмірімді.","songNumber":"98"},{"id":144,"title":"Қолымды жаямын басымды иіп","text":"[Куплет 1]\nҚолымды жаямын басымды иіп,\nЖүректі дайындап тіземді бүгіп.\nСөйлесем Өзіңмен жақынсың маған,\nҚұпия бар сырды айтамын Саған.\n\n[Куплет 2]\nПеріштеңді қойып мені сақтадың,\nСенен артық пана, Ием, таппадым.\nСөйлесем Өзіңмен жақынсың маған,\nҚұпия бар сырды айтамын Саған.\n\n[Куплет 3]\nКөзімді тігіп аспанға қараймын,\nАлғыс айтамын, батаңды қалаймын.\nСөйлесем Өзіңмен, жақынсың маған,\nҚұпия бар сырды айтамын Саған.","songNumber":"262"},{"id":929,"title":"Қолымды көкке жайып","text":"[Куплет 1]\n// Қолымды көкке жайып\nСүйем Сені.\nҚұтқардың азат еттің Ием менің.\nЖер көкте сиынарым бір Өзіңсің.\nӨмірдің болмас сірә Сенсіз сәні.  //\n\n[Припев 1]\nСүйемін Сені Иса, сүйем Сені.\nСүйемін Сені Иса, сүйем Сені Иса.","songNumber":"99"},{"id":581,"title":"Қолымды Саған көтерем","text":"[Куплет 1]\nҚолымды Саған көтерем, Тәңір,\nТәңір, мадақты қабыл ал.\nЖүректі Саған ашамын, Тәңір,\nТәңір, мадақты қабыл ал.\nМені киіндірді Ол,\nӘділдік киіміне.\nКүл орнына Ол маған\nПатшалық салтанат берді.","songNumber":"100"},{"id":96,"title":"Қолыңда мәңгі","text":"[Куплет 1]\nҚолыңда мәңгі біз боламыз\nКереметіңмен жазыламыз\nМейірімді Құдай\nБізді жарылқа.\nСауықтыр Әке, құдіретіңмен.\n\n[Куплет 2]\nЖаңа әнменен мадақтаймыз\nСауықтыр Әке, аурулардан.\nКүнәмізді кешір,\nРухыңа толтыр.\nСауықтыр Әке, аурулардан"},{"id":305,"title":"Қоңырау ән салады","text":"[Куплет 1]\nҚоңырау ән салады,\nАлақай! Алақай!\nМәсіхті жариялайды,\nАлақай! Алақай!\nСалтанатты шаттық мейрамы,\nИса Мәсіхтің туған күні!\nАлақай! Алақай! Алақай!\nАлақай! Алақай! Алақай!"},{"id":391,"title":"Қорада жатыр бір нәресте","text":"[Куплет 1]\nБалдырғандар келіңдер сендер мұнда,\nАстау ішінде жатыр бір нәресте.\nҚұдай Ұлы саған сыйға берілген,\nҚұтқарушымыз әлди нұрын төккен.\n\n[Куплет 2]\nМаңайда патшалығы қара күштің,\nҚорада бөбек жатыр көктен түскен.\nЖарқырайды маңайынан нұр шашып,\nАспанда періштелер қалды жасап.\n\n[Куплет 3]\nШөп-шалам, сабаннан Оның төсегі,\nТыныштық самалы аспаннан еседі.\nҚойшылар отыр тізерлеп айнала,\nШешесі Мәриям қарайды аймалап.\n\n[Куплет 4]\nОлар сияқты балалар тезірек,\nБәрің мінажат етіңіз тізерлеп.\nҚолды аспанға созып жалынайық,\nДұға етелік .................","songNumber":"227"},{"id":377,"title":"Қорға Тәңірім, мені, қорға Тәңірім","text":"[Куплет 1]\nҚорға, Тәңірім, мені, қорға, Тәңірім,\nҚорға мені мына дүниеден.\nҚолымда кітабың киелі Сөзіңмен,\nҚорға, Тәңірім, мені, қорға, Тәңірім!\n\n[Куплет 2]\nДаналық бер маған, киелі Сөз,\nЖүрекке сүйіспеншілік, Мәсіх Рухын.\nМәңгілікке жетелеші мені Өзің,\nҚорға, Тәңірім, мені, қорға, Тәңірім!\n\n[Куплет 3]\nҚай жерде жүрсем де, Сөздеріңді,\nХалыққа естіртем, Мәсіх ісін.\nСол кезде дұшпандар ізіме түскенде,\nҚорға, Тәңірім, мені, қорға, Тәңірім!\n\n[Куплет 4]\nКүнәлі өмірге қызықсам мен,\nСен маған қуат бер алданбауға.\nҚасиетті сенімде тұрақты болуға,\nЖетеле, Тәңірім, қорға, Тәңірім!","songNumber":"101"},{"id":448,"title":"Қорғаушымыз Құдайды мадақтаймыз ұдайы","text":"[Куплет 1]\nҚорғаушымыз Құдайды,\nмадақтаймыз ұдайы!\nӨмірде әркезде Ол,\nҚуанышты сыйлады!\n\n[Припев 1]\nИса менің Бағушым!\nИса менің Қорғаушым!\n\n[Куплет 2]\nБіз бақытты баламыз,\nЖылап әнге саламыз,\nҚыйындыққа кезіксек,\nТез Исаға барамыз!","songNumber":"260"},{"id":483,"title":"Қорықпа, енді сен жалғыз емессің","text":"[Куплет 1]\nҚорықпа, енді сен жалғыз емессің!\nҚорықпа, енді сен сүйіктісің!\n\n[Припев 1]\nӘкемнің сүйіспеншілігі\nжанымды сауықтырды!\nӘкемнің сүйіспеншілігі\nмаған тыныштық берді\nӘкемнің сүйіспеншілігі\nқуаныш, үміт берді\nӘкемнің сүйіспеншілігі\nмәңгілікке жол ашты\n\n[Бридж 1]\nКөктегі менің  Әкем,\nменің Әкетайым!"},{"id":535,"title":"Қос қанатындай құстардың","text":"[Куплет 1]\nҚос қанатындай құстардың,\nҚос жүрек бір жол таңдады.\nЖұлдызы жансын жастардың,\nҰзақ сапарға қамданды.\n\n[Припев 1]\nАңсаған өлкеге бірге жеткенше,\nӨмір сынағынан аман өткенше,\nБелестерді, ойлы-қырлы жерді өтіп,\nҰшыңдар, ұшыңдар, ұшыңдар.\n\n[Куплет 2]\nО, тұнық аспан сол жерге,\nОрнатқан Тәңір қаласын.\nМәңгі қалатын сол елге,\nСағына назар саласың.\n\n[Припев 2]\nТоңды жерге күн шуағын сепкендей,\nНұр шуақта бүр жарыңдар көктемдей.\nБелестерді, ойлы-қырлы жерді өтіп,\nҰшыңдар, ұшыңдар, ұшыңдар.\n\n[Куплет 3]\nШамшырағы жас отаудың,\nЖап-жарық боп жанып тұрсын.\nАдасқандар жарығының,\nСәулесіне келіп тұрсын.\n\n[Припев 3]\nМахаббат алауын мәңгі жағыңдар,\nМәсіх шамшырағы болып жаныңдар.\nБелестерді, ойлы-қырлы жерді өтіп,\nКөктегі мекенге ұшыңдар тездетіп.","songNumber":"210"},{"id":921,"title":"Қош келдің Мәсіх қауымына","text":"[Куплет 1]\nҚош келдің Мәсіх қауымына,\nқысылмай отыр бос орынға.\nҚұдай сөзін тыңда, жүрегіңде сақта.\nАлғыстарды айтып Жаратқанға.\n\n[Припев 1]\nКөк аспанға да бір қарашы,\nИеңді мадақтап жырлашы,\nкөктегі Патшаға әніңді арнашы.\nБар дауысыңмен шырқашы,\nжан-тәніңді сен аямашы,\nеңсеңді түсіріп тұрмашы, тыңдашы,\nҚұдайыңа жалықпастан ән салшы.\n\n[Куплет 2]\nКөңіліңді көтер, уақыт босқа өтер.\nБұл өмірдің бәрі өте шығар бекер.\nБақытыңды таптың, үміт отын жақтың.\nБүгін міне бүгін болашақтың.","songNumber":"92"},{"id":192,"title":"Қуанайық, шаттанайық бәріміз","text":"[Куплет 1]\nҚуанайық, шаттанайық бәріміз\nЖарық болып бұл өмірде жүруге.\nҚуанайық, шаттанайық бәріміз\nҚуанышым таусылмайды мәңгілік.\n\n[Припев 1]\nА,а,а,а, О,о,о,о,А,а,а,а, Иса\n\n[Куплет 2]\nҮміт-мақсат алға мені жетелер\nТәңір Ием өзіме қуат берер.\nНық сенемін, нық сенемін Иеме.\nСебебі Ол құдіретті Құдай Ие!","songNumber":"82"},{"id":593,"title":"Қуанам Құдайымды тапқаныма","text":"[Куплет 1]\nҚуанам Құдайымды тапқаныма,\nАрайлап сол бір таңның атқанына.\nЖүректің лүпілдеген жалынымен\nПаш етіп ақиқатты жатқаныма.\n\n[Куплет 2]\nСен менің, Иса Тәңір, Құтқарушым!\nМендей боп барлық халқым құтқарылсын.\nҚабыл ал, ей, адамзат ақиқатты,\nСенің де Иса Тәңір Құтқарушың.\n\n[Куплет 3]\nТапсыр да тағдырыңды Құдайыңа,\nӘрқашан сиынып жүр ұдайы да.\nҚадам бас мәңгі өмірге, ақиқатқа,\nБелшеңнен бата берме уайымға.\n\n[Куплет 4]\nМәңгілік, Ол мәңгілік - Иса жолы.\nБұрын күн түсінбеппіз біздер оны.\nКүнәнді кешіреді Ол қайырылсаң,\nСол Иса сен үшін де құрбан болды.\n\n[Куплет 5]\n«Танысын, міне, осыны» деп туыпты.\nСенен Ол тілемейді көп білікті.\nАқиқат - Иса жолы - Құдай жолы.\nБауырым, соны білсең жеткілікті.","songNumber":"92","alternateTitle":"Сен менің Иса Тәңір Құтқарушым, Қабыл ал ей адамдар ақиқатты"},{"id":594,"title":"Қуанам Құдайымды тапқаныма!","text":"[Куплет 1]\nҚуанам Құдайымды тапқаныма,\nАрайлап сол бір таңның атқанына.\nЖүректің лүпілдеген жалынымен\nПаш етіп ақиқатты жатқаныма.\n\n[Припев 1]\nСен менің, Иса Тәңір, Құтқарушым!\nМендей боп барлық халқым құтқарылсын.\nҚабыл ал, ей, адамзат ақиқатты,\nСенің де Иса Тәңір Құтқарушың.\n\n[Куплет 2]\nТапсыр да тағдырыңды Құдайыңа,\nӘрқашан сиынып жүр ұдайы да.\nҚадам бас мәңгі өмірге, ақиқатқа,\nБелшеңнен бата берме уайымға.\n\n[Куплет 3]\nМәңгілік, - Ол мәңгілік - Иса жолы.\nБұрын күн түсінбеппіз біздер оны.\nКүнәнді кешіреді Ол қайырылсаң,\nсол Иса сен үшін де құрбан болды.\n\n[Куплет 4]\n«Танысын, міне, осыны» деп туыпты.\nСенен Ол тілемейді көп білікті.\nАқиқат - Иса жолы - Құдай жолы.\nБауырым, соны білсең жеткілікті."},{"id":344,"title":"Қуанамыз бәріміз","text":"[Куплет 1]\nҚуанамыз бәріміз,\nТәңірді мадақтаймыз.\nИса Мәсіхтің үйлену тойына\nБәріміз бірге барамыз.\n\n[Припев 1]\nАллелуя!\nҚұдіретті Тәңір Патшалық етші!\nАллелуя!\nҚұдіретті Тәңір Патшалық етші!","songNumber":"104"},{"id":11,"title":"Қуанамыз біз әрдайым","text":"[Припев 1]\nҚуанамыз біз әрдайым,\nШаттанып әрқашанда!\nҚұдайдың қуаныш нұры,\nСөнбейді ешқашанда!\n\n[Куплет 1]\nКүресте көмектеседі,\nОл бізді жетектейді.\nАзап қайғыдан сақтайды,\nӨтінішті тыңдайды.\n\n[Куплет 2]\nМәсіх жолымен жүреміз,\nҚол астында боламыз,\nҚиыншылық түскен кезде,\nҚорғаусыз біз қалмаймыз.\n\n[Куплет 3]\nӨмір берген шаттық үміт,\nЖарық күндей нұр төкті.\nКүнәкарды сүйіп Ием,\nМол игіліктер берді.","songNumber":"263"},{"id":982,"title":"Қуанамын - Құдай жақсы","text":"[Куплет 1]\nҚуанамын: Құдай жақсы,\nОл мені жаратты.\nҚұдай мені қамқорлайды,\nӘрқашан қорғайды."},{"id":545,"title":"Қуан аспан, қуан жер!","text":"[Куплет 1]\nҚуан аспан, қуан жер!\nЕзілген жүрек, шаршаған жан.\nҚиналма енді, қуаныш келді.\nОл Патшамыз Иса Мәсіх!\n\n[Припев 1]\nОл бізге адал болып қалады,\nОл бізді қызметіне таңдады,\nОл бізге мәңгі өмір сыйлады.\n\n[Куплет 2]\nҚуан аспан Тәңірге!\nДостарым шаттаныңдар қуанып,\nҚұдай Ұлы біздерді сүйеді.\nҚұдайдың махаббатын көріңдер\nОл рақымды!","songNumber":"86"},{"id":566,"title":"Қуан әлем, Тәңір келмек!","text":"[Куплет 1]\nҚуан, әлем, Тәңір келмек.\nЖер, шаттан, қарсы ал.\nОл - Патшасы патшалардың,\nМадақта, сен ән сал,\nМадақта, сен ән сал,\nМадақта, мадақта, сен ән сал.\n\n[Куплет 2]\nҚуан, әлем, Мәсіх келді,\nҚауымдар тойлауда.\nДала, бақша, орман, төбе.\nҚуанды олар да,\nҚуанды олар да,\nҚуанды, қуанды олар да.\n\n[Куплет 3]\nКүнә, қасірет болмасын,\nТікенек жаппасын.\nҚарғыс оты жайлағанда,\nШапағат Ол берсін,\nШапағат Ол берсін,\nШапағат, шапағат Ол берсін.\n\n[Куплет 4]\nБейбіт өмірдің рахатын,\nОл Өз махаббатын,\nҰлылығын, әділдігін\nСыйлады ғой бізге,\nСыйлады ғой бізге,\nСыйлады, сыйлады ғой бізге","songNumber":"196"},{"id":502,"title":"Қуан бізбен","text":"[Куплет 1]\nҚуан бізбен,\nҚуан Құдайға,\nҚуан бізбен,\nӘн шырқа.\n\n[Куплет 2]\nКеліңдер, шалқиық,\nКеліңдер, толқиық,\nҚұдайды мадақтап,\nШаттанайық.\n\n[Припев 1]\n/// Біздің Құдай бізбен, ///\n// Иса әрқашан менімен //\nКел, шырқа,\nКел, шырқа,\nСҮЙІКТІ ӘКЕ алдында.","songNumber":"105"},{"id":496,"title":"Қуантатын қуанышым","text":"[Куплет 1]\nҚуантатын қуанышым Әкетайым.\nӘкетайым құшағыңда қуанамын\nЕркелетсең еркелеймін  Әкетайым.\nЕркелеткен Әкетайым қуанады\n\n[Припев 1]\nҚуантатын қуанышым\nӘкетайым өмірімде.\nҚуантатын қуанышым\nАғатайым жүрегімде.\nҚуантатын қуанышым\nКиелі Рух жан дүниемде.\nӘкетайым, Әкетайым қуанамын\n\n[Куплет 2]\nАғатайым әділдігің қуантады.\nАғатайым жүрегімде әділдігің.\nЫстық лебің Киелі Рух қуантады.\nӘкетайым, Әкетайым деп сиынамын"},{"id":613,"title":"Қуануда бүгін бар әлем","text":"[Куплет 1]\nҚуануда бүгін бар әлем,\nБетлехемдегі жатқан дала.\nҚойшыларға келді Ізгі хабар,\nМәсіх туды деген.\n\n[Припев 1]\nТүнек басқан әлем ғажап нұрланды,\nКөктен түскен шуақпенен арайлы.\n«Иса туылды» десті жер әлем,\nПеріштелер хабарлады ол жайлы.\n\n[Куплет 2]\nЖұлдызды көріп тым алыстан,\nБетлехемге келді данышпандар.\nҚуанышпен сый әкеліпті,\nИса Мәсіхке.\n\n[Куплет 3]\nБұл мереке қуаныш бізге,\nҚұдай нұры сөнбейді түнекте.\nШуағын төгіп жолын ашты,\nИса Мәсіхке.","songNumber":"264"},{"id":5,"title":"Қуаныңдар бүгін бүкіл әлем","text":"[Куплет 1]\nҚуаныңдар бүгін бар әлем,\nБетлехемдегі жатқан Бала!\nҚойшыларға келді Ізгі Хабар,\nМәсіх туды деген!\n\n[Припев 1]\nТүнек басқан әлем,\nҒажап нұрланды,\nКөктен түскен шуақпенен арайлы,\nИса туылды, есті жер-әлем,\nПеріштелер хабарлады ол жайлы!\n\n[Куплет 2]\nЖұлдызды көріпті алыстан!\nБетлехемге келді данышпандар,\nСүйіспеншілікпен сый әкеліпті,\nИса Мәсіхке!\n\n[Куплет 3]\nБұл мереке, қуаныш бізге,\nҚұдай нұры сөнбей түнекте,\nШуағын төгіп жолын ашты,\nИса Мәсіхке!"},{"id":39,"title":"Қуаныңдар, бүгін қуаныңдар!","text":"[Куплет 1]\nҚуаныңдар, бүгін қуаныңдар!\nҚұтқарушым өмірге келген күн.\nПайғамбарлар айтқан, сағынып аңсаған,\nУәдесі жеткен күн.\n\n[Припев 1]\nКеліңдер, бәрің де келіңдер,\nҰлылығын Тәңірдің көріңдер.\nСүйді Ол бізді бастан,\nКүнәға қарамастан,\n//  Махаббаты төгілген.  //\n\n[Куплет 2]\nШаттаныңдар, бүгін шаттаныңдар!\nКүнәнің құлдығынан босатып,\nЖүрекке Иса кірді, рухымыз тірілді\nБұрын өмірсіз болған.\n\n[Куплет 3]\nҮйреніңдер, бәрің үйреніңдер!\nМәсіхтей дүниені сүйіңдер.\nМәңгілік сонда біз Мәсіхпен боламыз,\nҚұдай сыйын біліңдер.","songNumber":"165"},{"id":933,"title":"Қуаныңдар достарым","text":"[Куплет 1]\nҚуаныңдар достарым,\nМадақтаңдар Тәңірді.\n// Исаны жерге жіберіп,\nСыйлаған мәңгі өмірді. //\n\n[Куплет 2]\nШаттаныңдар бауырлар,\nШырқатып әсем әнменен,\n// Ашылды бізге құпия,\nАта-бабаң сезбеген. //\n\n[Куплет 3]\nТамашаға бөленсін\nТабиғат біткен сүйсініп,\n// Исаның сөзін естісін\nБарлық халық құлшынып. //\n\n[Куплет 4]\nАқиқатты танысын,\nТүнектегі жұртшылық.\n// Ашылсын бәрі перденің,\nАрайлап атсын күн шығып. //\n\n[Куплет 5]\nОян бауыр, қалғыма.\nЖігеріңе жігер қос.\n// Құдайдың берген бұйрығын\nОрындамай жүрме бос. //","songNumber":"182"},{"id":111,"title":"Қуаныш әнін","text":"[Куплет 1]\nҚуаныш әнін, шырқаңдар көкке,\nОралды қайта, адасқан балаң!\nҚуаныш көз жасын төккін Тәңірге,\nСаған айқара құшақ ашқан.\n\n[Припев 1]\nШырқа, шырқа, шырқасын көкте!\nБар әлем толсын дауыстарға.\nКүнәдан тазарған жырласын бар жан.\nҚанымен Мәсіхтің тазарған.\n\n[Куплет 2]\nҚуаныш әнін шырқаңдар көкте!\nТабылды жоғалған қойың да.\nКүнәнің тұтқынында азап тартқан.\nТірі енді Әкенің жанында.\n\n[Куплет 3]\nҚуаныш әнін шырқандар көкте,\nМәсіхтің мейірімін мақтап!\nОянбаған жүректе жансын шырақ,\nМақтасын барлығы дауыстап.","songNumber":"265"},{"id":632,"title":"Құдай Әкем, лайықсың Сен","text":"[Куплет 1]\nҚұдай Әкем, лайықсың Сен,\nЛайықсың мәңгі құрметке.\nЕш өлмейтін, еш сөнбейтін,\nЛайықсың мәңгі өмірге.\n\n[Припев 1]\n// Сенің ғана мейірімің,\nСенің ғана жарық нұрың,\nҚымбат маған бәрінен де,\nҚұдай Әкем лайықсың Сен. //\n\n[Куплет 2]\nҚұдай Әкем, Патшасың Сен,\nПатшасың барлық әлемге.\nБиіксің Сен, ұлысың\nСен, Лайықсың Саған сенуге.\n\n[Куплет 3]\nТеңізде асау толқындар,\nЕріксіз Саған бағынар.\nАлып таулар, сан жұлдыздар,\nҚаласаң бәрі жоқ болар.","songNumber":"25"},{"id":993,"title":"Құдай Әкем мені естиді","text":"[Куплет 1]\nҚұдай Әкем мені естиді, естиді, естиді!\nҚұдай Әкем мені естиді, Ол мені сүйеді!"},{"id":159,"title":"Құдай Әке рақымымен","text":"[Куплет 1]\nҚұдай Әке рақымымен\nАдамзатты сонша сүйді.\nЖалғыз Ұлын құрбандыққа\nЖер бетіне Ол жіберді.\n\n[Куплет 2]\nКүнәға толған адамзат үшін,\nАйқыш ағашқа Ол шегеленді.\nЕш күнәсіз пәк таза болса да,\nКиелі қаны төгілді.\n\n[Куплет 3]\nМінсіз таза құрбандыққа\nҚараңдаршы бауырларым.\nОл сен үшін жанын қиды,\nҚаншалықты азап шекті.\n\n[Куплет 4]\nКөктен келген құрбандықты\nЖүрегіңмен қабылдашы.\nСонда ғана кенелесің,\nЖанаттағы тыныштыққа.","songNumber":"79"},{"id":343,"title":"Құдай балаларды сүйеді","text":"[Куплет 1]\nҚұдай балаларды сүйеді,\nЕсімдерін Ол біледі.\nҚараторы, ақшыл, сары,\nБәрін Құдай ұнатады.\nҚұдай балаларды сүйеді,\nЕсімдерін Ол біледі."},{"id":536,"title":"Құдай балаларды сүйеді","text":"[Припев 1]\nҚұдай балаларды сүйеді,\nӘлемнің балаларын!\nАтымызды Ол біледі, атымызды біледі,\nБәрімізді қолыменен қорғайды!\n\n[Куплет 1]\nМен эскимос, кішкентай қардан\nүйді саламын!\nШанамен сырғанаймын мен,\nТаудан домалаймын!\n\n[Куплет 2]\nҰзын шаштан өрімім,\nТақиям ұшқыр менің!\nДенемнің түсі сап-сары,\nКүрішті ұнатамын!\n\n[Куплет 3]\nАфрика елінде тұрам,\nОнда өте ыстық!\nШашым бұйра қап-қарамын,\nБарлық тістерім ақ!"},{"id":421,"title":"Құдай бәрін жаратты","text":"[Куплет 1]\nҚұдай бәрін жаратты, көбелекті де,\nӘсем қанаттарымен гүлдерге қонады."},{"id":641,"title":"Құдай бәрін жаратты","text":"[Куплет 1]\nҚұдай малдарды жаратты,\nҮлкен кішілерін.\nСиырлар мен қойларды да,\nОл бәрін жаратты."},{"id":645,"title":"Құдай - біздің Әкеміз","text":"[Куплет 1]\nҚұдай - біздің Әкеміз,\nЖан-жүрекпен Оны сүйеміз,\nИса - біздің Иеміз,\nОның соңынан біз ереміз.\n\n[Припев 1]\nКеліңдер, келіңдер,\nБәріңді бірдей Ол сүйеді.\nБәріңнің күнәңді кешіріп,\nЖұмақтан орын береді.","songNumber":"108"},{"id":451,"title":"Құдай біздің Панамыз","text":"[Куплет 1]\nҚұдай біздің Панамыз,\nҚиын кездегі Сенімді Жәрдемшіміз.\nҚұдай біздің Күшіміз,\nҚиын кездегі Сенімді Жәрдемшіміз.\n\n[Припев 1]\n// Неден қорқамыз, Иеміз жанымызда,\nОл біздің Қорғанымыз. //\n\n[Куплет 2]\nОның рақымы бұлақтың суындай\nНәр беріп бізді қуантады.\nТаң атқанда көмегін беретін\nӘлемнің Иесі жанымызда.","songNumber":"94","alternateTitle":"Неден қорқамыз, Иеміз жанымызда"},{"id":722,"title":"Құдай біздің панамыз бен күшіміз","text":"[Куплет 1]\nҚұдай біздің панамыз бен күшіміз\nҚиын кезде сенімді жәрдемшіміз\nДүние астаң-кестеңі шығып\nТұңғиыққа таулар құлап жатса да\nТеңіз долданып, ақ көбік боп атқылап\nТолқынынан тау сілкінсе қорықпаймыз!\n\n[Припев 1]\nӘлемнің Иесі жанымызда,\nҚорғанымыз Жақыптың Құдайы!\n\n[Куплет 2]\nҚұдайдың қаласына, киелі үйге,\nРақымы Оның нәр беріп қуантуда.\nҚаланың Тәңір ортасында,\nЕшқашан да қала қозғалмайды.\nТаң атқанда Тәңір көмек береді,\nТағаланың үнінен жер жоқ болат.","songNumber":"31","alternateTitle":"Әлемнің Иесі жанымызда"},{"id":74,"title":"Құдай бізді сонша сүйгендіктен","text":"[Куплет 1]\nҚұдай бізді сонша сүйгендіктен\nҚұдай бізді сонша сүйгендіктен,\nӨз Ұлы Исаны құрбан еткен\nҚұрбандық бағасы\nМақтау даңққа лайық,\nМәңгілік өмірге есік ашық\n\n[Припев 1]\nШегеленді бар күнәлар,\nАйқышта тозаққа кеткен,\nШегеленді бар қалаулар,\nБолмыстың іс-әрекеті.\nТазаланып жан-дүние\nБостандық шарықтайды,\nКөкке баруға Әкеміз шақырады\n\n[Куплет 2]\nҚұдай бізді сонша сүйгендіктен,\nБар күнәларымызды кешірген\nТозаққа бармауға,\nЖалында жанбауға,\nБарлық жағдайды туғызды бізге"},{"id":359,"title":"Құдай бізді шексіз сүйеді","text":"[Куплет 1]\nҚұдай бізді шексіз сүйеді,\nҚұдай бізді шексіз сүйеді,\nҚұдай бізді шексіз сүйеді, бұл керемет!\nЖұлдыздардан да жоғары,\nТеңіздерден де терең,\nАйналадан да кең байтақ,\nОның сүйіспеншілігі!"},{"id":341,"title":"Құдай Гүлжанды әдемі жаратты","text":"[Куплет 1]\nҚұдай Гүлжанды әдемі жаратты,\nҚұдай Гүлжанды қатты сүйеді!"},{"id":577,"title":"Құдайға жақындап","text":"[Куплет 1]\nҚұдайға жақындап, күнәдан құтылдым,\nШын жүректен сенемін Исаға.\nЖанымды тазартып, тыныштық берді Ол,\nМен Құдай Ұлына сенемін.\n\n[Припев 1]\nСенемін, сенемін,\nШын жүректен сенемін Исаға.\nСенемін, сенемін,\nМен Құдай Ұлына сенемін.\n\n[Куплет 2]\nҚұтқарды мені Ол, сенімім ақталды,\nШын жүректен сенемін Исаға.\nШынайы Сүюші, жанымды Сақтаушы.\nМен Құдай Ұлына сенемін.\n\n[Куплет 3]\nСүйеніп жүремін, жақындап мен Оған,\nЖан-дүниеммен Исаға сендім.\nМәңгіге даңқтаймын, Исаға табынам,\nМен Құдай Ұлына сенемін.","songNumber":"110"},{"id":460,"title":"Құдайды мадақтаңдар бар елдер","text":"[Куплет 1]\nҚұдайды мадақтаңдар бар елдер,\nБар ұлттар, халықтар,\nҚұдайды мадақтаңдар.\n\n[Куплет 2]\n// Мадақтаймын десең Құдайды,\nЕшкім кедергі бола алмайды.\nМадақтаймын десең Құдайды,\nРухани көзің ашылады.\nБайлыққа жүрегің толады,\nЖан дүниең азаттық алады.\nАзаттық алады. //\n\n[Куплет 3]\nАлғысқа шексіз, мадақта сансыз.\nШын жүректерден мақтау пен даңққа,\nЛайықты Құдай тек Құдай,\nЛайық біздің Әке Құдай.\nШын дәріптеуге шын құрметтеуге,\n......... күш құдіретке,"},{"id":944,"title":"Құдайдын тыныштығына","text":"[Куплет 1]\n// Құдайдың тыныштығына\nШынайы сүйіспеншілікке иеміз Исада\nКенеліп ие болдым! //\n\n[Припев 1]\nИ -и-са Көктің Патшалығына\nСен бізді кіргіздің,\nҚұдай Әкеміздің құшағына!\nИ -и -са- төгілген Сенің қаның,\nМәңгілік қуанышқа,\nШынай жолмен бізді жеткіздің!\n\n[Бридж 1]\n/// И-и-са -а, рахмет Саған! ///"},{"id":427,"title":"Құдайдың әр сөзі тербесін жанымызды","text":"[Куплет 1]\nДостым мойыма келсе қиындық, ешқашан,\nҚұдайға ән салайық жиылып, әрқашан.\nСені тазалады Ол күнәдан.\nҚуат алайық күнде сиынып, бәріміз,\nКір болса күнде тұрар жуылып жанымыз.\nСебебі Тәңір Ол біздің Әкеміз,\n\n[Припев 1]\nҚұдайдың әр сөзі тербесін жанымызды,\nҚұдай сүйеді сені.\nСүйеді бәрімізді,\nҚұдай сүйеді сені.\nЖәне Ол біз үшін пәк Жанын құрбан етті.\nСақтайық жанымызды,\nДұға етіп үнемі.\nШақырып бәрімізді,\nДұға етіп үнемі.\nДосыңа Құдайды жеткізейік үндесіп.\nСыйлыққа аспандағы біз жетейік бірлесіп.\n\n[Куплет 2]\nЕшкімді ренжітпейік ашумен, ешқашан,\nҚуанышта жүрейік тасумен, әрқашан.\nСебебі күнәлардан Ол құтқарған.\nҚуат алайық күнде сиынып, бәріміз,\nКір болса күнде тұрар жуылып жанымыз.\nСебебі Тәңір Ол біздің Әкеміз.\n\n[Припев 2]\nҚұдайдың әр сөзі тербесін жанымызды,\nСүйеді бәрімізді,\nЖәне Ол біз үшін пәк Жанын құрбан етті\nСақтайық жанымызды,\nШақырып бәрімізді,\nДосыңа Құдайды жеткізейік үндесіп,\nСыйлыққа аспандағы біз жетейік бірлесіп."},{"id":957,"title":"Құдайдың баласымын","text":"[Куплет 1]\nҚұтқардың мені, әсім әніңмен қоршадың мені Ием!\nАзат еттің Сен жаулардан мені, бар қорқыныш кетті.\n\n[Припев 1]\n// Күнәнің құлы емеспін.\nҚұдайдың баласымын! //\n\n[Куплет 2]\nТуылмай тұрып таңдадың мені, сүйіп есім бердің,\nҚайта туылдым, отбасым болып, төгілген қаныңмен.\n\n[Бридж 1]\nҚұшағыңа алып Көктегі Әкенің\nҚоршайды мені ұраны азаттықтың,\nҚұтқарылдық біз күнәнің құлдығынан.\nҰлы мен қызымыз бостандық жариялаймын!\nО-о-о-о...\n\n[Припев 2]\n// Менің күшім теңіздерді аштың Сен,\nМахаббат жойды қорқынышты.\nҚұтқардың енді жар саламын,\nҚұдайдың баласымын! //"},{"id":258,"title":"Құдайдың қасиеттілігінде біз","text":"[Куплет 1]\n//  Құдайды Қасиетті Ие қып біз,\nПатшалықта мәңгі бірге жүреміз!\nЖүректердің сенімі барлық нәрсені жеңді,\nМәсіхтің Кім екенін көрдік! //\n\n[Припев 1]\nЖан-дүниемен, аңсаған Патшамыз!\nЖүрегіммен армандаған Патшамыз!\nБіздің іздегеніміз,\nбіздің сұрағанымыз,\nЖалғыз Мәсіх - Патшамыз!"},{"id":140,"title":"Құдайдың мейірімі сондай керемет!","text":"[Куплет 1]\nҚұдайдың мейірімі сондай керемет!.\nҚұдайдың мейірімі сондай керемет!.\nҚұдайдың мейірімі сондай керемет!.\nОл керемет!\n\n[Припев 1]\nСондай биік, одан биік ешнәрсе жоқ,\nСондай терең, одан терең ешнәрсе жоқ.\nОл керемет!\n\n[Куплет 2]\nҚұдайдың адалдығы сондай керемет!.\nҚұдайдың адалдығы сондай керемет!.\nҚұдайдың адалдығы сондай керемет!.\nОл керемет!\n\n[Куплет 3]\nҚұдайдың сүйеніші сондай керемет!.\nҚұдайдың сүйеніші сондай керемет!.\nҚұдайдың сүйеніші сондай керемет!.\nОл керемет!","songNumber":"268"},{"id":682,"title":"Құдайдың Рухы бізді толтырғанда","text":"[Куплет 1]\nҚұдайдың Рухы бізді толтырғанда,\nТәңірге дұға етемін!\nҚұдайдың Рухы бізді толтырғанда,\nТәңірге дұға етемін!\n// Дұға етеміз, дұға етеміз!\nТәңірге дұға етеміз! //\n\n[Куплет 2]\nҚұдайдың Рухы бізді толтырғанда,\nТәңірге ән саламыз!\n// Ән саламыз, ән саламыз\nТәңірге ән саламыз! //\n\n[Куплет 3]\nҚұдайдың Рухы бізді толтырғанда,\nТәңірге би билейміз!\n// Би билейміз, би билейміз,\nТәңірге би билейміз! //\n\n[Куплет 4]\nҚұдайдың Рухы бізді толтырғанда,\nТәңірге алғыс айтамыз!\n// Алғыс айтамыз, алғыс айтамыз,\nТәңірге алғыс айтамыз! //\n\n[Куплет 5]\nҚұдайдың Рухы бізді толтырғанда,\nТәңірді біз сүйеміз!\n// Біз сүйеміз, біз сүйеміз,\nТәңірді біз сүйеміз! //"},{"id":271,"title":"Құдайдың Рухында көктегі Әкеммен","text":"[Куплет 1]\n// Құдайдың Рухында\nКөктегі Әкемен\nБіз біріктік\nБіз біріктік мәңгілікке //\n\n[Предприпев 1]\nИса келді өміріме\nМаған жол ашты Көкке\nЕнді мен жалғыз емеспін\nМен Құдаймен бірге\n\n[Припев 1]\n// Құдайға менің Әкеме\nБала болдым қуанамын //","alternateTitle":"Құдайға менің Әкеме"},{"id":490,"title":"Құдайдың салтанатты ұлылығы Сенде","text":"[Куплет 1]\nҚұдайдың салтанатты ұлылығы Сенде,\nБүкіл әлем Сенің қолыңда аспан да, жер де.\n\n[Припев 1]\nО, Тәңір Ием, Саған табынам\nКешірші деп сұраймын.\nБасымды иіп, Сенің алдыңда тұрып\nҚұтқаршы деп сұраймын.\n\n[Куплет 2]\nИса Тәңір Сен біздер үшін өмірге келдің.\nҚаныңды төгіп айқыш ағашта бізді құтқардың.\n\n[Куплет 3]\nҚұдайдың патшалығы мәңгілік Сенде.\nБіз жүрейік шәкіртің болып Сенің жолыңда.\n\n[Бридж 1]\nСүйем Сені, сүйем Сені, сүйем Сені Иса!","songNumber":"81"},{"id":907,"title":"Құдайдың Сөзімен өмірім өзгерді","text":"[Куплет 1]\nҚұдайдың Сөзімен өмірім өзгерді\nҚуанды жүрегім.\nТатулық, жақсылық күтіп тұр алдымда\nМен Оған сенемін.\n\n[Припев 1]\nИса,Иса, менің Тәңірім\nИса,Иса, жақын Жан Досым.\n\n[Куплет 2]\nӨлімнен құтқарып бір жолды мәңгілік\nӨмірді сыйлады.\nОсылай Тәңірім біз үшін айқышта\nАзаппен қиналды.\n\n[Куплет 3]\nКүнәкар әлемнен бас тартып қазағым\nБір жола келіңдер\nҚұдайдың ұсынған Құрбандық Тоқтысы\nИсаға сеніңдер.\n\n[Куплет 4]\nАдамзат келсін деп, шындықты білсін деп\nҚауымын орнатты.\nСенгендер қуаныш, бақытқа кенеліп,\nҚайғысын ұмытты.","alternateTitle":"Иса, Иса менің Тәңірім"},{"id":751,"title":"Құдайдың сүйіспеншілігі","text":"[Куплет 1]\nҚұдайдың сүйіспеншілігін аңсайтын,\nҚұдай тыныштығынан үміттенетін.\nЖаратқан сенде барды\nбіздің Құдай\nСені сүйеді соншалықты.\nМадақ пен сиынуды Оған беретін\nҚұдайдың ізгілігіне ұқсап жүретін,\nЖаратқан сенде барды\nбіздің Құдай\nСені Өз баласы қылдырды.\n\n[Припев 1]\nҚұдай мейірімді көзімен\nәр кезде де саған қарауда.\nҚұдай ынталы құлағымен\nәрқашан да сені тыңдауда.\nҚараңғылықта нұрын жарқыратып,\nәлсіз даусыңды да Ол тыңдауда.\nҚайда болсаң да Оған бағыттал,\nТек Оған ғана қара.\nТек Оған ғана қара.","songNumber":"113"},{"id":856,"title":"Құдайдың сүйіспеншілігі сондай","text":"[Куплет 1]\n///  Құдайдың сүйіспеншілігі,\nсондай керемет! ///\nОл керемет!\n\n[Припев 1]\nСондай биік, одан биік ешнәрсе жоқ!\nСондай терең, одан терең ешнәрсе жоқ!\nСондай кең, одан кең ешнәрсе жоқ!\nОл керемет!\n\n[Куплет 2]\n/// Құдайдың адалдығы,\nсондай керемет! ///\nОл керемет!\n\n[Куплет 3]\n/// Құдайдың құрметі,\nсондай керемет!\nОл керемет! ///"},{"id":954,"title":"Құдайдың тыныштығында","text":"[Куплет 1]\n/// Құдайдың тыныштығына,\nШынайы сүйіспеншілікке,\nИеміз Исада, кенеліп ие болдық! ///\n\n[Припев 1]\n// Иса!\nКөктің Патшалығына Сен бізді кіргіздің,\nҚұдай Әкеміздің құшағына.\nИса!\nТөгілген Сенің қаның, мәңгілік қуанышқа,\nШынайы жолмен бізді жеткіздің. //\nИса рахмет Саған!"},{"id":388,"title":"Құдайдың тірі өзені","text":"[Куплет 1]\nҚұдайдың тірі өзені,\nМахаббатқа бөлейді,\nТағының астынан аққан су\nТазалап бізді емдейді\n\n[Куплет 2]\nӨзен аққан жерлердің,\nӨзгертеді бәрінде.\nҚұдайдың берген өмірі мәңгі,\nОсында өзені болып ағады.\n\n[Припев 1]\nӨмір берер суыңнан Тәңірім\nШөлімді басып ішкім келеді\nӨмір өзенде бірге жүзіп\nҚұшағыңда тынығамын\nӨмір суының Иесі\nЖаратушым менің!"},{"id":849,"title":"Құдайдың Ұлы Иса","text":"[Куплет 1]\n//  Құдайдың Ұлы Иса,\nБізді ақтап алды,\nҚұрбан болып айқышта\nИсаның рақымында,\nБәрін жеңіп өтем,\nӨмірім қуанышта! //\n\n[Предприпев 1]\n// Исаның рақымы,\nАйқыштан ағылды! //\n\n[Припев 1]\nИса  Ол- мәңгілікке жетелейді!\nИса  Ол- Шынайы тірі жол!\nИса  Ол- Әкемізге есік ашқан,\nИса  Ол- Төгілген махаббат!"},{"id":934,"title":"Құдайды ізде, сарылып ізде","text":"[Куплет 1]\nҚұдайды ізде, сарылып ізде,\nКешікпей, досым, сағынып ізде.\nКүні-түні кезіп даланы,\nЖан жүрегіңмен, табынып ізде.\n\n[Припев 1]\nІздеген табар, Құдайды ізде,\nЖол болып бәлкім, жолығар сізге.\n\n[Куплет 2]\nСөз болып Тәңір жерге келеді,\nСенімің болса, бойға енеді.\nОған жүгіну тым қиын емес,\n«Кеш қалма» деген ойға келеді.\n\n[Куплет 3]\nЖүректі қақса, ашып есігін,\nҚұрметте әркез Тәңір есімін.\nШөлдегі судай Құдайды аңса,\nТабарсың сонда өмір шешімін.","songNumber":"100"},{"id":867,"title":"Құдай жар болсын, құрбандығың қабылдансын","text":"[Куплет 1]\n// Мүмкіндікті Құдай берді,\nҚұрбандығыңды беруді,\nШексіз жарылқауын төгеді.\nМыңдаған адам ішінен,\nСені бауырым таңдады,\nҚұрбандығыңды Ол күтеді. //\n\n[Припев 1]\n// Құдай жар болсын, құрбандығың қабылдансын,\nКөкте бауырым, жиналсын сый-тартуларың.\nҚұдай жар болсын, құрбандығың таза болсын,\nҚұдай жар болсын! //\n\n[Куплет 2]\n// Шын жүрегіңмен егілген,\nАлғыстармен безенген,\nЖеміс шығады ағашыңнан.\nЖаман жеміс алмау үшін,\nЖақсы ағашты отырғыз,\nНе ексең соны орып аласың. //"},{"id":354,"title":"Құдай жер мен көкті жаратты","text":"[Куплет 1]\nҚұдай жер мен көкті жаратты,\nҚұдай басында оларды жаратты."},{"id":112,"title":"Құдай Ие балаларды шақырады «Кел» деп","text":"[Куплет 1]\nҚұдай Ие балаларды шақырады «Кел» деп,\nОларға қолын созады, жүректі бер деп.\n\n[Припев 1]\nҚұдайды мадақтаңдар,\nЖүректен жыр төгілсін.\nҚұдайды мадақтаңдар,\nСөзі жерге себілсін.","songNumber":"266"},{"id":234,"title":"Құдай Ием бердің өмір","text":"[Куплет 1]\n// Құдай Ием, бердің өмір, сүйгендіктен, Өз пендеңді! //\n// Алайда біз, надандықпен, ұмыттық, мейіріміңді! //\n\n[Припев 1]\nКелді Иса, арамызға, нұрландырып түнекті!\nӨлді МәсіХ, біздер үшін - Киелі, қанын төкті!\n\n[Куплет 2]\n// Қарғыс, күнә ақталды, Мәсіх - Иса қанымен! //\n// Мәңгілікке, жетістік, Раббымыздың, құрбанымен! //"},{"id":727,"title":"Құдай керемет жақсы","text":"[Куплет 1]\nҚұдай керемет жақсы.\nҚұдай керемет жақсы.\nҚұдай керемет жақсы.\nОл сондай жақсы.\n\n[Куплет 2]\nҚұдай мені сүйеді.\nҚұдай мені сүйеді.\nҚұдай мені сүйеді.\nОл сондай жақсы.\n\n[Куплет 3]\nСиын, жауап береді.\nСиын, жауап береді.\nСиын, жауап береді.\nОл сондай жақсы.\n\n[Куплет 4]\nСұра бақыт береді.\nСұра бақыт береді.\nСұра бақыт береді.\nОл сондай жақсы.\n\n[Куплет 5]\nИса - бақыттың жолы.\nИса - сүйіспеншілік.\nИса - мәңгілік өмір.\nОл сондай жақсы.\n\n[Куплет 6]\nИса мені құтқарды,\nИса сені құтқарды,\nИса бізді құтқарды.\nОл сондай жақсы.","songNumber":"271"},{"id":124,"title":"Құдай қауымы Патшасын","text":"[Куплет 1]\nҚұдай қауымы Патшасын,\nӘрдайым мадақтаймыз,\nОл Әке, ал біз бір үйдің,\nБір туған шырақтары.\n\n[Припев 1]\nАллелуйя, аллелуйя,\nҚұдайға мадақ болсын.\nМол қуаныш сыйлайды Ол,\nКиелі үйге халық толсын.\nАлғыс Тәңір, алғыс Тәңір,\nИса төккен пәк қанын,\nБіздер үшін құрбан болып,\nАттырды бақыт таңын.\n\n[Куплет 2]\nӘрқашанда ақ батаңмен,\nІсімізді жарылқай бер.\nКиелі рух беріп бойға,\nДұғамызды қабылдай гөр.\n\n[Куплет 3]\nО, Тәңірім, аллелуйя,\nСен қуаныш сыйлайсың.\nРухыңменен желеп-жебеп,\nҚұшағыңа жинайсың.","songNumber":"267"},{"id":346,"title":"Құдай - құдіретті Құдай","text":"[Куплет 1]\nҚұдай - құдіретті Құдай,\nКөктен билік құрады,\nКүшпен,\nмахаббатпенен,\nҚұдай - құдіретті Құдай.","songNumber":"111"},{"id":990,"title":"Құдай мейірімді","text":"[Куплет 1]\nҚұдай мейірімді,\nҚұдай мейірімді,\nҚұдай мейірімді,\nОл маған мейірімді!"},{"id":458,"title":"Құдай мені жаратты","text":"[Куплет 1]\nҚұдай мені жаратты,\nҚұдай мені жаратты,\nҚұлақ, көз, мұрын, ауыз!\nҚұдай мені жаратты!\n\n[Куплет 2]\nҚұдай Сені жаратты,\nҚұдай Сені жаратты,\nҚұлақ, көз, мұрын, ауыз!\nҚұдай Сені жаратты!\n\n[Куплет 3]\nҚұдай бізді жаратты,\nҚұдай бізді жаратты,\nҚұлақ, көз, мұрын, ауыз!\nҚұдай бізді жаратты,","songNumber":"269"},{"id":747,"title":"Құдай отбасын қалайды","text":"[Куплет 1]\nҚұдай отбасын қалайды, ата-анасын сыйлайды.\nҚұдай отбасын қалайды, солай бізді қорғайды."},{"id":953,"title":"Құдай панасында","text":"[Куплет 1]\n// Құдай панасында тұрған адам,\nҚұдіреттінің саясында табады тыным. //\n\n[Куплет 2]\n// Бас сауғалайтын панам, қорғаным,\nСенімімді Саған артам Құдайым. //\n\n[Куплет 3]\n// Ол мені құтқарады, қорғап-қоршайды,\nМені аман-есен сақтап құрметтке Ол бөлейді.\nМен Оған сиынам, Ол құлағын салады,\nАзап шеккен кезде, маған Ол жар болады. //"},{"id":139,"title":"Құдай - рақымды","text":"[Куплет 1]\nҚұдай - рақымды, Ол деген бақыт\nҚұдай - рақымды, бізді сүйеді.\n\n[Припев 1]\nБарлығы шаттанып,\nШырқасын ардақтап,\nШырқасын Құдайдың мол рақымын.\n\n[Куплет 2]\nҚұдай - рақымды, жіберді Ұлын,\nҚұдай - рақымды, бізді құтқарды.\n\n[Куплет 3]\nҚұдай - рақымды, күнәдан бізді,\nСүйіспеншілігімен құтқарды.\n\n[Куплет 4]\nҚұтқарушым, Сен мені құтқардың,\nҚұтқарушым, Сен мені кешірдің.\n\n[Куплет 5]\nСені ардақтап шырқаймын мәңгі,\nРақымдылығыңды дәріптеймін.","songNumber":"273"},{"id":537,"title":"Құдай Саған табынамын","text":"[Куплет 1]\nҚұдай Саған табынамын,\nЖанымды Саған тапсырамын.\nСені сүйемін.\n\n[Куплет 2]\nИса Саған табынамын,\nЖанымды Саған тапсырамын.\nСені сүйемін,Сені сүйемін!\n\n[Куплет 3]\nКиелі Рух Саған табынамын,\nЖанымды Саған тапсырамын.\nСені сүйемін,Сені сүйемін!","songNumber":"270","copyright":"1972 Мараната! Мусик | КККМ Мусик"},{"id":755,"title":"Құдай сені жаратты","text":"[Куплет 1]\nҚұдай сені жаратты,\nКеремет жаратты.\nҚұдай сені\nӘдемі етіп жаратты."},{"id":756,"title":"Құдай сені жаратты","text":"[Куплет 1]\nҚұдай сені жаратты, өзіңе қарашы!\nӘсем етіп жаратты,\nҚұдай сені жаратты, өзіңе қарашы!\nӘсем етіп жаратты!"},{"id":347,"title":"Құдай сені тастамайды","text":"[Куплет 1]\n//// Құдай сені тастамайды ешқашан,\nБірге болар сенімен Ол әрқашан. ////\n\n[Припев 1]\n// Бәріміз барамыз жаннатқа,\nАлғыс, мадақ айтып Исаға.\nҚұтқарғанын біліп Тәңірдің,\nБала болдық Әке Құдайға. //","songNumber":"114"},{"id":181,"title":"Құдай сондай жақсы","text":"[Куплет 1]\nҚұдай сондай жақсы,Құдай сондай жақсы,\nҚұдай сондай жақсы, Ол сондай жақсы!\n\n[Куплет 2]\nҚұдай мені сүйеді, Құдай мені сүйеді!\nҚұдай мені сүйеді, Ол сондай жақсы!"},{"id":709,"title":"Құдай сондай жақсы","text":"[Куплет 1]\nМахаббатың ғажап Сенің,\nРақымды Құдайым!\nТолығымен құн төледің,\nЛайықсыз болсам да!\n\n[Припев 1]\nҚұдай сондай жақсы,\nҚұдай сондай жақсы,\nҚұдай сондай жақсы,\nОл сондай жақсы!\n\n[Куплет 2]\nӨмір бойы қарап өтем,\nСенің Атың\nКүнәкарды құтқардың,\nӨлімді жеңдің!\n\n[Куплет 3]\nЖарылқашы Құдай!"},{"id":383,"title":"Құдай сонша жақсы көрді қазақ даласын","text":"[Куплет 1]\nҚұдай сонша жақсы көрді қазақ даласын,\nОл жіберді Өзі сүйген Иса баласын.\n//  Күнәсінан құтқарылсын, аман болсын деп,\nСүйгендіктен құрбандыққа берді Баласын.  //\n\n[Куплет 2]\nО, Жаратқан неткен шексіз махаббатың,\nБітпес сонша бізге төгер шапағатың.\n//  Сиынамыз бір Өзіңе, Құдай Әке,\nТыныштықта, қуанышта бір Өзіңде.  //\n\n[Куплет 3]\nТалай адам білмей кетті бұл шындықты,\nБілсе дағы, қабылдамай құрбандықты.\n//  Ей, адамзат аялдашы, қабылдашы,\nИса төккен күнәң үшін таза қанды.  //","songNumber":"26"},{"id":83,"title":"Құдай Сөзі былай дейді","text":"[Куплет 1]\nҚұдай сөзі былай дейді\nЕкі мың жыл бұрын\nДүниеге бала келді,\nБізге үміт берді.\nТуған күні Исаның\nБіз үшін маңызды.\nӨмірге патша келді деп,\nПеріштелер қуанды.\n\n[Куплет 2]\nМалдарын күзетіп жатты\nСол түні малшылар.\nКенеттен нұр төгілді\nОларға белгі берді.\n\n[Куплет 3]\nКішкентай суық қорада.\nҰлы Патша туылды.\nЖарық беріп өмірге.\nОл - менің махаббатым.\n\n[Куплет 4]\nӘн салады періштелер\nҚуанышы шексіз\nҚұтқарылу қабылдаймыз\nМәңгі өмір сүреміз"},{"id":325,"title":"Құдай сөзін берді","text":"[Куплет 1]\nҚұдай сөзін берді,\nҚұдай сөзін берді,\nҚұдай сөзін берді.\nОны оқи бер,\nҚұдайды тыңдай бер!"},{"id":931,"title":"Құдай сүйіп біздерді жалғыз Ұлын жіберді","text":"[Куплет 1]\nҚұдай сүйіп біздерді жалғыз Ұлын жіберді\nМәңгіліктің есігі, айқара ашық, кір енді.\n\n[Припев 1]\nЖаңа өмірде жаңаша,\nҚуанайық балаша.\nТатулассаң Тәңірмен,\nӨмір сонда тамаша!\n\n[Куплет 2]\nИса келіп өмірге, жаңа дәуір басталды.\nПеріштелер әнімен, күңірентті аспанды.\n\n[Куплет 3]\nӨмір босқа өтпесін, қаулап гүлдер көктесін.\nИса жаққан шамшырақ, ешқашанда өшпесін.","songNumber":"99"},{"id":573,"title":"Құдайсыз өмір - бақытсыз өмір","text":"[Куплет 1]\nҚұдайсыз өмір - бақытсыз өмір,\nКүнәға толы алдамшы өмір.\n// Неге шындықты біле алмайсың сен?\nАйтшы бауырым, кімді алдайсың сен?. //\n\n[Куплет 2]\nМіне, тағы да жылап тұрсың сен,\nҚайғы-қасірет артып жүрмін деп.\n// Неге Құдайды танымайсың сен?\nАйтшы, бауырым, кімді алдайсың сен? //\n\n[Куплет 3]\nКүнәға батып, қиналасың сен,\nМұңыңды айтып, тұнжырайсың сен?\n// Неге Құдайды тыңдамайсың сен?\nАйтшы бауырым, кімді алдайсың сен? //\n\n[Куплет 4]\nКүнәңді айтсаң Тәңір алдында,\nКенелер едің шексіз бақытқа.\n// Келші Құдайға, келші бауырым,\nИсаның Сөзін алшы қолыңа. //","songNumber":"116"},{"id":380,"title":"Құдай сізді әуел баста таңдап қойған","text":"[Куплет 1]\nҚұдай сізді әуел баста таңдап қойған,\nТәубе қылар кезің келді терең ойлан.\nСонда ғана жүрегің азат болар,\nТыныштық пен Киелі Рух келіп қонар.\n\n[Припев 1]\n// Сізді осында Құдай әкелді,\nҚуаныштан айтамыз:\nОй, бәрекелді!\nТөрге қысылмай отырыңыз,\nҚұдайды мадақтауға қосылыңыз. //\n\n[Куплет 2]\nИса үшін Құдайға алғыс айтайық.\nБәрімізде Киелі Рухқа толып қайтайық.\nИса - Шындық - Шынайы Өмір - Әкеге Жол.\nТатуласып Онымен сен бақытты бол!","songNumber":"122"},{"id":141,"title":"Құдай торғайларды қорғап","text":"[Куплет 1]\nҚұдай торғайларды қорғап, сақтайды, сүйеді\nҚұстарды қалай Ол сүйсе, мені солай сүйеді.\n\n[Припев 1]\nСүйеді Ол, сүйеді Ол,\nБілем мені сүйеді.\nБалдырғандарды сүйгендей,\nМені солай сүйеді.\n\n[Куплет 2]\nҚұдай далада өскен гүлдерді де сүйеді,\nОл сүйсе, мені солай сүйеді.\n\n[Куплет 3]\nЖаратып гүлдер мен құстарды сәулесін төкті,\nОл балаларды ұмытпайды, мені де сүйеді.","songNumber":"272"},{"id":322,"title":"Құдай тышқанды әдемі жаратты","text":"[Куплет 1]\nҚұдай тышқанды әдемі жаратты,"},{"id":470,"title":"Құдай үнемі менімен","text":"[Куплет 1]\nҚұдай үнемі менімен,\nҚұдай үнемі менімен,\nТүнде де, күндіз де,\nҚұдай үнемі менімен!\n\n[Куплет 2]\nҚұдай мені сақтайды\nҚұдай мені сақтайды\nТүнде де, күндіз де,\nҚұдай мені сақтайды.\n\n[Куплет 3]\nҚұдай мені сүйеді\nҚұдай мені сүйеді\nТүнде де, күндіз де,\nҚұдай мені сүйеді.","songNumber":"274"},{"id":668,"title":"Құдайы Исраилдің","text":"[Куплет 1]\nҚұдайы Исраилдің мен үшін қанын төккен,\nҚұдай Тоқтысы - Иса, тыныштық Патшасы,\n\n[Куплет 2]\nТізе бүгіп табынамын, Ием,\nСен - Тәңірсің, жер Патшасы.\nТізе бүгіп табынамын, Ием,\nҚымбатты Иса, Сен - Патшамсың!","songNumber":"112"},{"id":262,"title":"Құдайым бізді сүйеді бауырым","text":"[Куплет 1]\nҚұдайым бізді сүйеді бауырым\nМахаббатта болайық біз әрдайым!\n// Шын жүректен бір-бірімізді сүйіп,\nӨсиетін Исаның орындайық! //\n\n[Куплет 2]\nӨсиеті Құдайымның тамаша,\nҮйретеді, сүйеді Ол жаңаша,\n// Өсиетін өте қатты ұнатып,\nЖұбаныш пен рахаттану мен табам! //"},{"id":149,"title":"Құдайым - қорғаным, паналар орманым","text":"[Куплет 1]\nҚұдайым - қорғаным, паналар орманым,\nСен барда жүректе, себеп жоқ қорқатын.\n\n[Припев 1]\nОйнаймын, күлемін.\nҚорықпай жүремін.\nЕң мықты қорғаушым,\nҚұдай бар, білемін.\n\n[Куплет 2]\nҚорғадың жаудан да, жаладан, даудан да,\nСөзіңе беріксің, биіксің таудан да.\n\n[Куплет 3]\nОрманға барғанда, адасып қалғанда,\nҚорғадың Құдайым, жүрдің Сен сол маңда.","songNumber":"275"},{"id":758,"title":"Құдайым қуанады","text":"[Куплет 1]\nҚұдайым қуанады мен Оны тыңдағанда,\nҚұайым қуанады мен Оны тыңдағанда."},{"id":6,"title":"Құдайым, мен күнәкар пақырыңмын","text":"[Куплет 1]\nҚұдайым, мен күнәкар пақырыңмын,\nКөптігін мойындаған айыбының.\nЖүрегім соттап, жаным жай таппайды.\n// Толқында аударылған қайығыңмың. //\n\n[Куплет 2]\nСұмдықтан, азғындықтан арылмадым.\nБарады күннен - күнге қажып жаным.\nАрылтшы мені Өзің Тәңір Ием.\n// Өзіңе Иса арқылы жалынамын. //\n\n[Куплет 3]\nМен үшін қанын төккен қасиетті.\nОрындап Таураттағы өсиетті.\nРахмет Сол Ұлыңа Құдай Әке,\n// Сыйлаған еш ақысыз мәңгілікті. //\n\n[Куплет 4]\nМойнымда күнәм ауыр болса-дағы,\nСенемін әділікті Ол сыйлады.\nАйыбын дүниенің мойнына алып,\n// Төгілді қара жерге тамшы қаны. //\n\n[Куплет 5]\nКешірші, кешір Тәңір, кешір Әкем.\nӨзіңнен соны ғана сұрай берем.\nАйыпсыз Иса атынан келіп тұрмын,\n// Күнәмді пәк қанменен өшір Әкем. //","songNumber":"102"},{"id":798,"title":"Құдайым, Сенің еркің","text":"[Куплет 1]\nҚұдайым, Сенің еркің болсын,\nЫдысың етші мені Өзің.\nЕркімді менің қайта құршы,\nАлдыңда Сенің сеніп тұрмын.\n\n[Куплет 2]\nҚұдайым, Сенің еркің болсын,\nТексерші, сынап мені Өзің.\nҚардан да әппақ мені ағартшы,\nМомындық берші, сабырлы етші.\n\n[Куплет 3]\nҚұдайым, Сенің еркің болсын,\nАйнала азап жүректі түйрейт.\nКүш пенен берші бекемділік,\nҚұтқар, аяшы, Патшасы әлем.\n\n[Куплет 4]\nҚұдайым, Сенің еркің болсын,\nАдамдар білсін өмір мәнін.\nЖүрек еселеп Рухты аңсайды:\n«Құдайды менен, - деп, - көрсе әркім».","songNumber":"117"},{"id":309,"title":"Құдайым табынамын","text":"[Куплет 1]\nҚұдайым табынамын,\nБір Өзіңе табынам!\nСен бізге өмір бердің,\nСен әлемді жараттың!\n\n[Припев 1]\nКел достарым, кел билейік,\nМадақтайық біз Құдайды,\nӘн салайық, би билейік,\nМадақтайық біз Құдайды!\n\n[Куплет 2]\nРахмет Саған Құдай Ием!\nРахмет Саған Тәңір Ием!\nСенің атың мадақталсын,\nҚұдайым деп табынамын!"},{"id":754,"title":"Құдайым үлкен, құдіретті","text":"[Куплет 1]\nҚұдайым үлкен, Ол мықты, құдіретті,\nОл бәрін де істей алады.\nҚұдайым үлкен, Ол мықты, құдіретті,\nОл бәрін де істей алады!\nТаулар Оныкі,\nКөлдер Оныкі,\nОл жұлдыөдарды жаратты.\nҚұдайым үлкен, Ол мықты, құдіретті,\nОл бәрін де істей алады."},{"id":374,"title":"Құдыретті Құдайға","text":"[Куплет 1]\nӘнім менің Патша туралы\nРахымды Сөзі шығады жүрегіңнен\nЖылы жүзі ғажап бейнесі\nШапағат шашады бүкіл әлемге\n\n[Припев 1]\nҚұдіретті Құдайға, менің Әкеме\nАлдыңа келіп, бой ұсынам мадақ айтып\nТыныштық пен амандық , сыйлайтын Иеме\nӨмірімді арнап , мадақ айтам\nСәби болып келген Әкеме\nҰл ретінде сыйға берілген Иеме\nЖер жүзі бағынады билігіне\nӘділдігін көріп ақиқатын ұғынып"},{"id":349,"title":"Құдіретті Иеміздің","text":"[Куплет 1]\nҚұдіретті Иеміздің алдында\nБәріміз тізерлеп мадақтайық.\nҚасиетті Иса Мәсіхке\nБас иіп сиынамыз.\n\n[Припев 1]\nИса - Мәсіх.\nИса - Ол Ие.\nКиелі Рухтың жетегімен\nМадақтайық Оны.","songNumber":"118"},{"id":878,"title":"Құдіретті Құдайға","text":"[Куплет 1]\nӘнім менің Патша туралы,\nРақымды Сөзі шығады жүрегіңнен.\nЖылы жүзі ғажап бейнесі,\nШапағат шашады бүкіл әлемге.\n\n[Припев 1]\nҚұдіретті Құдайға, менің Әкеме,\nАлдыңа келіп, бой ұсынам мадақ айтып.\nТыныштық пен амандық , сыйлайтын Иеме,\nӨмірімді арнап, мадақ айтам!\n\n[Куплет 2]\nСәби болып келген Әкеме\nҰл ретінде сыйға берілген Иеме\nЖер жүзі бағынады билігіне\nӘділдігін көріп ақиқатын ұғынып","alternateTitle":"Әнім менің Патша туралы"},{"id":435,"title":"Құдіретті Құдайымсың!","text":"[Куплет 1]\nҚұдіретті Құдайымсың!\nСенің тағың ең ұлы,\nЕсімің Сенің биікте.\nШынымен мен өзгердім!\nОсыған қуанамын.\nАтыңды мадақтаймын Ием!\n\n[Припев 1]\n//  Сен бәрінің Иесі!\nТәңірсің Сен мәңгі!  //\n\n[Куплет 2]\nТағың Сенің киелі,\nӘділетті бәрінен.\nҚолдарымды Саған көтерем.\nМен Өзіңе ұқсаттың\nОсыған қуанамын.\nБарлық өмірім Сенде болсын.","songNumber":"30"},{"id":599,"title":"Құдіретті Тәңір, көктегі Әке","text":"[Куплет 1]\nҚұдіретті Тәңір, көктегі Әке,\nЖаратқан бізді Патшасың жерде.\n//  Көреген, мәңгі, керемет, дана,\nЖіберші жарық, бол бізбен бірге.  //\n\n[Куплет 2]\nИгі істер көзі, көктегі Әке,\nӨзіңе сенген қалдырма бізді.\n//  Тыныштығыңды орнатып жүрекке\nБатаңмен бер көктен мол береке.  //\n\n[Куплет 3]\nКөктегі Әке, жамандықтан сақтап,\nҚасиетті болуға жетеле.\n//  Жанымызды жадырат жақсы әнмен,\nСенімде нығайт ақ батаңмен.  //","songNumber":"5"},{"id":787,"title":"Құлап даңқымды коямын","text":"[Куплет 1]\nҚұлап даңқымды коямын\nАяғына Оның.\nМейірім мен махаббатты\nСол жерден табамын.\n\n[Припев 1]\nЖар саламын Киелі, Киелі,\nЖар саламын Киелі, Киелі,\nЖар саламын Киелі, Киелі,\nОл Киелі.","songNumber":"87","alternateTitle":"Жар саламын Киелі","copyright":"1998 воршиптогетер.ком сонгс"},{"id":734,"title":"Құрбандық орын","text":"[Куплет 1]\nМен құрбандық шалар орынға\nҚоямын мендегі барымды,\nСаған, Тәңірім, Сен\nҚан төктің сүйгендіктен,\nБізді өмір сүрсін дедің.\nКиелі Тоқты, жаңарттың, Сен өмірімді.\n\n[Предприпев 1]\nАспан жырлайды, жариялайды,\nСенің шексіз махаббатыңды.\nБарлығы көрер кереметіңді,\nДүние білер Сені,\nәлемге қуаныш дер.\n\n[Припев 1]\nИеміз айқышта жеңді бар күнәны,\nОл - жер Патшасы, біз ұлы\nОның рақымын біз жеткіземіз,\nБүкіл халқы жердің\nТанысын Сені,\nЖердің бар халқы\nТанысын Сені.","songNumber":"120"},{"id":440,"title":"Құрбан еттің біз үшін","text":"[Куплет 1]\nҚұрбан еттің біз үшін,\nҚасиетті жаныңды.\nТөгіп кеттің мен үшін,\nӨз Киелі қаныңды.\n\n[Припев 1]\n// Күнәлардан құтқарып,\nМәңгі өмір сыйладың.\nЖан-тәніммен ұмтылам,\nҰсынғанда бағыңды.  //\n\n[Куплет 2]\nСен әлемді жаратқан\nБір Құдайдың Ұлысың\nШынайы өмір беретін,\nМөлдір бұлақ көзісің.\n\n[Припев 2]\n// О, Тәңірім жасаған,\nПатшалығың жақындап,\nОсы әлемге жарқырап,\nТөгіп тұрған нұрысың.  //\n\n[Куплет 3]\nЖанға дәру беретін,\nЖүрекке жылу төгетін.\nЖаратқан Өзің пендеңе\nКөңілінді бөлетін.\n\n[Припев 3]\n// Қандай шексіз махаббат\nҚандай ыстық құшағың.\nҚуанғанда Өзіңе,\nҚияға самғап ұшамын.  //\n\n[Куплет 4]\nНұрыңды төкші халқыма,\nҚараңғыдан құтқаршы,\nШындық тапсын жолыңнан\nКүнәсінан арылтшы.\n\n[Припев 4]\n// Жаратқан біздің Иеміз,\nТәңіріміз Бағушы.\nТар жолменен жетелеп,\nМәңгі өмірге апаршы.  //","songNumber":"119"},{"id":351,"title":"Құрметтегім келеді","text":"[Куплет 1]\nҚұрметтегім келеді,\nДегім келет: «Сүйем Сені».\nӨмірімсің Сен менің,\nАрдақтайм, Тәңір, ізгі Атыңды.\n\n[Припев 1]\nҚұрметтегім келеді,\nДегім келет: «Сүйем Сені».\nӨмірімсің Сен менің.\nАрдақтайм, Тәңір, ізгі Атыңды.\nАрдақтаймын ізгі Атыңды.\nАрдақтаймын ізгі Атыңды.","songNumber":"121"},{"id":1028,"title":"Құрметтеймін Сені балаңдай","text":"[Куплет 1]\nҚұрметтеймін Сені балаңдай,\nМадақтаймын әнменен тынбай.\nЖар болшы маған Тәңір,\nАдалсың Сен мәңгі.\nҚараңғыдан шығарған,\nРақымын мол сыйлаған,\nКүнәмді кешіріп, өлімнен\nмені құтқарған.\n\n[Припев 1]\nҚұтқарушым менің, мен Сені сүйемін.\nСаған мәңгі ризамын.\nЖан-тәніммен Сені, Иса, жалғыз Сені,\nМен мадақтаймын!\nҚұтқарушым менің, мен Сені сүйемін.\nКешірші деп сұраймын.\nМейірімді Иемді, жақсы адал Иемді,\nМәңгі жырлаймын, мәңгі жырлаймын.\n\n[Куплет 2]\nӘн саламын қуанғанымнан,\nЕшқашан кетпеші жанымнан.\nПанам болшы, О, Тәңір,\nАдалсын Сен мәңгі.\nТіршілікті жаратқан,\nОйын іске асырған.\nӨзін құрметтеген адамға\nЖаны ашыған.","songNumber":"122"},{"id":479,"title":"Құтқардың бар адамзатты күнәдан","text":"[Куплет 1]\nҚұтқардың бар адамзатты күнәдан,\nСыйладың ғажап өмірді жаңадан.\nҚуанамын әрқашан да Өзіңе,\nСенің әрбір кереметтей сөзіңе.\n\n[Припев 1]\nЖүрегімде, ойымда Сен болшы,\nЖүрегімді Киелі сөзіңе толтыршы.\nСүйемін тек Өзіңді Құдай Әке,\nО, Иса, Патшасың Сен жалғыз көкте.\n\n[Куплет 2]\nБілдім тек Исадан нағыз шындықты,\nАйтайын Саған барлық алғысымды.\nӨзгерттің Ием менің өмірімді,\nҮйреттің шынайы жолмен жүруді.","songNumber":"69"},{"id":294,"title":"Құтқардың күнә құрсауынан","text":"[Куплет 1]\nҚұтқардың күнә құрсауынан,\nНұр бердің түнекте сөзіңмен.\nШығардың жалған алдауынан,\nЖетеледің мәңгі өмірге!\nЖетеледің мәңгі өмірге!\nЖетеледің мәңгі өмірге!\n\n[Припев 1]\nИса - Ием, мәңгі ризамын Өзіңе!\nИса - Ием, мәңгі ризамын Өзіңе!\nИса - Ием, мәңгі ризамын Өзіңе!\nМәңгі ризамын Өзіңе!\nМәңгі ризамын Өзіңе!\nМәңгі ризамын Өзіңе!\n\n[Куплет 2]\nКүйзелдің, айқышта жаныңмен,\nҚорландың, қарғалдың тәніңде,\nАйыбымды жудың қаныңмен,\nМәңгі ризамын Өзіңе!\nМәңгі ризамын Өзіңе!\nМәңгі ризамын Өзіңе!"},{"id":699,"title":"Құтқардың мені Иса","text":"[Куплет 1]\nҚұтқардың мені Иса\nСенен артық ешкім жоқ.\nӘр күнімде мадақтаймын\nҰлы махаббатыңды.\nҚуаныш бердің Сен,\nӘлсіз болсам қиналмаймын.\nҚайда болсам, не болса да,\nМадақтаймын мен Сені.\n\n[Припев 1]\nПатшамызды шын жүректен мадақтайық!\nБүкіл әлем Исаға ән салайық.\nТеңіз, жайлау, орманмен\nӘн салды, ән салды.\nИса Мәсіх біз Сені мадақтаймыз!\nМәңгілікке біз Сенсіз бара алмаймыз.\nМахаббатың да, күшің де бізбен бірге.\nМахаббатың да, күшің де бізбен бірге.","songNumber":"48","alternateTitle":"Иса менің Құтқарушым","copyright":"1993 Хиллсонг Публишинг"},{"id":735,"title":"Құтқардың Сен адамзатты күнәдан","text":"[Куплет 1]\nҚұтқардың Сен адамзатты күнәдан\nСыйладың Сен ғажап өмір жаңадан.\nҚуанамын әрқашан мен Өзіңе\nСенің әрбір кереметтей Сөзіңе.\n\n[Припев 1]\n// Жүрегімде ойымда Сен болшы\nЖүрегімді Киелі Сөзіңе толтыршы.\nСүйемін мен Өзіңді Құдай Әке,\nО, Иса, Құдайсың Сен жалғыз, Көкте. //\n\n[Куплет 2]\nБілдім мен Исадан нағыз шындықты\nАйтайын Саған барлық алғысымды\nӨзгерттің Сен менің өмірімді\nКөрсеттің Сен шындық өмір сүруді.","songNumber":"111"},{"id":513,"title":"Құтқарушым","text":"[Куплет 1]\nҚұтқарушым, Құн Төлеушім,\nКүнәдан мені азат еттің.\nҚұдіретті, киелі Құдай,\nӨмірімді Сен өзгерттің.\n\n[Припев 1]\nО, Иса,\nБіздің әлемге мәңгіліктен келдің,\nҚұдайдың Тоқтысы.\nБіз үшін құрбан боп,\nҮшінші күні тірілдің.\nӘкеге жол аштың,\nБізге мәңгі өмір бердің.\nАллелуя Саған Иса","songNumber":"126"},{"id":970,"title":"Құтқарушым, ғажапсың","text":"[Куплет 1]\nҚұтқарушым, ғажапсың,\nМен үшін Сен көтердің.\nЕң ауырын азаптың,\nСені дос деп өтермін.\n\n[Припев 1]\n//  Есімде төгілген қаның,\nҚолдарың жара басқаны.\nКеліп Тәңірге мен тағы,\nБас иіп алғыс айтамын. //\n\n[Куплет 2]\nАйтқан Сөзің есімде:\n«Кешір Әке оларды».\nКез болғаның есімде,\nО, Иса, маған жолда.\n\n[Куплет 3]\nШақырмасаң Сен мені,\nТартпасаң жылы сөзбенен\nЖүрер едім адасып,\nӘр қилы жалған жолмен.\n\n[Куплет 4]\nМәсіх мені сүйгенде,\nӨміріме енді нұр.\nТек Исада тыныштық,\nШаттық, өмір мақсатым.","songNumber":"124"},{"id":135,"title":"Құтқарушым ғажапсың, Сені дос деп өтермін","text":"[Куплет 1]\nҚұтқарушым ғажапсың,\nСені дос деп өтермін.\n\n[Припев 1]\nЕң ауырын азаптың,\nМен үшін Сен көтердің.\n\n[Куплет 2]\nЕсімде төккен қаның,\nҚолдарың жара басқан.\n\n[Припев 2]\nҚайырылып Тәңірге мен,\nБас иіп алғыс айтам.\n\n[Куплет 3]\nАйтқан сөзің есімде:\n«Кешір Әке оларды».\n\n[Припев 3]\nКез болғаның есімде,\nО, Иса, жолда маған.\n\n[Куплет 4]\nШақырмасаң Сен мені,\nТартпасаң жылы сөзбен,\n\n[Припев 4]\nЖүрер едім адасып,\nӘр қилы жалған жолмен.\n\n[Куплет 5]\nМәсіх мені сүйгенде,\nӨміріме енді нұр.\n\n[Припев 5]\nТек Исада тыныштық,\nШаттық өмір мақсатым.","songNumber":"112"},{"id":530,"title":"Құтқарушым, жетеле мені","text":"[Куплет 1]\nҚұтқарушым, жетеле мені.\nҚайда болса да мен еремін.\nКөмектес айқышыма менің,\nҚиналмай қуанып жүрейін.\n\n[Припев 1]\nӘлсіреп құлаған кезімде,\nҚолыңды соза гөр киелі.\n// Көмектес соңыңнан еруге,\nМен сүйемін Жаратқан Сені! //\n\n[Куплет 2]\nКүлімдеп бәрі де қараса,\nСоңыңнан еру маған оңай,\nҚиындықтар келген жағдайда,\nКөмектес жетуге аспанға.\n\n[Куплет 3]\nСаған сенгім келеді менің,\nСенімімді нықтап Сен сақта.\nМен үшін айқышта қиналдың,\nҚиындық көруге лайықпын.\n\n[Куплет 4]\nСенсіз мен әлсіз бір адаммын.\nАлдыңда топырақпын Сенің.\nСенде ғана барлық үмітім.\nҚуаныш пен бақыт тек Сенсің.","songNumber":"113"},{"id":646,"title":"Құтқарушы Патша","text":"[Куплет 1]\nРухы әлсіз жарияласын:\n\"Мәсіхті өлімнен тірілткен күш менде бар!\"\nӘрбір жарлы мойындасын:\n\"Еншім Құдайымда, мен жарылқанғам!\"\n\n[Предприпев 1]\nЖүректерде отыңды жақ,\nҰлың үшін Сенің жалындап жанайық.\nАспанмен біз жариялаймыз:\n\"Патшамызсың!\"\n\n[Припев 1]\nСені сүйеміз, табынамыз,\nИемізсің, Ізгісің тек Сен.\nҰлыңнан сұрап өтіндің Сен,\nАлсын деп ауыр күнә айқышын.\n\n[Припев 2]\nСені сүйемін, табынамын,\nМаған қайта үміт бердің.\nМахаббаты құрметіне\nӨмір арнайм, Құтқарушым.\n\n[Куплет 2]\nБүкіл қауым жарқырасын,\nӨз қалыңдығыңдай, өміріңді арнаған\nЖоғалғандар қайта оралсын,\nМахаббатын көрсін,\nӨзің құтқарғандардың.","songNumber":"125"},{"id":191,"title":"Құтқарып алдың әлемді","text":"[Куплет 1]\nҚұтқарып алдың әлемді\nМахаббат нұрыңды төгіп.\nӨшкен жүректі жандырып\nСенімді бердің.\nСенің алдыңа келеміз.\nӘке Саған қымбатпыз біз.\nИеміз, Сенің атыңды\nМадақтаймыз.\n\n[Припев 1]\n// Мадақ пен даңқ Саған болсын,\nБарлық халық ғасырларда.\nКүшің Сенің шексіз Ием,\nШексіз рақымдылығың да.  //","songNumber":"49"},{"id":1031,"title":"Құшағыңа","text":"[Куплет 1]\nҚұшағыңа\nМені басып\nҚорға, Ием,\nАяулы қолыңмен.\n\n[Припев 1]\nАласұрып дауыл тұрса да,\nСамғап ұшам биік мен одан да.\nҚұдайым жалғыз Сен - панамсың,\nҚорықпаймын, біргесің Сен.\n\n[Куплет 2]\nЖаным бейқам\nҚұшағыңда,\nСенемін\nБіргесің Сен, Ием"},{"id":615,"title":"Қызықты телефоным бар","text":"[Куплет 1]\nҚызықты телефоным бар,\nСиыну телефоным бар.\nЖылағым келсе де, қуанған кезде де,\nҚоңырау шалам Құдайға.\n\n[Припев 1]\n1,2,3,4,5,6,7.\nТұтқаны алып дұғамды есті.\n\n[Куплет 2]\nҚұдаймен сөйлескеннен соң,\nЖүрегім тынышталады.\nҚайтадан ойнадым, қызыққа тоймадым,\nКөңілсіз енді болмадым.\n\n[Куплет 3]\nҚызықты телефоным бар,\nСиыну телефоным бар.\nИсамен егер де сиынам десеңдер,\nОнымен дос боп алыңдар.","songNumber":"276"},{"id":836,"title":"Қымбатсың Сен маған әр күнде","text":"[Куплет 1]\n// Қымбатсың Сен маған әр күнде,\nҚымбатсың Сен әрқашан күтем Сені\nИса, жүрегім аңсайды Сені.\nСенімен боламын мәңгіге! //\n\n[Припев 1]\n// Мен Саған өмірімді арнаймын,\nИса, мені Сен қолданшы.\nӘр күнде Сөзіңе ұмтыламын,\nТәңірім Саған мен сенемін. //","alternateTitle":"Мен Саған өмірімді арнаймын"},{"id":51,"title":"Қымбатты дос, аялдашы, тыңдашы","text":"[Куплет 1]\nҚымбатты дос, аялдашы, тыңдашы,\nҚұдайдан сен өтініп бір сұрашы.\n// Сен бейбақты құтқарады күнәдан,\nСен де Оны бар ниетпен сұрашы. //\n\n[Куплет 2]\nТазалашы жүрегіңді, ойыңды,\nТазалашы ластанған бойыңды.\n// Сен бейбақты құтқарады күнәдан,\nТек сұрай біл шын жүректен Исадан! //","songNumber":"115"},{"id":528,"title":"Лайық емеспін махаббатыңа","text":"[Куплет 1]\nЛайық емеспін махаббатыңа,\nЛайық емеспін шапағатыңа.\n\n[Припев 1]\n// Жылдар бойы Сенсіз адастым,\nКүнәнің торында шатастым! //\n\n[Куплет 2]\nБасқалардай дегеніммен жүрдім,\nМәнсіз мақсатсыз өмірді сүрдім.\n\n[Припев 2]\n// Жүрегім мұздап қатая берді,\nАрам пиғылдан шалқая бердім! //\n\n[Куплет 3]\nСен жүрегімнің есігін қақтың,\nОянып, оны айқара аштым.\n\n[Припев 3]\n// Адасқан ұлыңды Сен кешірдің,\nКүнәні істегем, Сен өшірдің! //\n\n[Куплет 4]\nБақыттан көп қуана жыладым,\nЖанымды Мәсіхке мен арнадым.\n\n[Припев 4]\n// Өзіне келгенді Ол ақтайды,\nКүнәларға жібермей сақтайды! //","songNumber":"116"},{"id":348,"title":"Лайықсың","text":"[Куплет 1]\nЛайықсың, Сен лайықсың,\nПатшасы патшалардың\nСен лайықсың.\nЛайықсың, Сен лайықсың\nИесі иелердің\nСиынамын Саған.\n\n[Куплет 2]\nКиелісің, Сен Киелісің,\nПатшасы патшалардың\nСен Киелісің....\n\n[Куплет 3]\nИса, Сен әділсің,\nПатшасы патшалардың\nСен әділсің...","songNumber":"128","copyright":"1999 Танкыоу Мусик, 1986 Интегриты'с Хосанна! Мусик"},{"id":820,"title":"Лайықсың Иса!","text":"[Куплет 1]\nИса Мәсіх Сен лайықсың\nСенің Киелі Атың мәңгі даңқталсын\nБас иіп Сенің алдыңа\nТізе бүгіп бүкіл әлем табынсын\nТізе бүгіп Саған табынсын!\n\n[Припев 1]\n//// Лайықсың Иса!\nЛайықсың Патша!\nЛайықсың Тәңір Ұлы даңққа! ////\n\n[Бридж 1]\nСен лайықсың! Сен лайықсың!\nСен лайықсың! Сен лайықсың!"},{"id":269,"title":"Лайықсың Сен ұлы даңққа","text":"[Припев 1]\nЛайықсын! Лайықсын Сен, ұлы даңққа!\nБүкіл адамзат Сені қастерлесін, Иса!\n\n[Куплет 1]\nО, Иса, шын жүректен Сені мадақтаймын\nЖанадан шыққан әнімен Сені дәріптеймін\nЖасаған кереметтеріңнің бәрін жариялаймын\nАйқыштағы құрбандығыңды мен ұмытпаймын","alternateTitle":"О Иса шын жүректен"},{"id":171,"title":"Лайықсың Тоқты","text":"[Куплет 1]\nАйқыш үшін рахмет!\nҚұным төлегеніңе.\nКүнәм мен ұятты алдың,\nСүйіп келдің,\nМаған рақым төктің.\nЖараларың үшін\nМахаббат үшін рахмет!\nМені жуып тазарттың,\nЕнді білем:\nКешірдің Сен мәңгіге!\n\n[Припев 1]\nЛайықсың Тоқты, тақта отырған,\nМәңгіге тәжіңді кидің.\nЖеңіспен билік құр!\nКөтеріл биік, Құдай Ұлы Иса!\nКөктен келген Сый құрбан болды,\nЛайықсың даңққа,\nЛайықсың Тоқты!","songNumber":"210"},{"id":777,"title":"Мадақта жаным Құдайды","text":"[Куплет 1]\nМадақта жаным Құдайды,\nӘн саламын Оған!\nМадақта жаным Құдайды,\nИгі Оған ән салған!\n\n[Припев 1]\nҚұдайға даңқ, // Жаратқанға //\nҚұдайға даңқ, Аллелуя!\n\n[Куплет 2]\nҚұдай Ұлы және күшті,\nОның құдіреті\nҚұдай Ұлы және шексіз\nАқыл парасаты\n\n[Куплет 3]\nКішіпейілді қолдайды,\nҚиналғанда күш беріп.\nАдалды көріп тұрады,\nМұқтаждықтарын беріп.\n\n[Куплет 4]\nКім Құдайға сенім артса,\nҰятқа қалмайды.\nӘн айтшы Құтқарушыға,\nАдам Оған ән айтшы."},{"id":428,"title":"Мадақта Исаны","text":"[Куплет 1]\n// Мадақта Исаны,\nМадақта Исаны!\nӘр күнде, әр күнде\nОның Атын мадақта! //\nЕш нәрседен қорықпа,\nИса бірге болады.\nЖеңіске сен ие боласың!\n\n[Припев 1]\nҚұдайды білу бақыт,\nҚұдаймен тату болу бақыт.\nҚұдаймен болу бақыт,\nҚұдаймен тату болу бақыт.","songNumber":"103"},{"id":61,"title":"Мадақтаймын, ән саламын","text":"[Куплет 1]\n//  Мадақтаймын, ән саламын,\nҚуанып мен шаттанамын.\nЖер бетіндегі барлық ұлт\nКөтерсің Сенің Атыңды.  //\n\n[Припев 1]\n////  Иса, Иса! Көтерілсің Сенің Атың!  ////","songNumber":"98"},{"id":288,"title":"Мадақтаймын мен Сені","text":"[Куплет 1]\nМадақтаймын мен Сені, Иса\nМақтаймын Сені, Иса\nӨйткені Сен ұлысың Тәңірім\n\n[Куплет 2]\nМадақтаймын мен Сені, Иса\nҰлысың Сен, Иса\nМақтаймын Сені\n\"Құдайым даңқты!\" деп"},{"id":68,"title":"Мадақтаймын Сені","text":"[Куплет 1]\nМадақтаймын Сені\nАрдақтаймын Сені\nӘнге қосып Сені жырлаймын.\nӘке деймін Сені\nДәріптеймін Сені\nӘр Сөзіңді Сенің тыңдаймын\n\n[Припев 1]\n// О, Иса, О, Иса,\nО, Иса Мәңгілік Сен жаса!  //\n\n[Куплет 2]\nСағынамын Сені\nСүйемін деп Сені\nТәңірім деп Сені санаймын\nПанам деймін Сені\nҚұрметтеймін Сені\nАллелуя Саған айтамын","songNumber":"130"},{"id":968,"title":"Мадақтаймын Сені, ардақтаймын Сені","text":"[Куплет 1]\nМадақтаймын Сені,\nАрдақтаймын Сені.\nӘнге қосып жырлаймын!\nӘке деймін Сені,\nДәріптеймін Сені.\nӘр сөзіңді Сенің тыңдаймын!\n\n[Припев 1]\n// О, Иса,\nО, Иса,\nО, Иса мәңгілік Сен жаса! //\n\n[Куплет 2]\nСағынамын Сені,\nСүйемін тек Сені,\nТәңірім деп Сені санаймын!\nПанам деймін Сені,\nҚұрметтеймін Сені,\nАллелуя Саған айтамын!"},{"id":749,"title":"Мадақтаймын Сені Тәңірім","text":"[Куплет 1]\nМадақтаймын Сені Тәңірім,\nӘр жерде Сен мадақтал.\nШайтан сен жеңілдің\nИсаның қаныменен.\nМадақтаймын Сені Тәңірім,\nТаулар да ән салады\nЖапырақтарда бізбен би билейді.\nМадақпен толады бүкіл әлем.\n\n[Предприпев 1]\nАспан мен жердің Тәңірі Иса,\nСондықтан мен жеңімпазбын\n\n[Припев 1]\nИса Тәңір, Оны мадақтаймыз\nИса Тәңір, құрметтеймін Оны.\n\n[Бридж 1]\nӨміріммен осы өлеңді\nСаған арнаймын, Ием менің.","songNumber":"131"},{"id":659,"title":"Мадақтайық","text":"[Куплет 1]\nМадақтайық, мадақтайық,\nПатшаны бар дауыспен мадақтайық.\n\n[Куплет 2]\nМадақты қабыл ал\nБұл мадақ Саған,\nБіздің өзгермес ғажап Құдай.\nТізе бүгіп Сені шақырамын,\n/// Иса - Тәңірім! ///\nАумин.","songNumber":"129"},{"id":575,"title":"Мадақталсын Тәңірдің Есімі","text":"[Куплет 1]\nМадақталсын Тәңірдің есімі,\nОл келеді, міне, ашық есігі.\nБарлығы көреді ақша бұлт үстінен,\nЖарқ еткен найзағай секілді.\n\n[Припев 1]\nКиелі, киелі, киелі,\nАйбынды // Тәңіріміз //\n/// Ол болған, бар және мәңгі болады ///\n\n[Куплет 2]\nБарлық ұлттар жиналмақ алдыңда,\nӨмір кітабы Сенің қолыңда.\nКім сенсе паш еткен Құрбандық Тоқтыңа,\nСол мәңгі болады жаныңда.\n\n[Куплет 3]\nПеріштелер ән салып мыңдаған,\nҚұрбандық Тоқтыны тыңдаған.\nЛайықты, лайықты Құрбандық Тоқты, - деп\nМадақтап барлығы шулаған.\n\n[Куплет 4]\nСен ғана, абзал Әке - Құдайым\nМенің өмірім алдыңда әрдайым.\nАбырой, атақ-даңқ - бәрі сенде Ием,\nМені қалдырмай жетеле Сен.","songNumber":"197"},{"id":814,"title":"Мадақтандар Құдайды Киелі Үйінде","text":"[Куплет 1]\nМадақтаңдар Құдайды киелі Үйінде\nМадақтаңдар құдіретті көктеге Әкені\nМадақтаңдар Құдайдың керемет ісін\nМадақтаңдар Құдайдың зор Ұлылығын\n\n[Припев 1]\nМадақтаңдар Құдайды ғажап Үндермен\nМадақтаңдар Құдайды домбыра Даусымен\nМадақтаңдар ән салып, би билеп\nМадақтаңдар Құдайды ішекті аспаппен.\n\n[Куплет 2]\nМадақтаңдар Құдайды Дауылпаз даусымен\nМадақтаңдар Құдайды Сылдырмақ үнімен\nМадақтаңдар Құдайды Қобызбенен\nМадақтаңдар Құдайды Сырнайменен"},{"id":119,"title":"Мадақтаңдар балалар, Құдайды","text":"[Куплет 1]\nМадақтаңдар балалар, Құдайды,\n// Ол - махаббат! //\n\n[Куплет 2]\nСүйіңдер балалар, Құдайды,\n// Ол - махаббат! //","songNumber":"277"},{"id":287,"title":"Мадақтаңдар бар халық","text":"[Куплет 1]\nМадақтаңдар бар халық\nТәңір Иеңді мадақта!\nМадақтаңдар, Ол-ізгі!\nМәңгі Оның мейірімі\n//////// Аллилуя ////////"},{"id":193,"title":"Мадақтаңдар Құдайды!","text":"[Куплет 1]\nМадақтаңдар Құдайды!\nАлеллу, Алеллу, Алеллуя!\n\n[Припев 1]\n/// Алеллуя! Алеллуя! Алеллуя! Аумин! ///\n\n[Куплет 2]\nӘн шырқаңдар Құдайға!\nАлеллу, Алеллу, Алеллуя!\n\n[Куплет 3]\nҚол жайыңдар Құдайға!\nАлеллу, Алеллу, Алеллуя!","songNumber":"132"},{"id":560,"title":"Мадақтаңдар Құдайды Өз Киелі үйінде","text":"[Куплет 1]\nМадақтаңдар Құдайды Өз Киелі үйінде!\nМадақтаңдар Құдіреттіні көктеде!\n//  Мадақтаңдар Оны керемет істері үшін,\nМадақтаңдар Оны зор ұлылығымен!  //\n\n[Куплет 2]\nМадақтаңдар Оны үнімен кернейдің\nМадақтаңдар Оны жетіген, домбырамен,\n//  Мадақтаңдар Оны барабанмен би билеп,\nМадақтаңдар Оны қобыз, сыбызғымен!  //\n\n[Куплет 3]\nМадақтаңдар Оны сылдырмақтың, сыңғырымен,\nМадақтаңдар дауылпаздың дауысымен!\n//  Жаны барлар, бүткіл ел мадақтасын Тәңірді!\nИемізді мадақтайық, құрметтейік!  //","songNumber":"117"},{"id":1005,"title":"Мадақта Тәңірді сен","text":"[Куплет 1]\nМадақта Тәңірді сен\nМәңгілік махаббатпен\nМадақта жан ұмытпа\nҚұдай адал барлық жолда\nМадақта жан әрі біл\nТастамайды Ол ешқашан\nМадақта жан әр ісін\nӨміріңде орын алған\n\n[Куплет 2]\nЖер менен мәңгілікте\nНе деген Ұлы жоспар\nБәрі дайын мен үшін\nЖан дүнием Оны даңқта\nКешті күнәмді енді мен\nКіршіксіз тазамын\nҰят пенен қайғы да жоқ\nОл берді бақыт тәжін\n\n[Припев 1]\n// Мадақта жаным, мәңгі ұмытпа\nБар рақымдылығын Оның //\n\n[Куплет 3]\n// Жеңіс бізде, Жеңімпаз бізбен\nКөтереміз біз Иса туын\nТыңда өлім қайда улы тісің\nТапталды күнә өлім //\n\n[Куплет 4]\n// Құтқарды Иса күшті қолымен\nБерді біздерге сенім, үміт\nАл енді жоқ қарғыс өмірде\nОған сенгендерде //"},{"id":505,"title":"Мақсаты жоқ адамдар","text":"[Куплет 1]\nМақсаты жоқ адамдар,\nШаршаған бәрі бүгін,\nКелешегі бұлыңғыр, мұң басқан жүзін.\nАзап, қайғыдан көзі шыланған жасқа,\nКім көреді оларды, Исадан басқа.\n\n[Припев 1]\nҚұдайды ізде, Ол саған керек,\nЖапа шеккен жаныңа береді көмек.\nҚұдайды ізде, Құдайды ізде.\nҮмітіңді үзбе, Құдайды ізде.\n\n[Куплет 2]\nБұл қараңғы дүниеге,\nКөктен төкті жарығын,\nШақырады бәріңді, Ғажап, нәзік үн.\nКеш қалмаңдар, келіңдер, күтуде әлі,\nТек Исада, біліңдер, өмірдің мәні.","songNumber":"127"},{"id":499,"title":"Мақтанатын, мақтанышым Өзіңсің","text":"[Куплет 1]\nЖүрегіме мәңгі көктем сыйладың\nҒұмырыма мәңгі өмір сыйладың\nЖалғызыңда жалғызым деп қуанттың,\nЖараланған жүрегімді жұбаттың\n\n[Припев 1]\nМақтанатын мақтанышым Өзіңсің\nДемалатын демалысым Өзіңсің\n// Рахаттанып тынығатын\nҚуанышпен қуантатын\nКөктегі Әкетайым Сен Өзіңсің! //\n(Құтқарушы Ағатайым Сен Өзіңсің)\n\n[Куплет 2]\nЖарқыраған жарық жүзің жайнатады\nЖарылқаған жарылқауың байытады\nЖараланған жарақатың жазатын\nЖарылқаған жаңа өмір сыйладың"},{"id":301,"title":"Малшылар ақырға жүгіріп келді","text":"[Куплет 1]\nМалшылар ақырға жүгіріп келді,\nНәрестеге олар қатты қуанды,\n\n[Припев 1]\n// Құрмет Тәңіріме, құрмет Тәңіріме,\nТыныштық Ол берді! //","songNumber":"279"},{"id":679,"title":"Мама, Иса жайлы айтып берші","text":"[Куплет 1]\nМама, Иса жайлы айтып берші,\nКөктен жерге неге келгенін.\nМама, Иса жайлы айтып берші,\nҚалай құтқарылу бергенін.\n\n[Припев 1]\nМама, айтшы Оның сиынғанын,\nБар адамзат үшін жердегі.\nАуруларды сауықтырғанын,\nКүнәкарды қалай емдеді.\n\n[Куплет 2]\nМама, айтшы Оның мейірімін,\nНеге бізді жақсы көреді?\nШын жүректен мен Оған сенемін,\nЕкінші рет тағы келеді.","songNumber":"280"},{"id":720,"title":"Марал мөлдір суды қалай аңсаса","text":"[Куплет 1]\nМарал мөлдір суды қалай аңсаса,\nМенің жаным да,\nСені іздеп шөліркейді, Тәңір,\nСені аңсайды.\n\n[Припев 1]\nҚұдайым, Сен қорғанышым,\nБар үмітім менің, жігерім, күшім,\nЖанымды да, өмірімді де,\nӨзіңе тек арнадым.\n\n[Куплет 2]\nКүндіз-түні рақым жасаған,\nТәңірімді жырлаймын.\nӨмір берген Құдай Әкеме,\nДұғамды бағыштаймын.\n\n[Припев 2]\nБағушым, ең жақын Досым,\nЖетелейді күшті қолың.\nМейірімді Тәңір Иемді,\nӘніммен мадақтаймын.","songNumber":"119","copyright":"1984 Мараната Праисе, Инк."},{"id":1008,"title":"Мараната","text":"[Куплет 1]\nМараната! Тәңір Иса,\nАңсаймыз, кел Сен қайта.\nХалықтар жырлап жер бетінде\nТабынады Құдай Иеге.\nМараната! Тезірек кел!\nАңсаймыз Тәңір Сені.\nБарлық халықтар Саған келеді,\nШаттанып ән салып би билейді.\n\n[Припев 1]\nПатшамыз, дайындаймыз Өзіңе жолды,\nАйқышымызд(ы) алып жер шетіне біз барамыз.\nПатшалығы Иеміздің жерге келген кезде,\nҰлттарға біз Патшаны көрсетеміз.\n\n[Бридж 1]\n/// Мараната! Мараната!\nАллелуя, аңсаймыз кел Сен қайта! ///","songNumber":"133"},{"id":21,"title":"Махаббат және күш","text":"[Куплет 1]\nМахаббат және күш\nКөп өмірімде менің.\n\n[Припев 1]\nСаған мен табынам, барлық жүрегіммен.\nСаған мен табынам, барлық есімменен.\nСаған мен табынам, барлық күшімменен.\nСен менің Патшам, Құдайым.","songNumber":"101","alternateTitle":"Махаббат пен күш, Махаббат, күш-қуат","copyright":"1987 Меркы / Винеярд Публишинг"},{"id":315,"title":"Махаббатпен қызмет етем","text":"[Куплет 1]\nБауырластан көрініп тұрған\nҚұдайдың бейнесі қандай әсем\nҚұдайдың қымбатты баласы боп\nМахаббатпен қызмет етем!\n\n[Куплет 2]\nБіздің арамызға келген\nҚұдай ұлылығы қандай әсем\nҚымбатты Патшамен бірге болып\nМахаббатпен қызмет етем!","songNumber":"24"},{"id":196,"title":"Махаббатымды әніммен","text":"[Куплет 1]\nМахаббатымды әніммен\nЖеткіземін Исаға.\nЖерменен көктің Тәңірі\nҚұтқарушы Патшама.\n\n[Припев 1]\nЖанымда әр кез болсаң менің\nШаттана соғар жүрегім.\nӨзіңнің оң қолыңмен\nЖетелеші әрқашан.\nКиелі Ием, Саған сенемін.\nТәңір Саған сенемін.","songNumber":"99"},{"id":406,"title":"Махаббатың бұлттан да жоғары","text":"[Куплет 1]\nМахаббатың бұлттан да жоғары\nАдалдығың жерді толтырады\nШындығың сенің асқар биік таудай\nӘділдігің мүлтіксіз қандай!\n\n[Припев 1]\n// Мен әнге саламын\nСиынам Патшама\nКүш қуат табамын\nҚанатыңның астында //  рет\n\n[Бридж 1]\nМахаббатың бұлттан да жоғары\nАдалдығың жерді толтырады"},{"id":669,"title":"Махаббатың қандай ғажап","text":"[Куплет 1]\nКешірілдім, себебі айыпталдың,\nҚабылдандым, Сен тасталдың.\nТірімін енді, Рухың менде ұлы Ием,\nСен өліп, қайта тірілдің.\n\n[Припев 1]\nМахаббатың қандай ғажап?!\nПатшасың,\nөлдің мен үшін.\nМахаббатың қандай ғажап?!\nҚастерлеймін, қуанамын,\nБар ісіммен құрметтеймін.\n\n[Бридж 1]\nСен Патшасың!\nСен Патшасың!\nИса, Сен Патшасың!\nИса, Сен Патшасың!","songNumber":"135","copyright":"1996 воршиптогетер.ком сонгс"},{"id":857,"title":"Махаббатыңның бір ұшқыны менің, жан-дүниеме тиді","text":"[Куплет 1]\nМахаббатыңның бір ұшқыны,\nМенің, жан-дүниеме тиді\nӨміріме жүрегімнен ыстық,\nТаза сезім кірді.\n// Жалындатып бұл махаббатынан\nТаба алмады жүрек\nЫстық сезім, таза сезім\nЖүрегімді алдлы билеп //\n\n[Куплет 2]\nНұр болып маған төгілдің,\nЖүрегім шаттыққа толды.\nКиелі Рухың жетелеп,\nӨзіңмен кездестіреді.\n// Кезедсуге әркез асықпын,\nСағындым Сені Иса,\nБақыт құсым, бақытымсың\nСен менің басыма қоған. //"},{"id":131,"title":"Мәңгіге Иса мадақталсын, Оның атына даңқ келсін","text":"[Куплет 1]\nАрайлап атқан таңымыз\nБөленеді Оның нұрына\nАйтамыз алғыс біз Саған\nҚұтардың бізді азаптан\n\n[Припев 1]\n// Мәңгіге Иса мадақталсын,\nОның атына даңқ келсін //\n\n[Куплет 2]\n// Тәңірім әрдайым Саған\nРухты әнге салайық\nҰлыңды қиып біз үшін\nМәңгілік өмір сыйладың //"},{"id":721,"title":"Мәңгілік мадақтаймын Сені","text":"[Куплет 1]\nШаттық тыныштық сыйлаған\nмахаббатың төгіледі\nжүректі Рухыңмен емдеп\nТек шыңдықта Сен тұр дедің\nСені ғана мадақтаймын\nШындықта мен тұрғаныма\nМәңгілік жырлап өтемін\nмахаббатыңды\n\n[Припев 1]\n// Мәңгілік мадақтаймын Сені\nМәңгілік мадақтаймын Сені //\n\n[Бридж 1]\nҚуанышқа толып\nШаттанып билейміз\nбүкіл әлем жарық көрсе\nОлар да билер біздермен бірге","copyright":"1994 Куриоус? Мусик УК"},{"id":938,"title":"Мәңгілік Сенімен, бірге болғым келеді","text":"[Куплет 1]\nМәңгілік Сенімен, бірге болғым келеді.\nӨмірлік серігім, жаным Саған сенеді.\n//  Құдайымсың Сен, қуанамын мен.\nҚуат алып әрбір сөзіңнен. //\n\n[Куплет 2]\nҚараңғы түндерде, сырласамын Өзіңмен.\nЖарық нұр төгілер, мейірім шашқан жүзіңнен.\n// Құдайымсың Сен, қуанамын мен,\nҚорғаушымдай қасымда жүрсең. //\n\n[Куплет 3]\nКөктен Сен келерсің, күндердің бір күнінде.\nКүтемін Сені мен, еш үзілмес үмітпен.\n// Құдайымсың Сен, қуанамын мен,\nЕрекше бір ғажап сезіммен. //","songNumber":"184"},{"id":270,"title":"Мәңгіліктің Құдайы","text":"[Припев 1]\n// Мәңгіліктің Құдайы\nСенің алдыңа келіп тұрмын\nСаған табынамын, о Иса! //\n\n[Куплет 1]\nСенің Рухыңды аңсаймын әр күнде\nТек Саған,, жалғыз Саған мен ұмтыламын\nСен құшағыңды маған жайып түрсын, Әке\nМені балам, деп қабыл алдың Ием\n\n[Бридж 1]\nӘке  Әке\nМенің Көктегі Әке"},{"id":19,"title":"Мәриям білдің бе","text":"[Куплет 1]\nМәриям білдің бе, су бетінде Ұлың жүретінін?\nМәриям білдің бе, адамзатты Ұлың құтқарарын?\nБілдің бе, саған ғана өмір сыйлайтынын,\nКөтерген сенің перзентің сені көтерерін?\n\n[Куплет 2]\nМәриям білдің бе, зағип жанды Ұлың емдейтінін?\nМәриям білдің бе, толқынға Ол бұйрық беретінін?\nБілдің бе, періштелер Оған жүгінерін,\nСәбиіңді сүйгеніңде, сүйдің Тәңір жүзін.\nБілдің бе сен?\n\n[Бридж 1]\nСоқыр көріп, керең естіп, өлгендер тірілді.\nМылқау сөйлеп, сал жазылып мадақтар Тәңірді\n\n[Куплет 3]\nМәриям білдің бе, бүкіл әлемнің Иесі Ұлың сенің?\nМәриям білдің бе, бар ұлтқа Ол билік жүргізерін?\nБілдің бе, балапаның Құрбандық боларын,\nАлақаныңдағы Сәбиің жаратқан Құдайың"},{"id":766,"title":"Мәриям, Мәриям","text":"[Куплет 1]\n\"Мәриям, Мәриям\" - деді періште,\n\"Саған Құдай сәби сыйлайды,\nИса деп ата Оны!\""},{"id":40,"title":"Мәсіх адам боп","text":"[Куплет 1]\nМәсіх адам боп дүниеге келді\nКиелі рух әділдігін дәлелдеді\nМәсіх періштелерге көрінді\nХалықтарға Ол жарияланды\n\n[Припев 1]\nЖер жүзінде Оған көбі сенді\nҰлылықпен көкке көтерілді"},{"id":918,"title":"Мәсіхке ән салу қуаныш маған","text":"[Куплет 1]\nМәсіхке ән салу қуаныш маған!\nМәсіхке ән салу қуаныш маған!\n// Құдайды мадақтау қуаныш емес пе?\nҚұдайды мадақтау қуаныш маған! //\n\n[Куплет 2]\nМәсіхке сиыну қуаныш маған\nМәсіхке сиыну қуаныш маған\n// Құдаймен сөйлесу қуаныш емес пе?\nҚұдаймен сөйлесу қуаныш маған. //\n\n[Куплет 3]\nМәсіх жайлы есту қуаныш маған,\nМәсіх жайлы есту қуаныш маған.\n// Құдаймен бір бол қуаныш емес пе?\nМәсіхпен бір болу қуаныш маған. //"},{"id":744,"title":"Мәсіх өліп тірілді","text":"[Куплет 1]\nМәсіх өліп тірілді, Аллилуйя!\nЕскі жылан езілді, Аллилуйя!\nЖеңіп шықты Мәсіғім, Аллилуйя!\nАқталды үмітім, Аллилуйя!\n\n[Припев 1]\nАллилуйя! Аллилуйя!\nАллилуйя! Аллилуйя!","songNumber":"2"},{"id":912,"title":"Мәсіхтегі азаттық","text":"[Куплет 1]\nМәсіхтегі азаттық\nЖанға берді бостандық\nМейірімін білдірген,\nЖалғыз Иса Ием!\nМәсіхтегі азаттық\nЖұбаныш пен тыныштық!\nӨмірдегі береке,\nЖалғыз Иса Ием!\n\n[Припев 1]\nМерейімді өсірді,\nЖаңа болмыс сыйлады,\nМаған берген шаттығы,\nЖан дүниеме симады!\n// Үмітімді жалғады,\nНұрлы күнге алдағы,\nСенімімді оятты махаббаты! //\n\n[Куплет 2]\nМәсіхтегі азаттық,\nРақымдылық, құрбандық!\nӨз ісімен көрсеткен,\nЖалғыз Иса Ием!\nМәсіхтегі азаттық,\nАсып тасқан адалдық!\nӨз өмірін үлгі еткен,\nЖалғыз Иса Ием!"},{"id":266,"title":"Мәсіхтің сөзімен ашылды","text":"[Куплет 1]\nМәсіхтің сөзімен ашылды,\nАлдыңда құтқарылу жолы.\nСаған тыныштықты сыйлайды,\nКел,сені күтеді.\n\n[Припев 1]\nҚуаныш болады аспанда,\nКездесеміз жұмақ алдында.\nСүйіспеншілік сәулесіне,\nБізді Ол бөлейді.\n\n[Куплет 2]\nПерзенттей бол деп шақырады\nМәсіх үні шаттық сыйлайды.\nӘрбір естіген қайталасын,\n«Кел» деп шақырғанын.\n\n[Куплет 3]\nЕнді Ол шақырады сені,\nШынымен сен таста күмәнді.\nКіре көр ашқан есігіне,\nКел, сені күтеді.","songNumber":"183"},{"id":522,"title":"Мәсіхтің сүйіспеншілігі","text":"[Куплет 1]\nМәсіхтің сүйіспеншілігі,\nКеремет өзендей, шексіз ұлы,\nТолқынындай болады теңіздің,\nТаза, терең, байтақ және тұнық.\n\n[Припев 1]\nЕгер Мәсіх сезімінен,\nЖұрдай болсақ үмітсізбіз.\nҚалар едік сүйе алмай,\nҚұтқарушыдай адамды біз.\n\n[Куплет 2]\nКелсеңші тез, тезірек келсеңші,\nОның күтіп тұрғанын білсеңші.\nЕсігіңді қағып тұр, ашсаңшы,\nӨзіңе тегін қабылдасаңшы.\n\n[Куплет 3]\nМәсіхсіз бәрі де қирар еді,\nДәл сол сәтте тыныс тоқтар еді.\nМәсіхті танып білгенде егер,\nӨмірің мүлде өзгерер еді.\n\n[Куплет 4]\nСені сүйді, мені де Ол сүйді,\nӨзіне сенбегенді де сүйді.\nКелші Оған, Ол әлі күтеді,\nМәсіхсіз өмір бекер өтеді.","songNumber":"27","alternateTitle":"Егер Мәсіх сезімінен"},{"id":241,"title":"Мәсіхтің сүйіспеншілігі жүрегіңде","text":"[Куплет 1]\nМәсіхтің сүйіспеншілігі,\nОрнасын жүрегіңде.\nБауырым шын көңілден,\nСаған деген тілегім де.\n\n[Припев 1]\nСені күтсе ауыр күндер,\nҚайғы-мұңға салынған.\nҚайратты бол, Иса бізбен,\nШығады Ол сенің алдыңнан.\n\n[Куплет 2]\nАспанда Құтқарушымыздың,\nОрны бар дайындаған.\nБар қайғың аяқталар,\nЖер бетінде уайымдаған.","songNumber":"120","alternateTitle":"Сені күтсе ауыр күндер"},{"id":371,"title":"Мейрамның құрбан қанымен","text":"[Куплет 1]\nМейрамның құрбан қанымен,\nӨміріме Есік ашылды.\nСол қараңғы билікте еш күші жоқ.\nҚұнды қаны құдіретті.\n\n[Куплет 2]\nЖаулар мені айыптаса да,\nМен әділ боп тұра алам.\nЕшбірде айыпталу жоқ,\nМен билігіндемін Қанның\n\n[Куплет 3]\nМен билігіндемін Қанның,\nСол Қанымен ақталдым мен\nМейірімі Құдайдың қасиетті қылды мені\nМен билігіндемін Қанның.\nЖаулар қандай шабуыл жасаса да,\nШайқалып құлап қалмаймын.\nМен билігіндемін Қанның."},{"id":46,"title":"Мейіріміңе толы бар әлем","text":"[Куплет 1]\nМейіріміңе толы бар әлем,\nМейіріміңді күнде мен көрем.\nМейірімің соттан да үстем.\nБиік жоғары барлық күштен\n\n[Припев 1]\nҚұнымды өтеп, ақтадың,\nАзат еттің, сақтадың.\nҚұнымды өтеп, ақтадың,\nКүнәдан Сен сақтадың.\n/// Алғыс Саған Иса ///","songNumber":"136"},{"id":903,"title":"Мен адасып жүргенімде Өзіңсіз","text":"[Куплет 1]\nМен адасып жүргенімде Өзіңсіз,\nӨтіп жатты бар өмірім көңілсіз.\nЕң болмаса бір сәт Сені ойламай\nОсы кезге дейін жүрдім сенімсіз.\n\n[Припев 1]\n// Кешірші мені Құдайым,\nӨтініп Сенен сұраймын.\nӨмірімнің өзгергенін қалаймын. //\n\n[Куплет 2]\nТүсінбедім бұл өмірдің мән-жайын,\nНеге келдім және қандай жағдайым?\nСені қалай ғана білмей жүрдім мен,\nСоқырлықпен сор болды ғой маңдайым.\n\n[Куплет 3]\nӨмірімде еш адамды сүймедім,\nҚиналғанға қол ұшымды бермедім.\nТек өзімді ойлауменен жүріппін,\nҚалай ғана қатты болған жүрегім?!","songNumber":"107","alternateTitle":"Кешірші мені Құдайым"},{"id":994,"title":"Мен бақаттымын, көңілдімін","text":"[Куплет 1]\nМен бақыттымын, көңілдімін.\nДүйсенбі, сейсенбі, сәрсенбі,\nБейсенбі, жұма, сенбі,\nЖексенбіде бақыттымын, көңілдімін!\nИса менің жақсы досым!"},{"id":660,"title":"Менде бар бір тілек","text":"[Куплет 1]\nМенде бар бір тілек -\nДәріптеу Сені.\nЖүрегіммен, Тәңір, даңқтайм Сені.\nМендегі бардың бәрі\nМадақтайт Сені.\nМахаббатым, Тәңір, бір Өзіңе.\n\n[Припев 1]\nЖүрегімді берем, жаныммен бірге,\nТек Сен - өмірімсің.\nӘр қадамым менің Сенімен болсын,\nЕркің Сенің орындалсын.","songNumber":"137","copyright":"1995 Хиллсонг Публишинг"},{"id":757,"title":"Менде екі көз бар","text":"[Куплет 1]\nМенде екі көз бар, екі құлақ, бір мұрын.\nМенде екі қол да бар, екі аяқ та бар.\nМенде ауыз да юар, мен күліп айтамы:\n\"Жаратқан Ием мені сүйеді!\""},{"id":714,"title":"Мен Иемнің ұлылығын көрем","text":"[Куплет 1]\nМен Иемнің ұлылығын көрем,\nБізбен бірге болатын Ие\nЖарық ұлылық барлық аспанда\nСол мадақ жерді толтырды.\n\n[Куплет 2]\nМен Иемнің ұлылығын көрем\nМадақтаулы менің Ием.\nИемнің жүзі барлық әлемге\nҚұдіретті қолын көтерді\n\n[Куплет 3]\nИемнің ұлылығы осы жерде\nБіз тұрамыз Иемізбен бірге\nМадақтап біз алға ұмтыламыз\nБарлық халық Иені көргенше\n\n[Куплет 4]\nКөктегі Әке бізді жаңарта гөрші\nХалықтар арасында қызмет ету үшін\nБар халықтар тұрып, мадақ ән салып,\nҰлылығын Иеміздің көрсін."},{"id":426,"title":"Мен қозысы Исаның","text":"[Куплет 1]\nМен қозысы Исаның,\nШаттанады жүрегім,\nҚамқор болды жол сілтеп,\nОрындалды тілегім.\nЖақсы көріп күн сайын,\nСүйетінін білемін.\n\n[Куплет 2]\nҮйден шалғай жүрсем де,\nСүйенішім, тірегім,\nАшықсам нәр беретін,\nЖайлауында жүремін.\nШөлдесем Ол апарар,\nТұнық суға үнемі.\n\n[Куплет 3]\nҚозысымын Исаның,\nМен бақытты баламын.\nЖердегі өмір біткенде,\nКөктегі үйіме барамын.\nҚұшағында Әкенің,\nАлаңсыз демаламын.","songNumber":"281"},{"id":556,"title":"Мен қозысы Исаның","text":"[Куплет 1]\nМен қозысы Исаның,\nӘр кезде жүрегім шат!\nҚамқор болып жол көрсетіп,\nТілегімді орындайды,\nЖақсы көріп күн сайын,\nатымды Ол біледі!\n\n[Куплет 2]\nЕгер шалғай жүрсем де,\nСүйенішім тілегім,\nАш болсам мен азық беріп,\nЖайлы өріске жетелейді,\nШөлдесем Ол апарар,\nТұнып тұрларған суға!"},{"id":915,"title":"Мен Мәсіхте қуанам","text":"[Куплет 1]\nМен Мәсіхте қуанам,\nОл - өмір маған!\nМен Мәсіхте қуанам,\nОл - өмір маған!\nМен Мәсіхте қуанам,\nОл - өмір маған!\nТәңірім менің бақыт бұлағым!\nТәңірім менің бақыт бұлағым!\n\n[Куплет 2]\n/// Ол өмір суын берді\nЕнді тірімін ///\n// Тәңірім менің бақыт бұлағым! //\n\n[Куплет 3]\n/// Бақытты қаласың сен,\nМәсіхті ізде. ///\n// Тәңірім менің бақыт бұлағым! //\n\n[Куплет 4]\n/// Бақытты қаласаң,\nМәсіх ізімен жүр. ///\n// Тәңірім менің бақыт бұлағым! //"},{"id":739,"title":"Мен неге Сені іздеймін","text":"[Куплет 1]\nМен неге Сені іздеймін,\nСен менің жанымдасың.\nСенсіз мен түсінбеймін,\nӨмірдің мағынасын.\n// Ешқашан көне алмаспын,\nТағдырдың салғанына,\nАйбынды Құтқарушым,\nАйбынды Құтқарушым, Сен тұрғанда. //\n\n[Куплет 2]\nӘкелік күнімді аңсап,\nОйланып, толғанамын,\nКетсемде алыс - ұзақ,\nӨзіңе ораламын.\n// Жетсемде талай-талай,\nӨмірдің шыңдарына\nСен менің арманым боп,\nСен менің арманым боп, қала берші. //\n\n[Куплет 3]\nКөзімді жұмған кезде,\nКөремін нұр бейнеңді,\nКеудемді күй кернеген\nҒажайып бір сезімді\n// Сен менің бақытымсың,\nАрайлы ақ таңымсың,\nМәңгілік айтып өтер,\nМәңгілік айтып өтер, ән жырымсың. //","songNumber":"72"},{"id":851,"title":"Мен Саған өлең айтамын","text":"[Куплет 1]\nМен Саған өлең айтамын,\nТәңір Саған табынамын.\nСаған мәңгі ризамын мен.\nҚұтқарғаныңа қуанамын.\n\n[Припев 1]\nКөктен жерге келдің\nШын өмір беру үшін.\nКиелі қаныңды төктің,\nҚұнымды төледің.\nӨлімнен Сен тірілдің,\nКөкке көтерілдің.\nАтыңды мен көтерем.","songNumber":"138","copyright":"1989 Мараната Праисе, Инк."},{"id":617,"title":"Мен сеземін күйзеліс көз жасын","text":"[Куплет 1]\nМен сеземін күйзеліс көз жасын,\nКездесер күн мен ауыр қоштасуды.\nҮміт пен қайғының араласқан\nДәмін көрдім ыстық тостағанның.\n\n[Припев 1]\nСен уайымдама, көңілсіз болма\nНеден қорқамыз, Құдай қасымызда\nСен уайымдама,көңілсіз болма\nҚұдай қасымызда.\n\n[Куплет 2]\nӨткен күндер үшін қайғырмаймын,\nКөріп уақыттың өте аз қалғанын.\nҚабылдадым осы құрбандықты,\nТөгілген мен үшін күнәсіз қанды.\n\n[Куплет 3]\nБостандық іздедім бұл өмірде,\nТұрмыстық қайғы мен қасіреттен.\nБар өмірім аз ғана шумақтай\nОңашада дұға еткен кезде.","songNumber":"125"},{"id":194,"title":"Мен Сендей болғым келеді О, Иса","text":"[Куплет 1]\nМен Сендей болғым келеді О, Иса\nМен Сендей болғым келеді.\nӨмірім Сенің қолыңда\nМен Сендей болғым келеді.\n\n[Куплет 2]\nМен Сендей сүйгім келеді. О, Иса\nМен Сендей сүйгім келеді.\nЖүрегім Сенің қолыңда\nМен Сеендей сүйгім келеді."},{"id":162,"title":"Мен Сенімен, Сен менімен","text":"[Куплет 1]\nМен Сенімен, Сен менімен\nӨмір бойы біргеміз біз\nЖүрегімді Сенің сөзің\nҚуанышқа толтырады.\n// Өмір бойы біргеміз біз //\n// Қуанышқа толтырады //\n\n[Куплет 2]\nКөз жастарымды Сен сүртесің\nҚорқыныш келгенде Сен жұбаттың Ием\nМенімен боласың О Иса....\n// Көз жасымды Сен сүртесің,\nҚорқынышты елемеймін, //\n\n[Бридж 1]\nТабынамыз Рәббім Исаға өмір бойы\nТабынамыз Рәббім Исаға мәңгілікке\nТабынамыз Рәббім Исаға Құдіретті Ием."},{"id":67,"title":"Мен Сенің алдыңа кеп жылап тұрмын","text":"[Куплет 1]\nМен Сенің алдыңа кеп жылап тұрмын,\nКешірім күнәм үшін сұрап тұрмын.\nБілемін мейіріміңнің мол екенін,\nСенемін, Сен мұңыма құлақ түрдің.\n\n[Припев 1]\nСен ғажайып нұрландың,\nЖер әлемге таралдың,\nҚұтқарушым Өзіңсің ғой,\nСаған сеніп оралдым.\nМен Өзіңнен қуат алдым,\nМейіріміңмен жұбата алдың.\nЖан дүниеме сая болып,\nСенімімді ояттың.\n\n[Куплет 2]\nӨзіңнен зор қуаныш алып тұрмын,\nМәңгілік өмір жайлы сыр ұқтырдың.\nМұңданып жеке қалған сәттерімде,\nЖақсылықтың нышанын сезіп тұрмын.\n\n[Куплет 3]\nБілемін, Сен мен үшін жан қиғансың,\nКүнәмнан тазартуды ойлағансың.\nСен менің өмірдегі күнәм үшін,\nӨзіңді ағашта айқыш қинағансың.\n\n[Куплет 4]\nМені енді Құдай Әке, қабыл алғын,\nКелетін сәтіңді мен сағынамын.\nЖақсы үлгімен сөздеріңді уағыздап,\nАрасынан ұлдарыңның табылармын.","songNumber":"71"},{"id":129,"title":"Мен Сені сүйем","text":"[Куплет 1]\nМен Сені сүйем Тәңірім Иса, Құтқарушым,\nҮміт артамын Тәңірім Саған Құтқарушым.\nКүнәміз үшін айқышқа бардың, Құтқарушым,\nБақытқа орай үшінші күні Сен тірілдің.\n\n[Припев 1]\n/// Мадақтаймын, мадақтаймын\nМадақтаймын. ///\n\n[Куплет 2]\nМен Саған сенем, о, Әкем Құтқарушым,\nСенсіз өмірде не істер едім Құтқарушым?\nӘдемісің Сен, бәрінен биік Тәңірімсің,\nО,Иса, Иса жалғыз Сен менің Құтқарушым."},{"id":352,"title":"Мен Сені сүйем","text":"[Куплет 1]\nМен Сені сүйем,\nСаған сиынам.\nСені мадақтаймын,\nШаттанамын.\nПатша, әнімді Саған арнаймын,\nТәңір Патша.","songNumber":"139","copyright":"1978, 1980 Хоусе оф Меркы Мусик"},{"id":62,"title":"Мен Сені сүйемін, о, Иса","text":"[Куплет 1]\nМен Сені сүйемін, о, Иса.\nСезімім белгілі Саған.\nКөзіме мейіріммен қарасаң.\nТулайды жаным Саған ұмтылған.\n\n[Припев 1]\nМенің жүрегімді.\nОй-санамды, жан-дүниемді.\nБаурап алдың өмірімді.\nҚұштармын, құштармын Саған Иса.\n\n[Куплет 2]\nСенімен мәңгі бірге боламын.\nТек осы менің қалауым.\nӨршиді жүректегі алауым.\nҚашан-ау орындалар арманым.\n//// Құштармын Саған, жүрекпен жанған Иса ////","songNumber":"124"},{"id":788,"title":"Мен сиынушымын","text":"[Куплет 1]\nМен құдайға сиынатын\nШын сиынушымын\nМен қай жерде болсамда\nҚұдайға сиынамын\n\n[Припев 1]\nРухым құдайдың рақымына қарай\nЖүрегім толық құдайға қарай\nҚазір осында құдайға сиынамын"},{"id":517,"title":"Мен тоқтап, біраз көз салсам","text":"[Куплет 1]\nМен тоқтап, біраз көз салсам,\nӨмірдің өткен жолына,\n//  Әр күнә келіп ойыма,\nБатады менің жаныма.  //\n\n[Куплет 2]\nМен қылған қанша күнә бар,\nЕстісе адам ұялар,\n//  Шындықты айтсам Құдайға,\nКүнәдан мені құтқарар.  //\n\n[Куплет 3]\nКүнәмді алып мойныма,\nБас иіп Тәңір алдында,\n//  Өтініп, тәубе қылайын,\nАпаршы өмір жолына.  //\n\n[Куплет 4]\nШындықты көрдім жолыңнан,\nӨзгерткен менің ойымды,\n//  Құтқарып алшы Тәңірім,\nҰсынып, созам қолымды.  //\n\n[Куплет 5]\nӨзімді Саған арнайын,\nЖүректе Сені сақтайын.\n//  Дүниеге айтып шындықты,\nМәңгілік Сені даңқтайын.  //","songNumber":"140"},{"id":710,"title":"Мен үшін өлгеніңе","text":"[Куплет 1]\nМен үшін өлгеніңе,\nҚаныңды төккеніңе,\nҚайта тірілгеніңе,\nӨлімді жеңгеніңе.\n\n[Припев 1]\nРахмет Саған Тәңір Иса!\nРахмет Саған Тәңір Иса!\nРахмет Саған Тәңір Иса!\nЖүрегім Саған риза,\nЖүрегім Саған риза!","songNumber":"109"},{"id":789,"title":"Мен үшін Тәңір істеді","text":"[Куплет 1]\nӘлсіз айтсын: «күштімін!»\nЖарлы айтсын: «Мен баймын!»\nЗағип айтсын: «Мен көрем!»\nІске асырды Тәңірім.\n\n[Припев 1]\nОсанна, Осанна\nЖанын қиған Тоқтыға!\nОсанна, Осанна\nИса өліп, тірілді.\n\n[Куплет 2]\nЖүзіп өттім мұхиттан,\nАрылдым күнәлардан.\nМахаббат мейіріне\nБөледі Құтқарушым.\n\n[Куплет 3]\nТерең судан шығарды,\nСақтаушы Тәңір қолы.\nҚұтқару әнін салам\nАзат еткен Исаға.","songNumber":"141"},{"id":411,"title":"Мені кім жаратты?","text":"[Куплет 1]\nМені кім жаратты?\nОл Құдай!\nАра менен көбелекті?\nОл Құдай!\nКім бәрін де жаратты?\nСен айтшы:\n\"Мейірімді Құдайымыз жаратты!\""},{"id":48,"title":"Мені қолдайсың Құдайым","text":"[Куплет 1]\nМені қолдайсың Құдайым\nҚорғайсың мені әрдайым\nҚұдіретті Әкем.\nМен құладым, Сен көтердің\nШөлдегенімде су бердің,\nЖаратушы Ием.\n\n[Припев 1]\n// Иса Құтқарушым,\nЛайықсың Өзіңнің атыңа.\nИса Жаратушым,\nКерексің Сен менің жаныма. //\n\n[Куплет 2]\nӨмірімізді өзгерттің,\nБіз үшін өліп тірілдің,\nҚұтқарушы Ием.\nКүнәдан бізді босаттың,\nМәңгілік өмір сыйладың,\nМенің Ұлы Әкем.\n\n[Куплет 3]\nҚай жерде болсамдағы мен,\nМенің жүрегімдесің Сен,\nЖұбатушы Әкем.\nРухыңды енгіз бойыма,\nЖарық бол енді жолыма,\nЖетелеші Ием.","songNumber":"30","copyright":"1991 Шеферд'с Хеарт Мусик, Инк."},{"id":105,"title":"Менің аяулы арманым","text":"[Куплет 1]\nМенің аяулы арманым,\nЕдемнің аспанын көру!\nМәңгі қалуға сол жақта,\nҒажайып отанында Адамның!\n\n[Припев 1]\nЕдем Аспаны, сен менің әнім!\nЕдем Аспаны, бүгінгі арманым!\nБәрінен жарық, бәрінен нәзік,\nӨмірімде әрқашан!\n\n[Куплет 2]\nМенің қалаулы арманым,\nИсаның аяғына жығылу,\nСонда күш алсам әрқашан,\nӘкемнің үйіне оралсам!\n\n[Куплет 3]\nТыңда мені Құтқарушым!\nҚайтаршы Едем аспанын,\nМәңгі болғым келеді Сенімен,\nКүнәсыз, рухани өмірмен!\n\n[Припев 2]\nЕдем аспаны, сен менің әнім!\nЕдем аспаны, бүгінгі арманым!\nБәрінен жарық, бәрінен нәзік,\nӨмірімде әрқашан!","songNumber":"146","alternateTitle":"Едем Аспаны"},{"id":4,"title":"Менің бақытым Сен - Иса!","text":"[Куплет 1]\nСенен таптым, бақытымды,\nБөлендім нұр-шуаққа!\nБесіктегі сәбидей, талпынам, Саған - Иса!\n\n[Припев 1]\nБақыт берген бір - Өзің!\nӨмір жолы бір - Өзің!\nӨмір жолы бір - Өзің!\nСаған ынтық жүрегім, менің бақытым Сен - Иса!\nМенің бақытым Сен - Иса!\n\n[Куплет 2]\nЖалғыз Сен-деп, соғады,\nАдамзаттың жүрегі,\nМәңгі өмір жолының, бір Өзіңсің - тірегі!"},{"id":195,"title":"Менің жан-дүнием","text":"[Куплет 1]\nМенің жан-дүнием\nСені мадақтаса,\nСонда жүрегіммен қуанамын.\nТәңір жан-дүнием\nӘн салады Саған.\nМахаббатым менің бір Өзіңде.\n\n[Припев 1]\nЖүрегімді Саған берем,\nТек Сені сүйем.\nӨмірім Сенімен.\nҚуаныш пен қайғыруда\nБолшы менімен,\nСенің киелі еркің болсын!","songNumber":"97"},{"id":228,"title":"Менің жүрегім","text":"[Куплет 1]\nМенің жүрегім, аңсап жылағанда,\nБар қайғы қасіретті, Саған бергім келеді.\nТәңірім тек Сені, жүрегім іздейді,\nҚысылып шығатын есік таппай дүрсілдейді!\n\n[Припев 1]\nТәңірім,осы кезде Сен ғана,\nМаған жақынсың, Ием!\nМені, құшағыңа тартып, қысасың Сен!\nӨзіңе, жақындаттың мені,\nЖұбатасың Сен, Өз қолыңда, мені сәбидей!\n\n[Куплет 2]\nОсыны түсінбей, Сенен алыстап,\nҚұшағыңнан, сытылып, шыққым келеді!\nАлайда Тәңірім, осы уақытта,\nСенің, Рухыңа толып, рахаттамын мен!","alternateTitle":"Тәңірім осы кезде Сен ғана"},{"id":281,"title":"Менің жүрегімде Иса сөйлеп тұрсын","text":"[Куплет 1]\nМенің жүрегімде Иса сөйлеп тұрсын.\nОйымда, сезімімде Ол жасасын.\n// Бұл жалғанда мені Иса іздеп тапқанда,\nСонда ғана, сонда ғана жүрек тынышталмақ. //\n\n[Куплет 2]\nЖеңісті маған Иса Өзі алып берді.\nҰлы күшін жүрегіме Ол табыс етті.\n// Ұлы күшін Иса маған сыйлағанда,\nЖүрегіме тыныштық майын төккізді! //\n\n[Куплет 3]\nЖаным күресіп, әлсізденіп мен тұрсам да,\nИса Өзі маған Рухын жіберді.\n// Көңілімнің баспанасын мен сонда таптым,\nЖүрегіме шаттық, қайрат Ол алып берді! //","songNumber":"129"},{"id":951,"title":"Менің жүрегім қазір қуанышты","text":"[Куплет 1]\nМенің жүрегім қазір қуанышты,\nҚуанышты, қуанышты!\nМенің жүрегім қәзір қуанышты,\nҚуанышты, жүрегім!\n\n[Куплет 2]\nИсаның махаббаты жүрегімде!\nЖүрегімде, жүрегімде!\nИсаның махаббаты жүрегімде!\nЖүрегімде, Иса!\n\n[Куплет 3]\nМенің жүрегім қазір қуанышты,\nҚуанышты, қуанышты!\nИсаның махаббаты жүрегімде,\nЖүрегімде Иса!","songNumber":"282","copyright":"Публик Домаин"},{"id":508,"title":"Менің Ием болған","text":"[Куплет 1]\nМенің Ием болған бәрінен бас тартып,\nТәңір Иемнің алдына барып,\nМен жақсы көрген барлық нәрсені қойып,\nТек Тәңірді сүйем.\n\n[Припев 1]\nМахаббаты сұрапыл дауылда да\nТерең теңіздей мені тыныштандырады\nМахаббаты жанымның жартасы\nСол махаббатта тұрам."},{"id":1033,"title":"Менің панамсың Иса","text":"[Куплет 1]\nМенің панамсың Иса, сүйенемін.\nМенің панамсың Иса, сүйенемін.\nМенің жолымда қатты дауыл соғып тұрса да,\nМенің панамсың Иса, сүйенемін.\n\n[Куплет 2]\nИем, мен Сені мәңгі сүйемін.\nИем, мен Сені мәңгі сүйемін.\nСаған деген махаббатым ештеңеден айыра алмайды.\nИем, мен Сені мәңгі сүйемін.\n\n[Припев 1]\nАбба Әке, мені сондай сүйесің,\nМенде барымды Саған беремін.\nАбба Әке, мен алдыңда тұрмын.\nМені қолданшы Сенің даңқың үшін.\nҚауымың үшін"},{"id":197,"title":"Менің Ұлы Ұстазым","text":"[Куплет 1]\nМенің Ұлы Ұстазым.\nМенің Ұлы Бағушым.\nМенің Ұлы Тәңірім.\nМенің жанымда.\n\n[Куплет 2]\nСөзін берді қолыма.\nЖарық берді жолыма.\nРухын берді бойыма.\nЕрдім соңына.\n\n[Припев 1]\n// Құдай сүйген халық\nҚауымға келіңдер.\nШындық жолдың Иесін\nТанып біліңдер.\nБәріңде келіңдер\nИсаға сеніңдер.\nБіздің Иса киелі.\nҰлы Тәлімгер. //","songNumber":"100"},{"id":146,"title":"Менің халқым тыңдашы сөзімді","text":"[Куплет 1]\nМенің халқымды тыңдашы сөзімді,\nМенің елім тыңдашы әнімді.\nКөп жылдар жүрдің Құдайсыз,\nКөп жылдар қиналдың Құдайсыз.\nМіне бүгін келіп тұр Құдайың.\n\n[Куплет 2]\nЖердің Жаратушысы Алла Тағалла\nӨз Ұлын жіберді Ол құрбандыққа.\nАдамдарды азаптан,\nАдамдарды тозақтан\nҚұтқару үшін келді Құдай Ұлы Иса Мәсіх.\n\n[Куплет 3]\nМенің халқым Иса келді Саған,\nЖүрегіңді халқым аш Сен Оған.\nСонда жерің көркейеді,\nҚайғы-қасырет кетеді.\nҚуаныш пен бақытқа кеңелесің сен халқым.","songNumber":"106"},{"id":28,"title":"Мөлдір аққан судай өмір бердің Сен","text":"[Куплет 1]\nМөлдір аққан судай өмір бердің Сен.\nҚуаныш пен күлкі сый ғып бердің Сен.\n// Алғыс Саған Иса, Тәңірім Ием.\nҚұтқарушым Иса жан-шуағым сен. //\n\n[Куплет 2]\nНұр мен махаббатқа бөлендірдің Сен.\nКүш пенен қуатты сый ғып бердің Сен.\n// Кәусар бұлағымсың Иса, Исажан.\nЖанған шырағымсың Иса, Исажан. //\n\n[Куплет 3]\nЖүрегімді жандыр махаббатыңмен.\nШөлімді Сен қандыр Киелі Сөзіңмен.\n// Тәңір, Тәңір Иса, берші рақымнан.\nКелші, келші Иса төкші Рухыңнан. //","songNumber":"96"},{"id":30,"title":"Мұңға батсам жүрегім мұздап","text":"[Куплет 1]\nМұңға батсам жүрегім мұздап,\nОл қасымда бір бола ма?\nКүйбің тірлігі бастан асса да,\nҚұшақ жайып қарсы ала ма?\n\n[Припев 1]\n// Мәсіх бізбен мәңгі бірге!\nОл мықты, берік ірге!. //\n\n[Куплет 2]\nАлдым соқпақ артым болса,\nОл қасымда бір бола ма?\nСөніп жарық күн, қараңғы болса,\nНұр бере ме кең далама?\n\n[Куплет 3]\nСапар шексем қайтып келмеске,\nОл қасымда бір бола ма?\nБеріп сый-тарту, құрмет көрсетіп,\nМәңгі досым болып қала ма?","songNumber":"133"},{"id":1023,"title":"Мұхит","text":"[Куплет 1]\nСу бетімен кел деп шақырдың\nКім жүрген су үстімен\nСонда жүзіңді мен көремін\nСу үстінде сенім артсам\n\n[Припев 1]\nАтыңды мен шақырамын\nкөзімді тек Саған қадап\nСу буырқанса\nЖаным табар тыным Сенен\nМен Сендікпін, Сен мендіксің\n\n[Куплет 2]\nРақымың мол тасқындап судай\nӨз қолыңмен жетелейсің\nҮрей басса тұла бойымды\nТабыласың Сен жанымнан\n\n[Припев 2]\nКиелі Рух сенімім менің шектелмес\nЖүргізсең кешіп су бетін\nШақырсаң мен барамын\nМені аяқ баспаған жерге апаршы\nСенімім нығайып өссін\nҚұтқарушымның алдында","copyright":"Хиллсонг Унитед"},{"id":620,"title":"Мұхиттар","text":"[Куплет 1]\nСен мені суға шақырасың\nӨте алмаймын сен болмасаң\nСенімім мұхитта орнайды\nСонда көремін, Ием, сені\n\n[Припев 1]\nШақырам сені атыңмен\nТолқыннан көзімді көтерем\nДауыл болса, Менің жаным тыныш табады\nМен сендемін, Сен мендесің\n\n[Куплет 2]\nТерең суда мейірімділігің\nСенің қолың жетелейді\nҚорқыныш қоршап сәтсіздік пе\nТастамадың, тастамайсың\n\n[Бридж 1]\nРухына Құдайдың шексіз мен сенемін\nСу үстімен жетелеші, мені шақырған жеріңе\nМен жеңе алмайтын тереңдікке жеткіз\nСенімім менің қуатты қасымда","copyright":"Хиллсонг Унитед"},{"id":717,"title":"Мұхиттар","text":"[Куплет 1]\nҮндедің мені тереңдікке -\nАяқ баспаған ұлы ғайып.\nСол құпиядан таптым Сені,\nТұңғиықта сенімім берік.\n\n[Припев 1]\nАтыңмен Сені шақырам\nТолқындардан көз аударам\nСаған, Құдай, жаным демалсын қолыңда\nМен Сенікімін, меніңсің Сен.\n\n[Куплет 2]\nМейріміңе тереңдік толы,\nЖөн сілтейді\nМаңғаз қолың.\nҚорқыныш анталасқан жерде,\nТірегім Сенсің әрдайым.\n\n[Бридж 1]\nСенімім шексіз жерге, Рух жетелеші,\nСу бетінде серуендетші,\nҚайда мені шақырсаң да,\nАяғым баспайтындай тереңге алшы,\nБекейеді сенім әрі\nҚұтқарушымның көзінше.","copyright":"Хиллсонг Унитед"},{"id":279,"title":"Мына өмір соғып өткен жел болса","text":"[Куплет 1]\nМына өмір соғып өткен жел болса,\nЖел ұшырған, қураған бір шөп болдым,\nҚулық, сұмдық, жамандыққа бар болсам,\nІзгілік пен жақсылыққа жоқ болдым.\n\n[Куплет 2]\nМына өмір ашырқанған аң болса,\nАл мен одан қаша алмай, жем болдым.\nАдамдарды жүрегімде жек көріп,\nКісі өлтірген жауыздармен тең болдым.\n\n[Куплет 3]\nМына өмір патша болса, би болса,\nБұйрығынан шыға алмайтын құл болдым.\nКісі өлтіріп, қиянат істемесем де,\nЕлді алдаған, қуыс кеуде қу болдым.\n\n[Куплет 4]\nӨмірдің шын мағынасын білмедім,\nІшіп-жеу мен ойын-сауық іздедім.\n«Өмір бізге бір-ақ рет берілген»,\nОсы-ақ болды өмір жайлы білгенім.\n\n[Куплет 5]\nЕнді бүгін бұрынғыдан басқа күн,\nЖүрегімде шырқалады асқақ үн.\nЕскі өмірмен біржолата қоштасып,\nИсаменен жаңа өмір бастадым.\n\n[Куплет 6]\nМенде бүгін, бұрынғыдан басқа күн,\nБар күнәмді еңсе басқан тастадым.\nКүнәларым қара бұлттай төнуші еді,\nЕнді бүгін шайдай ашық аспаным.\n\n[Куплет 7]\nМенде бүгін өзгеше күн, басқа күн,\nТауып алдым мәңгі өмірдің бастауын.\nКеше ғана танымастай басқа едім,\nЕнді бүгін, одан мүлде басқамын.\n\n[Куплет 8]\nЕнді білдім мағынасын өмірдің,\nЖүрек толды сөздерімен Тәңірдің.\nЖамандықтан жан-дүнием тазарып,\nЖиіркенішті кірі кетті көңілдің.\n\n[Куплет 9]\nСоқыр едім, Иса ашты көзімді,\nСаңырау едім, сауыққаным сезілді.\nСөз жетпейді-ау суреттеуге тілменен,\nЖүректегі сұлу ғажап сезімді.\n\n[Куплет 10]\nОсы Исаға сен де келсең болады,\nЖүрегің мол қуанышқа толады.\nКүнәңді айтып, тәубе қылсаң, басыңа,\nЖаратқанның ақ батасы қонады.\n\n[Куплет 11]\nМені сонша сүйетіндей кім едім?\nТозақ отқа кетейін деп тұр едім.\nИса берді біржолата бостандық,\nҚұмарымның құлдығында жүр едім.\n\n[Куплет 12]\nИсаға кел, ашылады көздерің,\nЕре бермей айтқанына өзгенің,\nМен сияқты сен де аласың бостандық,\nЕгер Оның қабылдасаң сөздерін.","songNumber":"130"},{"id":523,"title":"Міне бүгін келді уақыт Саған","text":"[Куплет 1]\nМіне бүгін келді уақыт Саған\nАлдың ауыр жаза.\nБолсаңдағы мейірімге толған\nКүнәлардан таза.\n\n[Припев 1]\n// Жас келеді мөлдіреп жанарыма,\nҚалай ғана шыдадың азабына?\nАйқыш ағаш, қағылған темір шеге,\nЖазықсыз қолдарыңа! //\n\n[Куплет 2]\nШақырдың Сен барлық адамзатты\nҒажайып өмірге.\nӨз қолыңмен салып берген\nЖолың жұмақтың төріне!\n\n[Припев 2]\n// Мәңгіліктің жетелеп есігіне\nҚұтқарылу сыйладың бар әлемге.\nАйтшы, неге бардың Сен\nӨз еркіңмен осы бір өлімге?!/ //\n\n[Куплет 3]\nБіздер үшін бұл дүниеге келіп\nӨлімнен тірілдің,\nЖер бетіне Рухыңды жіберіп\nБиіктен көріндің!\n\n[Припев 3]\n// Сенемін мен Сен менің қасымдасың.\nСаған деген сенімім таусылмасын.\nКүтемін мен Өзіңді Иса Ием\nАйтқаның орындалсын!/ //","songNumber":"139"},{"id":740,"title":"Міне қандай көп туыс","text":"[Куплет 1]\nМіне қандай көп туыс,\nКерек емес басқасы.\nЫстық сәлем жолдаймыз\nМәсіхшілер отбасы.\nОлар бізге тым ыстық\nМәсіхтегі бауырлар.\nТілейміз біз тыныштық,\nАмансың ба, бар достар?\n\n[Припев 1]\nМадақ достыққа киелі,\nЖүрекке жылы тиеді.\nАғайындарын көргенде\nШешілді сырдың тиегі.\n\n[Куплет 2]\nСарбаздары Мәсіхтің\nКелдіңдер ме, бауырлар?\nЖеткен Ізгі хабарың\nАман ба ел, ауылдар?\nӘпкелердің жүзінен\nМейірімділік төгілген.\nКиелі достығымыз\nОл Мәсіхтен берілген.","songNumber":"112"},{"id":996,"title":"Наурызда жаңа жыл бастаймыз","text":"[Куплет 1]\nНаурызда, наурызда жаңа жыл бастаймыз,\nНаурызда, наурызда қуана тойлаймыз."},{"id":868,"title":"Не болса да өміріңде мадақта Құдайды","text":"[Куплет 1]\nНе болса да өміріңде мадақта Құдайды,\nБәрін біз үшін жақсылыққа Ол аударады.\n// Ей, мейірімді, кешірімді табар ма едің басқаны,\nҚанатының астына Ол алды бізді, мәңгіге сүйді. //\n\n[Припев 1]\n// Тек Құдайдың қанаты сиғызды бәрімізді\nТек Құдайдың жүрегі кешірді күнәмізді.\nТек Құдайдың құшағы әрқашан да күтеді,\nТаңдағаным, мақтағаным, шақырғаным - деп қашан келеді. //\n\n[Куплет 2]\nНе болса да өміріңде алғыс айт Құдайға,\nАлғысың жолыңды ашады әркез болашаққа.\n// Ей, рухын берді сөзін берді алды бізді құшағына,\nАлғыс айтам, мадақ айтам Құдайыма әрқашан да. //\n\n[Куплет 3]\nНе болса да риза болсын жүрегің Иеңе,\nҚуанайық біз жеген тірі Адамға, Сөзіне.\nЕй, табынайық бағынайық күнәмізді кешіргенге,\nИелікке бәрін беріп жүрегіне кіргізгенге"},{"id":449,"title":"Не ектің сен, не ектің сен?","text":"[Куплет 1]\nНе ектің сен, не ектің сен?\nЖол бойына не ектің сен?\nҚұстар ұшып келеді,\nБидай дәнін әкетеді,\nҚұр қол қаласың сен сонда.\n\n[Куплет 2]\nНе ектің сен, не ектің сен?\nТасты жерге не ектің сен?\nТастар көп, топырақ аз.\nТез шықты да, қурап қалды,\nӨспей қурап қалды,\nӨспей қурап қалды ол.\n\n[Куплет 3]\nНе ектің сен, не ектің сен?\nТікенді жерге не ектің сен?\nБайлық пен қиыншылықтар,\nБидайдың өсуін басады,\nЖеміс бермейді, біліп қой.\n\n[Куплет 4]\nНе ектің сен, не ектің сен?\nТопыраққа не ектің сен?\nЕккен дәнің қурамайды,\nКүткен үмітті ақтайды.\nМол етіп жеміс береді.\n\n[Куплет 5]\nНе ектің сен, не ектің сен?\nБұл өмірде не ектің сен?\nАтқарған ісің, сөзіңмен бұл өмірде\nЕккеніңді ана өмірде орасың.","songNumber":"195"},{"id":82,"title":"Неліктен","text":"[Куплет 1]\nНеліктен бәріміз бірге Құдайды\nМадақтаймыз?\nНеліктен біз осы жерде би билеп ән\nШырқаймыз?\nНеліктен барлық халықтан\nНеліктен барлық ұлттан\nЖиналып біз мадақтаймыз\nОның атын, атын биік басқадан?\n\n[Припев 1]\nСебебі Тәңіріміз теңдесі жоқ\nҚұтқарушы\nСебебі Тәңіріміз бар әлемді Жаратушы\n\n[Куплет 2]\nНеліктен бүкіл әлемге күн сәулесін\nТөгеді\nНеліктен жерге өз нәрін қар мен\nжаңбыр береді\nНеліктен әуен төгіледі\nНеліктен жыр ағылады\nНеліктен бәрі мадақтайды\nОның атын, атын мәңгі даңқталған"},{"id":619,"title":"Неліктен шөп өседі?","text":"[Куплет 1]\nНеліктен шөп өседі? Жапырақтар түседі?\nНеліктен? Еш түсінбеймін мен.\nПілге ұзын тұмсықты, шиқылдаған шымшықты,\nКім жаратты? Түсіндірші сен.\n\n[Припев 1]\nБұлай болған неге бәрі деймін?\nНеліктен? Мен түк түсінбеймін.\nНеліктен жуас қойлар?\nНеліктен асау тайлар?\nНеге? Не үшін? Мен білмеймін.\n\n[Куплет 2]\nКім жаратқан аңдарды?\nКім орнатқан тауларды?\nБұлтты неге аспанға қойған?\nБұлақ неге ағады?\nҚайда ағып барады?\nНеліктен? Не үшін? Сен ойлан.\n\n[Куплет 3]\nБәрін Құдай жаратты,\nҚұсқа берген қанатты,\nОның жаратылысымыз біз.\nӘке-шешем, мені де, аң, құстарды, сені де\nЖаратқан біздің Құдайымыз.\n\n[Припев 2]\nТек Құдай ғана бәрін біледі,\nБар әлемнің жалғыз тірегі.\nБәрімізді сүйеді, жалғыз Өзі киелі,\nМадақтаңдар Құдай Иені.","songNumber":"283"},{"id":813,"title":"Не себептен жолдан тайдың бауырым","text":"[Куплет 1]\nНе себептен жолдан тайдың бауырым,\nКиелі үй, емес пе еді, тұрағың?\nНе арқылы сіңіп ап, жалған ойларың,\n// Қай кензеңде, сөнді екен шырағың? //\n\n[Куплет 2]\nСанадың ба өзіңді тым жоғары?!\nЕлеместен, Исаның, бар айтқанын!\nАзғырды ма әлемнің құмарлықтары?\n// Көлегейлеп, Әке берер, сыйларын! //\n\n[Куплет 3]\nАуыр соқты ма, Тәңірдің жолдары?\nМойынсын деп, тыныштыққа шақырған,\nАяусыз, шырмады ма, құрған торлары?\n// Әзәзілдің, арыстандай ақырған! //\n\n[Куплет 4]\nСергек бол, деп айтқан еді Тәңірім!\nМойынтұрғың, болмайды саған қиын!\nҚиналған кезеріңде, қуат беремін,"},{"id":339,"title":"Нөсер боп, төгіл Киелі рух","text":"[Куплет 1]\nНөсер боп, төгіл Киелі Рух\nДәрия тасысын жүректе!\nЖеңіске баста бізді - Иса,\nҚұдіретің дарысын бізге!\n\n[Припев 1]\n//  Алилу-Али-Алилуйя, Алилуйя-Алилуйя! //"},{"id":910,"title":"Нұрлы аспан, күн сәулесін шашады","text":"[Куплет 1]\nНұрлы аспан, күн сәулесін шашады\nКең даланың, табиғат көркін ашады\nБұл әлем көз тартарлық әсем ғой,\nЖаратушы өмірді сұлу қып жасады!\n\n[Припев 1]\nЖүрегім толы қуаныш,\nСен едің маған сыйлаған,\nОсы күнге Құдайым жеткізген!\nТалай-талай қыйындықтан өткізген!\n\n[Куплет 2]\nБәрі өтті, бұл өмірге келгендер,\nБәрі өтті, әр ағымға сенгендер!\nКөп адамдар шындық жолын таппады,\nМені болса Иса Ием сақтады!\n\n[Куплет 3]\nҚайда жүрсем, Сені аңсап жүремін,\nМен Өзіңді тірегім деп білемін!\nБір Өзіңе сенім артып келемін,\nЖанымдасын, мен сеземін, сеземін!","alternateTitle":"Жүрегім толы қуаныш"},{"id":533,"title":"Нұрсың Сен, Ақиқат Сенің қасиетің","text":"[Куплет 1]\nНұрсың Сен, Ақиқат Сенің қасиетің\nБіз үшін бағасыз кешірім бергенсің.\nТаусылмас рақымың, шексіз құдіретің,\nБіз үшін маңызды Сенің қызметің.\n\n[Припев 1]\n// Нұр шаштың әрбір басқан қадамыма,\nЖол аштың түнекте аяқ басқанда.\nЕй, Алла шындығыңды аштың маған,\nСен ғана жүрегімнің бол тағында //\n\n[Куплет 2]\nКиелі Сөздерің әсер еткенде,\nЖан-дүнием жайнайды раушан гүліндей.\nБақытым, байлығым Сенің қолыңда,\nБарымды арнаймын Сенің жолыңа.","songNumber":"113"},{"id":861,"title":"Нұрсың Сен, киелі Сенің қасиетің","text":"[Куплет 1]\nНұрсың Сен, киелі Сенің қасиетің,\nБіз үшін бағасыз кешірім бергенсің.\nТаусылмас рақымың, шексіз құдіретің,\nТәңірім, неткен сонша ұлы едің.\n\n[Припев 1]\nНұр шаштың әрбір басқан қадамыма,\nЖол аштың, жұмаққа біз бара алуға!\nО, Құдай, шындығыңды аштың маған,\nСен ғана жүрегімнің бол тағында!\n\n[Куплет 2]\nКиелі сөздерің әсер еткенде,\nЖан-дүнием жайнайды, раушан гүліндей.\nБақытым, байлығым Сенің қолыңда,\nБарымды арнаймын Сенің жолыңда!"},{"id":434,"title":"Нұрсың Сен, қасиетті, киелісің","text":"[Куплет 1]\nНұрсың Сен, қасиетті, киелісің,\nБағасыз кешіріміңді бергенсің.\nТаусылмас рақымың, шексіз құдіретің,\nТәңірім, неткен сонша ұлы едің.\n\n[Припев 1]\nНұр шаштың әрбір басқан қадамыма,\nЖол аштың жұмаққа біз бара алуға\nО, Құдай, шындығыңды аштың маған,\nСен ғана жүрегімнің бол тағында.\n\n[Куплет 2]\nКиелі Сөздерің әсер еткенде,\nЖан-дүнием жайнайды раушан гүліндей.\nБақытым, байлығым Сенің қолыңда,\nБарымды арнаймын Сенің жолыңда.","songNumber":"32"},{"id":667,"title":"Нұры әлемнің","text":"[Куплет 1]\nНұры әлемнің,\nСен түнекке келдің,\nКөзімді аштың, көремін.\nЖүрекпен Саған\nТабынамын, Тәңірім,\nСенімен мәңгі біргемін.\n\n[Припев 1]\nОсы жерде бас ием,\nСаған тағзым етем,\n«Сен Құдайымсың!» -\nдеймін, Саған.\nСен бәрінен сүйікті,\nМадаққа лайықты,\nБәрінен ғажапсың,\nСен маған.\n\n[Куплет 2]\nДәуір Иесі,\nСен жоғары биіксің,\nКөкте Атың даңқталсын.\nЖерге келдің,\nЖаратқаныңа Өзің,\nАзап шектің біз үшін.\n\n[Куплет 3]\nАйқышқа Сен күнәмды қақтың,\nБағасын мен еш білмеспін.","songNumber":"143","copyright":"2000 Танкыоу Мусик"},{"id":554,"title":"О, аспандағы Әкеміз","text":"[Куплет 1]\n//  О, аспандағы Әкеміз,\nКиелі болсын Сенің атың.  //\nПатшалығың орнасын,\nКүнде нанды бере гөр.\n\n[Куплет 2]\n//  О, аспандағы Әкеміз,\nКиелі болсын Сенің атың.  //\nБасқаларды кешірдік,\nКүнәмізді кешір.\n\n[Куплет 3]\n//  О, аспандағы Әкеміз,\nКиелі болсын Сенің атың.  //\nАзғындыққа түсірме,\nЖамандықтан сақта.\n\n[Куплет 4]\n//  О, аспандағы Әкеміз,\nКиелі болсын Сенің атың.  //\nПатшалық та, ұлылық,\nМәңгі Сенікі. Аумин.\n\n[Куплет 5]\n//  О, аспандағы Әкеміз,\nКиелі болсын Сенің атың.  //","songNumber":"6"},{"id":595,"title":"О, Иса, жанды Құтқарушым","text":"[Куплет 1]\nО, Иса, жанды Құтқарушым,\nКеудеңе тығыламын.\nТолқыннан аман сақташы,\nҚалдырма мені жолда,\nТек Саған ғана сенемін,\nТек Саған шын берілем,\nКөз тігіп Саған қараймын,\nСенікі боп қаламын.\n\n[Куплет 2]\nИгілік те, татулық та,\nТек Сенде, Құтқарушым,\nСаған ғана ұмтыламын,\nҚабылда мені Ием.\nСенен басқа баспана жоқ,\nЖалғызсың Сен мен үшін,\nМен науқасты тастамашы,\nӘбігер өмірімде.\n\n[Куплет 3]\nО, Иса, мені сақтай көр,\nӨмірдің дауылында,\nОтанымда демалайын,\nСапардың аяғында.\nӨмірдің қайнар көзісің,\nШөлімді қандыратын.\nОтанымның бұлағы боп,\nЖүрегімде тұрасың.","songNumber":"73"},{"id":947,"title":"О Иса Сен керемет Ұлысың","text":"[Куплет 1]\n// О, Иса Сен керемет Ұлысың,\nО, Ием салтанатқа бөлендің.\nЖарық Нұрды Сен шапандай киесің,\nШындық Сөзің Сенің шынайы өмір берді! //\n\n[Припев 1]\n// Патша Сен орнатқан билікті\nЕшкім ешқашан қозғай алмайды.\nИса төгілген Сенің қаның\nАса бағалы, теңдесі жоқ бүкіл әлемде. //"},{"id":999,"title":"Ойланшы жүрегім бақытыңның шегі бар ма","text":"[Куплет 1]\n// Ойланшы жүрегім бақытыңның шегі бар ма?\nҚарашы жан дүнием Құдайыңның тегі бар ма?\nТыңдашы уәдесін, бұдан сенімді сөз бар ма?\nӘлде сен жауабын, бұл жалғаннан табасың ба? //\n\n[Припев 1]\nДүниенің алдауынан, бір ішетін тамақтан,\nАқ батаңды ауыстырып алма!\nБарлы жоққа қызығып, соны бірінші қойып,\nСыйлап берген Рухты ренжітіп алма!\nӨкінгенмен қайыра қайтпас,\nБір кеткеннен,Ол оралмас,\nҚұдай берген ақ бата!\nҚұдай берген ақ бата!"},{"id":314,"title":"О, Киелі Рух","text":"[Куплет 1]\nО Киелі Рух\nКелші менің төріме\nТағдырымды бердім Сенің еркіңе\nСаған сендім\nСаған бердім бәрін де\n\n[Куплет 2]\nО, Киелі Рух, бәрі Сенің қолыңда.\nАдамдығым, адалдығым, арым да.\nБар күнәмды құрбан қылдым жолыңа.\n\n[Куплет 3]\nКел, Киелі Рух, жанұяма, балама,\nСен жоқ жерде тыныштығым бола ма?\nӨзің келіп ұялашы санама.\n\n[Куплет 4]\nО, Киелі Рух, келші менің қазағыма.\nТөзіп болдық бұл жалғанның мазағына.\nКүшіңді бер, шығар жалған азабынан","songNumber":"144"},{"id":966,"title":"О, Киелі Түн","text":"[Куплет 1]\nО, Киелі Түн, жұлдыздар жарқыраған,\nҒажап түнде Мәсіх келді дүниеге.\nӘлем батты заңсыздық пен күнәға.\nҚұдай Ұлы құтқару берді бізге.\n\n[Припев 1]\nЖүрек толар үміт пен қуанышқа,\nБолашақ нұры жетелер алға.\nТізеңді бүк, періште әнін тыңда,\nО, ғажап түн, Киелі Мәсіх туған,\nО, ғажап түн, Иса Мәсіх туған.\n\n[Куплет 2]\nОл үйретті сүюді махаббатпен,\nТыныштығын, рақымын жаудырып.\nБақытсыз бен қасірет шеккендерге,\nӨмір берді айқышта құрбан болып.\n\n[Припев 2]\nӘніміз Оны даңқтап дәріптесін,\nӘркім Құдайға қуанып келсін.\nМәсіх - Тәңір! Оны мәңгі даңқтаймыз.\nОған мадақ құрметпен бағышталсын,\nОған мадақ, алғыс бағышталсын.","songNumber":"145"},{"id":498,"title":"О, Құдай алдыңа келіп бас ием","text":"[Куплет 1]\nО, Құдай, алдыңа келіп бас ием,\nСенімен, бақытты, мәңгі өмір сүрем.\nСамал лебіңмен маған тіл қатшы,\nКүтемін, мен аңсаймын, келші маған кел!\n\n[Припев 1]\nҚандай сұлу көздерің, қандай ыстық сөздерің,\nҚандай ғажап істерің!\nТек Саған, мен табынам бүкіл жаныммен,\nШын жүрегіммен, мен Сені сүйем!\n\n[Куплет 2]\nЖаныма, жар болған Ием, Өзіңсің!\nАйқышта, өліп, тірілдің мен үшін!\nБүкіл өмірім, жалғыз Сен үшін,\nО, Иса мәңгілік жүрегімде Сен!","alternateTitle":"Тек Саған табынамын"},{"id":817,"title":"О құдай жаратты ғой аспан жерді","text":"[Куплет 1]\nО, құдай жаратты ғой аспан жерді,\nСол Құдай жаратты ғой адамзатты.\n// Адамдар дүниенің соңына еріп,\nАлданып қалған екен өткіншіге. //\n\n[Куплет 2]\nО, бауырым тұр орныңнан, аш көзіңді,\nБіздеді Құтқарушы Мәсіх келді.\n// Ол бізбен мәңгілік болады екен,\nЕгер тәубе қылып барсақ Оған. //\n\n[Куплет 3]\nТәңірім сүйеді екен бізді мәңгі,\nӨз қанын төгіп кетті күнәң үшін.\n// Біздерді тазалады Ол күнәдан,\nҚұтқарды Ол дүниенің азабынан. //\n\n[Куплет 4]\nМәсіғім алғысым көп менің Саған\nСен ашқан жолыңмен барам Саған.\n// Қолыңмен жетелеші Құдай Ұлы,\nҚұдаймен жарастыршы мәңгі бізді. //\n\n[Куплет 5]\nАдамзат аш көзіңді, көр Құдайды\nБіз үшін жалғыз Ұлын берді Құдай,\n// Адамзат көрмейсің бе Құдай мейірін\nТас болып қалған ба еді жүректерің. //"},{"id":387,"title":"О, Құдай Ием!","text":"[Куплет 1]\n// О, Құдай Ием! Сен әлемді жараттың.\nСен барлық бұлттардан биіксің!  //\n\n[Припев 1]\n// Саған табынам, Саған табынам,\nСаған табынам Құдай Ием!  //\n\n[Куплет 2]\n// О, Құдай Ием! Сен әлемді жараттың.\nСен барлық бұлттардан жоғарысың!  //","songNumber":"7","copyright":"1977 Пете Санчез, Джр."},{"id":821,"title":"О, Құдай Ием, Өзіңе мен басымды ием","text":"[Куплет 1]\nО Құдай Ием\nӨзіңе мен басымды ием\nСен біздің көктегі Әкемізсің\nӘрқашан Атыңды мадақтаймын\nСебебі Сен бұлттардан жоғарысың\nӨмірдің мәнісің\nЖүректің әнісің\nСені сүйемін!\n\n[Куплет 2]\nО, Құдай Тәңірім,\nРақмет Саған Ұлың үшін.\nОл бізді күнәдан құтқарды.\nО, Иса, біз Саған ерушіміз.\nСебебі Сен -\nҚұдай Әкеден келгенсің,\nБіз үшін өлгенсің,\nМәңгі өмір бергенсің,\nСені сүйеміз.\n\n[Куплет 3]\nО, Құдай Әке,\nӨзіңе мен қайтсем жетем.\nӨйткені Сен бізге Рухың бердің.\nО, Киелі Рух,\nБастай гөр мәңгі өмірге.\nСебебі Сен -\nЖанымның қорғаушысы,\nСенім қолдаушысың,\nБақыт жолдаушысың,\nСені сүйеміз!"},{"id":800,"title":"О, Құдай - Иса Ием, менің!","text":"[Куплет 1]\nО, Құдай - Иса Ием менің!\nТек, Саған өмірімді арнайм(ын).\nҮмітім Сенде, жүзіңді, тынысымдай аңсаймын.\nӘке, Әке, Әке - деп, дүрсілдейді жүрегім!\n\n[Припев 1]\nТәңірім Сенің алдыңда басымды ием,\nжалғыз тілегім,\nСенің Рухыңа, кенелемін мен!\nТәңірім Сенің алдыңда басымды ием,\nСені сүйемін!\nСенің қолыңда, менің жүрегім!\n\n[Бридж 1]\n// Сенің қолыңда, менің жүрегім!\nСенің қолыңда, менің өмірім! (2р) //"},{"id":889,"title":"О, Құдай Иса Тәңір Сенімен болғым келеді","text":"[Куплет 1]\nО, Құдай Иса Тәңір,\nСенімен болғым келеді!\nСыйладың бізге өмір,\nМәңгілік өміріңді!\n\n[Предприпев 1]\nО, Тәңір, алғыс Саған!\nО, Құдай, мадақ Саған!\nҚұтқардың Сен, ұлың мен қызыңды!\n\n[Припев 1]\n//  Алғысымыз, тек - Саған!\nМадақталсын Есімің!\nПаналаймыз, тек Сені,\nКиелі Патша - Құдайым Иса! //\n\n[Куплет 2]\nҚұтқардың бізді Иса,\nТәңірдің рақымымен,\nКүнәмізді кешіріп,\nЖуып-шайып қаныңмен!"},{"id":8,"title":"О, Құдай Саған келемін","text":"[Куплет 1]\nҚайғы тартып қиналғанда,\nО, Құдай, Саған келем.\nӘлсіз болып, күш кеткенде,\nҚұшағыңа енем.\n\n[Припев 1]\nО, Құдай Саған келемін\nРухымды қайта тірілт.\nМейіріммен қуат беріп,\nТас жүрегімді жібіт.\n\n[Куплет 2]\nАзапты өмір сүріп келдім,\nҚайдан тыныштық табамын?\nСаған келдім, Құтқарушым.\nҚасыңда мәңгі қаламын.\n\n[Куплет 3]\nЖаным кейіп, налып тұрмын,\nӨмір солай өте ме?\nЕңсем түсіп, шаршап тұрмын,\nӨзің мені жетеле.","songNumber":"71"},{"id":625,"title":"О, Құдай Сен Деген Жақсы","text":"[Куплет 1]\nО, Құдай Сен деген жақсы\nО, Құдай мейірімдісін\nҚұдай Сені аңсап ойлаймын.\n\n[Припев 1]\nҚинала келдім Саған\nЖақындадың Сен маған\nкөңіл-күйімді Сен көтердің."},{"id":295,"title":"О, Құдай, Сені ойлаймын","text":"[Куплет 1]\nО, Құдай, Сені ойлаймын,\nҚұдайым Сені аңсаймын.\nМейірімің Сенің мол маған.\n\n[Припев 1]\nҚинала келдім Саған,\nЖәрдем бердің Сен маған.\nТүнекиен рухымды Сен көтердің.\nСиынамын мен Саған,\nЖақындадың Сен маған.\nМенің жүрегімді Сен жұбаттың.","songNumber":"116"},{"id":983,"title":"О, Құдай сондай мейірімді маған","text":"[Куплет 1]\nО, Құдай сондай мейірімді маған!\nО, Құдай сондай мейірімді маған!\nО, Құдай сондай мейірімді маған!\nӘрқашан айтам: Ол мейірімді маған!"},{"id":409,"title":"О, Құдайым мені тағы қолдай гөр","text":"[Куплет 1]\nТабынайық, Ұлы Тәңір қолдайды\nБұл уақытта Сенің Сөзіңді ұғайық\n// Әр киелі Сөздеріңе қосылып,\nЖүрегімнің түбінде мен сақтайын //\n\n[Куплет 2]\nСені даңқтап бұл жаратқан дүниеде,\nӘр күн сайын біз жүрейік үйіңде.\nЖүрегімді қуанышқа толтырып,\nЖеміс беріп тұрсақ екен Өзіңе.\n\n[Куплет 3]\nҰлы Тәңір Өзің келген кезіңде,\nСезбей қалып біз қалмайық бұл жақта.\nӘр уақытта ұмытпастан сиынып,\nБіз толайық қуанышты Рухыңа.\n\n[Куплет 4]\nАз уақытта өкінбестен Сен үшін,\nБұл әлемнің қызығына шыдамай.\n// Әр күн сайын Өзіңменен бір болып,\nҚызмет етіп жүрсек екен Өзіңе. //"},{"id":815,"title":"Ол бар жерге","text":"[Куплет 1]\nОл бар жерге кел алғыспен,\nЖүрегіңде мадақта Оны,\nМадақта Оны.\nОл бар жерге кел алғыспен,\nЖүрегіңмен дауыста Оған,\nДауыста Оған.\n\n[Припев 1]\nМадақ пен құрмет бер\nОның құдіретіне.\nИса - ең Ұлы Есім!","songNumber":"148"},{"id":43,"title":"Ол мадақталсын","text":"[Куплет 1]\nОл мадақталсын,\nПатша мадақталсын\nОған табынамыз!\nОл мадақталсын,\nПатша мадақталсын\nМен Оған табынамын!\n\n[Припев 1]\nОл Тәңір! Өмірді жарқыратады.\nАспан мен жер қуан Оның киелі Атына.\nОл мадақталсын, Патша мадақталсын!","songNumber":"115","copyright":"1985 Страигхтвай Мусик | Моунтаин Спринг Мусик"},{"id":9,"title":"Ол мәңгі","text":"[Куплет 1]\n// Иса, жалғыз Сен - Иса!\nЖанымды жұбатып, қасымда боласың! //\nМәңгі өміріңді, сыйладың маған,\nРизамын мен - Саған!\n\n[Припев 1]\n// Ол мәңгі, ол мәңгі, ол мәңгі,\nБіздің Иеміз - Иса! //","songNumber":"66"},{"id":864,"title":"Оң жағыма жиналды","text":"[Куплет 1]\n// Гүлденіп жайқалады жүрегімде сөздерің,\nҚандай керемет, қандай әсем!\nОң жағында отырмын, әділеттілер тобы,\nЖыйналып Өзіңді тыңдайды! //\n\n[Припев 1]\n//  Оң жағыма жыйналды, әділеттілер тобы,\nСу сұрасаң, су беріп, шөлдегенде кіргізді!\nАуырғанда ем беріп, қамқорлығын көрсетті,\nЕнді мәңгілік өмір, сендерге беріледі! //\n\n[Куплет 2]\n// Қуаныш жүрегімде, тыныштық жан дүниемде,\nЖерге түсті көктің сәулесі!\nНеліктен қуанбасқа, Әке қолы жанымда,\nЖүрегім сөздерін тыңдайды! //"},{"id":773,"title":"Орындағым келеді еркіңді","text":"[Куплет 1]\nОрындағым келеді еркіңді,\nТазартшы мені, өтінем, қаныңмен!\nКөргім келеді Сенің даңқыңды,\nТолтыршы мені махаббатыңмен!\n\n[Припев 1]\nСенсіз ешбір білмеймін жолды,\nҚалай өмір сүрем, қайда барам!\nӨтінем үйретші сүюді,\nСен сүйгендей!\n\n[Бридж 1]\n// Тазартшы мені Өз қаныңмен!\nТайдырма мені Өз жолыңнан! //\nТазарт бізді!\nТазарт бізді!","songNumber":"150","alternateTitle":"Тазартшы мені"},{"id":389,"title":"Осанна","text":"[Куплет 1]\nПатша даңқын көремін,\nНұрлы бұлтта келеді.\nЖер толқиды.\nЖер толқиды.\nМейірімін көремін,\nжуған менің күнәмды.\nХалық жырлайды.\nХалық жырлайды.\n\n[Припев 1]\n// Осанна! Осанна!\nОсанна заңғар көкте //\n\n[Куплет 2]\nҰрпақтарды көремін,\nЖоғары көтерілген,\nАдал сенімге.\nАдал сенімге.\nЖаңаруды көремін,\nТізе бүгіп сұраған.\nБіз іздеген.\nБіз іздеген.\n\n[Бридж 1]\nТазарт, жүрегімді емде.\nКөзімді аш көрінбейтін әлемге.\nҮйрет махаббатыңды мені сүйген.\nЖұмсарт жүрегімді Сен.\nПатшалығыңа өзімді берем.\nБарамын жерден Саған мәңгілікке.","songNumber":"153","alternateTitle":"Патша даңқын көремін","copyright":"2006 Хиллсонг Публишинг"},{"id":799,"title":"Осанна!","text":"[Куплет 1]\n// Осанна! Құдай Атын көтерем!\nОсанна! Құдай Атын көтерем! //\nҚұрмет пен мадаққа\nлайықсың тек Сен,\nОсанна Құдайды көтерем.\nТағзым етуге\nлайықсың тек Сен,\nОсанна! Құдай Атын көтерем.","songNumber":"152","alternateTitle":"Құдай Атын көтерем!"},{"id":890,"title":"Осы әлемде мен жүрдім","text":"[Куплет 1]\nОсы әлемде мен жүрдім\nАяладым армандай\nӨмірдегі бар байлық\nКелді маған қиналмай.\nҚараңғыда жүр едім\nИса ашты көзімді.\nАйтып жеткізе алмай\nЖүректегі сезімді.\n\n[Припев 1]\n// Киелі Құдай (Ием)\nЖаным менің Сені аңсайды.\nЖалғыз бола алмай\nСаған қарады\nСені іздеп күтеді. //\n\n[Куплет 2]\nКөңілімді жұбатты\nБерді маған қуатты.\nСүйем деген сөзімен\nЖүрегімді қуантты.\nМені өлімнен құтқарған\nСүйемін мен Исаны.\nҚұдайым болып келген\nСүйемін Тәңірімді.","songNumber":"118","alternateTitle":"Киелі Құдай"},{"id":486,"title":"Осы жалған дүниеде ай өмір сүрген әр пенде","text":"[Куплет 1]\nОсы жалған дүниеде ай,\nөмір сүрген әр пенде,\nЖақсы - жаман ісіне\n// жауап берер Тәңірге! //\nКімдер келіп өмірге,\nКім кетпеген дүниеден,\nЖақсы - жаман, бәрі де\n// Өтіп кетпек өмірден! //\n\n[Припев 1]\nСезсеңші бауырым, сезсеңші,\nЖалған өмір сүргенің.\nОйланып, бауырым, көрсеңші,\nСенің де өтер өмірің.\n\n[Куплет 2]\nЕкі мың жыл ішінде,\nӨлген өліп, тіріліп,\nИса Тәңір алдында\n// Кездесер күн келер - ай! //\nДайын болып сол күнге,\nОйлап тұрсаң, бауырлар,\nӨз күнәңді мойындап,\n// Исаны шақыр көмекке! //\n\n[Куплет 3]\nТәңірден келген Жазбалар - ай,\nШындықтың бетін ашқандай,\nСол кітапты оқыған,\n// Құдайдың жолын тапқандай! //\nКелетінін Исаның,\nТаурат, Інжіл баяндап,\nДайын бол деп халқыма,\n// Құдай бүгін ашылды! //\n\n[Куплет 4]\nЕлес, елес, елес пе, ай,\nЕлес шындық емес пе,\nҮш кітабы Исаның,\nҚұдай Сөзі емес пе, ай\nБелес, белес, белес пе,\nБелес жақын емес пе,\nКелетіні Исаның,\nЖақын қалды емес пе?\nТастама Иса, тастама,\nмұсылман атты бауырымды,\nШындыққа бізді жетеле,\n// Өзіңнің келер күніңмен! //","songNumber":"141"},{"id":277,"title":"Осы жолменен барамын","text":"[Куплет 1]\nОсы жолменен барамын, Ием Иса оралып келгенше.\nТар есік, тар жолмен, Айқышымды көтеріп,\nОсы жолымның соңында  көремін мен Ием Исаны.\nМенің Ұлы Ием Иса мені қарсы алады.\n\n[Куплет 2]\nМен тұрайын, жүгірейін, Ием оралып, қайта келгенше.\nМен тұрайын ән салайын, жерді ұлылық жамылғанда.\n\n[Куплет 3]\nМенің сүйікті Ием Иса әлемнің Құтқарушысы.\nМенің сүйікті Ием Иса Ұлы Патшасың сен."},{"id":198,"title":"Осы күнді Құдай жаратқан","text":"[Куплет 1]\n///// Осы күнді Құдай жаратқан\nШаттанамыз Оның алдында /////\n\n[Припев 1]\n//// Шаттан Тәңірге ////\n\n[Куплет 2]\n//// Қуан сен Оның алдында\nИса лайық құрмет алуға ////","songNumber":"155"},{"id":588,"title":"Осы күн, жаратылды","text":"[Куплет 1]\nОсы күн, жаратылды,\nжаратылды жалғыз сен үшін!\nОсы күн, жаратылды,\nжаратылды жалғыз сен үшін!\n\n[Припев 1]\nОсы күнде, біз Құдаймен бірге!\nОсы күнде, біз Құдаймен бірге!\nОсы күнде, біз Құдаймен бірге!\nБіз, Құдаймен бірге!\n\n[Куплет 2]\n//  Мошу кун яратилди,\nяратилди ялғуз сән учун!\nМошу кун яратилди,\nяратилди ялғуз сән учун!  //\n\n[Припев 2]\n//  Мошу кундә - Худа билән биллә!\nМошу кундә - Худа билән биллә!\nМошу кундә - Худа билән биллә!\nХуда - биз билән, биллә!  //"},{"id":199,"title":"Осы өмірде қиналған кезде","text":"[Куплет 1]\nОсы өмірде қиналған кезде,\nЕсіме Сені аламын.\nӘрбір күнімде қуанған кезде,\nЕсіме Сені аламын.\n\n[Припев 1]\nЖанымдасың Сен менің әрқашан,\nЖан-тәніммен ұмтыламын мен Саған.\nСенімім бар ешқашан сарқылмайтын,\nҮмітім бар өшпейтін мәңгі.\n\n[Куплет 2]\nОсы өмірде қиналған кезде,\nЖаныма Сені шақырам.\nӘрбір күнімде қуанған кезде,\nЖаныма Сені шақырам.","songNumber":"119"},{"id":553,"title":"Осы тойға берсін Құдай батасын","text":"[Куплет 1]\nОсы тойға берсін Құдай батасын\nДаңқы артсын, Ұлы Тәңір жасасын!\nҚұдіретті күшіменен қорғасын!\nБастарыңда қайғы-қасірет болмасын!\n// Бақытты болсын жастар деп бәрің де,\nСиыныңдар бірге Иса Тәңірге. //\n\n[Куплет 2]\nЖас жұбайлар еркін Оның білуге,\nМәңгілікте бірге өмір сүруге,\nЖанында боп жарылқасын Тәңірім,\nЖарылқасын жер бетінде өмірін.\n// Бақытты болсын жастар деп бәрің де,\nСиыныңдар бірге Иса Тәңірге. //\n\n[Куплет 3]\nТой бітпесін, тойы тойға жалғассын,\nЕкеуің де жарқылдаған алмазсың.\nІңгәләған берсін Тәңір нәресте,\nЖас отаудың ол бір сәні емес пе?\n// Бақытты болсын жастар деп бәрің де,\nСиыныңдар бірге Иса Тәңірге. //","songNumber":"211"},{"id":308,"title":"О, Тәңір","text":"[Куплет 1]\nО, Тәңір,\nБүкіл әлемдегі\nБайлықтардан,\nҚымбатсың Сен!\nСен әсемсің,\nГаухар маржандардан!\nМұқтажбын өмірмде,\nМен Саған!"},{"id":941,"title":"О, Тәңір бұл әлемнің бастамасы","text":"[Куплет 1]\nБұл әлемнің бастамасы, Өзің болып,\nӘлемнің ақыры да Сен боласың!\nАспаннан жердегіге қуат беріп,\nАл Өзін кең әлемге құпиясын!\n\n[Припев 1]\n// О Тәңір! Бұл әлемнің патшасы,\nО Тәңір бұл әлемнің қолдаушысы.\nО Тәңір Саған ғана тағзым етем,\nО Тәңір бұл әлемнің берекесі! //\n\n[Куплет 2]\nКешір мені күнәләрдан арылайын,\nИса Тәңір Өзіңе мен табынайын.\nКуаныштан жұбаныштан көздің жасы,\nТөгіледі Құтқарушым айналайын.\n\n[Куплет 3]\nӨзің бол мендегі шынайы сезім,\nМәңгілік жүрегімде жаса менің.\nЖаратқан көрсет енді шындық жолын,\nҚұтқарылып саған келсін қазақ елім."},{"id":128,"title":"О, Тәңірім, жер бетінде","text":"[Куплет 1]\nО, Тәңірім, жер бетінде,\nЕсімің қандай қасиетті есім.\nО, Тәңір, дәріптейміз есіміңді, атыңды Ием.\nСені мадақтаймыз, бейбіт өмір Әміршісі,\nҰлы Құдай, Ұлы Тәңір.","songNumber":"284"},{"id":574,"title":"О, Тәңірім тыңдашы әнімді","text":"[Куплет 1]\nО, Тәңірім тыңдашы әнімді,\nШын ниетіммен мадақтаған жанымды.\nІзгі Бағушым алдыңа келемін.\nМәңгілік мекенге жетелейсің, сенемін.\n\n[Куплет 2]\nО, Тәңірім үйретші сүюді,\nМойынсұнуды, сеніммен өмір сүруді.\nЖүрегімнен Саған орын берейін\nСоңыңнан қалмай, үмітпен ерейін.\n\n[Куплет 3]\nПенделік болмысты тастап толықтай,\nЖаратқан Иемді мадақтап өтейін.\nҚарсы жаулардан қаймықпай, қорықпай,\nКөктегі үйге жеңімпаз болып жетейін.","songNumber":"136"},{"id":63,"title":"Өзге Есім жоқ","text":"[Куплет 1]\nӨзге Есім жоқ\nИсаның Есімінен.\nӨзге есім жоқ\nЕсімінен Тәңірдің.\n\n[Куплет 2]\nӨзге есім жоқ\nИсаның Есімінен,\nОл лайық құрметке,\nОл лайық мадаққа,\nОл лайық,\nДәріптейік Оны.\n\n[Припев 1]\nҰлы Оның Есімі, бәрінен Ұлы.\nЖоғары Есімі Оның бұлттан да.\nБиік Оның Есімі, көктен де биік,\nДаңқ, құрмет, мадақ бер\nОның Ұлы Есіміне.","songNumber":"156"},{"id":441,"title":"Өзгертші мені","text":"[Куплет 1]\nӨзгертші мені, жаңартшы жүрегімді.\nСен маған жаудыршы рақымыңды.\nЖалынам Саған, тек Өзің қалай қаласаң,\nӨзгертші мені Өзіңнің\nсүйіспеншілігіңмен.\n\n[Припев 1]\nАйналамды толтырсын махаббатың,\nСодан мен қуат аламын.\nҚанат жайып, самғай ұшсам соңыңнан.\nЖетелесең мені Сен,\nҒажайып еркіңмен,\nМен Өзіңе ерсем.\n\n[Куплет 2]\nКездескім келет,\nМен Өзіңмен бетпе-бет,\nБілсем деп ем махаббатың маған.\nЖаңартшы мені, еркіңді маған білдірші,\nӘр күнді толтыршы Өзіңнің\nСүйіспеншілігіңмен.","songNumber":"122","copyright":"1992 Ворд, Инк."},{"id":86,"title":"Өзен жолдан алшақ емес","text":"[Куплет 1]\nӨзен жолдан алшақ емес,\nБұлттар ұшар белес-белес.\nЖолаушыға жол бір елес,\nОңай емес, оңай емес.\n//  Көкейінде арман жатқан,\nШіркін, егер үй орнатсам,\nСол үйден мен бақыт тапсам,\nБақыт тапсам, бақыт тапсам! //\n\n[Куплет 2]\nМезгіл-мезгіл тұра қалар,\nҚоңыр үнмен әнге салар.\nӨзі сүйген әсем әнді,\nОсы қазір айтқан әнді.\n// Үй деген тек елес емес,\nТерезе емес, есік емес.\nДүние емес, жиһаз емес,\nОл үй емес, ол үй емес //\n\n[Куплет 3]\nҮйім бұл құтты ошағым,\nҚайта-қайта ораламын.\nТағдыр тәлкек етсе-дағы,\nҚұр сүлдерің жетсе-дағы.\n// Үйде сені түсінеді,\nСені күтіп күрсінеді,\nүйде жаның жай табады,\nсол байтағың, сол байтағың. //\n\n[Куплет 4]\nБұлттан да биік ғарышта,\nАспаннан ары алыста,\nНағыз үйді дайындаған,\nКөктегі Әке саған, маған.\n// Көктегі үйге барам десең,\nӨсиетке көңіл бөл сен,\nЖердегі үйде орындағын,\nҚұдай заңын, Құдай заңын. //","songNumber":"198"},{"id":282,"title":"Өзіме ием етіп","text":"[Куплет 1]\nӨзіме ием етіп\nӨзіме ием етіп\nҚойған бар нәрсені\nТастап Сенің\nАлдыңа келемін\nӨзім сүйгенімнің\nБәрінен бас тартып\nТек Сені сүйемін\n\n[Припев 1]\nМахаббатың\nЕң қиын жағдайда\nТерең теңіздердей\nТыныштық береді\nРухымның\nІргетасы болған\nМахаббатыңда тұрам"},{"id":706,"title":"Өзіңе тартшы","text":"[Куплет 1]\nТарт мені Өзіңе,\nЕшбір жіберме.\nАлдыңа тастайм мен бәрін,\nЕстісем: «Досыңмын!» - десең.\n\n[Припев 1]\nТілегім тек Сен\nНиет жоқ өзге.\nСаған теңдес ешкім жоқ,\nҚұшағыңа ал киелі.\nЖол көрсет маған,\nҚайтарш Өзіңе.\n\n[Бридж 1]\nБарымсың Сен,\nКерегім тек Сен, Ием.\nБарымсың Сен,\nЖақын танып-білсем.","songNumber":"158","copyright":"1994 Меркы / Винеярд Публишинг"},{"id":583,"title":"Өмір берген Құдайыма","text":"[Куплет 1]\nӨмір берген Құдайыма рахмет!\nЖалғыз Ұлын құрбандыққа шалған!\nМейірімін зор молыммен төккен,\nТәңірім бәрі , мені сүйгендіктен!\n\n[Припев 1]\nИсаның Киелі төгілген қанымен\nСенің алдыңа, мен, Әкем, деп келемін.\n\n[Куплет 2]\nӘкетайым, жүрегіммен табынамын\nСені сүйемін, зор, шексіз сағынамын\nСені аңсаймын әр сәтте\nЖүрегіммен қастерлеймін!\nӨз Рухыңмен келші, күтем осы жерге!"},{"id":488,"title":"Өмір бердің үмітті жалғадың","text":"[Куплет 1]\nӨмір бердің үмітті жалғадың\nАйқышта\nКешірім бердің күнәдан ақтадың\nТыныштық бақыт сыйладың\n\n[Припев 1]\nМадақталсын атың\nҒасырдан ғасырға\nМәңгілік Сен Патша\nПеріштелер ән сап\nБірге дауыстап\nҮн қоссын мадақтап!\n\n[Куплет 2]\nӨмір бердің үмітті жалғадың\nМахаббатыңмен баурадың\nСенім бердің жеңбейді қайғы мұң\nАсуларында тағдырдың"},{"id":263,"title":"Өмірге келдім, шындық көрмедім","text":"[Куплет 1]\nӨмірге келдім, шындық көрмедім\nҚай жол тура жол анық білмедім\nМақсат қоймадым болашағыма,\nҚызығып жүрдім бала шағыма!\nҚиындық түсті үйіп басыма,\nБілмеймін Құдай, көздің жасы ма?!\nЗұлымдық істер тұла бойымда,\nЖақсылығым жоқ, мүлде бойымда!\nТыным таппайды жүрегім менің,\nТәнім әлсіреп, жаным да менің!\nҚайдасың Құдай сөйлеші, қане,\nҚұтқаршы мені, үйімді және!\nЖаратқан Ием! Жаратқан Ием!\nАлдыңа келіп, басымды ием!\n\n[Куплет 2]\nАлғашқы қадам жасаған күні,\nҚуаныш берді маған Тәңірім!\nӨмірдің мәнін енді түсіндім,\nБар әділдікті Исадан көрдім!\nШындықтың көзі ашылды маған,\nЖүрекке құйды Рухани тағам!\nӘрбір сөздері ойды өзгертті,\nРухым тіріліп, ол бір сөз берді!\nҚұдайым менің, Саған мен сендім,\nШапағатыңды жүзіңнен көрдім!\nИсаға қарап көзім ашылды,\nОның сөздері, Нұр боп шашылды!\nКөктегі Әке! Көктегі Әке!\nҚұтқарған бізді, Ұлыңды сүйем!\nЖаратқан Ием! Жаратқан Ием!\nАлдыңа келіп, басымды ием!"},{"id":908,"title":"Өмірдегі бар асылдың, Саған құны жетпейді","text":"[Куплет 1]\nӨмірдегі бар асылдың,\nСаған құны жетпейді\nӨкінішке көп адамдар,\nСоны біле бермейді!\nЖақсы шығар олардың,\nСенім артып жүргені!\nБәрі бекер сүймесе,\nБір өзіңе сенгенің!\n\n[Припев 1]\nЖалғыз Сенсің қуанышқа,\nшаттығыңа бөлейтін,\nМахаббатың мәңгі болып,\nҚала берер ән болып!\nСені жырлап өтейінші,\nӨмірден, бір өмірге,\nБіз жаралдық бауырларды,\nЖәне Сені сүюге!\n\n[Куплет 2]\nКөктен келген Киелі Рух,\nОрын алды бойымнан,\nБақытымсың Сен менің,\nКөптен күткен жолыңнан!\nТек Өзіңсің мақтанышым,\nкөтеретін биікке,\nДаңқың өшпес біз үшін,\nБұл өмірден өтсекте!\n\n[Куплет 3]\nБала кезден армандадым,\nЖетегіңде жүруді!\nМахаббатың күші толған,\nҚұшағыңа енуге!\nҚаншама жыл аңсаумен,\nЖүрдім мен жай таба алмай,\nБілдің мені паналадың,\nБауыр бастың саялай!"},{"id":506,"title":"Өмірде нелер болмайды?","text":"[Куплет 1]\nӨмірде нелер болмайды?\nӨмірге көңлім толмайды,\n// Өмірдің бар ма қызығы,\nТанымасаң шын Құдайды? //\n\n[Куплет 2]\nҚұдайсыз өткен өмірің,\nСу сепкен оттай өшпей ме?\n// Құдайсыз жиған дүние,\nҚаңбақтай ұшып кетпей ме? //\n\n[Куплет 3]\nСенсің ғой менің бақытым,\nСенсің ғой менің байлығым.\n// Жетеле мені Құдайым,\nБолайын бірге әрдайым. //\n\n[Куплет 4]\nАлғыс айтыңдар Құдайға,\nМадақтап Оның есімін.\n// Жаратушым деп мойындап,\nБас иіп тәубе қылыңдар. //\n\n[Куплет 5]\nКешіріп сенің күнәңді,\nҚұшағын жайып қарсы алар.\n// Кел, қызым, кел, ұлым деп,\nЖәннаттың есігін ашар. //","songNumber":"129"},{"id":520,"title":"Өмірдің бұлағы","text":"[Куплет 1]\nТаптым мен мәңгілік өмір бұлағын.\nТаптым мен шынай дос - Иса.\nКүтем Сенің Рухыңды, даңқыңды әрдайым.\nӨмір бұлағын таптым бір Өзіңнен Тәңірім.\n\n[Припев 1]\nИса, қасымдасың Сен!\nИса, Тәңірімсің Сен!\nИса таптым өмірдің бұлағын\nтек Сенен\nТек Сенен, тек Сенен!","alternateTitle":"Иса қасымдасың Сен, Таптым мен мәңгілік өмір бұлағын"},{"id":249,"title":"Өмірдің долы толқыны тасиды","text":"[Куплет 1]\nӨмірдің долы толқыны тасиды,\nҚайықты шайқап асау тасқыны.\nӨлімнен үрейленіп, аласұрып:\n«Тәңірім!» деп Сені шақырамын.\n\n[Куплет 2]\nСен мені аяй гөр, кешіріп құтқар,\nӨмір бойы күресіп келемін.\nКүшім бітті, Өзіңе бағынамын,\n«Тәңірім!» деп Саған табынамын.\n\n[Куплет 3]\nМені жұбатып, жолды көрсете гөр,\nЖетелеп алып жүр кемежайға,\nӨмірдің толқынынан шығара гөр,\nМені Тәңір Ием, жағажайға.","songNumber":"76"},{"id":774,"title":"Өмірдің қиын шағында","text":"[Куплет 1]\nӨмірдің қиын шағында,\nЖүректі мұң басса,\n//  Бір ғажайып дұғаны мен,\nҚайталаймын жатқа.  //\n\n[Куплет 2]\nСол сөздің үндестігінде,\nҚұдіретті күш бар,\n//  Қасиетті бір көркемдік,\nСол сөздерден шығар.  //\n\n[Куплет 3]\nЖүректің жүгі жеңілдеп,\nЖаным рахат табар.\n//  Жан-дүниеме түскен жарық,\nҮміт отын жағар.  //\n\n[Куплет 4]\nАуырлық жүректен түседі,\nкүмән да алыстайды.\n//  Жылаймын да, сенемін де,\nжаным рахат табады!  //","songNumber":"160"},{"id":900,"title":"Өмірдің мақсаты не деп ойлайсың?","text":"[Куплет 1]\nӨмірдің мақсаты не деп ойлайсың?\nКүнәсіз болам деп кімді алдайсың?\nБақытты сен неге бола алмайсың?\n//  Құдайсыз өмірден шындық таппайсың.  //\n\n[Куплет 2]\nБұл жалған дүниеде адалдықты сен,\nТаптым деп ойладың, бірақ таппадың.\nСебебі өмірдің нағыз шындығы,\n//  Құдайдың жолында, соны түсінгін.  //\n\n[Куплет 3]\nТәңірдің сөзінен сусын тартыңдар,\nШындықтың нанынан тегін алыңдар.\nСонда Құдайменен мәңгі боларсың,\n//  Жұмақтың төрінде бақыт табарсың.  //","songNumber":"130"},{"id":923,"title":"Өмірдің тар жолы соңы бақыт","text":"[Куплет 1]\nӨмірдің тар жолы соңы бақыт,\nКелемін Тәңірге сенім артып.\nҚол созып күтіп тұр мені Тәңір,\nМәңгілік жұмақта ғажап өмір.\n\n[Припев 1]\nСол бір жарық дүниеге,\nСол бір әсем күндерге,\n// Жаным асығады-ай алып ұшып! //\n\n[Куплет 2]\nӨмірдің тар жолы соңы бақыт,\nЗымырап барады өтіп уақыт.\nБілемін сол бір сәт алыс емес,\nЖұмақта Иеммен бір жүрер кез.","songNumber":"139"},{"id":41,"title":"Өмір жолында жігермен жүреміз","text":"[Куплет 1]\nӨмір жолында жігермен жүреміз,\nЕгер сенетін болсақ Исаға.\nЕңбекте Құдайдың күшін табамыз,\nЕгер сенетін болсақ Исаға.\n\n[Припев 1]\nСенсек егер Исаға,\nМәңгі қуаныш болар,\nНұрланады жол сонда,\nДұшпан ешқашан абыржытпайды.\n\n[Куплет 2]\nҚұдайдың уәдесі анық болады,\nЕгер сенетін болсақ Исаға.\nЖүрегімізге игілік толады,\nЕгер сенетін болсақ Исаға.\n\n[Куплет 3]\nТілегін орындауға үйренеміз,\nЕгер сенетін болсақ Исаға.\nЖаңарып, ерекше күйге енеміз,\nЕгер сенетін болсақ Исаға.","songNumber":"74"},{"id":855,"title":"Өмір кітабында есімім","text":"[Куплет 1]\nӨмір кітабында есімім\nСаған алғыс айтамын.\nМәңгілікте бір өзгеріс,\nЖүрек жырын жырладым\nЖаңа әнін арнадым.\n\n[Припев 1]\nЖелдің самалындасың,\nКүннің шуағындасың!\nБұлбұл құстың әнінде,\nТеңіз толқынындасың!\nО, Құдайым, Сен менің жүрегімдесің!\n\n[Куплет 2]\nАғады өмір өзені,\nМәңгілік өмір суы.\nӘр тамшы суы Сенімен,\nӨткізген әр күндерім\nТек үмітпен, сеніммен!"},{"id":60,"title":"Өмірімді Саған арнадым","text":"[Куплет 1]\nӨмірімді Саған арнадым,\nБір Өзіңе ұмтыламын.\nСенімімді жасырмадым,\nБір Өзіңе сиынамын.\n\n[Припев 1]\n// Тек Сенің мәңгілік адалдығың,\nБолсын деп өмірлік қорғанышым.\nКүндіз-түні Саған қараймын,\nЕң Ұлы менің Құдайым. //\n\n[Куплет 2]\nСалшы мені Өз жолыңа,\nҚараңғыда адаспайын.\nАлшы мені Өз қолыңа,\nСаған келіп паналайын.","songNumber":"90"},{"id":1002,"title":"Өмірімді Саған бердім","text":"[Куплет 1]\nӨмірімді Саған бердім,\nСаған мұқтажбын әрдайым\nІздесем қасымдасың Сен.\nҚиын кезде Сені шақырам.\nСен бәрінен де жоғарысың.\nСаған Иса, толықтай бағынам!\n\n[Припев 1]\nБір жол, Иса, тек Сен үшін өмір сүремін мен.\n\n[Куплет 2]\nСен мені тастамайсың.\nРақымыңмен өмірімді\nАғыл-тегіл мол толтырасың.\nСен ешқашан өзгермейсің\nКеше, бүгін де мәңгілікте.\nСен тұрақтысың, Тәңірім менің!\n\n[Бридж 1]\nСен жол, шындық, шынайы өмір.\nСеніммен жүрем, сезіммен емес\nСен үшін, Ием Сен үшін.\n\n[Припев 2]\nТек Иса менің Ием!"},{"id":526,"title":"Өміріме Сен қажетсін Тәңір әр күнде","text":"[Куплет 1]\nӨміріме Сен қажетсің Тәңір әр күнде.\nСенімен сағат сайын біз, болайық бірге.\nСендей болып кім Тәңірім жетелер мені\nБарлық жағдайда қолыңмен көтерші мені.\n\n[Припев 1]\nСен қажетсің, Сен қажетсің,\nСені іздеймін\nСен қажетсің, Сен қажетсің,\nСені аңсаймын!\nИса қажетсің Сен,\nКиелі жүзіңмен өзгертші,\nЖүрегімді."},{"id":233,"title":"Өмірімнің мәні","text":"[Куплет 1]\nӨмірімнің мәні,\nМенің таңымның қуанышы.\nЖүрегімнің әні,\nСені мадақтайды Тәңір.\n\n[Припев 1]\nӘн сал, аллелуя, аллелуя.\nӘн сал, аллелуя,\nСені мадақтайды Тәңір!"},{"id":218,"title":"Өмірімнің мәні, жан-дүниемнің сәні","text":"[Куплет 1]\nӨмірімнің мәні, жан-дүниемнің сәні,\nЖүрегімнің әні, Сенсің, Иса.\n\n[Припев 1]\nШын жүрегіммен мадақтаймын\nЖақсылығыңды ұмытпаймын.\nБарлық ісімді, барлық күшімді,\nСаған ғана арнаймын.","songNumber":"52"},{"id":156,"title":"Өмірімнің мәні, менің таңымның қуанышы","text":"[Куплет 1]\nӨмірімнің мәні, менің таңымның қуанышы.\nЖүрегімнің әні,\nСені мадақтаймын Тәңір.\n\n[Припев 1]\nӘн сал, аллелуя, аллелуя.\nӘн сал, аллелуя,\nСені мадақтаймын Тәңір!","songNumber":"120"},{"id":688,"title":"Өмірім Сенде Ием","text":"[Куплет 1]\nӨмірім Сенде, Ием,\nКүшім де Сенде, Ием.\nҮмітім Сенде, Ием,\nСенде, тек Сенде.\n\n[Куплет 2]\nСиынам өміріммен, Ием,\nСиынам Саған барлық күшіммен.\nБар өміріммен,\nБарлық күшіммен,\nБар үмітім Сенде, Ием.","songNumber":"161","copyright":"1986 Интегриты'с Хосанна! Мусик"},{"id":32,"title":"Өте ертеде","text":"[Куплет 1]\nӨте ертеде, заңғар көктерде\nСенің атыңды Құдай атады.\nТәңір қарады, жаратып сені.\nРизашылықпен деді Ол сонда:\n«Орасан осы ғаламда барлығын\nМен Өз қолыммен сүйіп жараттым.\nСаған қарап қуанып,\nМен шаттанамын.\nЕсте сақта:\nМен сүйем сені.\n\n[Припев 1]\nСүйем сені,\nБата берем.\nСенің жүрегіңе сыйлаймын\nМахаббатымды Мен».","songNumber":"163"},{"id":866,"title":"Өте жақсы болады","text":"[Куплет 1]\nӨте жақсы болады!\nӨте жақсы болады!\n// Егер өзіміз шешкенді болашақты! //\n\n[Куплет 2]\n// Егер ақылды болсақ //\nТыныштық, керемет болар, соны қалаймыз біз.\n\n[Куплет 3]\n// Тату болсақ бәріміз //\nТыныштық, керемет болар, соны қалаймыз біз.\n\n[Куплет 4]\n// Егер салмақты болсақ //\nТыныштық, керемет болар, соны қалаймыз біз.\n\n[Куплет 5]\n// Егер біз әділ болсақ //\nТыныштық, керемет болар, соны қалаймыз біз."},{"id":586,"title":"Өткен іске өкініп","text":"[Куплет 1]\nӨткен іске өкініп,\nАлдыңа мен кеп тұрмын.\n// Тапсырдым өмірімді,\nӨзіңе мойын бұрдым. //\n\n[Куплет 2]\nТілімменен, ойменен\nӨлтіріппін талайды.\n// Өзіңменен жүрегім\nБір болуды қалайды. //\n\n[Куплет 3]\nСенсің жасыл жайлауым,\nСенсің тыныш өмірім.\n// Пендемін бір күнәлі,\nКешіре гөр, Тәңірім. //\n\n[Куплет 4]\nМадақтайын тек Сені,\nҚұдіретті Құдайым,\n// Қабыл алшы дұғамды,\nҚызметіңе жарайын. //","songNumber":"189"},{"id":626,"title":"Өтті, міне тағы бір күн","text":"[Куплет 1]\nӨтті, міне тағы бір күн,\nБітпейді сергелдең.\nБір-біріне ұқсас әр күн,\nИсасыз жүргенде.\nАлайда мен жарықтамын,\nҚуанышта, қайғыда.\nЖүрегімде тыныштық,\nИсамен болғанда.\n\n[Припев 1]\nТәңірім Сен, о, Иса!\nМаған Өзіңсің керегі.\nТәңірім Сен, о, Иса!\nСенімен болғым келеді.\n\n[Куплет 2]\nҰмытпаймын мейріміңді,\nЖаралы қолыңды.\nӨзгерттің Сен өмірімді,\nКөрсеттің жолымды.\nКездесер күн келер әлі,\nКөремін Өзіңді.\nСол күн Сені көрер бәрі,\nТүсінер сөзіңді.","songNumber":"285"},{"id":350,"title":"Пана","text":"[Куплет 1]\nАл мені, қанатыңа,\nСақташы, қолыңмен Құдіретті!\n\n[Припев 1]\nТеңіз долданып, дауыл тұрса,\nСенімен самғайм(ын) жоғарыда.\nӘке, Патшасың тасқынға да,\nСен біргесің, білем(ін), Құдайым!\n\n[Куплет 2]\nТыным табам, тек Мәсіхте,\nСенемін құдіретіңе Сенің!","songNumber":"78","alternateTitle":"Ал мені қанатыңа"},{"id":12,"title":"Патша ағзам","text":"[Куплет 1]\nКешіріп Сен\nМенің жазамды тарттың\nқабылдап Сен\nазап шектің\nболсын деп жаным сау\nӨмір рухын сыйладың\nӨліп, қайта Сен тірілдің\n\n[Припев 1]\nНеткен ғажап махаббат бұл\nмен үшін жанн қиған\nНеткен ғажап махаббат бұл\nмәңгі өмір сыйлаған\nҚастерлеймін Сені Ием\n\n[Бридж 1]\n// Патша ағзам тағзым Саған! //","copyright":"1996 воршиптогетер.ком сонгс"},{"id":534,"title":"Патшалардың патшасы","text":"[Куплет 1]\nПатшалардың патшасы,Атың мадақталсын!\nПатшалардың патшасы,Атың мадақталсын!\nИса! Құтқарушым,Атың мадақталсын.\nИса! Құтқарушым,Атың мадақталсын.\n\n[Куплет 2]\nПатшалардың патшасы,Атың мадақталсын!\nПатшалардың патшасы,Атың мадақталсын!\nИса - Күннің нұры, Атың мадақталсын!.\nИса - Күннің нұры, Атың мадақталсын!.\n\n[Куплет 3]\nПатшалардың патшасы, Атың мадақталсын!\nПатшалардың патшасы, Атың мадақталсын!\nИса - Патшасың Сен, Атың мадақталсын!\nИса - Патшасың Сен, Атың мадақталсын!\n\n[Куплет 4]\nПатшалардың патшасы, Атың мадақталсын!\nПатшалардың патшасы, Атың мадақталсын!\nИса кешірдің Сен, Атың мадақталсын!\nИса кешірдің Сен, Атың мадақталсын!","songNumber":"286"},{"id":254,"title":"Патшалық, салтанат","text":"[Куплет 1]\nПатшалық салтанат\nҰлылық жарқырап\nБәрі ән салсын\nҒаламға жар салсын!\nӨзін нұрға бөлеп\nЖасырынды түнек\nЕстіп үнін Оның,\nЕстіп үнін Оның\n\n[Припев 1]\nИеміз - ұлы!\nӘнге сал бірге, Ол - ұлы!\nБарлығы көрсін,\nБілсін Ол - ұлы!\n\n[Куплет 2]\nҒасырдан ғасырға\nБарлығы қолында\nБасы Ол соңы да, басы Ол соңы да\nҮшбірліктегі Ол\nӘке Рух және Ұл\n«Арыстан» да Өзі\nКелген болып «Қозы»\n\n[Бридж 1]\n// Есімі ең жоғары\nБар мадаққа лайықты,\nЖан дүнием жырласын,\nОл - ұлы! //"},{"id":893,"title":"Пәк жүрек соны сұраймын","text":"[Куплет 1]\nПәк жүрек,тағзым ететін пәк жүрек,\nКөкке жететін пәк жүрек, соны сұраймын!\nПәк жүрек,бәрін сүйетін пәк жүрек,\nАдал ниетті пәк жүрек, соны сұраймын!\n\n[Припев 1]\n// Тас жүрегімді жібіт,\nБерші Өзің сенім үміт,\nБолсыншы, ой-санам тыныш!\nШақырам Тәңір Сені,\nҚаныңмен тазарт мені,\nСұраймын Сенен пәк жүрек! //","songNumber":"18"},{"id":895,"title":"Періште көкте Тәңірді даңқтайды","text":"[Куплет 1]\nПеріште көкте Тәңірді даңқтайды,\nҰлының ұлысын мадақтайды, мадақтайды.\n// Мәңгілік даңқ, мәңгілік даңқ,\nМәсіхке даңқ, // атақ пен даңқ // .\n\n[Куплет 2]\nПеріште әуенімен біріккім келеді,\nХалқыңмен қосыла дәріптеймін, дәріптеймін.\n// Жеңімпаз, даңқты Исаға қуанып,\nЖүрегім шаттанып // әндетемін // .\n\n[Куплет 3]\nЖердегі қауымың күтеді Өзіңді,\nКүйеу жігіт келер күнді аңсайды, күнді аңсайды.\n// Пәк, таза қалыңдық даяр тұр күтумен,\nЖүрегі шаттанып, // мадақтайды // .\n\n[Куплет 4]\nМәсіх Құдай Ұлы, Ол мәңгі Патшамыз,\nКөкке әкетем деген уәдесін сақтайды.\n// Жүрегім Тәңірді, Иса Мәсіхті,\nДаңққа лайықтыны // мадақтайды // .","songNumber":"53"},{"id":616,"title":"Періште көрінді","text":"[Куплет 1]\nПеріште көрінді, тас домалатылды,\nӨлім қашты, жеңді, Ол тірілді!\nОл тозақтан күшті, Ол өлімнен күшті,\nЖасасын Иса! Ол тірілді!\n\n[Куплет 2]\nҚорқынышты басып, үрейді қуады,\nҚорқыныштан күшті, біздің Иса!\nБізді жұбатады, үрейді басады,\nЖасасын Иса! Ол тірілді!\n\n[Куплет 3]\nКүнәдан азатпыз, бақытты баламыз,\nКүнәдан босатты, біздің Иса!\nОл күнәдан үстем, Ол өлімнен күшті,\nЖасасын Иса! Ол тірілді!","songNumber":"287"},{"id":995,"title":"Рақмет, анам, сен мені қатты сүйесің","text":"[Куплет 1]\nРақмет, анам, сен мені қатты сүйесің,\nҚарным аш болғанда тамақ бересің"},{"id":764,"title":"Рақмет, Әкем, маған тамақ бердің","text":"[Куплет 1]\nРақмет, Әкем, маған тамақ бердің,\nРақмет, Әкем, Сен мейірімдісің!"},{"id":976,"title":"Рақмет, Иеміз Иса","text":"[Куплет 1]\nРақмет, Иеміз Иса,\nРақмет, Иеміз Иса,\nРақмет, Иеміз Иса,\nСен осындасың!\nСен қайта тірілдің,\nСен қайта тірілдің!\nРақмет, Иеміз Иса,\nСен осындасың!"},{"id":909,"title":"Рақымдылық","text":"[Куплет 1]\nРақымдылық, Сен құтқардың\nМені азап құрдымынан.\nӨлі едім, тірілдім ғажап,\nЗағип едім, көрдім нұр.\n\n[Куплет 2]\nЖүрекке алдымен үрей берді,\nСоңынан тыныштық берді.\nКөз жасыммен жудым қасіретімді,\nМейірің аққан теңіздей.\n\n[Куплет 3]\nСөздеріне Тәңір сенем,\nОл - берік менің қамалым.\nОл - бөлшегім, сенімді қалқаным,\nЖүріп өтер жолымда.\n\n[Куплет 4]\nАз тартпадым қасірет пен\nҚайғы-мұңды мен.\nМенімен дәйім болдың сонда,\nЖетеледің мені үйге.\n\n[Куплет 5]\nОндаған мың жылдар өтер,\nҰмытармыз өлімді.\nҚұдайға ән саламыз біздер,\nЕң алғашқы күндей.","songNumber":"166"},{"id":623,"title":"Рақымы мол Әкем","text":"[Куплет 1]\nРақымы мол Әкем, тек Өзіңе келем,\nӨзіңді шын сүйем, Иса Ием.\nКүнәмді ақтадың, мәңгіге сақтадың,\nШындыққа бастадың, Иса Ием.\n\n[Припев 1]\nИсаны сүйемін, сөздері киелі,\nЖүрекке тиеді,\nРақымы мол Әкем, тек Өзіңді сүйем,\nТек Өзіңді күтем, Иса Ием.\n\n[Куплет 2]\nИса әділ Қазы, халқың Саған разы,\nТіршіліктің басы, Иса Ием.\nДұғамен егілем, алдыңда иілем,\nТек Өзіңді сүйем, Иса Ием.\n\n[Припев 2]\nИсаны сүйемін, сөздері киелі,\nЖүрекке тиеді,\nИса әділ Қазы, халқың Саған разы,\nТіршіліктің басы, Иса Ием.\n\n[Куплет 3]\nӨмірсің Сен мәңгі, салтанатты, сәнді,\nАйтам мадақ әнді, Иса Ием.\nҚасиетті қаның, Өз қолыңда жаным,\nСенсің менің әнім, Иса Ием.\n\n[Припев 3]\nИсаны сүйемін, сөздері киелі,\nЖүрекке тиеді,\nӨмірсің Сен мәңгі, салтанатты, сәнді\nАйтам мадақ әнді, Иса Ием.","songNumber":"33"},{"id":160,"title":"Рақымын төгіп құтқарды бізді","text":"[Куплет 1]\nРақымын төгіп құтқарды бізді\nТозақтың мәңгі отынан.\nҚұтқарды бізді жан-рухымызды\nШайтанның шырмауынан.\n\n[Припев 1]\nАлғыс Саған, алғыс Саған.\nЖасасын Иса, мәңгіге Иса,\nМәңгіге Иса - Жеңімпаз!\n\n[Куплет 2]\nШайтанды жеңді Өз жанын қиып,\nҚағылып айқыш ағашта.\nКиелі қанын біз үшін төгіп\nТазартты күнәмыздан.\n\n[Куплет 3]\nТозақтын кілтін қолына алды.\nМәңгіге Иса - Жеңімпаз.\nМәңгілік өмір сыйлады бізге\nКөктегі алтын сарайды.","songNumber":"125"},{"id":38,"title":"Рақымың Сенің Құдай","text":"[Куплет 1]\n// Рақымың Сенің - Құдай,\nтөгіледі аспаннан!\nРақымың Сенің - Құдай,\nтөгіледі аспаннан! //\n\n[Предприпев 1]\nАллелуйя, мадақ - Саған!\nАллелуйя, алғыс - Саған!\nАллелуйя - рақымыңа!\nАллелуйя - махаббатыңа!\n\n[Припев 1]\nМадақтаңдар жерде де!\nМадақтаңдар көкте де!\nМадақтаңдар - Құдайды!\nМадақтаңдар - бар елдер!","songNumber":"123"},{"id":673,"title":"Рахмет Құдай жемістер үшін","text":"[Куплет 1]\nРахмет Құдай жемістер үшін,\nРахмет Құдай жемістер үшін,\nРахмет Құдай жемістер үшін.\nБізді қамқорлайсың!"},{"id":723,"title":"Рахмет Саған Иса","text":"[Припев 1]\nРахмет, Саған Иса,\nМен Сені сүйемін!\nСен менің қуатым,\nМен Саған табынамын!\n\n[Куплет 1]\nӘкем, Әкем!\nРахмет Саған,Иса үшін!\nИса, Иса!\nРахмет Саған, осы өмірге!\nКиелі Рух! Киелі Рух!\nМен Саған өлең айтамын!\n\n[Куплет 2]\nСенің атың, Сенің атың,\nМадақталсын әр жерде!\nСенің Рухың, Сенің Рухың,\nЖүрегімде болсын!\nСенің Сөзің, Сенің сөзің,\nЖетелейтін Сөз болсын!","songNumber":"32"},{"id":200,"title":"Рахмет Саған, Құдай!","text":"[Куплет 1]\n//  Рахмет Саған, Құдай!\nРахмет Саған, Құдай!\nРахмет, О, Құдай Ием!\nИса үшін рахмет!  //\n\n[Припев 1]\n//  Енді менің күшім бар!\nМенің байлығым бар!\nМен үшін Иса өмірге келді!  //\nРахмет!","songNumber":"144","copyright":"1978 Интегриты'с Хосанна! Мусик"},{"id":223,"title":"Рахмет Саған Құдай Әке","text":"[Куплет 1]\nРахмет Саған - Құдай, Әке!\nРахмет Саған - Құдай, Әке!\nРахмет Саған - Құдай, Әке!\nРахмет Саған - Құдай, Әке!\n\n[Припев 1]\nМен ешқашан ұмытпаймын, Сенің - махаббатыңды!\nМен ешқашан ұмытпаймын, рақымыңды!\nМен ешқашан ұмытпаймын, Сенің - махаббатыңды!\nМен ешқашан ұмытпаймын, рақымыңды!\n\n[Куплет 2]\nРахмет Саған - Тәңір Иса!\nРахмет Саған - Тәңір Иса!\nРахмет Саған - Тәңір Иса!\nРахмет Саған - Тәңір Иса!\n\n[Куплет 3]\nРахмет Саған - Киелі Рух!\nРахмет Саған - Киелі Рух!\nРахмет Саған - Киелі Рух!\nРахмет Саған - Киелі Рух!\n\n[Бридж 1]\nРахмет Саған - Құдай, Әке!\nРахмет Саған - Тәңір Иса!\nРахмет Саған - Киелі Рух!\nРахмет Саған!\n\n[Бридж 2]\nРахмет Саған!\nРахмет Саған!\nРахмет Саған!","alternateTitle":"Мен ешқашан ұмытпаймын Сенің махаббатыңды"},{"id":246,"title":"Рәббім Иса","text":"[Куплет 1]\nРәббім Иса, Саған көп алғыс айтамыз,\nСен біз үшін бұл дүниеге келгеніңе.\nКиелі рухыңмен бізді аяладың,\nКиелі қаныңмен жуып тазаладың.","songNumber":"54"},{"id":232,"title":"Ризамын","text":"[Куплет 1]\nСен , жалғыз Сен\nСен лайықсын өмірімде\nИса жүрегімді толықтай өзгертші\nСен , жалғыз Сен\nСен шындықпен жетелейсін.\nИса Саған алғысымды айтамын.\n\n[Припев 1]\nРизамын, ризамын, ризамын\nСаған Тәңір\nРизамын жалғыз Саған Иса ризамын"},{"id":418,"title":"Ризамын","text":"[Куплет 1]\nКүнәмді Сен кешірдің,\nМахаббатыңды төктің.\nСенің құшағыңда таптым тыныштық.\nРизамын Саған, Тәңір,\nСенің жарылқауыңа.\nӨз жүрегімді Саған мен арнаймын\n\n[Припев 1]\nРизамын, ризамын, Тәңір\nРизамын Тәңірім, Иса\n\n[Куплет 2]\nБіз үшін айқышта,\nҚұрбандық болдың Сен.\nӨзің өліп мәңгі өмір сыйладың\nКиелі қаның Сенің\nКүнәдан тазартты,\nСенің алдыңа келіп бас ием."},{"id":392,"title":"Ризамын Саған Имануил","text":"[Куплет 1]\nАйқышқа Сен мен үшін бардың.\nАйқышта Сен шегелендің.\nРизамын Саған Имануил\nСаған Имануил! Саған Имануил!\n\n[Припев 1]\n// Иса ақтадың мені.\nИса тазарттың мені.\nИса боссатың мені.\nБоссаттың мені Киелі қаныңмен! //\n\n[Куплет 2]\nТөгілген Сенің Қаның қымбат.\nӘкемен мені таныстырдың.\nРизамын Саған Имануил!\nСаған Имануил!","alternateTitle":"Айқышқа, Сен мен үшін бардың!"},{"id":121,"title":"Ризамын Саған, ризамын","text":"[Куплет 1]\nӨмірдің мәні жалғыз Сен,\nСенсіз ғұмырдың сәні жоқ.\nСен мен үшін құн төледің,\nИса Ием менің құрбым.\nҚандай жағдайға түспесем,\nСен қолыңмен жетелейсің,\nИса төзушім жолымсың,\nСаған қадамымды бастым.\n\n[Припев 1]\nСенің алдыңда тізе бүгіп,\nБасымды ием!\nСаған табынам, жүзіңді аңсаймын,\nТәңірім Саған Иса алғысымды айтам,\nРизамын, Саған ризамын!"},{"id":303,"title":"Рухыңмен асыл","text":"[Куплет 1]\nРухыңмен асыл\nкеудемді менің толтырдың,\nСөзіңмен шуақ\nкөңіліме менің нұр құйдың.\nТүбіне күнә көлінің батып кетер ем,\nҚұнымды төлеп,\nмен үшін азап шекпесең.\n\n[Припев 1]\nСүрінсем, сүйеп,\nЖығылсам, қайта тұрғыздың,\nӘлсіреп әлім,\nҚұласам, қуат-күш құйдың.\nБетіме баспай,\nҚатемді менің кешіріп,\nЖалтақтап, жалғыз қалғанда, маған,\nЖаныма келдің жүгіріп.\n\n[Куплет 2]\nСөздерің Сенің\nжолдарға жарық нұр шашқан,\nМейірің Сенің\nадамға құшақ кең ашқан.\nҚұрбан ғып Ұлды\nкүнәмыз үшін бердің Сен.\nАдамзат барар\nалдыңа жолды Сол ашқан.","songNumber":"167"},{"id":243,"title":"Сабан төселген астауда","text":"[Куплет 1]\nСабан төселген астауда,\nБала жатыр шырайлы.\nАнасы отыр қасында,\nҚуанышпен қарайды.\n\n[Припев 1]\nОл аспаннан келген,\nҚұтқарылу сыйын берген,\nҚұдай Ұлы - Мәсіх,\nЖұмақтың жолы ашық.\n\n[Куплет 2]\nАстауда Ол неге жатыр,\nМалдарға жем беретін?\nОсы жерге қиналғандар,\nЕмін еркін келетін.\n\n[Куплет 3]\nОл Патшасы бар әлемнің,\nҰлы сот боп келеді.\nЖер бетіндегі бар елдің,\nЖүректерін көреді.","songNumber":"166"},{"id":117,"title":"Саған келіп","text":"[Куплет 1]\nСаған келіп тағзым\nЕтіп,\nМадақтаймын Сені\nБүкіл шаттық Сенде\nҒана.\nЕш нәрсеге, еш кімге\nСені теңей алмаймын.\nСаған сиыну бақытым менің"},{"id":66,"title":"Саған мадақ ән айтқанда","text":"[Куплет 1]\nСаған мадақ ән айтқанда\nТілімнен бал тамады\nСаған мадақ ән айтқанда\nКөздерім нұрланады\nСаған мадақ ән айтқанда\nЖүрегім шаттанады\nШаттанам тағы шаттанам\nТәңірім мен Саған\n\n[Припев 1]\nҰлылығыңды жырлау үшін әрдайым\nЖүрегім менің қуанып мадақтасын\nСені Құдайым\nҚұдіретті Тәңірім Сен қасымдасың\nСені мадақтап жырлаудан\nЖаным менің шаршамайды"},{"id":611,"title":"Саған теңдес ешкім жоқ","text":"[Куплет 1]\nО Иса, бүкіл мадақ Саған\nҒажайып істерің Сенің шексіз!\nҰлысың теңдесі жоқ Патша\nӘр жүрек табынып,  Саған келсін\n\n[Предприпев 1]\nАйқышта қиналдың мен үшін Иса\nҚұрбандыққа шалындың\nКиелі қаның төгілді мен үшін\nСен бізді ақтап алдың\n\n[Припев 1]\nСаған теңдес ешкім жоқ\nСаған теңдес ешкім жоқ\nСаған теңдес ешкім жоқ\nБүкіл мадақ Саған\nСаған теңдес ешкім жоқ\nСаған теңдес ешкім жоқ\nСаған теңдес ешкім жоқ"},{"id":998,"title":"Сау болыңдар достарымыз","text":"[Куплет 1]\nСау болыңдар достарымыз,\nҮйімізге қайтамыз.\nБірақ жалғыз бармаймыз,\nБіз Құдаймен бірге боламыз"},{"id":741,"title":"Сәби дүниеге келді","text":"[Куплет 1]\nСәби дүниеге келді,\nОл дүниеге келді.\nСәби дүниеге келді,\nОның аты - Иса,\nОның аты - Иса!"},{"id":570,"title":"Сәлем! Бүгін міне жиналдық!","text":"[Куплет 1]\nСәлем! Бүгін міне жиналдық!\nТілейміз сіздерге амандық!\nСәби күлкісі лайым естілсін,\nТәңір қуанышқа жеткізсін.\nЕшкімді көмексіз қалдырма,\nЕшкімді жазықсыз жазғырма.\nТыныштықты тілейміз қауымға,\nБарлық бауырларға!\n\n[Припев 1]\nСәлем бауырларға! Сәлем қауымға да!\nШаттыққа толып жырлаймыз.\nТілеп ақ жүректен, таза, пәк ниетпен,\nТыныштық сұраймыз!\n\n[Куплет 2]\nЛайым Тәңіріміз сақтасын,\nШаңырағымыз шайқалмасын.\nСенімің бекісін ұзағынан,\nСақ бол дұшпанның тұзағынан.\nСәлем сіздерге біз жолдаймыз,\nСәлем сіздерден қабылдаймыз.\nТыныштықты тілейміз қауымға,\nБарлық бауырларға!","songNumber":"220"},{"id":54,"title":"Сәлем біздің Раушан!","text":"[Куплет 1]\nСәлем біздің Раушан!\nСенің келгенің жақсы.\nҚұдай скеі сүйеді,\nБіз бұған қуанамыз!"},{"id":780,"title":"Сәлем Саған, сәлем Саған","text":"[Куплет 1]\nСәлем Саған, сәлем Саған,\nСәлем Саған, сәлем Саған.\nСаған сәлем бүкіл әлем.\n\n[Куплет 2]\nТәңірден бізге сәлемді\nКиелі Рух бізге әкелді.\nҚұдай Сөзі Иса келді,\nЖарылқасын барлық елді.\nҚұдай Әкеме еркелеймін,\nКиелі Рухпен би билеймін.\nАлғыс Саған.\n\n[Припев 1]\n// Сәлем саған Қазақстан,\nСәлем саған биік аспан,\nСәлем саған туған жерім, туған елім\nСаған сәлем бүкіл әлем // .\n\n[Куплет 3]\nМадақтаймын Иса Иемді.\nБәрімізді Ол сүйеді.\nТыныштық бізге сыйлайды,\nМахаббаты таусылмайды.\nҚұдай Әкеме еркелеймін,\nКиелі Рухпен би билеймін.\nАлғыс Саған.","songNumber":"126"},{"id":1011,"title":"Сен айттың","text":"[Куплет 1]\nАлысамын түкке тұрмас жансың деген ойлармен\nЛайықсыз деп ішкі дауыс үн қатады сыбырмен\nСансыз күдік торлап менің тұмшалайды санамды\nАрашалап алшы мені жойшы жаман ойларды\n\n[Припев 1]\nСүйемін дейсің егер торықсам\nСенім арт дейсің егер қорықсам\nКөтерем дейсің кенет сүрінсем\nБіргемін дейсің жалғыз сезінсем\nСенемін, сенемін,\nСөзіңе сенемін\n\n[Куплет 2]\nҚымбатпын мен көз алдыңда алтыннанда бағалы\nТек өзіңмен жылынады жүрек тыным табады\n\n[Припев 2]\nСүйемін дейсің егер қорықсам\nСенім арт дейсің егер қорықсам\nКөтерем дейсің кенет сүрінсем\nБіргемін дейсің жалғыз сезінсем\nСенемін сенемін\nСөзіңе сенемін\n\n[Бридж 1]\nАқтарып мен бар сырымды\nЖығыламын алдыңда\nЖеңісім де жеңілісім тек өзіңнің қолыңда"},{"id":174,"title":"Сен әлемді құтқардың","text":"[Куплет 1]\nСен - әлемді құтқардың, түнектен шығардың!\nӨшкен жүректерді, жақтың, үміт бердің!\nБіз Саған - табынамыз, өміріміз, Саған қымбат!\nСаған - алғысымды, айтам, мадақтаймын!\n\n[Припев 1]\n// Алғыс Саған - Тәңір, алғыс Саған - Иса!\nМейірімділігің шексіз, махаббатың мол! //","songNumber":"168"},{"id":364,"title":"Сен Бағушым менің Иса Мәсіх","text":"[Куплет 1]\n// Сен Бағушым менің Иса Мәсіх,\nӨмірім Сенімен толық Ием, о, Тәңірім!\nТұнық суға мені апарасың,\nҚараңғы шатқалда жүрсемде, мен, еш қорықпаймын! //  .\n\n[Припев 1]\n/// Сен - Тәңір Ием! ///\nИә, Сен - Тәңір Ием!\n\n[Бридж 1]\nҚауымыңды Сен - Өзің орнаттың,\nБіз бірлікте Сені мадақтаймыз!\n////// Сен - Тәңір Ием! //////\nИә, Сен - Тәңір Ием!"},{"id":229,"title":"Сен дегенде шөлім қанбайды","text":"[Куплет 1]\nСен дегенде,шөлім қанбайды !\nСен дегенде,ашпын әрқашан !\nСен дегенде,шөлім қанбайды !\nСен дегенде,ашпын әрқашан !\n\n[Припев 1]\nСезіуім керек,Сенің Рухыңды.\nНөсер-жауыныңды төк, шөлірткен жеріме!"},{"id":1015,"title":"Сендей Әке","text":"[Куплет 1]\nСендей Әке бар ма екен бұл жерде?\nЖүресің Сен жанымда әркезде.\n// Қанатыңмен қалқалайсың әлдилеп,\nҚорғанышым боласың Сен әр жерде. //\n\n[Припев 1]\n// Сендей Әке табылмас маған! //\nСендей Әке табылмас маған!\n\n[Куплет 2]\nМейіріміңе шомылып мен келем,\nМаған деген рақымың мол екен.\n// Әке болып жүрегімді аштың Сен,\nМәңгілікке құшағыңа алдың Сен! //"},{"id":579,"title":"Сендей ешкім жоқ","text":"[Припев 1]\nСендей ешкім жоқ\nЖүрегім менің тебіренттің\nӨмір бойы іздесем де таппаймын\nИем, Сендей ешкім жоқ!\n\n[Куплет 1]\nМейірімің судай тасқындап\nЖарамызды емдеді\nЖарамызды аман сақтайтын\nСендей ешкім жоқ!"},{"id":680,"title":"Сендей кім бар","text":"[Куплет 1]\nСендей кім бар?\nҚұрбандық Тоқтысы мадаққа лайық?\nСиынамыз әндетіп Саған, әлем Иесі.\nМадақтаймын\nСені жаныммен Патшам\nКүні бойы әнмен тынбай!\nМадақтасын\nБар әлем халықтары\nАтыңды даңққаа бөлеп Ием!"},{"id":353,"title":"Сендерге тыныштық","text":"[Куплет 1]\nСендерге тыныштық қалдырам,\nЕшкім де бере алмас тыныштық.\nТек қана Тәңір сыйлайтын\nтыныштық.\nЖанға тыным, шапағат.\nСендерге тыныштық қалдырам.","songNumber":"169"},{"id":442,"title":"Сенемін, мен сенемін ұлы Құдайыма","text":"[Куплет 1]\nСенемін, мен сенемін ұлы Құдайыма,\nРақымын төкті Құдай жанарыма.\n\n[Припев 1]\nЖан-тәніммен Жаратқан\nИемді мадақтаймын,\nШын жүректен ардақтайм\nҚасиетті атын.\nЖан-тәніммен Жаратқан\nИемді мадақтаймын,\nЖасаған жақсылығын ұмытпаймын.\n\n[Куплет 2]\nОл бізді күнәмыздан тазалайды,\nІсімізге карап есесін қайтармайды.\n\n[Куплет 3]\nҰмтылыңдар бауырлар, Құдайдың жолына,\nМәңгілік шынайы жол Иса Иемізде.","songNumber":"146"},{"id":644,"title":"Сенемін Саған","text":"[Куплет 1]\nӘрбір арманымды беремін\nАлдына әкеп Сенің тағыңның.\nӨмірімде шалыс бассам да,\nӨзгермейді махаббатың Сенің.\nКүрескім келді өмірім үшін\nҚалжырап қалдым кетті бар күшім.\nМықты Жауынгер Жеңімпаз Патшам\nЖеңіске жетем менің Жақтаушым.\n\n[Припев 1]\nТауларды қозғалтпасаң,\nҚалағанымдай мен.\nТеңізді Сен ашпасаң,\nАлдымда долданған.\nЕгер жауап қатпасаң,\nЖалбарынғанда мен,\nСенемін, сенемін, сенемін Саған.\n\n[Куплет 2]\nЕртеңгі күн әкелер нені?\nБәрін білесің, белгілі бәрі.\nМенің өмірім, демімсің менің,\nЖолыңмен жүрем Сенің әр күні.\n\n[Бридж 1]\nТыныштығым мен күшім,\nСүйенішімсің Сен.\nСен менің негізімсің\nБерік жартасымсың.\nҒажап жолдарың Сенің\nБәрінен жоғары.\nБүкіл әлем қолыңда\nБәрінің Иесі."},{"id":420,"title":"Сен - жанымды тыныштыққа кіргіздің","text":"[Куплет 1]\nСен - жанымды тыныштыққа кіргіздің,\nСен жүрегімді нұрыңа кенелттің!\nСен босаған көңілімді толтырдың,\nСүйіспеншілігіңмен тірілттің!\nСен мол мейірімділігіңмен келдің,\nСен аса шыдамдылығыңмен күттің,\nСен шексіз рақымдылығыңды төктің,\nШаттыққа қуанышқа бөледің.\n\n[Припев 1]\nӨмір жолына бірге Өзіңмен,\nБолашаққа жол бастап сеніммен.\nРизамын бірінші тек Саған,\nНе болсада менің қасымда.\nСен мәңгілік Әкемсің\nСенсің Иесі жүрегімнің\nСен шексіз рақымдысың\n// Рахмет Саған бәрі үшін! //\n\n[Куплет 2]\nСен жүрегімдегінің бәрін көрдің\nСен жұбаныш маған керегін білдің\nСен мәңгілікке жанымды құтқардың\nЖанымды мәңгілікке шығардың\nСен жаманды жақсымен білдірдің\nСен жүрекке кешірімді бергіздің\nСен мәңгілік Өзімдікі деп айттың\nЕштемеме қарамай сүйе алдың."},{"id":224,"title":"Сен жарылқаудың жолы","text":"[Куплет 1]\nСен жарылқаудың жолы,\nИеміз бізге өсиет еткен.\nСен арқылы мадақтайт барлық ел,\nБәрі Тәңірге келет.\n\n[Куплет 2]\nСен жарылқаудың жолы,\nИеміз бізге өсиет еткен.\nСен арқылы мадақтайт барлық ел,\nИеге қызмет етеді.","songNumber":"170"},{"id":670,"title":"Сен киелісің","text":"[Куплет 1]\n// Сен киелісің, //\n// Сен күштісің, //\n// Сен лайықсың, //\n// Бар мадаққа. //\n\n[Куплет 2]\n// Мен еремін, //\n// Мен тыңдаймын, //\n// Сені сүйемін, //\nӘр күнімде.\n\n[Припев 1]\nӘн саламын, / Патшалар Патшасы,\nСиынамын, / Иелер Иесі,\nЛайықты / Сен күшті Құдай,\nПатшаға / Бәрінің Иесі.\nМен сүйемін, / Сен Имануил,\nҚұрметтейм, / Сен Ұлы Есім,\nБас иемін / Менің Патшамсың\nАлдында. / Сен Тоқтысың.\n\n[Припев 2]\nӘн саламын, / Тірісің Құдай,\nСиынамын, / Рақымдысың Сен,\nЛайықты / Патшалығың мәңгі,\nПатшаға. / Мәңгі Бар Болушы.\nМен сүйемін, / Сен Алғашқы, Соңғысың,\nҚұрметтейм, / Басы да, Соңы.\nБас иемін / Құтқарушым Мәсіхсің,\nАлдында. / Жан Досым Өзің.\n\n[Бридж 1]\nТыныштық Иесі,\nСен үшін өмір сүремін.","songNumber":"171","copyright":"1999 Хигхер Праисе"},{"id":663,"title":"Сен күштісің","text":"[Куплет 1]\nМахаббат көктен келді,\nМомын Ол айқыш алды.\nКүнәм мен Сен ұятты алдың,\nЖеңіспен Сен тірілдің.\n\n[Куплет 2]\nАдалсың Сен әрқашан,\nДауылда да, отта да,\nБұл шындық: азат етті,\nИса Мәсіх мендегі.\n\n[Куплет 3]\nСен күштісің,\nСен күштісің,\nКүнәны жеңдің, құтқардың Сен.\nБұл сөз шындық: Мәсіх тірі!\nИса бәрінің Иесі.\n\n[Куплет 4]\nШексізсің, мәңгі тірі,\nҮмітім, қорғанышым,\nАдасқанды құтқаруға,\nКелдің Сен құн төлеуге.\n\n[Куплет 5]\nАтыңды біз асқақтатамыз,\nАсқақтатамыз, асқақтатамыз.","songNumber":"172","alternateTitle":"Махаббат көктен келді"},{"id":170,"title":"Сен қастерлісің, Сен қасиеттісің","text":"[Куплет 1]\nСен қастерлісің, Сен қасиеттісің,\nСен пәк боп туылып, Сен азат еттің.\n\n[Припев 1]\nИса,Иса,Тәңірім боп қорғашы мені\nИса,Иса, Ием болып жетелеші.\nИса,Иса,Тәңірім боп қорғашы мені,\nИса, жетелеші, қорғашы!"},{"id":1007,"title":"Сен неткен ғажайыпсың","text":"[Куплет 1]\nСен неткен ғажайыпсың,\nТәңірім бәрінен әсемсің!\nЖүрегімде нәзіктік, жанымда сұлулық,\nӨміріңде тек, адалдық!\nНиетімде тазалық, тәнімде ұлылық,\nСенен басқа барма байлық?!\n\n[Припев 1]\nТәңірім Сенің сыйлағаның\nНиеті жан дүниеңнің, менің байлығым!\nҚазына сөзің мен шындығың,\nТірілдім Рухыңмен Сенің,\nНе теңес еді, нелер жетеді,\nСенң берген тірі байлығыңмен!\n\n[Куплет 2]\nСен бәрінен қымбатсың,\nТәңірім керемет Әкесің!\nСүйгеніңде шексізсің,сөзіңде шындықсың\nІсіңде мәңгі,әділсің!\nКешіргенде кексізсің,еркіңде беріксің,\nҚұрметке мәңгі лайықсың!"},{"id":272,"title":"Сенсіз Әке","text":"[Куплет 1]\nСенсіз Әке, өмір сәнсіз, өмірдің мәні жоқ!\nСенсіз Иса, өмір сәнсіз, өмірдің құны жоқ!\n\n[Припев 1]\nМахаббатым дейсің Сен! Махаббатым дейсің Сен!\nМахаббатым дейсің Сен, мені әр күнде!\nСүйіктім деп, Сен мені, Сүйіктім деп, Сен мені,\nСүйіктім деп, Сен мені, құшағыңа аласың!\n\n[Припев 2]\n// Еркетайым дейсің Сен! Еркетайым дейсің Сен!\nЕркетайым дейсің Сен, мені әр күнде!\nАлтыным деп, әр күнде! Алтыным-деп, әр күнде!\nАлтыным деп, әр күнде, бағалайсың Сен! //\n\n[Припев 3]\nЕркетайым дейсің Сен\nЕркетайым дейсің Сен\nЕркетайым дейсің Сен\nмені әр сәтте\nАлтыным деп әр күнде\nАлтыным деп әр күнде\nАлтыным деп әр күнде\nбағалайсың Сен\nСағынышым дейсің Сен\nСағынышым дейсің Сен\nСағынышым дейсің Сен\nҚұшағыңды жая\nАңсағаным деп мені\nАңсағаным деп мені\nАңсағаным деп мені\nасыға күтесің\n\n[Бридж 1]\nРизамын Саған Әкетайым\nРизамын Саған Иса\nРизамын Саған Әкетайым\nРизамын Саған Иса\n/// Сүйемін Сені Әке ///\nӨмірімсің Сен\n/// Сүйемін Сені Иса ///\nМахаббатымсың"},{"id":1024,"title":"Сенсің Құдайым","text":"[Куплет 1]\n// Дәл қазір ортамыздасың\nСиынамын, сиынамын.\nСен бізді өзгертіп жатсың,\nСиынамын, сиынамын. //\n\n[Припев 1]\n// Уәдеңе сай өмірді бердің,\nТүнекті жарып Нұр болып келдің,\nИә, Ол Сенсің - Құдайым. //\n\n[Куплет 2]\nТолтыршы әрбір жүректі,\nСиынамын, сиынамын.\nЕмдеші әрбір жүректі,\nСиынамын, сиынамын.\nСөйлеші әрбір жүрекке,\nСиынамын, сиынамын.\nӨзгертші өмірімізді,\nСиынамын, сиынамын.\n\n[Бридж 1]\n// Көрмесемде Сен ғажап жасайсың,\nСезбесемде Сен ғажап жасайсың.\nЖалғасады істерің Құдайым,\nЖалғасады істерің Құдайым. //","alternateTitle":"Дәл қазір ортамыздасың"},{"id":22,"title":"Сен, Тәңірім, күмістен де асыл","text":"[Куплет 1]\nСен, Тәңірім, күмістен де асыл,\nСен, Тәңірім, алтыннан да қымбат.\nСен, Тәңірім, асылдың асылы.\nСен, Бағушым, менің Құдайым!\n\n[Припев 1]\n//  Сенен басқа Құтқарушым жоқ,\nСенен басқа арманым да жоқ,\nСенен басқа үмітім де жоқ.\nСен менің Құдайым!  //","songNumber":"174"},{"id":718,"title":"Сен үшін өмір сүрем","text":"[Куплет 1]\nСен үшін өмір сүрем,\nЖолымсың өмірде мәнді.\nСен жанның суысың,\nБар байлықтан асылсың.\nСен жанның отысың,\nМахаббатымсың мәңгіге,\nСен менің демімсің,\nМенің әнімсің.\n\n[Куплет 2]\nТәңірім Иса,\nБәрінен биіксің,\nӨмірімнің Патшасы.\nИса, алдыңда мен тұрамын.\nЖүрегімді тек Саған\nМен арнаймын","songNumber":"175"},{"id":462,"title":"Сені әнге қосамын","text":"[Куплет 1]\nСені әнге қосамын,\nСаған табынамын,\nСаған мәңгі ризамын,\nҚұтқарғаныңа қуанам.\n\n[Припев 1]\nКөктен жерге келдің, шын өмір беру үшін,\nАсыл қаныңды төктің, құнымды өтедің.\nӨлімнен Сен тірілдің, көкке көтерілдің,\nАтыңды даңқтаймын, Иса Құтқарушым.\n\n[Куплет 2]\nИса Саған сиынамын,\nСені үздіксіз жырлаймын,\nСаған мәңгі ризамын,\nҚұтқарғаныңа қуанам.","songNumber":"51","copyright":"1989 Мараната Праисе, Инк."},{"id":35,"title":"Сені мадақтаймын Иса","text":"[Куплет 1]\nСені мадақтаймын Иса,\nМадақтаймын иса.\nКиелі Атыңды мен\nМадақтаймын!\n\n[Куплет 2]\nСені аялаймын Иса,\nАялаймын Иса.\nКиелі Рухыңды мен\nАялаймын!\n\n[Куплет 3]\nСені сағынамын Иса,\nСағынамын Иса.\nКиелі Сөзіңді мен\nСағынамын!","songNumber":"130"},{"id":250,"title":"Сенім арт, үзбе үмітіңді","text":"[Куплет 1]\nСенім арт, үзбе үмітіңді,\nОйлан тек Иса жайында.\nҮлгі бол ісіңмен басқаға,\nБерілме сен уайымға.\n\n[Припев 1]\nҮмітің қашанда жұбатсын,\nТәңірің сені қуантсын.\nБерік бол сеніміңді сақта,\nЖетесің сонда бақытқа.\n\n[Куплет 2]\nЕгер қайғыға ұшырасаң,\nЖаның күйзеліп жыласаң.\nЕске ал Иса тіл қатады,\nКөз жасыңды құрғатады.\n\n[Куплет 3]\nӘлемді жаратқан Құдайға,\nЖүрекпен сиын ұдайы.\nЖауабын аласың қашанда,\nСиынсаң егер шынайы.","songNumber":"78"},{"id":614,"title":"Сенімен келеді тілдескім","text":"[Куплет 1]\nСенімен келеді тілдескім,\nНағыз жақын жан Досым менің.\n//  Жоғарыдан Сен маған қарап,\nДүрсілін естисің жүректің.  //\n\n[Куплет 2]\nСенімен тілдескім келеді,\nЖеңілдетіп қайғы-мұңымды.\n//  Бұл өмір мені түсінбейді,\nАшамын Саған бар сырымды.  //\n\n[Куплет 3]\nТілдескім келеді Сенімен,\nөйткені алыста достарым.\n//  Қайғымды бөліспей олармен,\nбәрін де Саған мен беремін!  //\n\n[Куплет 4]\nАйналамды түнек басқанда,\nТілдесуді күтем асыға.\n//  Жоғарыдан Сен маған қара,\nСенімді Досым, кел қасыма.  //","songNumber":"176"},{"id":298,"title":"Сенімен кім теңеледі?!","text":"[Куплет 1]\nСенімен кім теңеледі?!\nСенімен кім теңеледі?!\nЖүрегімді Саған беремін.\nИса! Сүйем Сені.\n\n[Припев 1]\nСенімен кім теңеледі?!\nСенімен кім теңеледі?!\nЖүрегімді Саған беремін.\nСенімен кім теңеледі?!","songNumber":"134"},{"id":201,"title":"Сенімен кім теңелер","text":"[Куплет 1]\nСенімен кім теңелер\nЖүрегімді менің қозғадың.\nҚаншама іздесем де О, Тәңір,\nБәрінен де сұлусын!\nМейірімің Сенің мәңгі,\nСауықтыру Сенің қолыңда.\nБалаларыңды сақтап жүрсің Сен.\nСенімен кім теңелер!"},{"id":202,"title":"Сенің алдыңда","text":"[Куплет 1]\nСенің алдыңда,\nТәңірім ғажап өмір сүремін\nСенің қасыңда\nЖеңіс туын биік көтеремін.\nІзгілік заңы, шындықтың таңы\nЖарқырасын мәңгі.\n\n[Припев 1]\nО, Иса, Сен мәңгі тірісің\nҚасиетті, мейірімдісің\nЖүрегімнің төріне қоншы, Құдай\nТірегімсің асқар таудай.\n\n[Куплет 2]\nСаған мәңгілік,\nАрналады менің жүрегім.\nСаған жыр болып,\nАйтылады менің тілегім\nӨмір жолында, алшы қолыңа\nЖетелеші мені."},{"id":365,"title":"Сенің атың мадақталсын жүрегімде","text":"[Куплет 1]\n////  Сенің атың мадақталсын\nжүрегімде, өмірімде Иса!  ////\n\n[Припев 1]\n//  Төгілген Киелі Сенің қаның,\nӨмірімді толықтай өзгертті!\nАйқыштағы шалынған құрбаның,\nЖүрегімнен Ол кетпейді! Иса!  //\n\n[Бридж 1]\n////  Исаның Киелі қаны, ақтады мені мәңгіге!  ////"},{"id":75,"title":"Сенің батаң байытады өмірімді","text":"[Куплет 1]\nСенің батаң байытады өмірімді,\nСенің рухың көтереді көңілімді.\nБір Өзіңе ән айтуға жалықпаймын,\nЖан тербесең көкке ұшып қалықтаймын.\n\n[Припев 1]\nИса, о, Иса, болашақтың қайнар көзі,\nИса, о, Иса, Жаратқанның тірі сөзі.\nИса, о, Иса, өмірімді бағалайды,\nИсаның әр сөзі жүрегімді тазалайды.\n\n[Куплет 2]\nНазар салдың әрбір басқан қадамыма,\nСәуле шашқан нұр бөледің жанарыма.\nҮлгі беріп, тәрбиелеп, қамқорладың.\nМахаббатыңды бізден аямадың.\n\n[Куплет 3]\nСен болмасаң кім бар бізді жетелейтін?\nСен қолдасаң кім бар қарсы келетін?\nҚұдай Ұлы Құтқарушы жанымызда,\nҚуаныш пен мәңгі өмір қолымызда.","songNumber":"57"},{"id":17,"title":"Сенің ғана Есімің мадақталсын","text":"[Куплет 1]\nСенің ғана Есімің мадақталсын,\nЖалған пайғамбарларға сабақ болсын.\nАдасқандар табысып Тәңірменен,\nАңсағаны әркімнің,\nІздегені рухани тамақ болсын.\n\n[Припев 1]\n// Жаратқан Ием, Жарық дүнием!\nЖаным - тәніммен Өзіңді сүйем.\nАлғыс айтамын құтқарғаныңа\nТіземді бүгіп басымды ием. //\n\n[Куплет 2]\nСізді осында Құдай акелді\nКуаныштан айтамыз ой барекелелді\nТөрғе қысылмай отыріныз\nҚұдайды мадақтауға косылыныз","songNumber":"129"},{"id":608,"title":"Сенің Киелі Жүзіңнен","text":"[Куплет 1]\nСенің - Киелі жүзіңнен!\nЖарқын - Киелі жүзіңнен!\nНазарыңнан - Сенің, тастар балқиды!\n\n[Припев 1]\nШарасыздық, өкініш-күнә,\nҚарғыс-кесел, қатерлі жанға!\nНазарыңнан - Сенің, тастар балқиды!\n\n[Бридж 1]\nРахат табам/ын/, Сенің жаныңда!\nРахаттанам, Сенің жайыңда!\nРахаттанам, тек Сенімен - Иса!"},{"id":759,"title":"Сенің махаббатың жарқырап тұр","text":"[Куплет 1]\nСенің махаббатың жарқырап тұр,\nҚараңғыда жарқырап тұр.\nИса, әлемге жарқырашы,\nБізді күнәдан босатшы.\nЖарқырашы, Иса! Жарқырашы Иса!\n\n[Припев 1]\nЖарқырашы, Иса!\nӘлемді жарқыратшы Иса\nБіздің жүректер,\nСенің Рухыңмен толсын.\nТолтыр Иса,\nәлемді рақымдылығыңмен,\nСөзіңді жібер, түнек жарық болсын.\n\n[Куплет 2]\nТәңір мен Саған барамын,\nСенің жаныңда боламын.\nТөгілген қаныңмен ақтадың,\nМәңгілік қасыңда қаламын.\nЖарқырашы, Иса! Жарқырашы Иса!","songNumber":"56","alternateTitle":"Жарқырашы Иса!","copyright":"1987 Маке Вай Мусик"},{"id":654,"title":"Сенің өмір жолыңда","text":"[Куплет 1]\nСенің өмір жолыңда тұр ғалам Патшасы,\nБарлық жерде сені сақтайды.\nӨз қолымен жетелейт Ол ақиқатқа,\nКөзінен Ол етпейді сені таса.\n\n[Куплет 2]\nБіліп ал: Ол бата берет жүретін жолыңа,\nҰлы Құдай сақтайды аман.\nАяқ басқан жеріңде\nТәңір сенімен бірге.\nПатша алдында бүксеңші тізе.\n\n[Куплет 3]\nҚұдай Патшалығы үшін\nБауырларды Ол біріктірді.\nБәрін Иса шақырды,\nБарсаңшы сен Мәсіх Атымен.\n\n[Куплет 4]\nГүлдер сонда жайқалар,\nТәңір Атын дәріптеп.\nЖер де қайта түлейді,\nҚұдайдың құдіреті ұлы,\nҚуатты және заңғар.\nИсамен жеңіс келді бірге.\nҚуат беріп күшімен,\nШуақ шашат Ол әлемге.","songNumber":"179"},{"id":873,"title":"Сенің саяңда","text":"[Куплет 1]\n// Сенің саяңда, көңілім ләззат табар Ием!.\nЛебізің ыстық, жаралы жанға шипа берер!\nКиелі Рухыңды, аңсайды құлазыған жүрек.\nСенсіз өмір баянсыз, қараңғы түнек.\nКиелі Рухыңды, аңсайды құлазыған жүрек.\nСенсіз өмір баянсыз, қараңғы түнек! //\n\n[Припев 1]\n//  Иса - қадамымның шырағы сөзің!\nИса - медеткер жұбанышым Өзің!\nИса - пәк-мөлдір, шартсыз махаббатың,\nСарқылмас, шексіз мейір-шапағатың! //","alternateTitle":"Иса қадамымның шырағы сөзің!"},{"id":7,"title":"Сенің сөзіңді оқығанда Тәңірім","text":"[Куплет 1]\nСенің сөзіңді оқығанда Тәңірім,\nКүнәкар екеніме өкіндім.\nБұл жаратқан дүние өтіп кетерін,\nБілгенімде, бір Өзіңе шын сендім.\n\n[Припев 1]\n// О, Құдайым, о, Құдайым,\nОйымда да, сезімімде бір Өзің,\nДаңқтала бер жүрегімнің түбінде. //\n\n[Куплет 2]\nО, Құдайым, жүрегімде Сен жаса,\nҚасиетті Рухыңмен бағытта.\nСиынғанда, үнімді есті аспанда,\nҚолдап-қорғап жүрші Өзің жанымда.\n\n[Куплет 3]\nСені даңқтап әрбір құтты күнінде,\nЖиналамыз біз сиыну үйінде.\nОйымда да, сезімім де бір Өзің,\nДаңқтала бер жүрегімнің түбінде.\n\n[Куплет 4]\nӨкінесің осы сөзді ұқпасаң,\nҰлы Құдай айтқан сөздің бірінде.\nО, бауырым, қайырылсаңшы Тәңірге,\nУақытты ұттырмастан бекерге.\n\n[Припев 2]\n// О, бауырым, о, бауырым.\nО, бауырым, қайырылсаңшы Тәңірге,\nУақытты ұттырмастан бекерге. //\n\n[Куплет 5]\nОсы күнге ыразамыз біз-дағы,\nЖарық күн мен тыныштық бергеніңе.\nҰлы Тәңір, Өзің берген еліме,\nҰласа бер тыныштығы жерімде.\n\n[Припев 3]\n// О, Құдайым, О, Құдайым,\nҰлы Тәңір, Өзің берген еліме,\nҰласа бер тыныштығы жерімде. //","songNumber":"58"},{"id":84,"title":"Сенің сөзіңе құлақ түрсем","text":"[Куплет 1]\nСенің сөзіңе құлақ түрсем,\nҚұтқарушым, Сен ғажапсың,\nӨзімді терең түсінсем,\nКүнәкар мен бір пендеңмін.\n\n[Припев 1]\n// Сен Иса - киелі Бұтасың,\nАл мен нәзік бұтағыңмын.\nӨзіңнен тек қуат аламын,\nМенің Құтқарушымсың Сен. //\n\n[Куплет 2]\nСенен алған сезімнен жаным,\nҚуанып тынышталады,\nЖүрегім Саған жақындайды,\nҚұтқарушым, жан Тәңірім.\n\n[Припев 2]\n// Кейде Сенімен жан Тәңірім,\nБірге болмаған шағымда\nСол кезде жүрегім қиналып\nТыныштық болмайды жанымда. //\n\n[Куплет 3]\nСенің әр Сөзің бізге шындық,\nСенсіз өмірде кім едік?\nКүнә жайлаған өмірде,\nМағынасыз әр ісіміз.\n\n[Припев 3]\n// Сондықтан жалғыз бір тілегім\nМәңгілік болу Өзіңмен.\nАтқарылса барлық істерім,\nКүш алып Сенің сөзіңнен. //\n\n[Куплет 4]\nМәсіх - тіршілік қайнар көзі,\nМағына берер өмірге.\nЖаратушының тірі сөзі,\nЖол ашып берді Тәңірге.\n\n[Припев 4]\n// Сен Иса - киелі Бұтасың,\nАл мен нәзік сабағыңмын.\nӨзіңнен тек қуат аламын\nЖалғыз Құтқарушымсың Сен. //","songNumber":"150"},{"id":94,"title":"Сені Шақырамын","text":"[Куплет 1]\nСені шақырамын, Тәңір!\nЖауларымнан қорғанамын.\nСаған үміт артамын, Қорғаушым\nТәңір тірісің\nМахаббатың мәңгі\nҚұтқарушы Құдай Ием\nАтың мадақталсын"},{"id":10,"title":"Сені іздейм","text":"[Куплет 1]\nСені іздейм,\nҚұдіретті!\nБасымды ием,\nЖығыламын.\nСаған ұқсас патша жоқ кішіпейіл,\nҚұтқарып алып емдеген.\n\n[Предприпев 1]\nҚұралақанмын,\nБәрін Сен бердің.\nБасқа еш нәрсе,\nМаңызды емес.\n\n[Припев 1]\nСені сүйем,\nҚұтқардың Сен.\nТек Саған мұқтажбын,\nКерексің Сен.\n\n[Припев 2]\nСиынамын,\nБейбіт Ием.\nТыным табам,\nАзат еттің.\n\n[Бридж 1]\nАзаттығыңда тұрам.\nАзаттығыңда тұрам.\nАдалдық ұсынам.\nАдалдық ұсынам.","songNumber":"177","alternateTitle":"Азаттығыңда тұрам"},{"id":853,"title":"Сиынамын мен елім үшін","text":"[Припев 1]\n// Сыйынамын мен, елім үшін\nСыйынамын мен, халқым үшін,\nТәңірім-ай! //\nИ-и-иса алғыс Саған!\nИ-и-иса алғыс Саған!\n\n[Куплет 1]\n// Төгілген қаның Сенің,\nмен үшін айқышта,\nТөгілген жасың Сенің,\nАқтады күнәдан, өлімнен! //"},{"id":239,"title":"Сиынғанда","text":"[Куплет 1]\nСиынғанда, сиынғанда\nҚұдайменен сөйлесем,\nҚиналғанда, түн болса да,\nҰйықтамастан сиынам.\nЖаратқанның алдында,\nМен тізерлеп қол созып,\nБар қайғымды айтып жалындым:\nО, Құдайым, мені ұқсаң,\nТек Сенен күш сұраймын.\nКүшім кетіп, тұрмын әлсіреп.\n\n[Куплет 2]\nСыртта қатты дауыл ұрып,\nБет қаратпас мұздай қар.\nДәл осындай боран болып,\nЖүрегімді сыздатты.\nӘлсіздігімді сезіп,\nКөзімнен жас құйылып,\nМен Исаға тұрып жалындым:\nСен білесің, Құдайым,\nЖүректегі қайғымды,\nТұңғиықтан қайтып шығам мен?\n\n[Куплет 3]\nЖеңіл-желпі оңай өмір,\nТілемеймін Тәңірім,\nҚасіреті, қайғысы мол,\nБолса-дағы жолымның.\nТілеймін мен бір ғана:\nӘрдайым сезіп тұрсам,\nСенің құдіретті қолыңды,\nШырмалынған жолдардан,\nЖағаласқан жаулардан\nӨзің алып шығасың Құдай.\n\n[Куплет 4]\nСиынғанда, сиынғанда,\nРазы болып, қуанам.\nДаңқтап Сенің рақымыңды,\nҚұдіретті күшіңді.\nКүш күткенде әлсіреп,\nАзғындыққа алданып,\nМен жығылдым қарсы тұра алмай.\nЖүректен шыққан күйік,\nСаған жетті Құдайым,\nСиынып Сенен қуат алдым.","songNumber":"20"},{"id":417,"title":"Сиын қуанған сәттеріңде","text":"[Куплет 1]\nСиын қуанышты кезіңде\nҚиын шақтарда сиын.\n\n[Припев 1]\n// Сиын бақытсыздық төнгенде,\nқысылған кезде де сиын. //\n\n[Куплет 2]\nСиын ашуды жеңгенде.\nҚауіп төнген кезде сиын.\n\n[Припев 2]\n// Сұрап, жақының үшін сиын.\nДұшпаның үшін сиын. //\n\n[Куплет 3]\nСиын әлсізденген кезінде.\nМенмендігің үшін сиын.\n\n[Припев 3]\n// Сиын жақыныңнан айырылғанда.\nЖаңа өмір үшін сиын! //\n\n[Куплет 4]\nСиын сын сағаты қелгенде,\nӨзіңді-өзін женгенде.\n\n[Припев 4]\n// Сиын бойынды күнә жайласа,\nҚұдай кешірсін деп сиын. //","songNumber":"153"},{"id":153,"title":"Сиын сын сағаты келгенде","text":"[Куплет 1]\nСиын сын сағаты келгенде,\nӨзіңді-өзің жеңгенде.\n// Сиын бойыңды күнә жайласа,\nҚұдай кешірсін деп сиын. //\n\n[Куплет 2]\nСиын ашуды жеңгенде,\nБасыңа қауіп төнгенде.\n// Сиын жақын адамың үшін.\nДұшпаның үшін де сиын. //\n\n[Куплет 3]\nСиын рухың әлсізденгенде,\nМенмендігің үшін сиын.\n// Сиын жақыныңнан айырылғанда,\nЖаңа өмір үшін сиын. //\n\n[Куплет 4]\nСиын қуанышты сәттерде,\nҚиыншылықтан өткенде.\n// Сиын жеңістерге жеткенде,\nҚұдайды мадақтап сиын. //","songNumber":"21"},{"id":612,"title":"Сиынуды үйретші Тәңірім","text":"[Куплет 1]\nСиынуды үйретші Тәңірім,\nКиелі заңыңды сақтайын.\n//  Тәкаппар жүрегімді өзгертші,\nИманды болайын әрдайым.  //\n\n[Куплет 2]\nОрын ал мәңгілік жүрегімнен,\nКиелі Рухыңмен басқарып.\n//  Мадақтайын Сені жан-дүниеммен,\nӨсиеттеріңді орындап.  //\n\n[Куплет 3]\nТазарып киелі Қаныңменен,\nЖүрегімді таза сақтайын.\n//  Шынайы сүйейін жақынымды,\nКиелі атыңды даңқтайын.  //","songNumber":"22"},{"id":422,"title":"Сиыр далада жайылады","text":"[Куплет 1]\nСиыр далада жайылады,\nДалада шөп жейді\nСиыр далада жайылады,\nБізге көп сүт береді."},{"id":972,"title":"Соқыр болып көре алмау","text":"[Куплет 1]\nСоқыр болып көре алмау бұл ауыр,\nКөзіміз сау болса да жиі қарамаймыз."},{"id":859,"title":"Сол бір кез есімде менің","text":"[Куплет 1]\nСол бір кез есімде менің,\nҚұтқарылуымды аңсаған.\nТаң шырақтай нұрыңменен,\nАрылуымды күнәдан.\nМен жарлы зәру көмегіңе,\nҚұлақ тосып жауап берші.\nРақымыңды түсіре гөрші,\nӨзіңе сенімімді артам.\n\n[Припев 1]\nКім Саған тең келер Уа, Жаратқан\nБіз үшін жанын аямаған.\nСен мені сүйдің, бердің мәңгілік өмірді,\nО, Тәңірім неткен кереметсің.\nКешірімді, мейірімдісің,\nӨзіннің маған аштың ақиқат жолыңды,\nТәңірім рахмет Саған!"},{"id":658,"title":"Соңымнан ер теңіздер долданғанда","text":"[Куплет 1]\nСоңымнан ер теңіздер долданғанда,\nСоңымнан ер түнек салтанат құрғанда,\n// Соңымнан ер тікенді жолдармен,\nСоңымнан ер Менің. //\n\n[Куплет 2]\nСоңымнан ер азап шеккен кезіңде,\nСоңымнан ер күшің таусылған кезде,\n// Соңымнан ер көмек берем саған,\nСоңымнан ер Менің. //\n\n[Куплет 3]\nСоңымнан ер жау сені азғырғанда,\nСоңымнан ер досың сырт айналғанда,\n// Соңымнан ер тастамаймын сені,\nСоңымнан ер Менің. //\n\n[Куплет 4]\nСоңымнан ер ертеңің түнергенде,\nСоңымнан ер көзің қарауытқан кезде,\n// Соңымнан ер мәңгі үйге кіресің,\nСоңымнан ер Менің. //","songNumber":"181"},{"id":1021,"title":"Сөзіңді алдым қолыма","text":"[Куплет 1]\nСөзіңді алдым қолыма,\nЖарық боп жанған жолыма.\nӘлсіреп әлім таусылса,\nКүш-қуат берер бойыма.\n\n[Припев 1]\nКиелі кітап - ырысым,\nКүнәға қарсы қылышым.\nТастай боп қатқан жүректер\nСөзіңді оқып жібісін.\nМұздай боп тонған көңілдер\nОларды оқып жылысын.\n\n[Куплет 2]\nАшықсам оқып нәр алам,\nНәріңе мұқтаж әр адам.\nЖол етіп оны жұмаққа\nАдаспай тауып бара алам.\n\n[Куплет 3]\nСөзіңді берген жерге Сен\nСу етіп ішем шөлдесем.\nКиелі Сөзің болмаса,\nӨмірдің мәнін білмес ем.\n\n[Припев 2]\nТәңірдің тірі Сөзісің,\nКеудеме тұнған тынысым.\nТастай боп қатқан жүректер\nСөзіңді оқып жібісін.\nМұздай боп тонған көңілдер,\nОларды естіп жылысын.\n\n[Куплет 4]\nСөзіңе Сенің сүйеніп,\nЖығылсам қайта тұра алам.\nКүнәмның құны өтелді\nСөзіңнен оқып біле аламын.","songNumber":"87","alternateTitle":"Киелі Кітап - ырысым"},{"id":123,"title":"Су үстінде сенім артсам","text":"[Куплет 1]\nСу бетімен кел деп шақырдың\nКім жүрген су үстімен\nСонда жүзінді мен көремін\nСу үстінде сенім артсам\n\n[Бридж 1]\nАтыңды мен шақырамын\nкөзімді тек Саған қадап\nСу буырқанса\nЖаным табар тыным Сенен\nМен Сендікпін, Сен мендіксің\n\n[Куплет 2]\nРақымың мол тасқындап судай\nӨз қолыңмен жетелейсің\nҮрей басса тұла бойымды\nТабыласың Сен жанымнан\n\n[Припев 1]\nКиелі Рух сенімім менің шектелмес\nЖүргізсең кешіп су бетін\nШақырсаң мен барамын\nМені аяқ баспаңан жерге апаршы\nСенімім нығайып өссін\nҚұтқарушымның алдында"},{"id":805,"title":"Сұраймын Сені","text":"[Куплет 1]\nСұраймын Сені: Қайдан келдің Сен?\nАйтшы бауыр, қайда барасың?\nОйландың ба, не жасаймын деп,\nБұл жауабын, қайдан табасың?\n\n[Припев 1]\nАспанды да, жерде жаратқан,\nҚұдайымыз Тәңір бар екен.\nАдамдарды жерге таратқан,\nРақым беріп, өмір сүр деген.\n\n[Куплет 2]\nШайтан деген алдамшы болған,\nАзғырды ол Хауа Ананы,\nАдастырған, адамды жолдан,\nБұл шындықты біліп жүр екен.\n\n[Куплет 3]\nҰқпай сөзін Құдай Әкенің,\nКүнәға біз батып кеткенбіз.\nҚиналамыз тартып азабын,\nБіз тозаққа қарай кеткенбіз!\n\n[Куплет 4]\nҰлы Құдай бізге сүйгеннен,\nЖалғыз Ұлын жерге жіберген,\nКүнәмізды мойнына алып,\nЖазаланған, қайта тірілген!\n\n[Куплет 5]\nҚұдай айтады, осы құрбандық,\nАрылтад деп сені күнәдан,\nСенімменен, сені құтқарып,\nКүнә үшін Иса, Өзі өлген!"},{"id":130,"title":"Сұраңдар","text":"[Куплет 1]\nСұраңдар, сонда Құдай өздеріңе береді.\nІздеңдер, сонда табасыңдар.\nЕсікті қағыңдар, сонда сендерге ашады.\nСұраңдар, сонда Құдай өздеріңе береді.","songNumber":"288"},{"id":771,"title":"Сүйгендіктен адамзатты","text":"[Куплет 1]\nСүйгендіктен адамзатты,\nҚұрбандыққа бердің Ұлыңды.\nСенімін артқан әрбір жан,\nҚұтқарылсын деп мәңгілік оттан.\nСенген жанды құттаруға,\nЖұмаққа сені қабылдауға.\nӨмір, жол, шындық - Иса,\nБүкіл билік Оның қолында\n\n[Припев 1]\n// Қабылдадық Ұлыңның құрбандығын,\nАзатбыз оттан, бұл тек - рақымың.\nІзгі ісімізбен алмаймыз ақтала\nҚұтқарылу берілді бізге сыйға. //\n\n[Бридж 1]\n// Иса мадақтал Сен!\nСаған мадақ, Саған мадақ! //"},{"id":652,"title":"Сүйгеніне жетуді аңсаған әр жан","text":"[Куплет 1]\nСүйгеніне жетуді аңсаған әр жан\nДайынмын дер асуға таудан\nҚатал тағдыр дақ түсірсе жүрегіне\nТұрмас ол сертінде\nБиік шықпасамда шыңға\nБардым мен Ғолғотаға\n\n[Припев 1]\nӘлсіресең демеп, сүйеніш боламын\nБар жамандықтан қорғаймын\nҚалдырмаймын жалғыз бірге боламын\nЖетелеп сені аламын\n\n[Куплет 2]\nСүйгеніне ынтығар адам жетуге\nСерт етеді теңіз кешіп өтуге\nҚатал тағдыр дақ түсірсе жүрегіне\nТұрмас ол сертінде\nТеңіз кешіп өтпесемде\nТұрдым толқын бетінде\n\n[Куплет 3]\nШексіз сүйгенімді бағалап ұғына білсең\nАйқыштағы азабымды түсінсең\nОралсаң қайтадан Өзіме сен үшін әлі де\nДайынмын айқыш азабын қайта төзуге\n\n[Припев 2]\nӘлсіресең демеп, сүйеніш боламын\nБар жамандықтан қорғаймын\nҚалдырмаймын жалғыз бірге боламын\nЖетелеп сені аламын\nЖетелеп аламын\n// Қорғаның болам, мен қорғаның болам! //"},{"id":1010,"title":"Сүйемін Иса","text":"[Куплет 1]\n// Жалғызым менің сүйемін Сені Иса/Әке,\nМахаббатымсың, жарығымсың Сен Ием.\nҮмітім менің, ешбір қалдырмайсың Сен,\nШын жүрегіммен Сені аңсаймын мен. //\n\n[Припев 1]\n// Иса!\nШынайы, тірі жалғызым Сен менің! //\n\n[Куплет 2]\n// Тәңірім жалғыз Сені алғыстайм\nЖалғыз киелісің,\nЖалғыз мейірімді ізгі,\nТәңірім тек Сені сүйемін.\nСені қастерлеймін,\nБас иіп Саған келемін //"},{"id":274,"title":"Сүйемін Сені Әке, шын жүрекпен","text":"[Куплет 1]\n// Сүйемін Сені Әке, Сүйемін Сені Әке!\nШын жүрекпен Сені сүйемін!\nСүйемін Сені Әке! //\n\n[Припев 1]\n// Әке - Ием Саған ризамын!\nТек Саған табынамын\nМәңгі өмір сыйлаған үшін! //\n\n[Куплет 2]\n// Сүйемін Сені Иса\nСүйемін Сені Иса\nШын жүрекпен Сені сүйемін\nСүйемін Сені Иса! //\n\n[Припев 2]\n// Иса Ием Саған ризамын\nтек Саған табынамын\nМәңгі өмір сыйлаған үшін! //"},{"id":55,"title":"Сүйемін Сені Иса","text":"[Куплет 1]\nСүйемін Сені Иса\nБар жүрегім жаныммен.\nСен Тәңірім, Сен Бағушым,\nҚұтқарушым менің.\nҚұрметке Сен лайықсың,\nБар даңққа Сен лайықсың.\nСен Тәңірім, Сен Бағушым,\nҚұтқарушым менің.\n\n[Припев 1]\nМен Сені мадақтаймын Тәңірім менің,\nМен Сені мадақтаймын Иса.\nМен Сені мадақтаймын Тәңірім менің,\nМен Сені мадақтаймын","songNumber":"127"},{"id":865,"title":"Сүйемін Сені - Құдай Әке!","text":"[Припев 1]\nСүйемін Сені Құдай Әке!\nСүйемін Сені Тәңір Иса!\nСүйемін Сені Киелі рух, сүйемін Сені сүйемін !!!\n\n[Припев 2]\nТәңірім тек Сен ғана лайықсын,\nБарлық құрметке, барлық даңққа!\nКұдыретті Сен жалғыз Ұлысын!\nСүйемін Сені Иса!"},{"id":76,"title":"Сүйемін сені, сүйемін","text":"[Куплет 1]\nСүйемін сені, сүйемін.\nТәңірім менің, Тәңірім.\nАдал да берік, өмірлік Серік\nБолдың Сен маған Ием.\nСенен артық Дос, артық Дос.\nТаба алмадым мен, таппадым.\nЖүрегімді ашам тек Саған ғана,\nТек Сендей боламын - Ием!\n\n[Припев 1]\n// Адал да мейірімді - Ол,\nӨз таңдаған ұл-қызына.\nТәңір алдында таза болайық,\nТаза жүрейікші бауырым. //\n\n[Куплет 2]\nКешір дедің сен, кешіреді.\nСүй бауырыңды - дедің Сен.\nОй-санама кірмеген махаббат,\nБердің Сен маған Ием.\nКелемін Саған, келемін\nТаза жүрекпен тек таза.\nСүйдің Сен бізді,\nБіз үшін ғана қолыңды бердің Ием.","songNumber":"132"},{"id":355,"title":"Сүй, сүй","text":"[Куплет 1]\nСүй, сүй, сүй, сүй,\nІзгі Хабарды мәңгі сүй.\nӨзіңді сүйгендей көршіңді сүй,\nӨйткені Құдай сүйеді бәріңді.","songNumber":"183"},{"id":672,"title":"Сүйікті Әке","text":"[Куплет 1]\nСүйікті Әке, Көктегі,\nАтыңды даңқтаймыз Сенің.\nХалқың Сенің\nАтыңды жариялағанда,\nПатшалығың мадақта құрылсын.\n\n[Припев 1]\nҚұдіретті Құдай қастерленсін.\nКелген, Қазір бар,\nЕнді келетін.\nҚұдіретті Құдай қастерленсін.\nМәңгі билік Иесі.","songNumber":"185","copyright":"1984 Скриптуре ин Сонг"},{"id":863,"title":"Сүйіктімін, Құдайға мен жақын болдым","text":"[Куплет 1]\n//  О Әке мені сүйесің Сен,\nСенің сүйікті Ұлында\nИсада мен сүйіктімін!  //\n\n[Припев 1]\n//  Сүйіктімін, сүйіктімін,\nҚұдайға мен жақын болдым!\nСүйіктімін, сүйіктімін,\nҚұдайға мен жақын болдым!  //\n\n[Бридж 1]\nИсаның киелі төгілген қаны\nәркүнде мені  тазартып ақтап алды\nИсаның киелі төгілген қаны\nәркүнде мені тазарты!"},{"id":14,"title":"Сүйікті Тәңірім!","text":"[Куплет 1]\nАйқыш ағашта Тәңірім, мен үшін өлдің,\nҚасиетті қаныңды мен үшін төктің!\nҚұшағыңды маған аштың,\nӨз қолыңа мені алдың,\nКиелі құрбандығыңмен күнәмді кешірдің!\n\n[Припев 1]\nРахмет Саған Тәңірім,\nөмірімді өзгерткеніңе!\nРахмет Саған Киелі,\nМахаббатыңды көрсеткеніңе,\nСен мен үшін, құрбан болдың,\nКиелі қаныңды төктің!\nСен мен үшін, құрбан болдың,\nСүйікті Тәңірім!","alternateTitle":"Айқыш ағашта Тәңірім мен үшін өлдің, Рахмет Саған Тәңірім"},{"id":471,"title":"Сүйінші","text":"[Куплет 1]\nҚұдай қауымын негіздеп,\nАтамекен елімізде,\nКелді Ол бізді сүйіп,\nҚуаныңдар, Сүйінші,\nКиелі қауымын Ол\n\"Сүйінші\" деп атады.\n\n[Припев 1]\nСүйінші!\nАзат етіп Мәсіх\nСүйінші!\nБолдық бір дене\nСүйінші!\nБірлікті сақтап біз,\nБір отбасындай боламыз бірге!"},{"id":370,"title":"Сүйіспеншілікпен әндетіп","text":"[Куплет 1]\nСүйіспеншілікпен әндетіп,\nСенімде бірге жүруші ек.\n//  Асуы биік жолдарда,\nБоранға қарсы тұрушы ек.  //\n\n[Куплет 2]\nАз ғана еңбек етсек те,\nОт болып жанып тұрушы ек.\n//  Түнгі аспанға қараумен,\nАлысқа көзді тігуші ек.  //\n\n[Куплет 3]\nБізді қорқытқан сөздерді,\nТайсалмай қарсы алушы ек.\n//  Құдайдың сөзін орындап,\nДүниеде таза жүруші ек.  //\n\n[Куплет 4]\nШуақты қымбат жұмаққа,\nӘндетіп бірге барамыз.\n//  Қайғысы, мұңы жоқ жерде,\nМәңгілік жасап қаламыз.  //","songNumber":"156"},{"id":509,"title":"Сүюдің отымен жарқырайын","text":"[Куплет 1]\nСүюдің отымен жарқырайын,\nТүнектен біржола арылайын.\n// Тәңірім шеккен азабыңа көз салайын,\nАйқышты әркез еске алайын. //\n\n[Куплет 2]\nТүнгі сапарда жарықты көрдім,\nЖарыққа қарай бетімді бұрдым.\n// Тәңірім нұрыңмен жүрек отын тұтатшы,\nЖетелеші қолыңнан ұстатшы. //\n\n[Куплет 3]\nРухың от жалын боп жарқырасын,\nҚуаныш тасқыны сарқырасын.\n// Исаның алауы жүрегіңді жандырсын,\nБұлағыңмен шөліңді қандырсын. //\n\n[Куплет 4]\nҚұдайдың оты менде лауласын,\nРухым сәулесімен нұрлансын.\n// Бейнеңді Сенің менен ел көріп таңдансын,\nБүкіл адамзат Сені даңқтасын. //","songNumber":"140"},{"id":276,"title":"Сізді сүйем","text":"[Куплет 1]\nСізді сүйем Исаның махаббатымен.\nСізді сүйем Исаның махаббатымен.\nСіздің жүзіңізден Әкемнің даңқын көрем.\nСізді сүйем Исаның махаббатымен.\n\n[Куплет 2]\nҚарсы алам Исаның махаббатымен.\nҚарсы алам Исаның махаббатымен.\nСіздің жүзіңізден Әкемнің даңқын көрем.\nҚарсы алам Исаның махаббатымен.","songNumber":"187"},{"id":204,"title":"Табиғатыңмен, махаббатыңмен","text":"[Куплет 1]\nТабиғатыңмен, махаббатыңмен,\nӨмірімді менің баурап алдың Сен\nАяулы Әкем, рақымын төккен\nНұрға толы жүзің көрікті неткен.\n\n[Припев 1]\nӘн айтамын мен сағынышымды басып\nӘн айтамын мен қуанышым тасып\nӘн айтамын мен алақанымды жайып\nӘн айтамын мен жүрек үнін қосып.","songNumber":"158"},{"id":852,"title":"Тағы да түн","text":"[Куплет 1]\nТағы да түн,\nКең жайғанда қанатын,\nСенен көмек сұраймын:\nӘке, жалынам, үрейді алыстатшы.\nЖадыратшы жанымды,\nТаң шапағын сақташы,\nӘке, жалынам, Өз кеңесіңді берші.\n\n[Припев 1]\n// Өтінішім: менің аш көзімді,\nТапқым келеді Сенен өзімді.\nМың жолдан табуды тек тілеймін,\nТура жолда болайын,\nІзгі Әкем Құдайым! //  2р\n\n[Куплет 2]\nТағы да қыс\nАқ желпуішпен желпіп,\nКөңілді қарығанда.\nӘке, жалынам, жүрекке жылу берші.\nМаған үйрет сақтауды,\nНық сеніммен сенуді.\nӘке, жалынам, жылу беретін етші."},{"id":399,"title":"Тазалап мені арылттың мүлде күнәдан","text":"[Куплет 1]\nТазалап мені арылттың мүлде күнәдан,\nАлғысымды айтам шын жүрекпенен мен Саған.\nМәңгілік сүю шын көңілменен Исадан,\n/// Иса сүйеді, Иса сүйеді. ///\n\n[Куплет 2]\nӨмірдің мәнін түсіндім енді жаңадан,\nҚуаныш шексіз тасиды толқып шамадан.\nӨзгертті Иса жасады менен жаңа адам,\nИса сүйеді, Иса сүйеді.\n\n[Куплет 3]\nЖолдаймын жырды, жүректен шыққан лаулаған,\nСыйладың маған арманымды Сен аңсаған.\nДаңқталсын атың Көктегі Әкем, әрқашан,\nИса сүйеді, Иса сүйеді.","songNumber":"59"},{"id":525,"title":"Тазартты мені","text":"[Куплет 1]\nТазартты мені Сенің қаның,\nБерді өмір, жуды күнәмды.\nСен азат еттің мені,\nҚұрбан болдың Сен мен үшін.\nСен жудың,\nҚардан әппақ ағарттың мені.\nИса Ием, аяулы - құрбандық.","songNumber":"189"},{"id":453,"title":"Талай жолмен Мәсіх жүріп қайтты","text":"[Куплет 1]\nТалай жолмен Мәсіх жүріп өтті\nЯһуда аймағын аралаумен,\nБір соқыр жол шетінде отырды,\nТүңіліп қараңғы өмірінен.\nӨтеуші өтіп бара жатыр,\nНауқастарды емдеп аурудан.\nО, Иса, о, Иса Дәуіт ұлы\nРақымыңды түсірші маған.\n\n[Куплет 2]\nЖасымнан жол шетінде отырмын\nСадақа сұраумен күнелтемін.\nҚайғымның шегін Сен берген едің\nКөрсетші пендеңе нұр сәулесін.\nСорлымын, бейшара қайыршымын,\nКүн көзін көрмейтін\nО, Иса, о, Иса Дәуіт ұлы\nРақымыңды түсірші маған.\n\n[Куплет 3]\nСол сияқты өлім түнегінен\nМенің де жан рухым душар болды.\nАлайда жақындап Тәңір Ие,\nНұрымен жанымды жадыратты.\nЖүректі ауыр шақ.........\nКеудеде ................\n// Сол соқыр секілді өтінемін,\nО, Иса рақымды бол маған //"},{"id":78,"title":"Тамаша мен жаралдым","text":"[Куплет 1]\nТамаша мен жаралдым\nҚұрсағында анамның\nМен мұны шын жүректен\nМойындаймын\nТәңір білді өзімді, ойларымды сөзімді\nБәрібір де Ол мені шексіз сүйді\n\n[Припев 1]\nМені сүйеді мені сүйеді\nБәрінен жақсы білетін Біреу\nОл Иса\n\n[Куплет 2]\nОтырғаным, тұрғаным\nЖүргенім, демалғаным\nЖолдарымның барлығы Саған айқын\nТұңғиыққа түссем де\nҚанша құлап жүрсем де\nМені қолдап жетелейсің Тәңірім"},{"id":543,"title":"Тамаша, Өзіңмен бірге болған","text":"[Куплет 1]\nТамаша, Өзіңмен бірге болған.\nБіз Сені бірігіп даңқтаймыз.\nТамаша қиыншылыққа шыдасаң,\nҮмітпен мақсатқа жетеміз.\n\n[Припев 1]\nТамаша, жүрегің таза болса .\nТамаша жамандық болмаса.\nТамаша жан тыныштығын алсақ.\nТамаша, Құдаймен табысқан.\n\n[Куплет 2]\nТамаша, жаның мен өміріңді\nМәсіхке сеніп сен тапсырсаң.\nТамаша, азғындықты тойтарып,\nзұлымдыққа қарсы тұра алсақ.\n\n[Куплет 3]\nТамаша, Исамен барлық жерде.\nОнымен өміріміз жеңіл .\nТамаша, Исаға жүректі ашсақ.\nТәңір Ием бізді қолдайды.\n\n[Куплет 4]\nТамаша, Құдайдың қол астында.\nТастамайды Ол бізді ешқашан.\nТар жол, тайғақ кешумен жүргенде,\nқорғайды Иеміз әрқашан.","songNumber":"185"},{"id":671,"title":"Тамаша Тәңірді даңқтау","text":"[Куплет 1]\nТамаша Тәңірді даңқтау,\nӘн айту құдіретті Иеге.\nЖариялау күндіз атыңды,\nТүнде Сенің шындығыңды.\n\n[Припев 1]\nШаттыққа мені бөледің Сен,\nТәңірім, Сені мадақтаймын.\nСенің істерің ұлы, о, Әкем,\nСен Әкемсің, Жаратушым.\n\n[Куплет 2]\nКөзімді қадаймын көкке,\nҚолымды жоғары көтерем.\nҚұдайым - біздің Иеміз!\nЖер бетінде де, көкте де.","songNumber":"190"},{"id":960,"title":"Таң атқанда","text":"[Куплет 1]\n// Таң атқанда оянып, Сені шақырам,\nҚуанып мен ән салам. Сені жырлаймын. //\n\n[Припев 1]\nАңсайсың Сен менің жырымды,\nСаған арналған өмірімді.\nКүні бойы Сені мақтаймын,\nМахаббатыңды жариялаймын.\nО, Иса! (О, Иса) О, Иса! Иса! О, Иса,\nДәл қазір келші маған,\nСағындым мен.\n\n[Бридж 1]\nСені сүйем, мен бас ием, Тәңірім-ай!"},{"id":356,"title":"Таң атқаннан Сені","text":"[Куплет 1]\nТаң атқаннан Сені,\nКүн батқанша Сені,\nТек Сені мадақтаймыз біз.\nЛа-ла-ла шүкір тәуба,\nҚұдайдың балаларымыз.\nМадақтаймыз Сені.\nМәңгілікке барамыз,\nән айтып, қуанып,\nмадақтаймыз Сені.","songNumber":"192"},{"id":142,"title":"Таңда күн шығады жылытып жерді","text":"[Куплет 1]\nТаңда күн шығады жылытып жерді,\nШуағын шашады қуантып елді.\n// Жарығы, жылуы болмайды түнде,\nМәсіхтің алауы сөнбейді мүлде //\n\n[Куплет 2]\nНұр Иса Мәсіхте, Оның Өзі күн,\nКүндіз де, түнде де болмас онда түн.\n// Сүйіспеншілігін мадақта бәрің,\nЖүректен төгілсін тасқындап әнің //","songNumber":"289"},{"id":16,"title":"Таң келеді қызарды аспан","text":"[Куплет 1]\nТаң келеді қызарды аспан,\nТаң самалы неткен таза, бетімді оған тоссам!\nБұл дүние сондай ғажап маған,\nжаңа күн қуаныш әкелгеннен, келдім мен Саған!\nБұл жалған өмірге келген,\nжаныма тыныштық берген,\nБір үмітім бар, қуандырған!\n\n[Припев 1]\nАрман менің жігерім, үміт берген сенім!\nҚуат берген сенім жүрегімде!\nАрман жұбатады мені, жаным сыр шертеді!\nҮміт берген сенім жүрегімде!\nТөзімде ұғамын, бәріне бұл жалғанда,\nРизамын, тағдырыма!\n\n[Куплет 2]\nКүн нұрына қуанған дала,\nҚандай көрік берді,\nТөсіне гүлдері жайнаған!\nСүйсінеді Саған қараған,\nМен бақытты жанмын өмірге,\nТолық риза болған!\nБұл жалғанға нұр әкелген,\nЖаныма тыныштық берген!\nБір үмітім бар, қуандырған!"},{"id":597,"title":"Таң шапағындай, жүзіңнен нұр төгіліп","text":"[Куплет 1]\nТаң шапағындай, жүзіңнен нұр төгіліп,\nЕң сұлу жан тек сенсің бүгін әлемде.\nЖелегің тұр желбіреп, келін, міне, келді деп,\nЖанарың жайнап, қуанышқа бөленген.\n\n[Куплет 2]\nЖиылған жұрттың қадалды-ау саған жанары,\nБал-бұл жүзің көз жауын алып барады.\nТал бойында төгіліп тұрған ақ көйлегің,\nПәктігіңнің куәсі болып қалады.\n\n[Куплет 3]\nТәңір еркімен ата-ана үйін қалдырдың,\nЖан жарыңмен мәңгілік бірге болуға.\nКездесер қуанышы мен қайғысын тағдырдың,\nАсыл жарыңмен бірге қарсы алуға.\n\n[Куплет 4]\nБүгін қалыңдық, ал болашақтағы анасың,\nСүйген жарыңның жүрек кілтін таба біл.\nИсаның сөзімен ұрпақтың толтыр санасын,\nМінәжатпен барлық қамалды ала біл.\n\n[Куплет 5]\nАқ көйлек, ақ желекті, көптен күткен тойың тез,\nӨте шықты деп қам көңілді болмағын.\nАсыға күткен нағыз қымбат арманың,\nҚалыңдық болып Иса Мәсіхпен кездесер кез.","songNumber":"212"},{"id":862,"title":"Тас, темірден жасалған, жез, ағаштан","text":"[Куплет 1]\n// Тас, темірден жасалған, жез, ағаштан,\nКелмедім сиынуға тәңірге жалған,\nКелмедім мен сенуге, өтірікке,\nШын Тәңірді тануға, келдім бұл өмірге! //\n\n[Припев 1]\nЖүректерің алыстамасын Тәңірден\nӨмірлерің оралмасын жәбірленген,\nАлданбасын жүректерің, құр бостарға,\nҰмытылмасын Құдайдың бір жақсылығы да!"},{"id":701,"title":"Тауға көзді қадаймын","text":"[Куплет 1]\nТауға көзді қадаймын\nҚайдан жәрдем келер деп\nКөк пен жерді жаратқан\nТәңір Ие маған жар\n\n[Припев 1]\nТайдырмайды табаныңды Ол\nҰйықтамайды Қорғаушы\nИсраилды Қолдаушы\nҰйықтамайды, қалғымайды\n\n[Куплет 2]\nТәңір Ие қорғайды,\nҚұдіретімен қолының.\nКүндіз күннің тимесін деп,\nТүнде айдың сәулесі.\n\n[Куплет 3]\nЖамандықтың бәрінен\nИеміз сені қорғайды.\nЖаныңды Ол сақтайды,\nЖаныңды Ол қорғайды.\n\n[Куплет 4]\nМәңгі-бақи бүгіннен\nИеміз сені қорғайды.\nКету-келу сапарыңды\nТәңір Өзі қолдайды.","songNumber":"193","alternateTitle":"Ұйықтамайды Қорғаушым"},{"id":95,"title":"Таулар мен өзен, арқылы","text":"[Куплет 1]\n// Таулар мен өзен, арқылы,\nСенің сүйіспеншілігің,\nМаған мәңгі, жетіп тұрады - Ием!\nКүнәлардан, азат болып,\nШындыққа, шексіз қуанам,\nМадақтаймын Сені, Киелі Рухқа - тола! //\n\n[Припев 1]\nМадақтаймын Сені - мәңгілік!\nДәріптеймін Сені - мәңгілік!\nМахаббатыңа мен толамын,\nТынбастан соны, мен айтамын!\n\n[Бридж 1]\nМүмкін, ұғымсыз ойға, жүректен, шырқаған ән!\nҚуансын, жырласын әлем, шаттансын бірге, билесін бізбен!","songNumber":"146","copyright":"1994 Куриоус? Мусик УК"},{"id":797,"title":"Таурат, Забур, Інжіл мен Жазбадағы","text":"[Куплет 1]\nТаурат, Забур, Інжіл мен Жазбадағы\nСөздеріне ден қойдым Жаратқанның.\nАқиқатты тауып мен бұдан дағы,\nБәз жолымнан бас тарттым, қазақтарым.\n\n[Припев 1]\nМына өмірдің мәні не бұл дүниеде,\nМақсаты не Құдайдың - Жаратқанның?\nОсы сауал көкейге тірелгенде,\nКөп кітапты киелі парақтадым.\n\n[Куплет 2]\nМақсатымды қып-қысқа мына өмірлік,\nАйырбастап алдым мен мәңгілікке.\nКерегі не қызықтың бірер күндік,\nАдамзаттың ақ жолы мәңгілікте.","songNumber":"194"},{"id":147,"title":"Таяуда келеді Ұлы Патшам","text":"[Куплет 1]\nТаяуда келеді Ұлы Патшам,\nАлтын тәжде көреміз тақтан.\nОған ұқсаймын кездескенде мен,\nКеледі Патшам.\n\n[Куплет 2]\nПатшам келеді мен бірге кетем,\nКөкте үй бар сенімім бекем.\nБар күнәм үшін жасалды өтем,\nПатшама жетем.\n\n[Припев 1]\nЖаныма тыным табамын,\nЖүздесуге барамын.\nАйтады жаным жар салып,\nКеледі Патшам.\n\n[Куплет 3]\nТаяуда келеді Тағын көрем,\nПеріштелрі төгеді өлең.\nАлдыңа келіп Тәжімді берем,\nПатшама келем.\n\n[Бридж 1]\nҚазір Ол көрінбейді,\nБірақ, Ол менде.\nИса Мәсіх құрбан болды,\nБіздер үшін."},{"id":85,"title":"Тәңір бізбен бірге бол","text":"[Куплет 1]\nТәңір бізбен бірге бол,\nЖарылқашы біздерді.\nБіздің жүректер,\nСенің Рухыңмен толсын.\n\n[Припев 1]\n//   Алғыстар айтамыз Саған,\nСаған мәңгі Иса.\nИем жарқырашы мәңгі,\nAm\nМәңгі жарқырашы.  //\nРахмет Саған, О, Құдай!\n\n[Куплет 2]\nБіз Сенімен болғымыз\nКеледі Иса,\nСенің Атыңды\nБіздер қастерлейміз.","songNumber":"144"},{"id":286,"title":"Тәңір біргеміз","text":"[Куплет 1]\n// Тәңір біргеміз\nБіз бір денеміз\nБіз бір денеміз Мәсіхте //\n\n[Куплет 2]\nИса Мәсіхке деген сенім\nБізді қызметіне шақырды\nҚұдайда бар үмітіміз\nБәрімізде бір Әке"},{"id":939,"title":"Тәңірге ән сал","text":"[Куплет 1]\nТәңірге ән сал, әлем,\nҚұтқарғанын Оның паш етіңдер.\nОның ғажайып істерін,\nБілуге тиісті әр адам.\n\n[Куплет 2]\nӨйткені Ол құдіретті,\nкүшпенен,\nұлылықпенен.\nШаттан, әлем,\nТәңір - біздің Патшамыз.","songNumber":"199"},{"id":265,"title":"Тәңірге қуаныңдар","text":"[Куплет 1]\n// Тәңірге қуаныңдар,\nӘділдер шаттаныңдар,\nШын жүректен адалдар,\nҚуанып ән салыңдар! //\n\n[Припев 1]\n// Тәңірге қуаныңдар,\nҚуанып ән салыңдар! //"},{"id":134,"title":"Тәңірге рахмет айтатын жөнім","text":"[Куплет 1]\nТәңірге рахмет айтатын жөнім,\nөйткені жарадан тазарды жаным.\nШырқаймын енді мадақтау әнін,\nМәсіх өмірдің мәніменен сәні.\n\n[Припев 1]\nМен Оны сүйем адал ниетпен.\nҚайратпен, күшпен, таза жүрекпен.\nТәңірім рахмет айтатын ретім.\nКөктегі мекеннен орын бердің.\n\n[Куплет 2]\nКүні-түні мен оқыдым дұғамды,\nАзғырылғанда кешірім сұрадым.\nҚиындықтарда қол ұшын береді,\nҚұдайымның қолынан ол келеді.\n\n[Куплет 3]\nТәңірім бізді соңынан ертеді,\nАспан әуені жанымды тербеді.\nАйқыш ағашта Өз жанын қиғанын,\nҚасына барып, аяғын құшамын.","songNumber":"162"},{"id":971,"title":"Тәңірге тілек","text":"[Куплет 1]\nТұнық аспан жымың қағады сан жұлдыздар\nКөз ілеспей ағып барады шоқ жұлдыз да\nЖұлдыз ақса арман тілектер орындалар\nДеп сенгендер жұлдызға тілек жолдап жатар\n\n[Припев 1]\nАл менің тілегім Саған жетеді\nЖұлдыздан да жылдам\nҚалауымды Тәңірім ескересің\nЖолдаған Саған\n\n[Куплет 2]\nТұнық аспан Айдың сәулесі нұр төгеді\nТілегіме құлақ түргенің сезіледі\nЖарық айдың нұры астына қайта-қайта\nТәңіріме тілек айтуға мен келемін\n\n[Припев 2]\n// Ал менің тілегім Саған жетеді\nЖұлдыздан да жылдам\nҚалауымды Тәңірім ескересің\nЖолдаған Саған //","alternateTitle":"Ал менің тілегім Саған жетеді"},{"id":845,"title":"Тәңірден бізге сәлемді","text":"[Куплет 1]\nТәңірден бізге сәлемді\nКиелі Рух бізге әкелді.\nҚұдайдың Сөзі Иса келді,\nЖарылқасын барлық елді.\nҚұдай Әкеме еркелеймін,\nКиелі Рухпен би билеймін.\nАлғыс Саған.\n\n[Припев 1]\n//  Сәлем саған Қазақстан,\nСәлем саған биік аспан,\nСәлем саған туған жерім, туған елім\nСаған сәлем бүкіл әлем. //\n\n[Куплет 2]\nМадақтаймыз Иса Иені.\nБәрімізді Ол сүйеді.\nТыныштық бізге сыйлайды,\nМахаббаты таусылмайды.\nҚұдай Әкеме еркелеймін,\nКиелі Рухпен би билеймін.\nАлғыс Саған."},{"id":255,"title":"Тәңірді мадақта","text":"[Припев 1]\nТәңірді мадақта жан-дүнием!\nКиелі есімін!\nБар дауыспен мадақта жан-дүнием!\nТәңірді мадақта!\n\n[Куплет 1]\nТамаша арайлы таң атты,\nТәңірім ғажап күн жаратты.\nОсынау керемет рақымы үшін,\nАрнайық біз мадақты.\n\n[Куплет 2]\nРақымың мен махаббатың шексіз,\nТәңірім Сен ұлысың.\nОн мың себеп те аз болар маған\nМәңгі айтар жырымсың!\n\n[Куплет 3]\nҚуатым кеміп сарқылған күні,\nАжалым жетіп ақырғы.\nЖан-дүнием Сені жырлайды тағы,\nМәңгілікке Атыңды!\n\n[Припев 2]\nТәңірді мадақта жан-дүнием!\nКиелі есімін!\nБар дауыспен мадақта жан-дүнием!\nТәңірді мадақта!\nТәңірді мадақта!\nТәңірді мадақта!","alternateTitle":"Он мың себеп"},{"id":600,"title":"Тәңірді мадақтайық","text":"[Куплет 1]\nКеліңдер, достарым\nИені, мадақтайық\nҚуанып, Ән айтып\nБи-билеп, жырлайық\n\n[Припев 1]\nКиелі біздің Құдай\nҰлы біздің Тәңір\nМәңгілік біздің Патшаның\nЕсімі мадақталсын\n\n[Предприпев 1]\n// Рэп\nЖартастай берік\nҚорғанымсың сен\nШын жүректен оған\nСенім артамын мен\nҚұтқарушы құдайым\nЖалғыз өзіңсің сен\nМәңгілік өзіңе\nАлғыс айтамын мен //\n\n[Куплет 2]\nБарлық ұлттар, құдайға\nҚол соғыңдар, дәріптеңдер\nШаттық үнмен, дауыстаңдар\nИені, мадақтаңдар\n\n[Предприпев 2]\nРэп\nҚол соғып, тәңірді мадақтайық\nБи-билеп, ән салып, шаттанайық\nТәңірді мадақтаудан, жалықпайық\nҚане достар, Тәңірден, күш алайық"},{"id":278,"title":"Тәңірдің жарылқауы","text":"[Куплет 1]\nБасталды,  біздің Иеміздің күші\nМенің өмірімді басқарып, жаңартады\nБосатылдым, күнәларымнан, өлімнен.\nМенің өмірім өзгеріп,толады\n\n[Припев 1]\nЖарылқауы, мейірімі,\nӨлшемі жоқ Оның мейірімі,\nЖарылқауы,  мейірімі,\nӨзгермейтін сенімді Оның мейірімі."},{"id":137,"title":"Тәңірдің жолымен алға жүремін","text":"[Куплет 1]\nТәңірдің жолымен алға жүремін,\nТәңірдің жолымен алға жүремін,\nТәңірдің жолымен алға жүремін,\nБұл жолдан бірақ қайтпаймын.\n\n[Куплет 2]\nӘлемге емес, айқышқа қараймын,\nӘлемге емес, айқышқа қараймын,\nӘлемге емес, айқышқа қараймын,\nБұл жолдан бірақ қайтпаймын.\n\n[Куплет 3]\nЖалғанда мен жалғыз қалсам да мейлі,\nЖалғанда мен жалғыз қалсам да мейлі,\nЖалғанда мен жалғыз қалсам да мейлі,\nБұл жолдан бірақ қайтпаймын.","songNumber":"291"},{"id":585,"title":"Тәңірдің Рухы мені толтырғанда","text":"[Куплет 1]\nТәңірдің Рухы мені толтырғанда,\n// Дәуітше дұға етемін. //\n// Дұға етемін, дұға етемін,\nДәуітше дұға етемін //\n\n[Куплет 2]\nТәңірдің Рухы мені толтырғанда,\n// Дәуітше ән саламын. //\n// Ән саламын, ән саламын\nДәуітше ән саламын //\n\n[Куплет 3]\nТәңірдің Рухы мені толтырғанда,\n// Дәуітше би билеймін //\n// Би билеймін, би билеймін,\nДәуітше би билеймін //\n\n[Куплет 4]\nТәңірдің Рухы мені толтырғанда,\n// Дәуітше дұға етемін. //\n// Дұға етемін, ән саламын\nДәуітше би билеймін //\n\n[Куплет 5]\n// Тәңір Рухы мені толтырғанда,\nДәуітше мадақтаймын. //\n// Мадақтаймын, мадақтаймын,\nДәуітше мадақтаймын. //","songNumber":"200"},{"id":379,"title":"Тәңір жолыма жарық шашып","text":"[Припев 1]\n// Тәңір жолыма жарық шашып\nҮйге ертіп келеді. //\n\n[Куплет 1]\nЖалғыз қалсам да,\nЖолымнан адассам да\nСен мені жетелейсің.\nСонда қорқыныш бірден ғайып болады.\nТәңір мені тастама, тастама.\n\n[Припев 2]\n// Тәңір жолыма жарық шашып,\nҮйге ертіп келеді. //\n\n[Куплет 2]\nРақымыңа мен\nКенелемін, О, Әкем!\nСенде менің бақ-берекем.\nЖолымда менің\nИса адал серігім.\nҚұтқарушы Ол менің,\nОл менің.\n\n[Припев 3]\n// Тәңір жолыма жарық шашып,\nҮйге ертіп келеді. //","songNumber":"290","copyright":"1984 Ворд Мусик, ЛЛК, Меадовгреен Мусик & Буг Анд Беар Мусик"},{"id":290,"title":"Тәңір Ием арамызда","text":"[Куплет 1]\n// Тәңір Ием арамызда, Киелі, Киелі! //\n\n[Припев 1]\n// Жоғарыда Ол мадақталсын\nҚұдіретті күшпен, қуанышпен.\nБилік етсін арамызда\nБүгіннен, мәңгіге, Аумин! //","songNumber":"150"},{"id":3,"title":"Тәңір Ием, Сен менің - Бағушым!","text":"[Куплет 1]\nТәңір Ием, Сен менің - Бағушым!\nЕшнәрседен де, тарықпаймын мен.\nҚұнарлы жайлауда, тынықтырып,\nМөлдір суға, жетелейсің мені!\n\n[Припев 1]\nҚайда жүрсем де, қорықпайм(ын) қатерден,\nҚайда жүрсем де, жанымдасын Сен!\nҚайда жүрсем де, сойыл, таяғың,\nӘрқашан да, жігер берер!"},{"id":64,"title":"Тәңір мені жаратты","text":"[Куплет 1]\nТәңір мені жаратты,\nсоған қуанам!\n\n[Припев 1]\nМен, сендермен біргемін!\nМен, сендермен біргемін!\nМен, сендермен біргемін!\nДеді Иса!\n\n[Куплет 2]\nҚорқыныш пен түнектен,\nИса сақтайды!\n\n[Куплет 3]\nСенем әрқашан Иса,\nменімен бірге!\n\n[Куплет 4]\nКешірді Ол күнәмді,\nМені құтқарды!\n\n[Куплет 5]\nМадақтаймын Исаны ,\nбар жүрегіммен!","songNumber":"293"},{"id":467,"title":"Тәңір менің Бақташым","text":"[Куплет 1]\nТәңір менің Бақташым!\nСоңынан ердім Оның!\n\n[Припев 1]\nСоңынан, соңынан,\nСоңынан ердім Оның!\n\n[Куплет 2]\nОл мөлдір суға апарады,\nСоңынан жүрсем Оның!\n\n[Припев 2]\nСоңынан, соңынан,\nСоңынан жүрсем Оның!\n\n[Куплет 3]\nБағыт тап шындық жолына,\nСоңыңнан жүріп қуанам!\n\n[Припев 3]\nСоңыңнан,Соңыңнан,\nСоңыңнан, жүріп қуанам!","songNumber":"292"},{"id":752,"title":"Тәңір Өзі көктен түсіп, жер бетіне келеді","text":"[Куплет 1]\nТәңір Өзі көктен түсіп, жер бетіне келеді,\nҚұдай Рухын жіберіп, таза қызға енеді.\nПайғамбарлар Жазбадан, бізге айтып береді,\nОсы Сәби күнәдан, құтқарады әлемді.\n\n[Припев 1]\nИмануил - Құдай бізбен бірге,\nЕгер Ол бірге болса, кім қарсы болады,\nҚұдай бізбен бірге - Имануил.\nЖүректе өлім қорқынышы болса,\nТәңір аспаннан келді.\nКім түнекте жолдан адасса,\nҚұтқарушыны берді.\n\n[Куплет 2]\nҚұдай не істегенінестісін барлық халық,\nТүнектегі ел үшін келді Исамен жарық.\nМәсіхпен бір болғандар қиындықты жеңеді,\nСенімінде нық тұрып, Әкесіне келеді.","songNumber":"167"},{"id":489,"title":"Тәңір саған бата берді","text":"[Куплет 1]\nТәңір саған бата берді\nШексіз сүйіп жарылқады\n// \"Басын иіп балам келді\"\nДеп құшағын саған жайды //\n\n[Куплет 2]\nТәңір сені жарылқады,\nМәңгі өмірді сыйға тартты.\n// Сен арқылы басқаларды\nҚұтқаруға өсиет етті. //\n\n[Куплет 3]\nСөзінен Иса қуат алғын:\n«Қиындық көрсең жар боламын.\n// Жүрсең-дағы қиыр шетте,\nҚасыңда бірге мен боламын». //","songNumber":"198"},{"id":826,"title":"Тәңірім алдыңда тұрмын","text":"[Куплет 1]\nТәңірім алдыңда тұрмын\nШақыршы Сен мені.\nЖан-тәнімді алшы Тәңірім қолыңа,\nҚабылдашы мені.\n\n[Куплет 2]\nТәңірім алдыңда тұрмын\nҚолдашы Сен мені,\nБарлығын аямай мен Саған беремін,\nҚабылдашы мені.\n\n[Припев 1]\nАллелуя!\nАллелуя!\nАллелуя!\nАллелуя!","songNumber":"151"},{"id":79,"title":"Тәңірімді мадақтаймын","text":"[Куплет 1]\nТәңірімді мадақтаймын\nҮзілмейді мадақтауым\nҮзілмейді мадақтауым\nАлғысымды жеткізуге\nЖетпейді тіпті сөздерім\nЖетпейді тіпті сөздерім\n\n[Припев 1]\nСені аңсап іздеп едім\nДауысымды естіп Сен келдің\nҚұтқардың қауіп-қатерден\nҚасымдасың Тәңір Ием"},{"id":206,"title":"Тәңірімді мен даңқтаймын","text":"[Куплет 1]\nТәңірімді мен даңқтаймын,\nҮзілмейді мадақтауым,\nҮзілмейді мадақтауым.\nАлғысымды жеткізуге\nЖетпейді тіпті сөздерім.\nЖетпейді тіпті сөздерім.\n\n[Припев 1]\nСені аңсап іздеп едім.\nДауысымды естіп Сен келдің.\nҚұтқардың қауіп-қатерден.\nҚасымдасың Тәңір Ием.","songNumber":"138"},{"id":77,"title":"Тәңірім жан-дүниеммен Сені көргім келеді","text":"[Куплет 1]\n//  Тәңірім жан-дүниеммен,\nСені көргім келеді!\nКемелді Киелі қалпыңа,\nСендей болғым келеді! //\n\n[Предприпев 1]\n//  Жолымның соңыңдағы,\nжанып тұрған шырақсың,\nҮмітпенен, сеніммен,\nӨзіңе ұмтыламын! //\n\n[Припев 1]\nТәңірім тербетші,\nТәңірім кетпеші,\nКүнәның есігін қайта ашқым келмейді!\nТәңірім жұбатшы,\nТәңірім қорғашы,\nҚұшағыңа алып, тыныштықты сыйлашы!\n\n[Куплет 2]\n// Тәңірім жүрегімнің,\nӨзіңсің бар арманы!\nАрманға жеттім бе, екен?!\nРухыңмен табысқаным?! //"},{"id":382,"title":"Тәңірім құрбан бәрі үшін","text":"[Куплет 1]\nБауырымды сүю, қиын болды,\nТәңірді алдым есіме,\nӨйткені Тәңір Өз жанын қиып,\nболашаққа Ол жол ашқан!\n\n[Припев 1]\n// Тәңірім құрбан, мен үшін болды!\nТәңірім құрбан, сен үшін болды!\nТәңірім құрбан, ол үшін болды!\nТәңірім құрбан бәрі үшін! //\n\n[Куплет 2]\nАзғырушылық келмейді енді,\nАлдаушы рухтар жеңілді!\nЖар-салып айтам, халқыма, келіп,\nКешірімділік берілді!\n\n[Куплет 3]\nАйқышқа қарап сүйдім Сені,\nАйқышқа қарап, кешірдім бәрін!\nАйқыштың құнын, төлемін берген,\nТәңірім менің, құрметті!"},{"id":49,"title":"Тәңірім - менің Бағушым","text":"[Куплет 1]\nТәңірім менің Бағушым\nМен еш нәрседен тарықпаймын\nОл мені жасыл жайлауға жайып\nТұнық суға апарады\n\n[Припев 1]\nЖаныма күш береді\nЕсімі қасиетті болғандықтан\nМен Оған нық сенемін\nОл мені тура жолмен жүргізеді\n\n[Куплет 2]\nҚараңғы шатқалда жүрсем де\nҚауіп-қатерден қорықпаймын.\nСебебі Сен қасымдасың,\nАқ таяғың сүйенішім.\n\n[Куплет 3]\nСен маған дастархан жаясың,\nДұшпандарымның көз алдында.\nҚұрметтеп мені қарсы алып,\nТостағанымды толтырасың.\n\n[Куплет 4]\nЖақсылық пен мейірімділік\nӨмірлік менің үлесім.\nМен мәңгі Тәңірдің үйінде\nҚала беретін боламын","songNumber":"202","alternateTitle":"Тайдырмайды табанымды"},{"id":677,"title":"Тәңірім менің Бағушым","text":"[Припев 1]\n//////  Тәңірім менің - Бағушым!\nМен ешнәрседен де, тарықпаймын!  //////\n\n[Куплет 1]\nҚап-қараңғы, шатқалда жүрсемде мен,\nҚорықпаймын қауіп-қатерден,\nСебебі қасымдасың Сен - Тәңірім!\nЖігер береді маған!\nЖігер береді маған!\nЖігер береді - таяғың мен сойылың!\n\n[Бридж 1]\n//////  Жасыл жайлауға жаяды мені,\nТұнық суға апарады мені - Тәңірім! //////"},{"id":691,"title":"Тәңірім менің Бағушым","text":"[Куплет 1]\nТәңірім - менің Бағушым,\nМен еш нәрседен тарықпаймын.\nОл мені жасыл жайлауға жайып,\nТұнық суға апарады.\n\n[Припев 1]\nЖаныма күш береді,\nЕсімі қасиетті болғандықтан,\nМен Оған нық сенемін.\nОл мені тура жолмен жетелейді.\n\n[Куплет 2]\nҚараңғы шатқалда жүрсем де\nҚауіп-қатерден қорықпаймын.\nСебебі Сен қасымдасың,\nАқ таяғың сүйенішім.\n\n[Куплет 3]\nСен маған дастархан жаясың,\nДұшпандарымның көз алдында.\nҚұрметтеп мені қарсы алып,\nТостағанымды толтырасың.\n\n[Куплет 4]\nЖақсылық пен мейірімділік\nӨмірлік менің үлесім.\nМен мәңгі Тәңірдің үйінде\nҚала беретін боламын."},{"id":251,"title":"Тәңірім менің қалқаным","text":"[Куплет 1]\nТәңірім менің қалқаным,\nЖасқансам болар жартасым.\n// Өзіңнен өзге ешкім жоқ, Әке,\nКүтемін көмек тек Сенен. //\n\n[Куплет 2]\nТәңірім менің жәрдемшім,\nКөзімді саған тігемін.\n// Қанатыңның астында Әке,\nҚауіпсіз өмір сүремін. //","songNumber":"165"},{"id":97,"title":"Тәңірім менің Құдайым!","text":"[Куплет 1]\nТәңірім менің Құдайым!\nӨзіңе арнап жыр жазамын.\nБізге жіберген Ұлыңды, Құтқарушым деп,\nТәңір Ием деп қарсы аламын.\n\n[Припев 1]\nЕй, халықтар, барлық ұлттар келіңдер!\nҚұдайдың махаббатын көріңдер.\nОл бізді сүйіп, Ол бізді сүйіп.\nҚұрбан ғып берді жалғыз Ұлын.\n\n[Куплет 2]\nИсаға сенген әркімге\nМәңгілік өмір беріледі.\nСенімін Оған жүктесе,\nЖұмақтан орын, жұмақтан орын алады.","songNumber":"147"},{"id":582,"title":"Тәңірімнің Аты қамал сияқты","text":"[Куплет 1]\nТәңірімнің Аты қамал сияқты.\nОған кірген адам құтқарылады.\nОның Аты ардақталсын\nОның Аты мадақталсын\nОның Аты ардақталсын\nЖер мен көкте!","songNumber":"61"},{"id":604,"title":"Тәңірімнің керней үні","text":"[Куплет 1]\nТәңірімнің керней үні,\nЖер бетіне жеткенде,\nЖарқырап мәңгі, таң нұры шығады.\nҚұтқарылғанды түгендеп,\nБәрін шақырған кезде,\nАрасында мені де Ол атайды.\n\n[Куплет 2]\n/// Аспанда жиналғанда,   ///\nТәңірімнің еркімен мен боламын.\n\n[Куплет 3]\nМәсіхте тірілген жандардың\nИгілік күнінде,\nТазаланғандарды Мәсіх Қанымен,\nПатшаның мекеніне шақырып\nКіргізген кезде,\nШақырған үнге мен жауап беремін.\n\n[Куплет 4]\nСен үшін еңбек етіп,\nТаң атқаннан күн батқанша,\nТәңірім, бәріне қызмет етемін.\nЖер бетіндегі жұмысты\nЕркіңмен тоқтатқанда,\nАспандағы түгендеуге барамын.","songNumber":"147"},{"id":841,"title":"Тәңірім, рақымыңды енді","text":"[Куплет 1]\nТәңірім, рақымыңды енді,\nҚалай айтпай тұра алам.\nІздеп таптың Өзің Ием, мені,\nЖүрген едім жолмен бұралаң.\n\n[Припев 1]\nЖетелеші мені, өтінемін Сенен,\nӨзіңмен бірге болсам деп ем.\nҚолыңды бер маған, жетегіңе ерем,\nҚұдіретіңе анық сенем.\n\n[Куплет 2]\nТәңірді біреу аңыз дейді,\nҚиналса жаны іздейді.\nМен үшін Мәсіх - Құтқарушы,\nКүтеді, үмітін үзбейді.\n\n[Куплет 3]\nҚұтқарушым, жарылқашы Өзің,\nНәр берсін жүрекке Сөзің.\nҚарасам айқышқа үздіксіз,\nЕшқашан сарқылмас төзім.","songNumber":"163"},{"id":842,"title":"Тәңірім Сенің Рухыңды аңсаймын","text":"[Куплет 1]\nТәңірім Сенің Рухыңды аңсаймын.\nКүтемін Сені Киелі күтемін.\nСүйіспеншілігіңмен, жүрегімді толтыршы.\nАлдыңа келіп, жүзіңді іздеймін.\n\n[Припев 1]\nӘкетайым Өз құшағыңа алшы.\nӨз Жүзіңменен мені өзгертші.\nСенің алдыңа Тәңірім аңсап,\nМен жүгіріп шығам(ын)\nТәңірім құшағыңа қысып мені алшы.\n\n[Бридж 1]\n// Иса  Сені сүйемін.\nИса Сені сүйемін\nИса  Сені сүйемін.\nТәңірім құшағыңа қысып мені алшы! //  2р.","alternateTitle":"Тәңірім Өз Құшағыңа алшы"},{"id":205,"title":"Тек қана Исада бақыттымын мен","text":"[Куплет 1]\nТек қана Исада бақыттымын мен,\nИса Досым, Онымен бөлісем.\nЕңбектен тек Исада мен демалам,\nСенімді Досты мен Содан таптым.\n\n[Припев 1]\nМәсіхке дос болу қандай бақыт,\nЖеткізе алмайсың ауызбен айтып.\nМенің жүрегім қуанады Онда,\nҒажайып жан Досым Исада.\n\n[Куплет 2]\nЖан Досыммен тату тұрамын мәңгі,\nДосым Өз қанымен мені құтқарды.\nСүйіспеншілігін айқышта дәлелдеді,\nСодан таптым сенімді мен Досты.","songNumber":"141"},{"id":237,"title":"Тек қана Исаның қаны","text":"[Куплет 1]\nКүнәдан тазартады\nТек қана Исаның қаны.\nМені не жаңартады?\nТек қана Исаның қаны.\nҚымбат қан төгілді\nАппақ қардай етті.\nМені тазартады\nТек қана Исаның қаны.\n\n[Куплет 2]\nҮміт берер тыныммен\nТек қана Исаның қаны\nӘділдік беретін ол -\nТек қана Исаның қаны.\nДаңқ құрметке лайықты\nТек қана Исаның қаны.\nМадақтаймын жаныммен\nТек қана Исаның қанын.","songNumber":"205","copyright":"Публик Домаин"},{"id":23,"title":"Тек қана Құдайда тыныштық табасың","text":"[Куплет 1]\nТек қана Құдайда тыныштық табасың.\nСоңынан ерсең сен Тәңірдің, тек Соның.\nШақырып Өзіңе Ол сені,\nБақытты еткісі келеді.\nКелсеңші, келсеңші!\n\n[Куплет 2]\nТаста бұл күнәкар өмірді, зұлымды,\nСүйіспеншілігі жоқ осы жалғанды.\nАсық сен келуге Исаға.\nБақыт пен тыныштық табасың // Исада! //\n\n[Куплет 3]\nШақырады Тәңірім енді асық сен.\nАйқышта Қаны ақты Оның сен үшін.\nНеге енді асықпай тұрсың,\nҚұдай қауымына кел, досым // келсеңші! //\n\n[Куплет 4]\nСақтайды сені жамандықтан, азаптан.\nӘкеңдей бәріне де ортақ әрқашан.\nӘлсіресең Ол күш береді.\nЕгер де сиынсаң сен Оған // әр күні! //","songNumber":"132","alternateTitle":"Бақыт пен тыныштық табасың Исада!"},{"id":896,"title":"Тек Мәсіхте үміттенем","text":"[Куплет 1]\nТек Мәсіхте үміттенем,\nОл жарығым, күшім, әнім.\nДауыл соқса, азап, шөлде,\nБерік негіз іргетасым.\nҚасірет пен қорқынышта,\nМахаббат пен тыным шыңы,\nМенің барым, жұбанышым -\nМәсіх нұрында мен тұрам.\n\n[Куплет 2]\nТек Мәсіх боп тәнде келді,\nҚұдай Өзі Сәби болды.\nОл әділдік, сүю сыйы,\nАдамдар бірақ бас тартты.\n\n[Куплет 3]\nАйқышта Ол өлген кезде,\nТынышталды Құдай қаһары.\nОған біздің күнә артылды,\nТұрам Мәсіх өлімінде.\n\n[Куплет 4]\nЖерге көмді Оның тәнін,\nТүнек басты әлем нұрын.\nДаңқты күні Ол жарқ етті,\nҚабірден Ол қайта тұрды.\nИса Мәсіх - жеңімпаз Ол!\nКүнә қарғысы жойылды, жоқ.\nОл менікі, мен Онікі,\nМәсіх қаны жуды мені.\n\n[Куплет 5]\nЕш айып жоқ, қорқыныш жоқ,\nБұл мендегі Мәсіх күші.\nСәби кезде, соңғы шақта,\nӨмірім Иса қолында.\nТозақ торы, амал-айла,\nҚолынан Оның еш алмайды.\nОл келгенше, шақырғанша,\nТұрамын Мәсіх күшінде.","songNumber":"204","copyright":"2001 Танкыоу Мусик"},{"id":840,"title":"Тек Сен үшін Әке","text":"[Куплет 1]\nТәңірім менің - Сені сүйемін\nШын жүрегімнен Сені сүйемін\nАлдыңа  келіп, Саған табынамын\nӘкетайым тек Сені сүйемін\n\n[Припев 1]\nТек Сен үшін Әке менің жүрегім соғады\nТек Сен үшін Әке әрбір тынысым менің\nТек Сен үшін Әке бүгінгі күнім туылады\nТек Сен үшін Әке, тек Сен үшін Әке"},{"id":803,"title":"Тек Сенімен болғым келеді","text":"[Куплет 1]\nТек Сенімен болғым келеді,\nӘр күні Сенің үйіңде.\nТабынғым келмейді алыста,\nЖақындатшы Өзіңе.\n\n[Куплет 2]\nТек Сенімен болғым келеді,\nМәңгілік орындағы үйде.\nҚайда болсаң да ал Өзіңе,\nСенімен болам бірге\n\n[Куплет 3]\nТек Сенімен боламын,\nСен бар үйде, орында.\nДастарханда тойлаймын,\nКенелген Сенің даңқыңа.\nСенің үйіңде\nәрқашан болғым келеді.\nМенің қалауым -\nСенімен бірге болу.\n\n[Куплет 4]\nО, Құдай,\nСен - құдіретсің әнімсің,\nСенің үйіңде болам.\nәлсізбін, Сен күштісің.","songNumber":"206","copyright":"1989 Интегриты'с Хосанна! Мусик"},{"id":59,"title":"Теңдесі жоқ Ұлы Құдай","text":"[Куплет 1]\nТеңдесі жоқ Ұлы Құдай\nСиынам Саған.\nТағзым етіп келгенімде\nТыныштыққа бөлейсің.\n\n[Припев 1]\nЖан-дүниемді Тәңірім Саған берем.\nҰлы Құдай өмірімнің бұлағысың Сен.\n\n[Куплет 2]\nАлдыңа келіп, бас ием,\nТәңірім, Саған.\nЖұбаныштың жалғыз көзін\nТаптым мен тек Өзіңнен.\nҰлысың Сен,\nТең келер жан жоқ Саған.\nАлдыңа кеп табынамын,\nМейірімді Әкем.","songNumber":"10"},{"id":115,"title":"Тең келер Саған","text":"[Куплет 1]\nЖаратқан Иені\nДәріптеймін жырыммен\nСебебі Ол жеңімпаз\nМерейі үстем бәрінен\nМадақтау жырымды\nОған арнай берейін\nТәңір мені құтқарып\nАман сақтайды бәрінен\n\n[Припев 1]\nТең келер Саған ешкім жоқ\nҚай Тәңір Саған тең келер\nЕшкім жоқ Сендей қасиетті\nКеремет істер жасайтын\n\n[Куплет 2]\nҚұтқарылған халқыңа\nРақымыңды бересің\nКиелі мекеніңе\nРухыңмен жетелейсің\nТәңірім сол жерде\nКиелі орын жасады\nМәңгі болады билігі\nЖаратушы Исаның"},{"id":557,"title":"Тербетеді әуен менің жанымды","text":"[Куплет 1]\nТербетеді әуен менің жанымды,\nТыңдай ма екен Тәңір менің әнімді?\nҚайта-қайта келді жүрекке осы ән.\nМадақтасам деп ем Иса Тәңірді.\n\n[Куплет 2]\nЖүрегімде орнап Сенің сөздерің,\nАшылды ғой Ием, менің көздерім.\nАқ жолыңа түстім, баста Сен мені.\nАйтқанына ермен енді өзгенің.\n\n[Куплет 3]\nАқиқатты нұсқа, ашып ұлыңа,\nОяныш бер менің алыс қырыма.\nМадақтайын Сені, Иса Тәңірім.\nАқ батаңды берші осы жырыма.\n\n[Куплет 4]\nКөкте Сенің даңқың арта берсінші,\nБарлық халқым келіп Саған ерсінші.\nАшшы Өзің жүрегін қазақ елімнің,\nАдамзатқа даңқың қайта келсінші.\n\n[Куплет 5]\nМадақтаңдар, достар, Тәңірді бүгін,\nМадақтаңдар осы ұлылығы үшін.\nАспанменен жерде мадақтаңдаршы,\nИеміздің рақым, шапағаты үшін.","songNumber":"170"},{"id":719,"title":"Тойлаймыз бүгін біз тойлаймыз","text":"[Куплет 1]\nТойлаймыз,\nБүгін біз тойлаймыз\nТойлаймыз,\nБүгін біз тойлаймыз\n\n[Припев 1]\nОл тірілді\nОл тірілді\nОл тірі\nМәнгі тірі!\nОл тірілді\nОл тірілді\nКеліндер, тойлайық\nТәнірімізге қуанып!","songNumber":"208"},{"id":730,"title":"Тойлайық Құдайдың халқы!","text":"[Куплет 1]\nТойлайық Құдайдың халқы!\nОл бізді жарылқады.\nҚұдайға шүкір бізді құтқарды.\nСебеп жоқ қайғыруға Әкеміз қасымызда.\n// Құдайға шүкір Ол бізді сүйді. //\n\n[Припев 1]\nТуылдық біз жеңу үшін\nМейірімін жеткізуге.\n«Сүйемін» деп сөзін берді.\nБіз сенеміз уәдесіне.","songNumber":"140"},{"id":825,"title":"Тоқтай тұршы бауырым сәл баяулап","text":"[Куплет 1]\nТоқтай тұршы бауырым сәл баяулап,\nКөз салшы табиғатқа, қандай ғажап!\nҚұлпырған әсем гүлдер, айналада,\nҚалықтап құстар ұшқан, көк аспанда!\n\n[Куплет 2]\nБолған емес, бұның бәрі, өздігінен\nЖаратты бәрін Иса Өз Сөзімен.\nКөрмейді, естімейді соқыр болған,\nРухани өлген адам күнәсінан\n\n[Куплет 3]\nЖаратылыс,Жаратқанды дәріптейді\nМойындап Құдіретін бас иеді\nАл адам қасарысқан жүрегімен\nАлысқа безіп кетті Тәңірінен.\n\n[Куплет 4]\nИса Мәсіх шынайы Құтқарушы,\nАйқышта біздер үшін қанын төкті.\nБүгінде шақырады күнәхарды,\nКешіреді, мойындашы бар күнәңды."},{"id":839,"title":"Төгілген көктен махаббатың..","text":"[Припев 1]\n// Лайықсың, лайықсың, лайықсың - Иса! //\n\n[Куплет 1]\nТөгілген көктен махаббатың...\nЖүрегімді қуанышқа толтырды.\nӨмірдің қайнар көзін таптым Иса тек Сенде!\nСенің салтанатың әлемді,\nДүниені толықтай толтырады\nөмірдің қайнар көзін таптым\nИса тек Сенде\n\n[Предприпев 1]\nАспан мен жерде Иса Патша\nТәңір - Ол мейірімді\nАспан мен жерде Иса Патша\nТәңір - Құдыретті!\n\n[Бридж 1]\nТәңір Сені мен мадақтаймын\nЛайықсың Иса!\nТәңір Сені мен мадақтаймын\nЛайықсың Иса!","alternateTitle":"Лайықсың - Иса"},{"id":762,"title":"Төсегім үшін рахмет","text":"[Куплет 1]\n\"Төсегім үшін рақмет\" - деп Құдайға айтам,\n\"Төсегім үшін рақмет\" - мені анам жатқызады."},{"id":834,"title":"Туылдың Тәңірім Сен бір пәк қыздан","text":"[Куплет 1]\nТуылдың, Тәңірім - Сен, бір, пәк - қыздан,\nТабиғатың - Киелі Рухтан нұрланған!\nМуса, Дәуіт- секілді, пендеден болмай,\nҚұдайдың Демінен- кәміл, жаралған!\n\n[Припев 1]\nӨзімді бүкілдей, арнаймын Саған!\nИса - шейіт болдың Сен, мен үшін - құрбан!\nӨзіңе әрқашан, алғысымды айтам,\nМахаббатың, жан-дүниемді билесін, баурап!\n\n[Куплет 2]\nЖүрегіме арайлы, шырақты жақтың,\nСұрапыл-дауыл, өшіре алмайтын!\nКиелі Келбетің - нұрлы құяштай,\nЖаннатың-гүліндей, мәңгі солмайтын!"},{"id":622,"title":"Тұз өз күшін жоғалтса керегі жоқ","text":"[Куплет 1]\nТұз өз күшін жоғалтса керегі жоқ,\nҚасиетін сақтаса пайдасы көп.\nТұзы болып Исаның жер бетінде,\nКөмектесші, Тәңірім, ер жетуге.\n\n[Припев 1]\nТұзы болсақ Исаның,\nНұры болсақ Исаның.\nХаты болсақ Исаның,\nЖеңімпаздармыз!\n\n[Куплет 2]\nҚараңғыда шам жарығын түсірер,\nАлыс жерден көрер оны кісілер.\nНұры болып Исаның жер бетінде,\nКөмектесші, Тәңірім, ер жетуге.\n\n[Куплет 3]\nІзгі хабар жазылған хат болайын,\nАдамдардың керегіне жарайын.\nМені оқып Исаны ел танысын,\nАдал болсын жердегі барлық ісім.","songNumber":"295"},{"id":500,"title":"Түн болып, бар әлем тыным тапқанда","text":"[Куплет 1]\nТүн болып, бар әлем тыным тапқанда,\nЖалғыздық жүректе зілдей жатқанда.\nШамның да сәулесін түнек жапқанда,\nЖалынам Тәңірге ойға батқанда.\n\n[Куплет 2]\nҚара түнек бүкіл жер бетін басты,\nЗұлымдық пен күнә шегінен асты.\nАдамдар адасты теріс жолында,\nКүнәға тәуелді, үрей бойында.\n\n[Куплет 3]\nСүюдің Ұстазы - Кеңесші келді,\nШындықты паш етті, жұбаныш берді.\nМәңгі өмір нұры бәрін тазартты,\nКөкке жол ашты айқышы азапты.\n\n[Куплет 4]\nҚұтқарылу нұрын жерге төгіп тұр,\nАдасқан ұл-қызын «Кел» деп күтіп тұр.\nШегінді зұлымдық, одан құтылдық,\nЖарық шамын басқаларға ұсындық.","songNumber":"141"},{"id":1017,"title":"Түнгі дала тұрды тұнжырап","text":"[Куплет 1]\nТүнгі дала тұрды тұнжырап,\nТұрды жарық жұлдыз жарқырап.\nГетсиман бағында бір адам\nТұрды көздеріне жас алып.\n\n[Припев 1]\n«О, Әкем егер қаласаң\nБолсыншы Сенің қалауың.»\n// Осы еді айтқан сөздері\nЖай ғана тұрған Адамның. //\n\n[Куплет 2]\nКенеттен сәулесі нұр шашып,\nЖақыннан періште көрінді.\nПеріште үнсіз бір сыр ашып\nЖаңағы Адамға күш берді.\n\n[Куплет 3]\nҚолдарына қару ұстаған,\nБір топ әскер келді әр жақтан.\nСол Адамды ешбір жазықсыз\nСоқпағына салды жан жақтан.\n\n[Припев 2]\nТөменге қарап тұрдың Сен,\nБолсаң да таза бір мінсіз.\n// Мойныңа алдын күнәсін\nЖай ғана басқа адамның //","songNumber":"142"},{"id":833,"title":"Түнекте жүрдім адасып жолдан","text":"[Куплет 1]\nТүнекте жүрдім адасып жолдан,\nІздедім нұрды, сәулесін шашқан\nСол сәтте Тәңір шақырды мені,\nСыйлауға жаннат, өмірдің гүлін!\n\n[Припев 1]\n// Керемет Сенің саяңда болған\nСыйладың жәннат, ішуге маған!\nПәк-таза тура жолыңмен жүріп,\nӘрқашан алғыс айтамын Саған! //\n\n[Куплет 2]\nЖібердің Көктен, Сен жалғыз Ұлыңды,\nҚұтқару үшін, біздерді Иса!\nБіз үшін төгіп Киелі қаныңды,\nШынайы өмір, сыйладың мәңгі!"},{"id":242,"title":"Түнекте мен жалғыз жүрдім","text":"[Куплет 1]\nТүнекте мен жалғыз жүрдім\nЕсік таппасымды білдім, қараңғыдан, (қараңғыдан.)\nБір жарық жұлдыз нұр төкті\nЖолымды нұсқап көрсетті ердім оған, (ердім оған.)\n\n[Припев 1]\nЖүректен шықты алғыстар\nСаған арналды мадақтар\nТек Сенің даңқыңды көтеріп\nЖар саламыз біз\nИса біздің Тәңіріміз\nЖарқыраған жұлдызымыз\nШынайы жолды көрсететін\nИса Иеміз!\n\n[Куплет 2]\nЕнді мен еш қиналмаймын\nӨйткені жанымда Тәңір жар болады, (жар болады.)\nИса Сен менің тірегім\nМәңгі Құдайсың білемін, аспандағы, (аспандағы.)\n\n[Куплет 3]\nСенімен әрқашан болсам\nЖұмақтан орын аласың, о, бауырым, (о, бауырым.)\nИса Өз құшағын ашып\nСені де қарсы алады, қуанышқа сен толасың.","songNumber":"63"},{"id":703,"title":"Түсінбей жүрген екенмін","text":"[Куплет 1]\nТүсінбей жүрген екенмін\nТәңірдің еркін, жоспарын\nБілемін: тұр Құтқарушым\nоң жағында Патшаның\nМәсіх өлді күнәм үшін\nСөздерінен оқып білдім\nОған зәру жан-дүнием -\nҚұтқарушы Патшама\n\n[Бридж 1]\nКөктегі тағын тастады\nКүнәкар жерге Ол келді\nАқылым бұған жетпейді\nҚұтқарып алды мені\n\n[Припев 1]\n// Бәрін сүйді\nБәрін жеңді\nМәңгі менімен болады\nКеше болған\nҚазір де бар\nМәңгілікте де болады //\n\n[Куплет 2]\nӨмір мен өлім қолында\nКүшім де, жұбанышым да\nҚұтқарушым менің, Патшам\nБолды құрбан мен үшін","copyright":"2005 Бридге Буилдинг Мусик, Инк."},{"id":321,"title":"Тық-тық","text":"[Куплет 1]\n\"Тық-тық\" сағат тықылдайды,\nМейірім саған қуанам.\n\"Тық-тық\" сағат тықылдайды,\nҚұдай осында!\n\"Тық-тық\" сағат тықылдайды,\nАлтынбек саған қуанам.\n\"Тық-тық\" сағат тықылдайды,\nҚұдай бізді естиді."},{"id":860,"title":"Тыныштықта сездім Құдайым, жүрегіме сөйлегеніңді","text":"[Куплет 1]\n// Тыныштықта сездім Құдайымның,\nЖүрегіме сөйлегенін.\nБалам берген ақ жарылқауыңды\nҚабылда атымды менің //\n\n[Припев 1]\n// Ақ бата - сен менің қорғанымсың!\nАқ бата көктен жарылқауымсың!\nҚұдайдың берген сыйы,\nТәңірмен жүрген жолы,\nАқ бата, ақ бата! //\n\n[Куплет 2]\n// Қайда жүрсем де сеземін сені,\nЖанымда жүрегімдесің.\nШын өмір берген Құдайым,\nБатаңа толы өмірім! //"},{"id":991,"title":"Тыныш, тыныш","text":"[Куплет 1]\nТыныш, тыныш шуламаңдаршы,\nЕнді дұға етеміз.\nҚұдайға сөйлейміз,\nТыныш, тыныш шуламаңдаршы."},{"id":745,"title":"Тыңда және орында","text":"[Куплет 1]\nТыңда және орында, тыңда және орында!\nБұл өте жақсы іс!\nАнам маған не айтса да, соны орындаймын,\nҚұдайым соған қуанады!"},{"id":779,"title":"Тыңдаумен жүріп Өзіңді","text":"[Куплет 1]\nТыңдаумен жүріп Өзіңді,\nСырыңа бойлап келемін.\nКиелі әрбір Сөзіңмен,\nБақытқа мені бөледің.\n\n[Припев 1]\n//   Өмірдің көп қой жолдары,\nШартарапқа тараған.\nАл, Сенің жолың біреу-ақ,\nОдан өтер «жаңа адам».  //\n\n[Куплет 2]\nБір күндер Құдай күш беріп,\nҰғармын сөздің астарын.\nҚазірше жүрмін тыңдаумен,\nРухани бауырластарды.\n\n[Куплет 3]\nКиелі кітап қолға алып,\nСырыңа сүңгіп келемін.\nТәй-тәй басқан баладай,\nӨзімді әлсіз көремін.\n\n[Куплет 4]\nАқ бата беріп, Құдайым,\nӨзіңе қабыл ал мені.\nУағыздаушың боп шығайын,\nАқ жолыңа сал мені.","songNumber":"93"},{"id":284,"title":"Тыңдашы әке, бірер сәтке ұлыңды","text":"[Куплет 1]\nТыңдашы әке, бірер сәтке ұлыңды,\nӨзіңе арнап кіші-гірім жырымды.\nҚұлақ салшы, Ізгі хабар айтайын,\nБұл туралы естіп пе едің бұрын-ды?\n\n[Куплет 2]\n«Сен кімсің?» деп баласынып, сөкпеші,\nАз өміріңді ысырап қып төкпеші.\nҚұдай бізге жіберіпті Мәсіхті,\nМәсіхсіз сен о дүниеге өтпеші.\n\n[Куплет 3]\nҚұдай беріп Құтқарушы Мәсіхті,\nКөкке кірер «есікті» Ол ашыпты.\nАшық есік жабылмастан тұрғанда,\nТәубе қылып, тез кіруге асықшы.\n\n[Куплет 4]\nМына өмірдің мәні жайлы ойлашы,\nБар ма екен мағынасы, пайдасы?\nЖанбағыс та, күнкөріс те болар-ау,\nБірақ Мәңгі өмірден құр қалмашы.\n\n[Куплет 5]\nСен де ойлашы, тағдырыңды анашым,\nҚұдайға тек Исаменен барасың.\nИса арқылы тәубе қылсаң Құдайға,\nСонда ғана жан тыныштық табасың.\n\n[Куплет 6]\nКүнәмізден жалығыпты Ол, жеріпті,\nҚұтқаруға Иса болып келіпті.\nАдамзатты сүйгендігі соншалық,\nӨзін-өзі құрбандыққа беріпті.\n\n[Куплет 7]\nБізді өсіріп, бақтың, қақтың, баптадың,\nӘдет-ғұрып, ырымдарды сақтадың.\nОсылайша құтқарылам дейсің сен,\nБірақ бұлай құтқарылу таппадың.\n\n[Куплет 8]\nАлла дейсің, дұрыс, бірақ сол Алла,\nБерген екен бар билікті Исаға.\nСен де аласың кешірім мен мәңгі өмір,\nИсаға кел, жалтақтама, жасқанба.","songNumber":"133"},{"id":761,"title":"Тыңдашы мені, Тәңірім менің","text":"[Куплет 1]\nТыңдашы мені, Тәңірім менің,\nРухымның бүкіл тілегін\nтексере гөрші.\nСен маған берген өмірімді\nРухыңмен жетелеп,\nҚараңғылықтағы әлем үшін\nСәуле қылдыршы мені.\n\n[Куплет 2]\nТыңдашы мені, Тәңірім менің,\nРухымның бүкіл тілегін\nТексере гөрші.\nСен маған берген өмірімді\nЕркіңмен жетелеп,\nБұзылып кеткен әлем үшін\nТұз қылдыршы мені.","songNumber":"212"},{"id":590,"title":"Тырс-тырс","text":"[Куплет 1]\nТырс-тырс, тырс-тырс,\nЖаңбыр жауып тұр.\nТырс-тырс, тырс-тырс,\nГүл су боп тұр."},{"id":643,"title":"Тізе бүгіп, басымды ием","text":"[Куплет 1]\nТізе бүгіп, басымды ием,\nКиелі Рух, кішіпейіл етші.\nЗұлымдықтан көзді бұрып,\nҚуамыз жалған құдайларды.\n\n[Куплет 2]\nТазарт ойымды, жүректі тазарт,\nЖанымызды жалғанға бұрмайық.\nҰрпағың болып, біз Сені іздейікші,\nКөмек берші, Жақыптың Құдайы.","songNumber":"213"},{"id":304,"title":"Тілалғыш болсам","text":"[Куплет 1]\nТілалғыш болсам деймін,\nТек Исама менің,\nӘнге қосқым келеді,\nЖаратқан Иені!\n\n[Припев 1]\nСүйіспеншілік,Сүйіспеншілік,\nҚайталайды құстар!\nҚұдай Өзі - Сүйіспеншілік,\nЖырлайды балалар!"},{"id":831,"title":"Тіршіліктің қайнар көзі","text":"[Куплет 1]\nТіршіліктің қайнар көзі,\nЖаратқан Иеміз!\nЖер бетіне келді Өзі!\n//  Біз Оған сенеміз! //\nБіз Оған сенеміз!\n\n[Куплет 2]\nЖалындаған махаббатын\nЖүрекпен сеземіз\nТөкті әлемге шапағатын\n/// Біз Оған сенеміз! ///\n\n[Припев 1]\nЖаратушым жетелейді\nАлып алақанымен\nЖауымнан қауіп төнбейді\nЖанында бірге жүрсем\nҚамалымсын таудай биік\nҚалың тастан қаланған\nДұшпан келсе жолын қиып\nҚорғанышым бола алған!\n\n[Бридж 1]\n//// Иса, ол - Иса! ////","alternateTitle":"Біз Оған сенеміз!"},{"id":775,"title":"Уақыт келді, төнді қайғы-қасірет","text":"[Куплет 1]\nУақыт келді, төнді қайғы-қасірет,\nТемір шеге сүйектен де өтіп еді.\n// Иса Ием, қандай жаза шегіп ең?\nКөз жасымды тоқтатарға күшім жоқ. //\n\n[Куплет 2]\nЖыла елім, жылай түсші, қазағым,\nИса Ием тәнін берді біз үшін.\n// Азап шекті, төкті қанын, ол - шындық,\nБар мағына осында екен, біз білдік. //\n\n[Куплет 3]\nКешір бізді, айналайын Құдайым,\nСаған елім тағзым етуге дайын.\n// Жар саламыз қазақ деген еліме,\nИса келді кең даламның төріне. //","songNumber":"143"},{"id":208,"title":"Уа, Тәңір жанымдасың","text":"[Куплет 1]\nУа, Тәңір жанымдасың,\nКөз салсам, бар жердесің.\nҚуанам дұғамда мен,\nҚайта шаттанып қуанамын мен!\n\n[Припев 1]\nУайым-қайғымды ұмыттым,\nҚолымды көкке жайдым.\nЖер астымнан ғайып болды,\nСенің жүзіңді көрдім.\nНәзік рухыңнан дем алдым,\nБойыма мен күш алдым,\nМен қуандым.\n// Қуаныш таратылсын,\nЖер жүзінде жасасын! //","songNumber":"152"},{"id":772,"title":"Ұлы да Киелі тағы","text":"[Куплет 1]\nҰлы да Киелі тағы,\nҚұдай отырат.\nКиімінің өңірлері\nҮйді толтырат.\nКөктегі әскері Оны\nДаңқтап мадақтайды,\nПеріштелердің дауысы\nҮйді толтырат.\n\n[Куплет 2]\nКиелі, Киелі Құдай,\nДәріптейміз Сені.\nМейірім мен даңқың\nЖерді кернеп толтырат.","songNumber":"214"},{"id":155,"title":"Ұлы Құдай, Әкелік махаббатпен сыйға тартып","text":"[Куплет 1]\nҰлы Құдай, Әкелік махаббатпен,\nСыйға тартып,нұрыңды төккенде,\nӨз қолыңмен Жаратушым жасаған,\nБар тіршілік, әлемді көргенде.\n\n[Припев 1]\n// Тәңірім, сонда,\nСаған рухым жырлайды:\nҰлысың Сен!\nҰлысың Сен! //\n\n[Куплет 2]\nАспанға, жұлдыздарға көз салсам мен,\nҒажайып жарқын әлем жүзіне.\nМұхиттағы кемедей жүзіп жүрген,\nАй мен күнді әуеде көргенде.\n\n[Куплет 3]\nЖаратылыс көктемде құлпырғанда,\nЖұпар иісі кеудеме толғанда,\nБұлбұл әнін тоғайда естігенде,\nБұлақтың сылдырын тыңдағанда.\n\n[Куплет 4]\nКүн күркіреп, найзағай жарқ еткенде,\nүстімізден қара бұлт төнгенде,\nкемпірқосақ назарыма түскенде,\nқұнарсыз жерге жауын жауғанда.\n\n[Куплет 5]\nАдамзатты сүйіп жер бетіндегі,\nқайғы қасіреттен Ол құтқарғанда,\nмейірін төгіп, жасаған қасиетті,\nісі туралы мен оқығанда.\n\n[Куплет 6]\nБұл дүниеде адамға үлгі болған,\nМәсіхтің жуас жүзін көргенде,\nайқышта бізге кешірім берем деп,\nбар әлемнің Патшасы өлгенде.\n\n[Куплет 7]\nЖүрегімді құмарлық жайлағанда,\nқара қайғы жанға батқанында,\nСүйіспеншілікпен басын иіп кеудеме,\nжылы сөзбен мені Ол жұбатар.\n\n[Куплет 8]\nТәңір мені Өзіне шақырғанда,\nнұрын шашып, сәулесі жарқырап,\nсонда рухым үн шығармай қалады,\nұлылығын Құдайдың мойындап.","songNumber":"177"},{"id":437,"title":"Ұлы Құдай, Әкелік мейіріммен","text":"[Куплет 1]\nҰлы Құдай, Әкелік мейіріммен,\nСыйға тартып, нұрыңды төккенде,\nӨз қолыңмен Жаратушым жасаған,\nБар тіршілік, әлемді көргенде.\n\n[Припев 1]\nТәңірім, сонда Саған рухым жырлайды:\nҰлысың Сен! Ұлысың Сен!.\n\n[Куплет 2]\nАспанға, жұлдыздарға көз салсам мен,\nҒажайып жарқын әлем жүзіне.\nМұхиттағы кемедей жүзіп жүрген,\nАй мен күнді әуеде көргенде.\n\n[Куплет 3]\nЖаратылыс көктемде құлпырғанда,\nЖұпар иісі кеудеме толғанда,\nБұлбұл әнін тоғайда естігенде,\nБұлақтың сылдырын тыңдағанда.\n\n[Куплет 4]\nКүн күркіреп, найзағай жарқ еткенде,\nҮстімізден қара бұлт төнгенде,\nКемпірқосақ назарыма түскенде,\nҚұнарсыз жерге жауын жауғанда.\n\n[Куплет 5]\nАдамзатты сүйіп жер бетіндегі,\nҚайғы-қасіреттен құтқарғанда,\nМейір төгіп, жасаған қасиетті,\nІстері туралы оқығанда.\n\n[Куплет 6]\nБұл дүниеде адамға үлгі болған.\nМәсіхтің жуас жүзін көргенде,\nАйқышта кешірімін беремін деп,\nБар әлемнің Патшасы өлгенде.\n\n[Куплет 7]\nЖүрегімді құмарлық жайлағанда,\nБар қайғы-мұң жанға батқанында,\nМейіріммен басып Өз кеудесіне,\nЖылы сөзбен мені Ол жұбатар.\n\n[Куплет 8]\nИса мені Өзіне шақырғанда,\nНұрын шашып, сәулесі жарқырап,\nСонда рухым үн шығармай қалады,\nҰлылығын Құдайдың мойындап.\n\n[Припев 2]\nҚұдайымызды ән-жырмен мадақтау игі,\nБұл қандай ұнамды да жарасымды!","songNumber":"35"},{"id":576,"title":"Ұлылығың жеткілікті","text":"[Куплет 1]\nҰлылығың жеткілікті,\nМадақтауға лайықты.\nЖарылқасын біздерді Иса\nСаған сенген халықты.\n\n[Припев 1]\nСаған алғыс айтамын\nЖүрегімнен шыққан әніммен.\nСаған алғыс айтамын\nТаңдаулы асыл халқыңмен.\nСаған өте ризамын\nРақымдылығың үшін берген.\nСаған өте ризамын\nМахаббатты көрдім жүзіңнен.","songNumber":"154"},{"id":973,"title":"Ұлылық, салтанат","text":"[Куплет 1]\n// Ұлылық, салтанат,\nҚұдірет Саған! //\nҚұдай Әке табынам Саған,\nҚұтқарушым, сүйемін Сені.\nКиелі Рух, келші бізге.\nКиелі Рух, келші бізге.\nКиелі Рух, келші бізге.\nЖалыныңмен, Жалыныңмен!\nҰлылық,\nСалтанат,\nҚұдірет Саған!\n\n[Припев 1]\nҚұдай Әкем!\nТабынам Саған!\nҚұтқарушым,\nСүйемін Сені!\n/// Киелі Рух, келші бізге ///\nЖалыныңмен!\nЖалыныңмен!","songNumber":"155"},{"id":830,"title":"Ұлым ау, қайда жүрсің","text":"[Куплет 1]\nӨзіңді сағынады Әкең бүгін,\nЖаныңа жетер ме екен, осы үнім?!\n//   Ұлым ау, қайда жүрсің?\nЕсен сау аманбысың?\nЖолыңа көзімді алмай,\nҚарап жүрмін, қарап жүрмін!  //\n\n[Куплет 2]\nӨзіңді шақырады Әкең бүгін,\nҮйіңнен бақыт іздеп кеткен бе едің?!\n//  Сөзіме құлақ салшы,\nЖанымды жадыратшы,\nҰлым ау көп ұзамай,\nҚайта оралшы, қайта оралшы!  //\n\n[Куплет 3]\nҰлым ау ұмыттың ба Әкең барын?!\nБолмаса білдірсеңші ау бір хабарын!\n//  Айтатын сырларым көп,\nСені аңсап жыладым көп!\nҰлым ау сыйлығым бар,\nМенің саған дайындаған!  //\n\n[Куплет 4]\nБауырым ойлансаңшы,\nТезірек оралсаңшы,\nКүтіп тұр Құдай Әкең,\nСені әрқашан, сені әрқашан!","alternateTitle":"Өзіңді сағынады Әкең бүгін"},{"id":584,"title":"Ұлы Тәңір","text":"[Куплет 1]\nҰлы Тәңір, Сен жаратқан дүниеге\nКөз жіберіп қараған кезімде.\nБілемін мен Әкелік махаббатыңмен,\nТіршілікке шапағат нәр бердің.\n\n[Куплет 2]\nСонда Тәңірім,\nСаған рухым жырлайт:\nҰлысың Сен!\nҰлысың Сен!\n\n[Куплет 3]\nКөктем келіп, табиғат гүлдегенде,\nЕстігенде сайраған бұлбұлды.\nЖұпар иіс кеудемді кернегенде,\nЕрке бұлақ сылдырай аққанда.\n\n[Куплет 4]\nБізге айқышта кешірім алып берген,\nАйқышта өлген ғаламның Патшасы.\nЖер бетінде адамның құлы болған,\nМомын жүзін Мәсіхтің көргенде.\n\n[Куплет 5]\nМәсіх келіп, үн қатқан кезде маған,\nНұр төгілер шуақ жанарынан.\nКөндігеді тыншығып сонда рухым,\nШақырады Құдай ұлылығын.","songNumber":"215"},{"id":697,"title":"Ұрандайды көк аспан","text":"[Куплет 1]\nКиелі, киелі Тәңірсің!\nБүкіл жер толы даңқыңа Сенің.\nБарлық халық жырласын,\nҚұрметпен Сені мақтасын.\nЖарқырашы Сен бізден,\nТек Өзіңді әлем көрсін.\n\n[Припев 1]\nҰрандайды көк аспан:\n\"Неткен әсем Құдайым!\"\nӘн салад(ы) ғалам;\n\"Аллелуя! Патша Құдай!\"\n\n[Бридж 1]\n/// Аллелуя патша Құдай! ///","songNumber":"90"},{"id":905,"title":"Ұшамын көктегі ғарышқа","text":"[Куплет 1]\nҰшамын көктегі ғарышқа,\nСамғаймын алысқа, алысқа.\nСені көремін, Саған еремін.\nШексіз қуанар сонда жүрегім.\nЖаныма қуаныш сыйлайсың.\nТаңымды жалғайсың, жалғайсың.\nЖаратқан Ием, Саған сенемін.\nҚайда жүрсем де, болдың тірегім.\n\n[Припев 1]\nЖетеле, жетеле арманға,\nЖас қанатым менің талғанда.\nЖалғыз Сен бөлейтін бақытқа.\nАлғыс айтып әнді салғанда.\n\n[Куплет 2]\nМақтаймын Өзіңді әлемге,\nЖасашы мәңгіге, мәңгіге.\nӨмірдің сырын, махаббат жырын\nБарлық халыққа бірдей ұсындың.\nЖүздерің жарқырап жайнаған.\nНұрланшы әрқашан, әрқашан.\nЖарығың барда жүрейін алға,\nТоқтап қалмайын қараңғы жолда.","songNumber":"156","alternateTitle":"Жетеле арманға"},{"id":781,"title":"Үйіңді сүйем Тәңір, сүйіспеншілік сарайын","text":"[Куплет 1]\nҮйіңді сүйем Тәңір,\nСүйіспеншілік сарайын.\n//  Мәсіх қанымен өтелген,\nҚауымды сүйемін. //\n\n[Куплет 2]\nАлмас-Қауымыңды\nСүйемін мен Құдай,\n// Босағасын сақтайсың\nСен көздің қарасындай. //\n\n[Куплет 3]\nҚымбатты Қауымды,\nТірі жан жиының,\n// Жан-тәніммен өтініште,\nЕске түсіремін. //\n\n[Куплет 4]\nҚұтқарушым, Ием,\nҚауымды Сен басқар,\n// Төзетіндей күш-қуат бер,\nМен Өзіңе келем. //\n\n[Куплет 5]\nҚауыммен бірлікте,\nТұрар менің жаным,\n// Қасіретті айқыш қызметін,\nКөтерем салмағын. //\n\n[Куплет 6]\nСенің даңқыңды,\nБіз бірге бөлісеміз.\n// Сонда аман қалып жаным,\nАлдыңда жырлаймын. //","songNumber":"187"},{"id":209,"title":"Халқын сүйгені соншалық","text":"[Куплет 1]\nХалқын сүйгені соншалық,\nҚұрбан қылды Өзін,\nЖер бетіне түсіп.\nКүнәмыздың бәрін артып,\nҚиналды сотталып\nҚұдайдың Өзі.\n\n[Припев 1]\nХалқым сұраймын дәл қазір\nҚарашы Құдайға,\nОйланшы бір мезгіл.\nЕгер жүрегіңді ашып\nҚабылдасаң Оны\nҚұтқарады сені.\n\n[Куплет 2]\nҚұдай жер бетіне түсіп\nАдам бейнесінде\nАрамызда жүрді.\nӨз қанатының астында\nАнамыздай жылытып\nСүю үшін бізді.","songNumber":"153"},{"id":943,"title":"Харон пайғамбардың ақ батасы","text":"[Куплет 1]\nЖаратқан Ие сені жарылқап\nАман-есен сақтай көрсін\nИеміз саған жүзінің нұрын шашып,\nРақымын төге көрсін!\nИеміз саған жылы жүзбен қарап,\nАмандық пен тыныштық,\nСыйлай берсін!","alternateTitle":"Жаратқан Ием сені жарылқап"},{"id":1003,"title":"Шақыр мені","text":"[Куплет 1]\nШақыр мені естимін,\nШақыр мен барамын,\nСоңыңнан Құдай,\nШетіне жердің.\n\n[Припев 1]\nЖүрегімдесің менің\nСен жақтың отыңды.\nҚұдайым, Сенің\nІзіңмен жүрем.\n\n[Куплет 2]\nЖетелеші,\nМені, Құдайым.\nБоламын бірге\nСен бар жерлерде.\nСені сондай сүйем."},{"id":211,"title":"Шақыршы мені Тәңір","text":"[Куплет 1]\nШақыршы мені Тәңір,\nШақыршы соңыңнан\nАйқышымды арқалап\nЖүруге дайынмын.\nСен менің жүрегімнің\nҮміт отын жақтың.\nТар жолыңмен Сенің\nЖүріп өтейін.\n\n[Припев 1]\nЖетеле мені Тәңір Ием.\nСенімен бірге болғым келеді әрқашан.\nМен Сені сүйемін.","songNumber":"158"},{"id":746,"title":"Шапалақтаймын","text":"[Куплет 1]\nШапалақтаймын қарашы,\nҚұдайым рахмет, қолдарым үшін!\nШапалақтаймын қарашы,\nҚұдайым рахмет қолдарым үшін!"},{"id":98,"title":"Шаттанайық барлығымыз","text":"[Куплет 1]\n//   Шаттанайық барлығымыз,\nИса Тәңір - ән-жырымыз.  //\n\n[Припев 1]\n//   Құдіретті Құдайым,\nМәңгіліктің Құдайы.\nҚұрбан еттің өлімге,\nКүнәм үшін Ұлыңды.  //\n\n[Куплет 2]\n//  Бұл өмірде мен адастым,\nСен мені сүйдің, таңдап алдың.  //","songNumber":"186"},{"id":13,"title":"Шаттанайық мәңгілікке!","text":"[Куплет 1]\n//   Шаттанайық мәңгілікке!\nИса Тәңір құдіретті!  //\n\n[Припев 1]\n//   Мәңгіліктің Құдайы!\nҚұдіретті Құдайым!\nБіз үшін Сен Ұлыңды,\nҚұрбан еттің мәңгіге!  //\n\n[Куплет 2]\n//  Бұл өмірде мен адастым.\nСен мені сүйдің, таңдап алдың.  //","songNumber":"159"},{"id":116,"title":"Шаттанамын Ұлы Құдай жүрегімде","text":"[Куплет 1]\nШаттанамын ұлы Құдай жүрегімде\nМенің мәңгі өмір сүрсе шаттанамын\nҚуанамын Киелі Рух, жүрегімде\nМенің мәңгі өмір сүрсе қуанамын\n\n[Припев 1]\nСүйіспеншілік жолымен жетеледің\nКүнәнің торынан бізді азат еттің\n\n[Куплет 2]\nТәңірім Иса, Сенің даңқың бар әлемде\nБола берсін мәңгілікте бола берсін.\nТәңірім Иса, Сенің атың бар әлемге\nТарай берсін мәңгілікте, тарай берсін.","songNumber":"157"},{"id":300,"title":"Шаттан әрдайым Құдайға!","text":"[Куплет 1]\nШаттан әрдайым Құдайға!\nҚайталаймын шаттан!\n\n[Припев 1]\nШаттан, шаттан!\nҚайталаймын шаттан!","songNumber":"296"},{"id":316,"title":"Шаттаныңдаршы бәрің де!","text":"[Куплет 1]\nШаттаныңдаршы бәрің де!\nЕл жұртым, суым, жерім де.\nШабындықтар мен ормандар,\nШаттықтан қалмаңдар.\n\n[Припев 1]\nМәсіх тірі! Мәсіх тірі!\nМәсіх өлімнен тірілді!\nОл тірілді! Ол тірілді!\nШынымен тірілді!\n\n[Куплет 2]\nӨлімнің кісенін бұздың!\nКүнә байланысын үздің!\nКөтерілдің көк аспанға,\nӘкеге, Құдайға.\n\n[Куплет 3]\nСенімде біз нық басайық,\nЖұмаққа қадам жасайық,\nТәңірді әнге қосайық,\nОны дәріптейік.","songNumber":"171"},{"id":466,"title":"Шаттыққа толы, бақытқа толы","text":"[Куплет 1]\nШаттыққа толы, бақытқа толы\nИсаның туған күні.\nКүнәдан қажыдық, келді бізге Мәсіх,\nСалтанаттың енді жетті үні.\n\n[Куплет 2]\nШаттыққа толы, бақытқа толы\nИсаның туған күні.\nҒажайып әнменен, аспаннан періштелер\nСалтанатты күнді хабарлады.\n\n[Куплет 3]\nШаттыққа толы, бақытқа толы\nИсаның туған күні.\nҚұтқарушы келді, Иеммен табыстырды,\nҚуан, салтанатты күн туды."},{"id":312,"title":"Шеге Сенің денеңе қадалғанда","text":"[Куплет 1]\nШеге Сенің денеңе қадалғанда,\nҚарап тұр-ау соған шыдап адамдар да!\nМәз болады-ау соқыр сезім билеп алған,\nСен кешірім алып едің адамдарға!\n\n[Припев 1]\nМен жасаған күнә үшін Өзің өлдің,\nМен көретін азапты Өзің көрдің!\nШеге маған қадалса шыдайтындай,\nМаған сондай мейірім, төзім бердің!\n\n[Куплет 2]\nӨз еркіңмен айқышқа барғаныңда,\nМен мейіріңде, таң болып жанғанымда,\nЖүрегімде жарқ етті жарық сәуле,\nАспанда бірге болу арманында!\n\n[Куплет 3]\nЕкі мың жылдай өтті, арамызда,\nКөктен келді, Көктен біздің санамызға,\nСаған сеніп құтқарылу алып жатыр,\nБарлық халық, әкемізбен, баламыз да!\n\n[Куплет 4]\nСен күш-қуат бердің біздің бойымызға,\nСен ізденіс бердің біздің ойымызға,\nСен арқылы құтқарылып, барша халық,\nАспанда болар әлі, тойымызда!"},{"id":888,"title":"Шексіз алғыс Саған, Тәңірім","text":"[Куплет 1]\nШексіз алғыс Саған, Тәңірім,\nӨшпес мәңгі нұр сыйладың.\nӨлгенше Сені дәріптеймін,\nБалам деп мені атадың.\n\n[Припев 1]\n// Әлсіздіктен арылсам да,\nСапарымда шаршасам да.\nАрманға жету күресін,\nСен білесің! //\n\n[Куплет 2]\nҚайғы-мұң мені жылатады,\nЖүрегімді сыздатады.\nЖалғыз Сен мені жұбатасың,\nҚуанышты дарытасың.\n\n[Куплет 3]\nДұғамды Саған арнаймын,\nЕстисің мені, күмән жоқ.\nТәңір, шын жүректен сұраймын,\nКешір, себебі күнәм көп.","songNumber":"152"},{"id":405,"title":"Шиқ-шиқ құс","text":"[Куплет 1]\n// \"Шиқ-шиқ\" құс ән айтады,\n\"Құдай мені жаратты\" //\nҚанаттарыма қарашы, мен тез ұша аламын!\n\"Шиқ-шиқ\" құс ән айтады,\n\"Құдай мені жаратты\""},{"id":974,"title":"Шөл далада","text":"[Куплет 1]\nШөл далада жамандықтан қорықпаймын!\nИса Өзі менімен біраге болса.\nБар қатерден Өзі алып өтеді,\nЖұбатып жетелейді мені отанға.\n\n[Куплет 2]\nЖердегі өмірім қиын болса да,\nСенемін Құдайым бірге.\nҰзақ жүрсемде қараңғы шатқалда\nМені еш уақытта тастамайды."},{"id":1012,"title":"Шын жүрегіммен","text":"[Куплет 1]\nШын жүрегіммен\nСені сүйемін Иса\nСені сүйемін Иса\nСені сүйемін\n\n[Припев 1]\nМаған деген махаббатыңды\nЕшкім ешқашан сөндіре алмайды\nМенің отым Сенің рухыңда\nлаулап жатыр, Иса\nСаған деген махаббатымды\nЕшкім ешқашан сөндіре алмайды\nСенің отың менің рухымда\nлаулап жатыр, Иса\n\n[Куплет 2]\nТабынамын мен\nшын жүрегіммен Иса\nБүкіл жаныммен Иса\nСаған табынам\n\n[Припев 2]\nСені аңсайды жан - тәнім аңсайды\nТек Сен ғана Иса маған қажетсің\nМен табынамын басымды иемін\nӘрбір күнім тек Сен үшін Иса\n\n[Припев 3]\nТек Сен үшін Иса"},{"id":829,"title":"Шын жүрегіммен Сені сүйемін Иса","text":"[Припев 1]\n//// Шын жүрегіммен Сені сүйемін Иса.\nСені сүйемін Иса. Сені сүйемін! ////\n\n[Куплет 1]\n// Саған деген махаббатымды,\nЕшкім ешқашан сөндіре алмайды!\nСенің отың менің рухымда,\nЛаулап жатыр Иса! //\n\n[Бридж 1]\nСені аңсайды, жан-тәнім аңсайды.\nТек Сен ғана, Иса маған қажетсің,\nМен табынамын, басымды иемін.\nӘрбір күнім тек Сен үшін Иса! Gm Am"},{"id":765,"title":"Шырша ағашы","text":"[Куплет 1]\nШырша ағашы әдемі ағаш,\nОл әрдайым жап-жасыл.\nТек қана жаз кезінде емес,\nҚыста да жасыл боп көрінеді.\nШырша ағашы әдемі ағаш,\nОл әрдайым жап-жасыл"},{"id":698,"title":"Ыбрайымның Құдайы","text":"[Куплет 1]\nЫбрайымның Құдайы,\nБіз үшін қан төккен.\nҚұрбандыққа Иса,\nкелді көктен.\n\n[Припев 1]\n//   Тағзым етіп алдына келемін,\nӘділетті Патшамның!\nТағзым етіп алдына келемін,\nМейірімді Патшамның!  //\n\n[Куплет 2]\nСүйіп бізді құтқарды,\nТәңіріміз ұлы.\nМәңгі тірі сөздері,\nтиеді жылы.\n\n[Куплет 3]\nТәңір Сенің рақымың,\nТыныштық береді..\nЖарық, нұрың жаныма,\nең керегі.","songNumber":"134"},{"id":733,"title":"Ізгі Құдай, Саған рақмет!","text":"[Куплет 1]\nІзгі Құдай, рақмет Саған!\nБізге тамақ бересің.\nІзгі Құдай рақмет Саған,\nӘр күн бізді сүйесің!"},{"id":871,"title":"Ізгі құдіретпен","text":"[Куплет 1]\nІзгі құдіретпен Тәңір қоршайды,\nӨз қолымен рақымды ұстайды.\nҚиындықтың алдында еш күдіксіз,\nОны ізде Әкемізді ізгі.\n\n[Припев 1]\nҚұдіретті күшпен біз нық тұрамыз,\nСүйенеміз жалғыз Мәсіхке біз.\nСенің мәңгі уәдеңе сенеміз,\nҰлылықпен келесің күтеміз.\n\n[Куплет 2]\nҚасірет пен қайғы-мұң басса да,\nКейде жүру қиындар жолында.\nӨмірімізді тапсырып сеніммен,\nҚарсы(ы) аламыз Иені жеңіспен.\n\n[Куплет 3]\nАзап шеккен Иса Мәсіхпен бірге,\nҚуанышпен жолында жүреміз.\nҚалған азабын толықтыра түсіп,\nЖалғыз Ол үшін өмір сүреміз."},{"id":823,"title":"Ізгі хабар, ізгі хабар таралсын","text":"[Куплет 1]\nІзгі хабар, ізгі хабар таралсын.\nКедергілер, кедергілер болмасын.\nБіз сияқты, біз сияқты ұл-қыздар\nҚұтқарылмай, құтқарылмай қалмасын.\n\n[Припев 1]\nҚұдаймен болсам, қауымға барсам қайғым жоқ\nҚұдайсыз болсам өмірде менің қайғым көп.\nТастама мені Өзіңді енді тапқанда.\nӨмірде менің Өзіңнен басқа Ием жоқ.\n\n[Куплет 2]\nІзгі хабар, Ізгі хабар айтқанда\nҚиын таңдар, қиын таңдар атқанда\nАзғырулар, азғырулар, сынақтар\nАртқа қарай, артқа қарай тартқанда."},{"id":816,"title":"Іздедім Сені күнмен түндерде","text":"[Куплет 1]\nІздедім Сені күнмен түндерде,\nЖайқалған шексіз, алау гүлдерден!\nІздедім Сені, тау мен қыраттан,\nСылдырлап аққан, мөлдір бұлақтан!\nЖаратқан Ием, басымды ием,\nЖалғанда, мына, Өзіңді сүйем!\nӨмірім менің, қолыңда Сенің,\nКешірген қанша, күнәмды менің!\n\n[Куплет 2]\nӨткізген мені, өзен, көлдерден,\nСақтаған боран, ыстық шүлдерден!\nЖетелеп мені, жас балаларша,\nКүтемін Сені, қайта оралғанша!\nӨзіңе ерем, жанымды берем,\nҚиналған шақта, тек Саған сенем!\nАңсаған менің, таңдарым едің,\nЖұбатқан мені, сөздерің, Сенің!\nТәңірім дедім, артамын сенім,\nБәрінен биік, есімің Сенің!"},{"id":796,"title":"Іздеп жүрген бар әлемнің адамы","text":"[Куплет 1]\nІздеп жүрген бар әлемнің адамы,\nБар екен-ау бұл өмірдің ғажабы!\nҚұдай Оны біздер үшін жіберген,\nБолмасын деп адамзаттың азабы.\nЕнді білдім, енді сездім Құдайым,\nСен қасымда жүріпсің ғой әрдайым.\nӘкем-ай деп жылағаным сол еді-ақ,\nӘжептәуір жібіп қалды маңдайым.\n\n[Припев 1]\nОу, көктегі Әке, оу, Көктегі Әке!\n//  Жетеледің мені ғажап өмірге Әке!  //\n\n[Куплет 2]\nБұл өмірден шындық таппай Өзіңсіз,\nКөп қиналдым Сенің асыл Сөзіңсіз.\nӨзімді-өзім алдауменен жүріппін,\nБоламын деп бұл өмірде күнәсіз.\nКешір Әке, кешір менің күнәмді,\nҚолың созып қабыл алшы балаңды.\nҚұтқара гөр азап шеккен жанымды,\nБілмеппін-ау Әке, сенің барыңды.\n\n[Куплет 3]\nБалаң бүгін ақылға кеп ойланды,\nЖүректе бір жаңа сезім оянды.\nКөз алдыда айқыш ағаш көрініп,\nЕнді ғана қызыл қанға боялды.\nӨз Ұлыңды біздің жерге жібердің,\nКүнәм үшін Құрбандығыңды бердің.\nНеткен шексіз, неткен ыстық махаббат!\nӨз қаныңмен күнәмді Сен кешірдің.","songNumber":"135"},{"id":961,"title":"Інжір ағаштары гүлдемесе де","text":"[Куплет 1]\nІнжір ағаштары гүлдемесе де\nБақтарда жүзім шоқтары піспесе де\nЗәйтүн ағаштары өнім бермесе де\nЕгістіктерден астық жиналмаса да\nҚорада қой, табында мал қалмаса да\nМен бәрібір Жаратқанға шаттанамын\nҚұтқарушы Құдайыма қуанамын.\n\n[Куплет 2]\nІнжір ағаштары гүлдемесе де\nБақтарда жүзім шоқтары піспесе де\nЗәйтүн ағаштары өнім бермесе де\nЕгістіктерден астық жиналмаса да\nҚорада қой, табында мал қалмаса да\nЖаратушы Тәңір күш-қуатым болады\nИем мені бұғыдай жүйрік қылады\nҚырат жолмен жүруіме күш дарытады\nЖаратушы Тәңірім"},{"id":210,"title":"Ісін аяқтап жеңіс алып берді","text":"[Куплет 1]\nІсін аяқтап жеңіс алып берді.\nШайтан жеңілді\nӨлімде билік жоқ енді.\nИса - Жеңімпаз!\nО, Аллелуйя!\nҚұтқарушымыз!\nПатшаның Патшасы!\n\n[Припев 1]\n/////  Иса - Тәңір! /////\nИса - Тәңір бар халықтың!","songNumber":"114"},{"id":152,"title":"Эвейну Шалом Алейхем","text":"[Куплет 1]\nЭвейну шалом алейхем.\nЭвейну шалом алейхем.\nЭвейну шалом алейхем.\nЭвейну шалом, шалом, шалом алейхем.\n\n[Куплет 2]\nМы вам желаем мира.\nМы вам желаем мира.\nМы вам желаем мира.\nМы вам желаем мира, мира во Христе.\n\n[Куплет 3]\nСізге тыныштық тілейміз.\nСізге тыныштық тілейміз.\nСізге тыныштық тілейміз.\nТәңіріміз Исаның тыныштығын.","songNumber":"297"}];
